final_template:
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC that will be associated with the private hosted zone."
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_domain_name" {
  description = "Domain name for the private hosted zone."
  type        = string
  default     = "internal.example.local"
}

variable "tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default = {
    Name        = "route53-zone-association"
    Environment = "development"
  }
}

locals {
  common_tags = merge(
    var.tags,
    {
      ManagedBy = "terraform"
    },
  )
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = local.common_tags
}

# The hosted zone intentionally defines NO inline vpc {} blocks.
# The zone-to-VPC association is exclusively owned by the dedicated
# aws_route53_zone_association resource below to avoid conflicting
# association state and perpetual diffs.
resource "aws_route53_zone" "private" {
  name          = var.private_domain_name
  force_destroy = true

  tags = local.common_tags
}

resource "aws_route53_zone_association" "main" {
  zone_id    = aws_route53_zone.private.zone_id
  vpc_id     = aws_vpc.main.id
  vpc_region = "us-east-1"
}

output "hosted_zone_id" {
  description = "ID of the private hosted zone."
  value       = aws_route53_zone.private.zone_id
}

output "hosted_zone_name" {
  description = "Domain name of the private hosted zone."
  value       = aws_route53_zone.private.name
}

output "associated_vpc_id" {
  description = "ID of the VPC associated with the private hosted zone."
  value       = aws_route53_zone_association.main.vpc_id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "domain_name" {
  description = "Private DNS domain name used for the Route 53 hosted zone."
  type        = string
  default     = "db.internal"
}

# -----------------------------------------------------------------------------
# Data sources and locals
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  db_master_username = "dbadmin"
  db_name            = "appdb"
  reader_record_name = "reader.${var.domain_name}"
  reader_record_ttl  = 60
  replica_weight     = 100
}

# -----------------------------------------------------------------------------
# Network foundation
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "main"
  }
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  availability_zone = data.aws_availability_zones.available.names[count.index]
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)

  tags = {
    Name = "main-private-${count.index + 1}"
  }
}

resource "aws_db_subnet_group" "main" {
  name       = "main-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "main"
  }
}

resource "aws_security_group" "database" {
  name        = "database-tier"
  description = "Database tier - permits MySQL access from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from within the VPC"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "MySQL replication from read replicas to the primary"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "DNS (UDP) to the VPC resolver"
    from_port   = 53
    to_port     = 53
    protocol    = "udp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "DNS (TCP) to the VPC resolver"
    from_port   = 53
    to_port     = 53
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "database-tier"
  }
}

# -----------------------------------------------------------------------------
# Database master credentials
# -----------------------------------------------------------------------------

resource "random_password" "master" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}:?"
  min_upper        = 2
  min_lower        = 2
  min_numeric      = 2
  min_special      = 2
}

resource "aws_secretsmanager_secret" "db_master" {
  name                    = "rds-mysql-primary-master"
  description             = "Master credentials for the primary MySQL database instance"
  recovery_window_in_days = 0

  tags = {
    Name = "rds-mysql-primary-master"
  }
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    username = local.db_master_username
    password = random_password.master.result
    engine   = "mysql"
    host     = aws_db_instance.primary.address
    port     = 3306
    dbname   = local.db_name
  })
}

# -----------------------------------------------------------------------------
# Database instances
# -----------------------------------------------------------------------------

resource "aws_db_instance" "primary" {
  identifier                 = "primary"
  engine                     = "mysql"
  engine_version             = "8.0"
  instance_class             = "db.t4g.medium"
  allocated_storage          = 20
  max_allocated_storage      = 100
  storage_type               = "gp3"
  storage_encrypted          = true
  db_name                    = local.db_name
  username                   = local.db_master_username
  password                   = random_password.master.result
  db_subnet_group_name       = aws_db_subnet_group.main.name
  vpc_security_group_ids     = [aws_security_group.database.id]
  publicly_accessible        = false
  multi_az                   = false
  backup_retention_period    = 7
  backup_window              = "03:00-04:00"
  maintenance_window         = "sun:04:30-sun:05:30"
  auto_minor_version_upgrade = true
  copy_tags_to_snapshot      = true
  deletion_protection        = true
  skip_final_snapshot        = true

  tags = {
    Name                       = "primary"
    MasterCredentialsSecretArn = aws_secretsmanager_secret.db_master.arn
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_db_instance" "replica_1" {
  identifier             = "replica-1"
  replicate_source_db    = aws_db_instance.primary.identifier
  instance_class         = aws_db_instance.primary.instance_class
  vpc_security_group_ids = [aws_security_group.database.id]
  publicly_accessible    = false
  skip_final_snapshot    = true

  tags = {
    Name                       = "replica-1"
    MasterCredentialsSecretArn = aws_secretsmanager_secret.db_master.arn
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_db_instance" "replica_2" {
  identifier             = "replica-2"
  replicate_source_db    = aws_db_instance.primary.identifier
  instance_class         = aws_db_instance.primary.instance_class
  vpc_security_group_ids = [aws_security_group.database.id]
  publicly_accessible    = false
  skip_final_snapshot    = true

  tags = {
    Name                       = "replica-2"
    MasterCredentialsSecretArn = aws_secretsmanager_secret.db_master.arn
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Route 53 private hosted zone, health checks, and weighted reader records
# -----------------------------------------------------------------------------

resource "aws_route53_zone" "main" {
  name    = var.domain_name
  comment = "Private hosted zone for the RDS reader endpoints"

  vpc {
    vpc_id = aws_vpc.main.id
  }

  tags = {
    Name = "main"
  }
}

resource "aws_route53_health_check" "replica_1" {
  fqdn              = aws_db_instance.replica_1.address
  port              = 3306
  type              = "TCP"
  failure_threshold = 3
  request_interval  = 30

  tags = {
    Name = "replica-1-health-check"
  }
}

resource "aws_route53_health_check" "replica_2" {
  fqdn              = aws_db_instance.replica_2.address
  port              = 3306
  type              = "TCP"
  failure_threshold = 3
  request_interval  = 30

  tags = {
    Name = "replica-2-health-check"
  }
}

resource "aws_route53_record" "reader_replica_1" {
  zone_id = aws_route53_zone.main.zone_id
  name    = local.reader_record_name
  type    = "CNAME"
  ttl     = local.reader_record_ttl

  weighted_routing_policy {
    weight = local.replica_weight
  }

  set_identifier  = "replica-1"
  records         = [aws_db_instance.replica_1.address]
  health_check_id = aws_route53_health_check.replica_1.id
}

resource "aws_route53_record" "reader_replica_2" {
  zone_id = aws_route53_zone.main.zone_id
  name    = local.reader_record_name
  type    = "CNAME"
  ttl     = local.reader_record_ttl

  weighted_routing_policy {
    weight = local.replica_weight
  }

  set_identifier  = "replica-2"
  records         = [aws_db_instance.replica_2.address]
  health_check_id = aws_route53_health_check.replica_2.id
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "reader_fqdn" {
  description = "FQDN of the weighted CNAME record that splits read traffic between the two replicas."
  value       = aws_route53_record.reader_replica_1.fqdn
}

output "replica_1_weight" {
  description = "Route 53 weighted-routing weight assigned to the replica-1 CNAME record."
  value       = aws_route53_record.reader_replica_1.weighted_routing_policy[0].weight
}

output "replica_2_weight" {
  description = "Route 53 weighted-routing weight assigned to the replica-2 CNAME record."
  value       = aws_route53_record.reader_replica_2.weighted_routing_policy[0].weight
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Project identifier applied to all resources via the Project tag."
  type        = string
  default     = "batch-job-processing"
}

variable "worker_environment_name" {
  description = "Name of the Elastic Beanstalk worker tier environment."
  type        = string
  default     = "batch-job-worker-env"
}

variable "worker_instance_type" {
  description = "EC2 instance type used by the worker tier Auto Scaling group."
  type        = string
  default     = "t3.small"
}

variable "batch_job_queue_visibility_timeout" {
  description = "Visibility timeout in seconds for the batch job SQS queue."
  type        = number
  default     = 300
}

locals {
  common_tags = {
    Project   = var.project_name
    ManagedBy = "terraform"
  }
}

# ---------------------------------------------------------------------------
# Worker tier application source bundle (built locally, zipped for deployment)
# ---------------------------------------------------------------------------

data "archive_file" "worker_bundle" {
  type        = "zip"
  output_path = "${path.module}/build/batch-worker-bundle.zip"

  source {
    content = <<-EOT
      """Minimal batch worker application for the Elastic Beanstalk worker tier.

      The worker environment daemon (sqsd) polls the batch job queue and
      forwards every SQS message to this WSGI application as an HTTP POST
      request on the local web server. Responding with HTTP 200 acknowledges
      successful processing so the message is deleted from the queue.
      """

      def application(environ, start_response):
          """WSGI entry point invoked for every polled batch job message."""
          if environ["REQUEST_METHOD"] == "POST":
              # Batch job payload processing would be implemented here; this
              # scaffold acknowledges every job so messages are consumed.
              start_response("200 OK", [("Content-Type", "text/plain")])
              return [b"Batch job accepted"]
          start_response("200 OK", [("Content-Type", "text/plain")])
          return [b"Batch worker running"]
    EOT
    filename = "application.py"
  }

  source {
    content = <<-EOT
      # The scaffold worker application relies on the Python standard library only.
    EOT
    filename = "requirements.txt"
  }
}

# ---------------------------------------------------------------------------
# S3 bucket storing the Elastic Beanstalk application version source bundles
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "sampleapril26426" {
  bucket = "sampleapril26426"

  tags = merge(
    local.common_tags,
    {
      Name = "sampleapril26426"
    },
  )

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "sampleapril26426" {
  bucket = aws_s3_bucket.sampleapril26426.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "sampleapril26426" {
  bucket = aws_s3_bucket.sampleapril26426.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "sampleapril26426" {
  bucket = aws_s3_bucket.sampleapril26426.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "sampleapril26426" {
  bucket = aws_s3_bucket.sampleapril26426.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_object" "examplebucket_object" {
  bucket = aws_s3_bucket.sampleapril26426.id
  key    = "application-versions/batch-worker-bundle.zip"
  source = data.archive_file.worker_bundle.output_path
  etag   = data.archive_file.worker_bundle.output_md5

  content_type = "application/zip"

  tags = merge(
    local.common_tags,
    {
      Name = "examplebucket_object"
    },
  )

  depends_on = [
    aws_s3_bucket_server_side_encryption_configuration.sampleapril26426,
    aws_s3_bucket_versioning.sampleapril26426,
  ]
}

# ---------------------------------------------------------------------------
# SQS queue used as the batch job intake queue for the worker tier
# ---------------------------------------------------------------------------

resource "aws_sqs_queue" "batch_job_queue" {
  name                       = "batch_job_queue"
  visibility_timeout_seconds = var.batch_job_queue_visibility_timeout
  message_retention_seconds  = 345600
  sqs_managed_sse_enabled    = true

  tags = merge(
    local.common_tags,
    {
      Name = "batch_job_queue"
    },
  )

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# IAM role, least-privilege inline policy, and instance profile for EC2
# ---------------------------------------------------------------------------

resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEC2AssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })

  tags = merge(
    local.common_tags,
    {
      Name = "eb_ec2_role"
    },
  )
}

resource "aws_iam_role_policy" "eb_worker_sqs_s3" {
  name = "eb-worker-sqs-s3-access"
  role = aws_iam_role.eb_ec2_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ConsumeBatchJobQueue"
        Effect = "Allow"
        Action = [
          "sqs:ReceiveMessage",
          "sqs:DeleteMessage",
          "sqs:GetQueueAttributes",
          "sqs:SendMessage",
        ]
        Resource = aws_sqs_queue.batch_job_queue.arn
      },
      {
        Sid      = "ListApplicationVersionBucket"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = aws_s3_bucket.sampleapril26426.arn
      },
      {
        Sid      = "FetchApplicationVersions"
        Effect   = "Allow"
        Action   = ["s3:GetObject"]
        Resource = "${aws_s3_bucket.sampleapril26426.arn}/*"
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eb_worker_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name

  tags = merge(
    local.common_tags,
    {
      Name = "eb_ec2_profile"
    },
  )
}

# ---------------------------------------------------------------------------
# Elastic Beanstalk application, version, and worker tier environment
# ---------------------------------------------------------------------------

resource "aws_elastic_beanstalk_application" "batch_job_app" {
  name        = "batch_job_app"
  description = "Elastic Beanstalk application hosting batch processing jobs"

  tags = merge(
    local.common_tags,
    {
      Name = "batch_job_app"
    },
  )

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_elastic_beanstalk_application_version" "version" {
  name        = "version"
  application = aws_elastic_beanstalk_application.batch_job_app.name
  description = "Initial batch worker application source bundle"
  bucket      = aws_s3_bucket.sampleapril26426.id
  key         = aws_s3_object.examplebucket_object.key

  tags = merge(
    local.common_tags,
    {
      Name = "version"
    },
  )

  depends_on = [aws_s3_object.examplebucket_object]
}

resource "aws_elastic_beanstalk_environment" "batch_worker" {
  name                = var.worker_environment_name
  application         = aws_elastic_beanstalk_application.batch_job_app.name
  description         = "Worker tier environment for batch processing jobs"
  solution_stack_name = "64bit Amazon Linux 2023 v4.3.0 running Python 3.12"
  tier                = "Worker"
  version_label       = aws_elastic_beanstalk_application_version.version.name

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = var.worker_instance_type
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "4"
  }

  setting {
    namespace = "aws:elasticbeanstalk:worker"
    name      = "WorkQueueURL"
    value     = aws_sqs_queue.batch_job_queue.url
  }

  setting {
    namespace = "aws:elasticbeanstalk:worker"
    name      = "WorkQueueSize"
    value     = "10"
  }

  setting {
    namespace = "aws:elasticbeanstalk:worker"
    name      = "MessageRetentionTimeout"
    value     = "345600"
  }

  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  tags = merge(
    local.common_tags,
    {
      Name = var.worker_environment_name
    },
  )

  depends_on = [
    aws_iam_role_policy.eb_worker_sqs_s3,
    aws_iam_role_policy_attachment.eb_worker_tier,
  ]

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Outputs for downstream batch producers
# ---------------------------------------------------------------------------

output "worker_environment_name" {
  description = "Name of the Elastic Beanstalk worker tier environment."
  value       = aws_elastic_beanstalk_environment.batch_worker.name
}

output "batch_job_queue_arn" {
  description = "ARN of the SQS queue that downstream batch producers should enqueue jobs into."
  value       = aws_sqs_queue.batch_job_queue.arn
}

output "batch_job_queue_url" {
  description = "URL of the SQS queue that downstream batch producers should enqueue jobs into."
  value       = aws_sqs_queue.batch_job_queue.url
}

output "application_version_label" {
  description = "Label of the currently deployed Elastic Beanstalk application version."
  value       = aws_elastic_beanstalk_application_version.version.name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
  }
}

# Default provider serves the us_west stack (us-west-2).
provider "aws" {
  region = "us-west-2"
}

# Aliased provider serves the eu_central stack (eu-central-1).
provider "aws" {
  alias  = "eu_central"
  region = "eu-central-1"
}

variable "domain_name" {
  description = "Public domain for the Route53 hosted zone used for geolocation routing."
  type        = string
  default     = "example.com"
}

variable "solution_stack" {
  description = "Elastic Beanstalk solution stack (Python 3.12 runtime on Amazon Linux 2023)."
  type        = string
  default     = "64bit Amazon Linux 2023 v4.3.0 running Python 3.12"
}

variable "instance_type" {
  description = "EC2 instance type for the Elastic Beanstalk web servers."
  type        = string
  default     = "t3.micro"
}

data "aws_availability_zones" "us_west" {
  provider = aws
  state    = "available"
}

data "aws_availability_zones" "eu_central" {
  provider = aws.eu_central
  state    = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  us_west_region         = "us-west-2"
  eu_central_region      = "eu-central-1"

  us_west_env_name       = "us-west"
  eu_central_env_name    = "eu-central"

  us_west_app_version    = "us-west-v1"
  eu_central_app_version = "eu-central-v1"

  app_fqdn               = "app.${var.domain_name}"

  common_tags = {
    ManagedBy = "terraform"
  }

  geo_tags_us_west    = merge(local.common_tags, { Geo = "us-west" })
  geo_tags_eu_central = merge(local.common_tags, { Geo = "eu-central" })
  geo_tags_global     = merge(local.common_tags, { Geo = "global" })

  wsgi_requirements = "# No third-party dependencies are required; the application uses only the Python standard library.\n"
}

locals {
  us_west_wsgi_app = <<-EOT
    """Minimal WSGI application for the ${local.us_west_env_name} Elastic Beanstalk environment."""
    import os

    ENVIRONMENT_NAME = "${local.us_west_env_name}"
    REGION_NAME = os.environ.get("AWS_REGION", "${local.us_west_region}")

    def application(environ, start_response):
        status = "200 OK"
        headers = [("Content-Type", "text/plain; charset=utf-8")]
        body = "Hello from Elastic Beanstalk environment {} in {}!\n".format(
            ENVIRONMENT_NAME, REGION_NAME
        ).encode("utf-8")
        start_response(status, headers)
        return [body]
  EOT

  eu_central_wsgi_app = <<-EOT
    """Minimal WSGI application for the ${local.eu_central_env_name} Elastic Beanstalk environment."""
    import os

    ENVIRONMENT_NAME = "${local.eu_central_env_name}"
    REGION_NAME = os.environ.get("AWS_REGION", "${local.eu_central_region}")

    def application(environ, start_response):
        status = "200 OK"
        headers = [("Content-Type", "text/plain; charset=utf-8")]
        body = "Hello from Elastic Beanstalk environment {} in {}!\n".format(
            ENVIRONMENT_NAME, REGION_NAME
        ).encode("utf-8")
        start_response(status, headers)
        return [body]
  EOT
}

###############################################################################
# Networking: us-west-2
###############################################################################

resource "aws_vpc" "us_west" {
  provider             = aws
  cidr_block           = "10.10.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.geo_tags_us_west, { Name = "eb-us-west-vpc" })
}

resource "aws_internet_gateway" "us_west" {
  provider = aws
  vpc_id   = aws_vpc.us_west.id

  tags = merge(local.geo_tags_us_west, { Name = "eb-us-west-igw" })
}

resource "aws_subnet" "us_west_a" {
  provider                = aws
  vpc_id                  = aws_vpc.us_west.id
  cidr_block              = "10.10.0.0/20"
  availability_zone       = data.aws_availability_zones.us_west.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.geo_tags_us_west, { Name = "eb-us-west-public-a", Tier = "public" })
}

resource "aws_subnet" "us_west_b" {
  provider                = aws
  vpc_id                  = aws_vpc.us_west.id
  cidr_block              = "10.10.16.0/20"
  availability_zone       = data.aws_availability_zones.us_west.names[1]
  map_public_ip_on_launch = true

  tags = merge(local.geo_tags_us_west, { Name = "eb-us-west-public-b", Tier = "public" })
}

resource "aws_route_table" "us_west" {
  provider = aws
  vpc_id   = aws_vpc.us_west.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.us_west.id
  }

  tags = merge(local.geo_tags_us_west, { Name = "eb-us-west-public-rt" })
}

resource "aws_route_table_association" "us_west_a" {
  provider       = aws
  subnet_id      = aws_subnet.us_west_a.id
  route_table_id = aws_route_table.us_west.id
}

resource "aws_route_table_association" "us_west_b" {
  provider       = aws
  subnet_id      = aws_subnet.us_west_b.id
  route_table_id = aws_route_table.us_west.id
}

resource "aws_security_group" "us_west" {
  provider    = aws
  name        = "eb-us-west-web-sg"
  description = "Public web tier security group for the us-west Elastic Beanstalk environment"
  vpc_id      = aws_vpc.us_west.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "All outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.geo_tags_us_west, { Name = "eb-us-west-web-sg" })
}

