###############################################################################
# IAM (global resources, default provider)
###############################################################################

resource "aws_iam_role" "eb_service_role" {
  name        = "eb-geo-elasticbeanstalk-service-role"
  description = "Elastic Beanstalk service role for the geolocation-routed environments"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowElasticBeanstalkToAssumeRole"
        Effect    = "Allow"
        Principal = { Service = "elasticbeanstalk.amazonaws.com" }
        Action    = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = "elasticbeanstalk"
          }
        }
      }
    ]
  })

  tags = merge(local.geo_tags_global, { Name = "eb-geo-elasticbeanstalk-service-role" })
}

resource "aws_iam_role_policy_attachment" "eb_service_enhanced_health" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AWSElasticBeanstalkEnhancedHealth"
}

resource "aws_iam_role_policy_attachment" "eb_service_managed_updates" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AWSElasticBeanstalkManagedUpdatesCustomerRolePolicy"
}

resource "aws_iam_role" "eb_ec2_role" {
  name        = "eb-geo-ec2-role"
  description = "EC2 instance role for instances in the geolocation-routed environments"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowEc2ToAssumeRole"
        Effect    = "Allow"
        Principal = { Service = "ec2.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.geo_tags_global, { Name = "eb-geo-ec2-role" })
}

resource "aws_iam_role_policy_attachment" "eb_ec2_web_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_worker_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_enhanced_health" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AWSElasticBeanstalkEnhancedHealth"
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb-geo-ec2-instance-profile"
  role = aws_iam_role.eb_ec2_role.name

  tags = merge(local.geo_tags_global, { Name = "eb-geo-ec2-instance-profile" })
}

###############################################################################
# Application source bundles (S3, per region)
###############################################################################

data "archive_file" "us_west_app_bundle" {
  type        = "zip"
  output_path = "${path.module}/build/us-west-app-bundle.zip"

  source {
    content  = local.us_west_wsgi_app
    filename = "application.py"
  }

  source {
    content  = local.wsgi_requirements
    filename = "requirements.txt"
  }
}

data "archive_file" "eu_central_app_bundle" {
  type        = "zip"
  output_path = "${path.module}/build/eu-central-app-bundle.zip"

  source {
    content  = local.eu_central_wsgi_app
    filename = "application.py"
  }

  source {
    content  = local.wsgi_requirements
    filename = "requirements.txt"
  }
}

resource "aws_s3_bucket" "us_west_app" {
  provider = aws
  bucket   = "elasticbeanstalk-${local.us_west_region}-${data.aws_caller_identity.current.account_id}-geo-app"

  tags = merge(local.geo_tags_us_west, { Name = "eb-us-west-app-bundles" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "us_west_app" {
  provider = aws
  bucket   = aws_s3_bucket.us_west_app.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "us_west_app" {
  provider = aws
  bucket   = aws_s3_bucket.us_west_app.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "us_west_app" {
  provider = aws
  bucket   = aws_s3_bucket.us_west_app.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "us_west_app" {
  provider = aws
  bucket   = aws_s3_bucket.us_west_app.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "ElasticBeanstalkServiceRoleListBucket"
        Effect    = "Allow"
        Principal = { AWS = aws_iam_role.eb_service_role.arn }
        Action    = ["s3:ListBucket", "s3:GetBucketLocation"]
        Resource  = aws_s3_bucket.us_west_app.arn
      },
      {
        Sid       = "ElasticBeanstalkServiceRoleGetObjects"
        Effect    = "Allow"
        Principal = { AWS = aws_iam_role.eb_service_role.arn }
        Action    = ["s3:GetObject", "s3:GetObjectVersion"]
        Resource  = "${aws_s3_bucket.us_west_app.arn}/*"
      },
      {
        Sid       = "ElasticBeanstalkInstancesGetObjects"
        Effect    = "Allow"
        Principal = { AWS = aws_iam_role.eb_ec2_role.arn }
        Action    = ["s3:GetObject", "s3:GetObjectVersion"]
        Resource  = "${aws_s3_bucket.us_west_app.arn}/*"
      }
    ]
  })
}

resource "aws_s3_object" "us_west_bundle" {
  provider     = aws
  bucket       = aws_s3_bucket.us_west_app.id
  key          = "bundles/${local.us_west_app_version}.zip"
  source       = data.archive_file.us_west_app_bundle.output_path
  source_hash  = data.archive_file.us_west_app_bundle.output_base64sha256
  content_type = "application/zip"

  tags = merge(local.geo_tags_us_west, { Name = "eb-us-west-app-bundle" })
}

resource "aws_s3_bucket" "eu_central_app" {
  provider = aws.eu_central
  bucket   = "elasticbeanstalk-${local.eu_central_region}-${data.aws_caller_identity.current.account_id}-geo-app"

  tags = merge(local.geo_tags_eu_central, { Name = "eb-eu-central-app-bundles" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "eu_central_app" {
  provider = aws.eu_central
  bucket   = aws_s3_bucket.eu_central_app.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "eu_central_app" {
  provider = aws.eu_central
  bucket   = aws_s3_bucket.eu_central_app.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "eu_central_app" {
  provider = aws.eu_central
  bucket   = aws_s3_bucket.eu_central_app.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "eu_central_app" {
  provider = aws.eu_central
  bucket   = aws_s3_bucket.eu_central_app.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "ElasticBeanstalkServiceRoleListBucket"
        Effect    = "Allow"
        Principal = { AWS = aws_iam_role.eb_service_role.arn }
        Action    = ["s3:ListBucket", "s3:GetBucketLocation"]
        Resource  = aws_s3_bucket.eu_central_app.arn
      },
      {
        Sid       = "ElasticBeanstalkServiceRoleGetObjects"
        Effect    = "Allow"
        Principal = { AWS = aws_iam_role.eb_service_role.arn }
        Action    = ["s3:GetObject", "s3:GetObjectVersion"]
        Resource  = "${aws_s3_bucket.eu_central_app.arn}/*"
      },
      {
        Sid       = "ElasticBeanstalkInstancesGetObjects"
        Effect    = "Allow"
        Principal = { AWS = aws_iam_role.eb_ec2_role.arn }
        Action    = ["s3:GetObject", "s3:GetObjectVersion"]
        Resource  = "${aws_s3_bucket.eu_central_app.arn}/*"
      }
    ]
  })
}

resource "aws_s3_object" "eu_central_bundle" {
  provider     = aws.eu_central
  bucket       = aws_s3_bucket.eu_central_app.id
  key          = "bundles/${local.eu_central_app_version}.zip"
  source       = data.archive_file.eu_central_app_bundle.output_path
  source_hash  = data.archive_file.eu_central_app_bundle.output_base64sha256
  content_type = "application/zip"

  tags = merge(local.geo_tags_eu_central, { Name = "eb-eu-central-app-bundle" })
