###############################################################################
# Elastic Beanstalk applications, versions, environments
###############################################################################

resource "aws_elastic_beanstalk_application" "us_west" {
  provider    = aws
  name        = local.us_west_env_name
  description = "Geolocation-routed Elastic Beanstalk application in us-west-2"

  tags = merge(local.geo_tags_us_west, { Name = local.us_west_env_name })
}

resource "aws_elastic_beanstalk_application_version" "us_west" {
  provider    = aws
  name        = local.us_west_app_version
  application = aws_elastic_beanstalk_application.us_west.name
  bucket      = aws_s3_bucket.us_west_app.id
  key         = aws_s3_object.us_west_bundle.key

  tags = merge(local.geo_tags_us_west, { Name = local.us_west_app_version })
}

resource "aws_elastic_beanstalk_environment" "us_west" {
  provider               = aws
  name                   = local.us_west_env_name
  application            = aws_elastic_beanstalk_application.us_west.name
  cname_prefix           = local.us_west_env_name
  solution_stack_name    = var.solution_stack
  tier                   = "WebServer"
  version_label          = aws_elastic_beanstalk_application_version.us_west.name
  wait_for_ready_timeout = "45m"

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.us_west.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", [aws_subnet.us_west_a.id, aws_subnet.us_west_b.id])
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", [aws_subnet.us_west_a.id, aws_subnet.us_west_b.id])
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBScheme"
    value     = "public"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = var.instance_type
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.us_west.id
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.arn
  }

  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "4"
  }

  tags = merge(local.geo_tags_us_west, { Name = local.us_west_env_name })

  depends_on = [
    aws_iam_role_policy_attachment.eb_service_enhanced_health,
    aws_iam_role_policy_attachment.eb_service_managed_updates,
    aws_iam_role_policy_attachment.eb_ec2_web_tier,
    aws_iam_role_policy_attachment.eb_ec2_worker_tier,
    aws_iam_role_policy_attachment.eb_ec2_enhanced_health,
    aws_iam_instance_profile.eb_ec2_profile,
  ]

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_elastic_beanstalk_application" "eu_central" {
  provider    = aws.eu_central
  name        = local.eu_central_env_name
  description = "Geolocation-routed Elastic Beanstalk application in eu-central-1"

  tags = merge(local.geo_tags_eu_central, { Name = local.eu_central_env_name })
