###############################################################################
# Route53: hosted zone, health checks, geolocation records
###############################################################################

resource "aws_route53_zone" "main" {
  name    = var.domain_name
  comment = "Public hosted zone for geolocation-routed Elastic Beanstalk traffic"

  tags = merge(local.geo_tags_global, { Name = var.domain_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route53_health_check" "us_west" {
  fqdn              = aws_elastic_beanstalk_environment.us_west.cname
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  request_interval  = 30
  failure_threshold = 3

  tags = merge(local.geo_tags_us_west, { Name = "eb-us-west-health-check" })
}

resource "aws_route53_health_check" "eu_central" {
  fqdn              = aws_elastic_beanstalk_environment.eu_central.cname
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  request_interval  = 30
  failure_threshold = 3

  tags = merge(local.geo_tags_eu_central, { Name = "eb-eu-central-health-check" })
}

resource "aws_route53_record" "app_geo_na" {
  zone_id        = aws_route53_zone.main.zone_id
  name           = local.app_fqdn
  type           = "CNAME"
  ttl            = 60
  records        = [aws_elastic_beanstalk_environment.us_west.cname]
  set_identifier = "us-west-north-america"

  geolocation_routing_policy {
    continent = "NA"
  }

  health_check_id = aws_route53_health_check.us_west.id
}

resource "aws_route53_record" "app_geo_eu" {
  zone_id        = aws_route53_zone.main.zone_id
  name           = local.app_fqdn
  type           = "CNAME"
  ttl            = 60
  records        = [aws_elastic_beanstalk_environment.eu_central.cname]
  set_identifier = "eu-central-europe"

  geolocation_routing_policy {
    continent = "EU"
  }

  health_check_id = aws_route53_health_check.eu_central.id
}

resource "aws_route53_record" "app_geo_default" {
  zone_id        = aws_route53_zone.main.zone_id
  name           = local.app_fqdn
  type           = "CNAME"
  ttl            = 60
  records        = [aws_elastic_beanstalk_environment.us_west.cname]
  set_identifier = "rest-of-world-default"

  geolocation_routing_policy {
    country = "*"
  }
}

###############################################################################
# Outputs
###############################################################################

output "us_west_environment_id" {
  description = "ID of the us-west Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.us_west.id
}

output "us_west_environment_name" {
  description = "Name of the us-west Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.us_west.name
}

output "us_west_environment_cname" {
  description = "CNAME endpoint of the us-west Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.us_west.cname
}

output "eu_central_environment_id" {
  description = "ID of the eu-central Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.eu_central.id
}

output "eu_central_environment_name" {
  description = "Name of the eu-central Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.eu_central.name
}

output "eu_central_environment_cname" {
  description = "CNAME endpoint of the eu-central Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.eu_central.cname
}

output "geo_routed_endpoint_fqdn" {
  description = "Fully-qualified domain name served via Route53 geolocation routing."
  value       = local.app_fqdn
}

output "hosted_zone_name_servers" {
  description = "Name servers of the public Route53 hosted zone."
  value       = aws_route53_zone.main.name_servers
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

# Static, well-known provider metadata used for AZ placement.
data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  db_name             = "my_db1"
  db_master_username  = "dbadmin"
  public_subnet_ids   = [aws_subnet.public_1.id, aws_subnet.public_2.id]
  database_subnet_ids = [aws_subnet.database_1.id, aws_subnet.database_2.id]
}

# -----------------------------------------------------------------------------
# Networking
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "eb-rds-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "eb-internet-gateway"
  }
}

# Public subnets for the Beanstalk EC2 instances and the environment ALB.
resource "aws_subnet" "public_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "eb-public-subnet-1"
  }
}

resource "aws_subnet" "public_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = {
    Name = "eb-public-subnet-2"
  }
}

# Dedicated, isolated subnets for the RDS instance (no internet route).
resource "aws_subnet" "database_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.11.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "eb-database-subnet-1"
  }
}

resource "aws_subnet" "database_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.12.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "eb-database-subnet-2"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "eb-public-route-table"
  }
}

resource "aws_route_table_association" "public_1" {
  subnet_id      = aws_subnet.public_1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_2" {
  subnet_id      = aws_subnet.public_2.id
  route_table_id = aws_route_table.public.id
}

# Route table for the database subnets: local VPC traffic only, no public route.
resource "aws_route_table" "database" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "eb-database-route-table"
  }
}

resource "aws_route_table_association" "database_1" {
  subnet_id      = aws_subnet.database_1.id
  route_table_id = aws_route_table.database.id
}

resource "aws_route_table_association" "database_2" {
  subnet_id      = aws_subnet.database_2.id
  route_table_id = aws_route_table.database.id
}

# -----------------------------------------------------------------------------
# Security groups
# -----------------------------------------------------------------------------
resource "aws_security_group" "beanstalk_alb" {
  name        = "eb-alb-sg"
  description = "Elastic Beanstalk environment ALB: ingress restricted to HTTP/HTTPS from the internet"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from the internet"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from the internet"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow outbound traffic to the application instances"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "eb-alb-sg"
  }
}

resource "aws_security_group" "beanstalk_ec2" {
  name        = "eb-ec2-sg"
  description = "Elastic Beanstalk EC2 instances: application port open only to the environment ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Application traffic from the environment ALB only"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.beanstalk_alb.id]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "eb-ec2-sg"
  }
}

resource "aws_security_group" "rds" {
  name        = "eb-rds-sg"
  description = "my_db1 RDS instance: database port open only to the Beanstalk EC2 instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "PostgreSQL access from the Beanstalk EC2 instances only"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.beanstalk_ec2.id]
  }

  tags = {
    Name = "eb-rds-sg"
  }
}

# -----------------------------------------------------------------------------
# IAM: EC2 instance role and instance profile
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eb_ec2_role" {
  name               = "eb-ec2-role"
  description        = "EC2 instance role for the Elastic Beanstalk environment"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = {
    Name = "eb-ec2-role"
  }
}

resource "aws_iam_role_policy_attachment" "eb_ec2_web_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_worker_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_multicontainer_docker" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name

  tags = {
    Name = "eb_ec2_profile"
  }
}

# -----------------------------------------------------------------------------
# IAM: Elastic Beanstalk service role
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "eb_service_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["beanstalk.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eb_service_role" {
  name               = "eb-service-role"
  description        = "Service role assumed by Elastic Beanstalk to manage the environment"
  assume_role_policy = data.aws_iam_policy_document.eb_service_assume_role.json

  tags = {
    Name = "eb-service-role"
  }
}

resource "aws_iam_role_policy_attachment" "eb_service_enhanced_health" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkEnhancedHealth"
}

resource "aws_iam_role_policy_attachment" "eb_service_managed_updates" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkManagedUpdatesCustomerRolePolicy"
}

# -----------------------------------------------------------------------------
# Elastic Beanstalk application
# -----------------------------------------------------------------------------
resource "aws_elastic_beanstalk_application" "app" {
  name        = "my-eb-app"
  description = "Elastic Beanstalk application connected to the my_db1 RDS instance"

  tags = {
    Name = "my-eb-app"
  }
}

# -----------------------------------------------------------------------------
# RDS: subnet group, generated credentials, and instance
# -----------------------------------------------------------------------------
resource "aws_db_subnet_group" "my_db1" {
  name        = "my-db1-subnet-group"
  description = "Database subnets for the my_db1 RDS instance"
  subnet_ids  = local.database_subnet_ids

  tags = {
    Name = "my-db1-subnet-group"
  }
}

resource "random_password" "db_master" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+"
}

resource "aws_secretsmanager_secret" "db_master" {
  name        = "my-db1-master-credentials"
  description = "Master credentials for the my_db1 RDS instance"

  tags = {
    Name = "my-db1-master-credentials"
  }
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    username = local.db_master_username
    password = random_password.db_master.result
  })
}

resource "aws_db_instance" "my_db1" {
  identifier                 = "my-db1"
  db_name                    = local.db_name
  engine                     = "postgres"
  engine_version             = "16.6"
  instance_class             = "db.t3.micro"
  allocated_storage          = 20
  storage_type               = "gp3"
  port                       = 5432
  username                   = local.db_master_username
  password                   = random_password.db_master.result
  db_subnet_group_name       = aws_db_subnet_group.my_db1.name
  vpc_security_group_ids     = [aws_security_group.rds.id]
  publicly_accessible        = false
  storage_encrypted          = true
  multi_az                   = false
  auto_minor_version_upgrade = false
  backup_retention_period    = 7
  deletion_protection        = true
  skip_final_snapshot        = true
  copy_tags_to_snapshot      = true

  tags = {
    Name = "my_db1"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Elastic Beanstalk environment (WebServer tier) wired to the VPC and RDS
# -----------------------------------------------------------------------------
resource "aws_elastic_beanstalk_environment" "env" {
  name                   = "my-eb-env"
  application            = aws_elastic_beanstalk_application.app.name
  solution_stack_name    = "64bit Amazon Linux 2023 v6.3.1 running Python 3.12"
  tier                   = "WebServer"
  wait_for_ready_timeout = "30m"

  # VPC wiring for the EC2 instances and the environment ALB.
  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", local.public_subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", local.public_subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBScheme"
    value     = "public"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "LoadBalancerType"
    value     = "application"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.arn
  }

  # Attach the locked-down security group to the environment ALB.
  setting {
    namespace = "aws:elbv2:loadbalancer"
    name      = "SecurityGroups"
    value     = aws_security_group.beanstalk_alb.id
  }

  # EC2 instance configuration: instance profile, size, and security group.
  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = "t3.small"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.beanstalk_ec2.id
  }

  # Enhanced health reporting.
  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  # Auto Scaling capacity.
  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "4"
  }

  # Auto Scaling trigger on average CPU utilization.
  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "MeasureName"
    value     = "CPUUtilization"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "Statistic"
    value     = "Average"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "Unit"
    value     = "Percent"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "UpperThreshold"
    value     = "70"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "LowerThreshold"
    value     = "30"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "UpperBreachScaleIncrement"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "LowerBreachScaleIncrement"
    value     = "-1"
  }

  # Rolling deployments based on health.
  setting {
    namespace = "aws:autoscaling:updatepolicy:rollingupdate"
    name      = "RollingUpdateEnabled"
    value     = "true"
  }

  setting {
    namespace = "aws:autoscaling:updatepolicy:rollingupdate"
    name      = "RollingUpdateType"
    value     = "Health"
  }

  # Database connectivity injected into the application environment.
  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_HOSTNAME"
    value     = aws_db_instance.my_db1.address
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PORT"
    value     = tostring(aws_db_instance.my_db1.port)
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_DB_NAME"
    value     = aws_db_instance.my_db1.db_name
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_USERNAME"
    value     = aws_db_instance.my_db1.username
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PASSWORD"
    value     = random_password.db_master.result
  }

  tags = {
    Name = "my-eb-env"
  }

  depends_on = [
    aws_iam_role_policy_attachment.eb_ec2_web_tier,
    aws_iam_role_policy_attachment.eb_ec2_worker_tier,
    aws_iam_role_policy_attachment.eb_ec2_multicontainer_docker,
    aws_iam_role_policy_attachment.eb_service_enhanced_health,
    aws_iam_role_policy_attachment.eb_service_managed_updates,
  ]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "beanstalk_environment_url" {
  description = "Public URL (CNAME) of the Elastic Beanstalk environment"
  value       = aws_elastic_beanstalk_environment.env.cname
}

output "rds_endpoint_address" {
  description = "Connection endpoint address of the my_db1 RDS instance"
  value       = aws_db_instance.my_db1.address
}

output "rds_endpoint_port" {
  description = "Connection endpoint port of the my_db1 RDS instance"
  value       = aws_db_instance.my_db1.port
}

output "db_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the my_db1 master credentials"
  value       = aws_secretsmanager_secret.db_master.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "domain_name" {
  description = "Root domain name for the public Route 53 hosted zone."
  type        = string
  default     = "example.com"

  validation {
    condition     = can(regex("^([a-z0-9]([a-z0-9-]*[a-z0-9])?\\.)+[a-z]{2,}$", var.domain_name))
    error_message = "domain_name must be a valid domain name, e.g. example.com."
  }
}

variable "ipv6_address" {
  description = "IPv6 address that the AAAA record maps the domain name to."
  type        = string
  default     = "2001:db8::1"

  validation {
    condition     = can(cidrhost("${var.ipv6_address}/128", 0))
    error_message = "ipv6_address must be a single valid IPv6 address, e.g. 2001:db8::1."
  }
}

variable "environment" {
  description = "Environment name applied as a tag for traceability."
  type        = string
  default     = "production"
}

locals {
  zone_name = lower(var.domain_name)
}

resource "aws_route53_zone" "main" {
  name = local.zone_name

  tags = {
    Name        = local.zone_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route53_record" "ipv6_aaaa" {
  zone_id = aws_route53_zone.main.zone_id
  name    = local.zone_name
  type    = "AAAA"
  ttl     = 300
  records = [var.ipv6_address]
}

output "hosted_zone_id" {
  description = "ID of the public hosted zone."
  value       = aws_route53_zone.main.zone_id
}

output "hosted_zone_name_servers" {
  description = "Name servers to delegate the domain to at the registrar."
  value       = aws_route53_zone.main.name_servers
}

output "ipv6_record_fqdn" {
  description = "Fully qualified domain name of the AAAA record."
  value       = aws_route53_record.ipv6_aaaa.fqdn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "eu-west-1"
  region = "eu-west-1"
}

########################################################################
# Variables / locals
########################################################################

variable "domain_name" {
  description = "Public domain managed by the Route 53 hosted zone (e.g. example.com)."
  type        = string
  default     = "example.com"
}

locals {
  solution_stack = "64bit Amazon Linux 2023 running Python 3.12"
  db_username    = "dbadmin"
  db_name        = "maindb"
  db_port        = 5432
  instance_type  = "t3.small"
}

########################################################################
# Availability zone discovery (static provider metadata only)
########################################################################

data "aws_availability_zones" "us" {
  provider = aws
  state    = "available"
}

data "aws_availability_zones" "eu_west" {
  provider = aws.eu-west-1
  state    = "available"
}

########################################################################
# Shared IAM (global service): EC2 instance profile + EB service role
########################################################################

data "aws_iam_policy_document" "eb_ec2_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "eb_service_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["elasticbeanstalk.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eb_ec2_role" {
  name               = "eb_ec2_role"
  description        = "Elastic Beanstalk EC2 instance role (shared by both regional environments)"
  assume_role_policy = data.aws_iam_policy_document.eb_ec2_trust.json
}

resource "aws_iam_role_policy_attachment" "eb_ec2_web_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_worker_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_multicontainer_docker" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
}

resource "aws_iam_instance_profile" "eb_ec2_profile3" {
  name = "eb_ec2_profile3"
  role = aws_iam_role.eb_ec2_role.name
}

resource "aws_iam_role" "eb_service_role" {
  name               = "eb_service_role"
  description        = "Elastic Beanstalk service role (enhanced health, managed updates)"
  assume_role_policy = data.aws_iam_policy_document.eb_service_trust.json
}

resource "aws_iam_role_policy_attachment" "eb_service_enhanced_health" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSElasticBeanstalkEnhancedHealth"
}

resource "aws_iam_role_policy_attachment" "eb_service_managed_updates" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkManagedUpdatesCustomerRolePolicy"
}

########################################################################
# Network foundation - us-east-1 (default provider)
########################################################################

resource "aws_vpc" "us" {
  provider             = aws
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = { Name = "myapp-us-east-vpc" }
}

resource "aws_internet_gateway" "us" {
  provider = aws
  vpc_id   = aws_vpc.us.id

  tags = { Name = "myapp-us-east-igw" }
}

resource "aws_subnet" "public_us_1" {
  provider                = aws
  vpc_id                  = aws_vpc.us.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.us.names[0]
  map_public_ip_on_launch = true

  tags = { Name = "myapp-us-east-public-a" }
}

resource "aws_subnet" "public_us_2" {
  provider                = aws
  vpc_id                  = aws_vpc.us.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.us.names[1]
  map_public_ip_on_launch = true

  tags = { Name = "myapp-us-east-public-b" }
}

resource "aws_subnet" "private_db_us_1" {
  provider          = aws
  vpc_id            = aws_vpc.us.id
  cidr_block        = "10.0.11.0/24"
  availability_zone = data.aws_availability_zones.us.names[0]

  tags = { Name = "myapp-us-east-private-db-a" }
}

resource "aws_subnet" "private_db_us_2" {
  provider          = aws
  vpc_id            = aws_vpc.us.id
  cidr_block        = "10.0.12.0/24"
  availability_zone = data.aws_availability_zones.us.names[1]

  tags = { Name = "myapp-us-east-private-db-b" }
}

resource "aws_route_table" "public_us" {
  provider = aws
  vpc_id   = aws_vpc.us.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.us.id
  }

  tags = { Name = "myapp-us-east-public-rt" }
}

resource "aws_route_table_association" "public_us_1" {
  provider       = aws
  subnet_id      = aws_subnet.public_us_1.id
  route_table_id = aws_route_table.public_us.id
}

resource "aws_route_table_association" "public_us_2" {
  provider       = aws
  subnet_id      = aws_subnet.public_us_2.id
  route_table_id = aws_route_table.public_us.id
}

# Isolated route table for the private database subnets (no internet routes).
resource "aws_route_table" "private_db_us" {
  provider = aws
  vpc_id   = aws_vpc.us.id

  tags = { Name = "myapp-us-east-private-db-rt" }
}

resource "aws_route_table_association" "private_db_us_1" {
  provider       = aws
  subnet_id      = aws_subnet.private_db_us_1.id
  route_table_id = aws_route_table.private_db_us.id
}

resource "aws_route_table_association" "private_db_us_2" {
  provider       = aws
  subnet_id      = aws_subnet.private_db_us_2.id
  route_table_id = aws_route_table.private_db_us.id
}

