########################################################################
# Security groups - us-east-1
########################################################################

resource "aws_security_group" "eb_instance_us" {
  provider    = aws
  name        = "myapp-eb-instance-us-east"
  description = "Elastic Beanstalk EC2 instances (us-east-1): web ports only"
  vpc_id      = aws_vpc.us.id

  ingress {
    description = "HTTP from anywhere (web tier)"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere (web tier)"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "All outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = { Name = "myapp-eb-instance-us-east" }
}

resource "aws_security_group" "rds_us" {
  provider    = aws
  name        = "myapp-rds-us-east"
  description = "RDS PostgreSQL (us-east-1): reachable only from Beanstalk instances"
  vpc_id      = aws_vpc.us.id

  ingress {
    description     = "PostgreSQL from Beanstalk instances only"
    from_port       = local.db_port
    to_port         = local.db_port
    protocol        = "tcp"
    security_groups = [aws_security_group.eb_instance_us.id]
  }

  tags = { Name = "myapp-rds-us-east" }
}

