########################################################################
# Database credentials in Secrets Manager (no plaintext passwords)
########################################################################

resource "random_password" "db_us" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+"
}

resource "aws_secretsmanager_secret" "db_us" {
  provider                = aws
  name                    = "myapp/rds/main_db_us_east"
  description             = "Master credentials for main_db_us_east (us-east-1)"
  recovery_window_in_days = 0

  tags = { Name = "myapp-rds-main_db_us_east" }
}

resource "aws_secretsmanager_secret_version" "db_us" {
  provider  = aws
  secret_id = aws_secretsmanager_secret.db_us.arn

  secret_string = jsonencode({
    username = aws_db_instance.main_db_us_east.username
    password = random_password.db_us.result
    engine   = "postgres"
    host     = aws_db_instance.main_db_us_east.address
    port     = aws_db_instance.main_db_us_east.port
    dbname   = aws_db_instance.main_db_us_east.db_name
  })
}

resource "random_password" "db_eu_west" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+"
}

resource "aws_secretsmanager_secret" "db_eu_west" {
  provider                = aws.eu-west-1
  name                    = "myapp/rds/main_db_eu_west"
  description             = "Master credentials for main_db_eu_west (eu-west-1)"
  recovery_window_in_days = 0

  tags = { Name = "myapp-rds-main_db_eu_west" }
}

resource "aws_secretsmanager_secret_version" "db_eu_west" {
  provider  = aws.eu-west-1
  secret_id = aws_secretsmanager_secret.db_eu_west.arn

  secret_string = jsonencode({
    username = aws_db_instance.main_db_eu_west.username
    password = random_password.db_eu_west.result
    engine   = "postgres"
    host     = aws_db_instance.main_db_eu_west.address
    port     = aws_db_instance.main_db_eu_west.port
    dbname   = aws_db_instance.main_db_eu_west.db_name
  })
}

########################################################################
# DB subnet groups (each spans two AZs using private subnets)
########################################################################

resource "aws_db_subnet_group" "db_us" {
  provider    = aws
  name        = "main-db-subnet-group-us-east"
  description = "Private subnets for main_db_us_east"
  subnet_ids  = [aws_subnet.private_db_us_1.id, aws_subnet.private_db_us_2.id]

  tags = { Name = "main-db-subnet-group-us-east" }
}

resource "aws_db_subnet_group" "db_eu_west" {
  provider    = aws.eu-west-1
  name        = "main-db-subnet-group-eu-west"
  description = "Private subnets for main_db_eu_west"
  subnet_ids  = [aws_subnet.private_db_eu_1.id, aws_subnet.private_db_eu_2.id]

  tags = { Name = "main-db-subnet-group-eu-west" }
}

########################################################################
# RDS PostgreSQL instances
########################################################################

resource "aws_db_instance" "main_db_us_east" {
  provider                   = aws
  identifier                 = "main-db-us-east"
  engine                     = "postgres"
  instance_class             = "db.t3.small"
  allocated_storage          = 20
  storage_type               = "gp3"
  max_allocated_storage      = 100
  storage_encrypted          = true
  db_name                    = local.db_name
  username                   = local.db_username
  password                   = random_password.db_us.result
  port                       = local.db_port
  db_subnet_group_name       = aws_db_subnet_group.db_us.name
  vpc_security_group_ids     = [aws_security_group.rds_us.id]
  publicly_accessible        = false
  multi_az                   = false
  backup_retention_period    = 7
  deletion_protection        = true
  copy_tags_to_snapshot      = true
  auto_minor_version_upgrade = true
  skip_final_snapshot        = true

  tags = {
    Name   = "main_db_us_east"
    Region = "us-east-1"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_db_instance" "main_db_eu_west" {
  provider                   = aws.eu-west-1
  identifier                 = "main-db-eu-west"
  engine                     = "postgres"
  instance_class             = "db.t3.small"
  allocated_storage          = 20
  storage_type               = "gp3"
  max_allocated_storage      = 100
  storage_encrypted          = true
  db_name                    = local.db_name
  username                   = local.db_username
  password                   = random_password.db_eu_west.result
  port                       = local.db_port
  db_subnet_group_name       = aws_db_subnet_group.db_eu_west.name
  vpc_security_group_ids     = [aws_security_group.rds_eu.id]
  publicly_accessible        = false
  multi_az                   = false
  backup_retention_period    = 7
  deletion_protection        = true
  copy_tags_to_snapshot      = true
  auto_minor_version_upgrade = true
  skip_final_snapshot        = true

  tags = {
    Name   = "main_db_eu_west"
    Region = "eu-west-1"
  }

  lifecycle {
    prevent_destroy = true
  }
}

########################################################################
# Elastic Beanstalk applications
########################################################################

resource "aws_elastic_beanstalk_application" "myapp_us_east" {
  provider    = aws
  name        = "myapp_us_east"
  description = "Multi-region application - us-east-1"
}

resource "aws_elastic_beanstalk_application" "myapp_eu_west" {
  provider    = aws.eu-west-1
  name        = "myapp_eu_west"
  description = "Multi-region application - eu-west-1"
}

########################################################################
# Elastic Beanstalk environments
########################################################################

resource "aws_elastic_beanstalk_environment" "myenv_us_east" {
  provider            = aws
  name                = "myenv_us_east"
  application         = aws_elastic_beanstalk_application.myapp_us_east.name
  description         = "Web environment (us-east-1)"
  solution_stack_name = local.solution_stack
  tier                = "WebServer"

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "LoadBalancerType"
    value     = "application"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.arn
  }

  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile3.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "EC2SecurityGroups"
    value     = aws_security_group.eb_instance_us.id
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = local.instance_type
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "2"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "4"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.us.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", [aws_subnet.public_us_1.id, aws_subnet.public_us_2.id])
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", [aws_subnet.public_us_1.id, aws_subnet.public_us_2.id])
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_HOSTNAME"
    value     = aws_db_instance.main_db_us_east.address
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PORT"
    value     = tostring(aws_db_instance.main_db_us_east.port)
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_DB_NAME"
    value     = aws_db_instance.main_db_us_east.db_name
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_USERNAME"
    value     = aws_db_instance.main_db_us_east.username
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_SECRET_ARN"
    value     = aws_secretsmanager_secret.db_us.arn
  }

  depends_on = [
    aws_iam_role_policy_attachment.eb_ec2_web_tier,
    aws_iam_role_policy_attachment.eb_ec2_worker_tier,
    aws_iam_role_policy_attachment.eb_ec2_multicontainer_docker,
    aws_iam_role_policy_attachment.eb_service_enhanced_health,
    aws_iam_role_policy_attachment.eb_service_managed_updates,
    aws_secretsmanager_secret_version.db_us,
  ]
}

resource "aws_elastic_beanstalk_environment" "myenv_eu_west" {
  provider            = aws.eu-west-1
  name                = "myenv_eu_west"
  application         = aws_elastic_beanstalk_application.myapp_eu_west.name
  description         = "Web environment (eu-west-1)"
  solution_stack_name = local.solution_stack
  tier                = "WebServer"

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "LoadBalancerType"
    value     = "application"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.arn
  }

  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile3.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "EC2SecurityGroups"
    value     = aws_security_group.eb_instance_eu.id
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = local.instance_type
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "2"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "4"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.eu.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", [aws_subnet.public_eu_1.id, aws_subnet.public_eu_2.id])
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", [aws_subnet.public_eu_1.id, aws_subnet.public_eu_2.id])
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_HOSTNAME"
    value     = aws_db_instance.main_db_eu_west.address
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PORT"
    value     = tostring(aws_db_instance.main_db_eu_west.port)
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_DB_NAME"
    value     = aws_db_instance.main_db_eu_west.db_name
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_USERNAME"
    value     = aws_db_instance.main_db_eu_west.username
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_SECRET_ARN"
    value     = aws_secretsmanager_secret.db_eu_west.arn
  }

  depends_on = [
    aws_iam_role_policy_attachment.eb_ec2_web_tier,
    aws_iam_role_policy_attachment.eb_ec2_worker_tier,
    aws_iam_role_policy_attachment.eb_ec2_multicontainer_docker,
    aws_iam_role_policy_attachment.eb_service_enhanced_health,
    aws_iam_role_policy_attachment.eb_service_managed_updates,
    aws_secretsmanager_secret_version.db_eu_west,
  ]
}

########################################################################
# Route 53: hosted zone, health checks, regional routing records
########################################################################

resource "aws_route53_zone" "main" {
  name = var.domain_name

  tags = {
    Name = "${var.domain_name}-zone"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route53_health_check" "us_east" {
  fqdn              = aws_elastic_beanstalk_environment.myenv_us_east.cname
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  request_interval  = 30
  failure_threshold = 3
  measure_latency   = true

  tags = {
    Name = "myapp-us-east-health-check"
  }
}

resource "aws_route53_health_check" "eu_west" {
  fqdn              = aws_elastic_beanstalk_environment.myenv_eu_west.cname
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  request_interval  = 30
  failure_threshold = 3
  measure_latency   = true

  tags = {
    Name = "myapp-eu-west-health-check"
  }
}

resource "aws_route53_record" "us_east" {
  zone_id         = aws_route53_zone.main.zone_id
  name            = "us-east-1.${var.domain_name}"
  type            = "CNAME"
  ttl             = 60
  records         = [aws_elastic_beanstalk_environment.myenv_us_east.cname]
  set_identifier  = "us-east-1"
  health_check_id = aws_route53_health_check.us_east.id

  failover_routing_policy {
    type = "PRIMARY"
  }
}

resource "aws_route53_record" "eu_west" {
  zone_id         = aws_route53_zone.main.zone_id
  name            = "eu-west-1.${var.domain_name}"
  type            = "CNAME"
  ttl             = 60
  records         = [aws_elastic_beanstalk_environment.myenv_eu_west.cname]
  set_identifier  = "eu-west-1"
  health_check_id = aws_route53_health_check.eu_west.id

  failover_routing_policy {
    type = "SECONDARY"
  }
}

########################################################################
# Outputs
########################################################################

output "hosted_zone_id" {
  description = "Route 53 hosted zone ID."
  value       = aws_route53_zone.main.zone_id
}

output "hosted_zone_name_servers" {
  description = "Name servers for the Route 53 hosted zone."
  value       = aws_route53_zone.main.name_servers
}

output "us_east_environment_cname" {
  description = "Public CNAME of the myenv_us_east Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.myenv_us_east.cname
}

output "eu_west_environment_cname" {
  description = "Public CNAME of the myenv_eu_west Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.myenv_eu_west.cname
}

output "us_east_rds_endpoint" {
  description = "Connection endpoint of main_db_us_east."
  value       = aws_db_instance.main_db_us_east.endpoint
}

output "eu_west_rds_endpoint" {
  description = "Connection endpoint of main_db_eu_west."
  value       = aws_db_instance.main_db_eu_west.endpoint
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables (all have safe defaults so apply runs unattended)
# -----------------------------------------------------------------------------

variable "application_name" {
  description = "Descriptive name of the Elastic Beanstalk application."
  type        = string
  default     = "go-sample-app"
}

variable "environment_name" {
  description = "Name of the Elastic Beanstalk environment."
  type        = string
  default     = "go-sample-env"
}

variable "cname_prefix" {
  description = "Unique CNAME prefix for the environment's public endpoint."
  type        = string
  default     = "go-sample-app-env"
}

variable "instance_type" {
  description = "EC2 instance type used by the environment's Auto Scaling group."
  type        = string
  default     = "t3.small"
}

variable "solution_stack_name" {
  description = "Pinned Elastic Beanstalk Go platform (public AWS platform identifier; re-pin when AWS retires this build)."
  type        = string
  default     = "64bit Amazon Linux 2023 v4.2.0 running Go 1.23"
}

variable "tags" {
  description = "Default tags applied to every managed resource."
  type        = map(string)
  default = {
    Name        = "go-sample-app"
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Static provider metadata lookups
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

locals {
  go_source_file  = "${path.module}/main.go"
  go_bundle_path  = "${path.module}/go-app.zip"
  go_bundle_key   = "bundles/go-app-${substr(data.archive_file.go_app_bundle.output_md5, 0, 16)}.zip"
  go_version_name = "go-app-${substr(data.archive_file.go_app_bundle.output_md5, 0, 16)}"
  version_bucket  = "go-sample-app-eb-versions-${data.aws_caller_identity.current.account_id}"
}

# -----------------------------------------------------------------------------
# Self-contained sample Go application (packaged locally, no external artifacts)
# -----------------------------------------------------------------------------

resource "local_file" "go_main" {
  filename        = local.go_source_file
  file_permission = "0644"

  content = <<-EOT
    package main

    import (
        "fmt"
        "log"
        "net/http"
        "os"
        "time"
    )

    func main() {
        port := os.Getenv("PORT")
        if port == "" {
            port = "8080"
        }

        mux := http.NewServeMux()

        mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
            w.WriteHeader(http.StatusOK)
            fmt.Fprintf(w, "Hello from the Terraform-managed Go app on Elastic Beanstalk! Time: %s\\n", time.Now().UTC().Format(time.RFC3339))
        })

        mux.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
            w.WriteHeader(http.StatusOK)
            fmt.Fprintln(w, "OK")
        })

        log.Printf("Go sample application listening on port %s", port)
        log.Fatal(http.ListenAndServe(":"+port, mux))
    }
  EOT
}

data "archive_file" "go_app_bundle" {
  type        = "zip"
  source_file = local.go_source_file
  output_path = local.go_bundle_path

  # Ensure the source file is written to disk before the bundle is built.
  depends_on = [local_file.go_main]
}

# -----------------------------------------------------------------------------
# Private, stateful S3 bucket for Elastic Beanstalk application versions
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "eb_app_versions" {
  bucket = local.version_bucket

  tags = merge(
    var.tags,
    {
      Name = "go-sample-app-eb-versions"
    },
  )

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "eb_app_versions" {
  bucket = aws_s3_bucket.eb_app_versions.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "eb_app_versions" {
  bucket = aws_s3_bucket.eb_app_versions.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "eb_app_versions" {
  bucket = aws_s3_bucket.eb_app_versions.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "eb_app_versions" {
  bucket = aws_s3_bucket.eb_app_versions.id

  rule {
    id     = "expire-noncurrent-versions"
    status = "Enabled"

    filter {}

    noncurrent_version_expiration {
      noncurrent_days = 90
    }
  }
}

data "aws_iam_policy_document" "eb_app_versions_tls" {
  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.eb_app_versions.arn,
      "${aws_s3_bucket.eb_app_versions.arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "eb_app_versions" {
  bucket = aws_s3_bucket.eb_app_versions.id
  policy = data.aws_iam_policy_document.eb_app_versions_tls.json
}

resource "aws_s3_object" "go_app_bundle" {
  bucket = aws_s3_bucket.eb_app_versions.id
  key    = local.go_bundle_key
  source = data.archive_file.go_app_bundle.output_path
  etag   = data.archive_file.go_app_bundle.output_md5
}

# -----------------------------------------------------------------------------
# Greenfield networking
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    var.tags,
    {
      Name = "go-sample-app-vpc"
    },
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    var.tags,
    {
      Name = "go-sample-app-igw"
    },
  )
}

resource "aws_subnet" "app_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(
    var.tags,
    {
      Name = "go-sample-app-a"
    },
  )
}

resource "aws_subnet" "app_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = merge(
    var.tags,
    {
      Name = "go-sample-app-b"
    },
  )
}

resource "aws_subnet" "public_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.101.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(
    var.tags,
    {
      Name = "go-sample-elb-a"
    },
  )
}

resource "aws_subnet" "public_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.102.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(
    var.tags,
    {
      Name = "go-sample-elb-b"
    },
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    var.tags,
    {
      Name = "go-sample-app-public-rt"
    },
  )
}

resource "aws_route_table_association" "app_a" {
  subnet_id      = aws_subnet.app_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "app_b" {
  subnet_id      = aws_subnet.app_b.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# IAM: EC2 instance role/profile and Elastic Beanstalk service role
# -----------------------------------------------------------------------------

resource "aws_iam_role" "eb_instance_role" {
  name = "go-sample-app-eb-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEC2ToAssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })

  tags = merge(
    var.tags,
    {
      Name = "go-sample-app-eb-instance-role"
    },
  )
}

resource "aws_iam_role_policy_attachment" "eb_instance_web_tier" {
  role       = aws_iam_role.eb_instance_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_instance_worker_tier" {
  role       = aws_iam_role.eb_instance_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_instance_profile" "eb_instance_profile" {
  name = "go-sample-app-eb-instance-profile"
  role = aws_iam_role.eb_instance_role.name

  tags = merge(
    var.tags,
    {
      Name = "go-sample-app-eb-instance-profile"
    },
  )

  depends_on = [
    aws_iam_role_policy_attachment.eb_instance_web_tier,
    aws_iam_role_policy_attachment.eb_instance_worker_tier,
  ]
}

resource "aws_iam_role" "eb_service_role" {
  name = "go-sample-app-eb-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowElasticBeanstalkToAssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
        Condition = {
          StringEquals = {
            "sts:ExternalId" = "elasticbeanstalk"
          }
        }
      },
    ]
  })

  tags = merge(
    var.tags,
    {
      Name = "go-sample-app-eb-service-role"
    },
  )
}

resource "aws_iam_role_policy_attachment" "eb_service_enhanced_health" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkEnhancedHealth"
}

resource "aws_iam_role_policy_attachment" "eb_service_managed_updates" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkManagedUpdatesCustomerRolePolicy"
}

# -----------------------------------------------------------------------------
# Elastic Beanstalk application, version, and environment
# -----------------------------------------------------------------------------

resource "aws_elastic_beanstalk_application" "go_app" {
  name        = var.application_name
  description = "Sample Go web application managed by Terraform."
  tags        = var.tags
}

resource "aws_elastic_beanstalk_application_version" "go_app" {
  name        = local.go_version_name
  application = aws_elastic_beanstalk_application.go_app.name
  description = "Sample Go application bundle built and uploaded by Terraform."
  bucket      = aws_s3_bucket.eb_app_versions.id
  key         = aws_s3_object.go_app_bundle.key
  tags        = var.tags

  # Ensure the bundle is fully uploaded before the version is registered.
  depends_on = [aws_s3_object.go_app_bundle]
}

resource "aws_elastic_beanstalk_environment" "go_app" {
  name                   = var.environment_name
  application            = aws_elastic_beanstalk_application.go_app.name
  description            = "Load-balanced Go web server environment."
  solution_stack_name    = var.solution_stack_name
  tier                   = "WebServer"
  cname_prefix           = var.cname_prefix
  version_label          = aws_elastic_beanstalk_application_version.go_app.name
  wait_for_ready_timeout = "30m"
  tags                   = var.tags

  # --- EC2 launch configuration ---
  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_instance_profile.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = var.instance_type
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "DisableIMDSv1"
    value     = "true"
  }

  # --- VPC wiring (greenfield VPC declared in this configuration) ---
  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", [aws_subnet.app_a.id, aws_subnet.app_b.id])
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", [aws_subnet.public_a.id, aws_subnet.public_b.id])
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBScheme"
    value     = "public"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  # --- Capacity and autoscaling ---
  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "3"
  }

  # --- Environment and load balancer (public traffic enters here only) ---
  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "LoadBalancerType"
    value     = "application"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.arn
  }

  # --- Operational health and CloudWatch integration ---
  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:cloudwatch:ec2"
    name      = "HealthStreamingEnabled"
    value     = "true"
  }

  # --- Managed platform updates ---
  setting {
    namespace = "aws:elasticbeanstalk:managedactions"
    name      = "ManagedActionsEnabled"
    value     = "true"
  }

  setting {
    namespace = "aws:elasticbeanstalk:managedactions"
    name      = "PreferredStartTime"
    value     = "Tue:09:00"
  }

  setting {
    namespace = "aws:elasticbeanstalk:managedactions:platformupdate"
    name      = "UpdateLevel"
    value     = "minor"
  }

  setting {
    namespace = "aws:elasticbeanstalk:managedactions:platformupdate"
    name      = "InstanceRefreshEnabled"
    value     = "true"
  }

  depends_on = [
    aws_iam_role_policy_attachment.eb_service_enhanced_health,
    aws_iam_role_policy_attachment.eb_service_managed_updates,
  ]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "environment_endpoint" {
  description = "Public endpoint (CNAME) of the Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.go_app.cname
}

output "application_name" {
  description = "Name of the Elastic Beanstalk application."
  value       = aws_elastic_beanstalk_application.go_app.name
}

output "environment_name" {
  description = "Name of the Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.go_app.name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      Project     = "terraform-codebuild-example"
      Environment = "example"
      ManagedBy   = "terraform"
    }
  }
}

data "aws_caller_identity" "current" {}

locals {
  codebuild_project_name = "terraform-example-codebuild"
  artifacts_bucket_name  = "codebuild-artifacts-${data.aws_caller_identity.current.account_id}"
  log_group_name         = "/aws/codebuild/${local.codebuild_project_name}"
}

resource "aws_iam_role" "codebuild_service_role" {
  name = "codebuild-service-role-example"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowCodeBuildToAssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "codebuild-service-role-example"
  }
}

resource "aws_iam_role_policy" "codebuild_inline_policy" {
  name = "codebuild-least-privilege-inline-policy"
  role = aws_iam_role.codebuild_service_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CodeBuildCloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.codebuild_logs.arn,
          "${aws_cloudwatch_log_group.codebuild_logs.arn}:*"
        ]
      },
      {
        Sid    = "CodeBuildArtifactBucket"
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:GetBucketLocation",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.codebuild_artifacts.arn,
          "${aws_s3_bucket.codebuild_artifacts.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_cloudwatch_log_group" "codebuild_logs" {
  name              = local.log_group_name
  retention_in_days = 14

  tags = {
    Name = local.log_group_name
  }
}

resource "aws_s3_bucket" "codebuild_artifacts" {
  bucket = local.artifacts_bucket_name

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = local.artifacts_bucket_name
  }
}

resource "aws_s3_bucket_public_access_block" "codebuild_artifacts" {
  bucket = aws_s3_bucket.codebuild_artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "codebuild_artifacts" {
  bucket = aws_s3_bucket.codebuild_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "codebuild_artifacts" {
  bucket = aws_s3_bucket.codebuild_artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_codebuild_project" "example" {
  name         = local.codebuild_project_name
  description  = "Example CodeBuild project with public GitHub source, S3 artifacts, and CloudWatch logs"
  service_role = aws_iam_role.codebuild_service_role.arn

  source {
    type     = "GITHUB"
    location = "https://github.com/hashicorp/terraform-example-repo.git"

    buildspec = <<-EOT
      version: 0.2

      phases:
        install:
          commands:
            - echo "Install phase - installing dependencies"
        build:
          commands:
            - echo "Build phase - build started on $(date)"
            - echo "Hello from CodeBuild managed by Terraform"
        post_build:
          commands:
            - echo "Post-build phase - build completed on $(date)"

      artifacts:
        files:
          - '**/*'
    EOT
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/standard:7.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
  }

  artifacts {
    type                = "S3"
    location            = aws_s3_bucket.codebuild_artifacts.id
    name                = "example-build-output"
    packaging           = "ZIP"
    encryption_disabled = false
  }

  logs_config {
    cloudwatch_logs {
      group_name = aws_cloudwatch_log_group.codebuild_logs.name
    }
  }

  tags = {
    Name = local.codebuild_project_name
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Data sources (pure, well-known static lookups only)
###############################################################################

data "aws_caller_identity" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  # Fixed project name string: the CloudWatch log group and the IAM policy
  # resource ARN reference this literal so no circular dependency arises
  # between the IAM policy, the log group, and the CodeBuild project.
  project_name = "example-project"

  tags = {
    Project   = "example-codebuild"
    ManagedBy = "terraform"
  }
}

###############################################################################
# IAM: CodeBuild service role and least-privilege logging policy
###############################################################################

resource "aws_iam_role" "codebuild_role" {
  name = "${local.project_name}-codebuild-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.tags, {
    Name = "${local.project_name}-codebuild-role"
  })
}

resource "aws_iam_policy" "codebuild_logs_policy" {
  name        = "${local.project_name}-codebuild-logs-policy"
  description = "Least-privilege logging permissions for the ${local.project_name} CodeBuild project (CloudWatch Logs and S3 logs bucket)"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CodeBuildCloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:aws:logs:*:*:log-group:/aws/codebuild/${local.project_name}:*"
      },
      {
        Sid    = "CodeBuildS3Logs"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Resource = "${aws_s3_bucket.codebuild_logs.arn}/*"
      }
    ]
  })

  tags = merge(local.tags, {
    Name = "${local.project_name}-codebuild-logs-policy"
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_logs" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = aws_iam_policy.codebuild_logs_policy.arn
}

###############################################################################
# S3 bucket receiving CodeBuild S3 logs (stateful, protected from destroy)
###############################################################################

resource "aws_s3_bucket" "codebuild_logs" {
  bucket = "${local.project_name}-codebuild-logs-${data.aws_caller_identity.current.account_id}"

  tags = merge(local.tags, {
    Name = "${local.project_name}-codebuild-logs"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "codebuild_logs" {
  bucket = aws_s3_bucket.codebuild_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "codebuild_logs" {
  bucket = aws_s3_bucket.codebuild_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "codebuild_logs" {
  bucket = aws_s3_bucket.codebuild_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "codebuild_logs" {
  bucket = aws_s3_bucket.codebuild_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.codebuild_logs.arn,
          "${aws_s3_bucket.codebuild_logs.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.codebuild_logs]
}

###############################################################################
# CloudWatch Logs group for CodeBuild build logs
###############################################################################

resource "aws_cloudwatch_log_group" "example" {
  name              = "/aws/codebuild/${local.project_name}"
  retention_in_days = 30

  tags = merge(local.tags, {
    Name = "/aws/codebuild/${local.project_name}"
  })
}

###############################################################################
# CodeBuild project
###############################################################################

# NOTE: This example builds from a public HTTPS GitHub repository URL and
# therefore requires no credentials. If private repository access is ever
# required, store the GitHub personal access token in
# aws_secretsmanager_secret / aws_secretsmanager_secret_version and reference
# only the secret ARN — never hardcode tokens or credentials in this file.

resource "aws_codebuild_project" "example" {
  name          = local.project_name
  description   = "Example CodeBuild project with GitHub source, CloudWatch Logs and S3 logging"
  service_role  = aws_iam_role.codebuild_role.arn
  build_timeout = 10

  source {
    type      = "GITHUB"
    location  = "https://github.com/octocat/Hello-World.git"
    buildspec = <<-EOT
      version: 0.2

      phases:
        install:
          commands:
            - echo "Install phase started on $(date)"
        build:
          commands:
            - echo "Build phase started on $(date)"
        post_build:
          commands:
            - echo "Build completed successfully on $(date)"
    EOT
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/standard:7.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
  }

  artifacts {
    type = "NO_ARTIFACTS"
  }

  logs_config {
    cloudwatch_logs {
      status      = "ENABLED"
      group_name  = aws_cloudwatch_log_group.example.name
      stream_name = "${local.project_name}-build-stream"
    }

    s3_logs {
      status              = "ENABLED"
      location            = "${aws_s3_bucket.codebuild_logs.bucket}/${local.project_name}/logs"
      encryption_disabled = false
    }
  }

  tags = merge(local.tags, {
    Name = local.project_name
  })

  depends_on = [aws_iam_role_policy_attachment.codebuild_logs]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

locals {
  project_name          = "example-secondary-sources-project"
  artifacts_bucket_name = "codebuild-artifacts-${data.aws_caller_identity.current.account_id}"
  log_group_name        = "/aws/codebuild/${local.project_name}"
  log_stream_name       = "build-logs"

  common_tags = {
    Project     = "codebuild-example"
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# S3 bucket for CodeBuild primary and secondary artifacts
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "build_artifacts" {
  bucket = local.artifacts_bucket_name

  tags = merge(local.common_tags, {
    Name = "codebuild-build-artifacts"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "build_artifacts" {
  bucket = aws_s3_bucket.build_artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "build_artifacts" {
  bucket = aws_s3_bucket.build_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "build_artifacts" {
  bucket = aws_s3_bucket.build_artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

# -----------------------------------------------------------------------------
# CloudWatch log group for CodeBuild build logs
# -----------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "codebuild_build_logs" {
  name              = local.log_group_name
  retention_in_days = 30

  tags = merge(local.common_tags, {
    Name = "codebuild-build-logs"
  })
}

# -----------------------------------------------------------------------------
# IAM role and least-privilege inline policy for CodeBuild
# -----------------------------------------------------------------------------
resource "aws_iam_role" "codebuild_service_role" {
  name        = "example-codebuild-service-role"
  description = "Service role assumed by the example CodeBuild project"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCodeBuildToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "codebuild_least_privilege" {
  name = "example-codebuild-least-privilege"
  role = aws_iam_role.codebuild_service_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CodeBuildCloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.codebuild_build_logs.arn,
          "${aws_cloudwatch_log_group.codebuild_build_logs.arn}:*"
        ]
      },
      {
        Sid    = "CodeBuildArtifactObjects"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Resource = "${aws_s3_bucket.build_artifacts.arn}/*"
      },
      {
        Sid      = "CodeBuildArtifactBucketList"
        Effect   = "Allow"
        Action   = "s3:ListBucket"
        Resource = aws_s3_bucket.build_artifacts.arn
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Secrets Manager secret backing the SECRETS_MANAGER environment variable
# -----------------------------------------------------------------------------
resource "random_password" "example" {
  length  = 32
  special = true
}

resource "aws_secretsmanager_secret" "example" {
  name        = "codebuild/example-app-secret"
  description = "Example secret referenced by the CodeBuild SECRETS_MANAGER environment variable"

  tags = local.common_tags
}

resource "aws_secretsmanager_secret_version" "example" {
  secret_id     = aws_secretsmanager_secret.example.id
  secret_string = random_password.example.result
}

# -----------------------------------------------------------------------------
# CodeBuild project with primary/secondary sources and primary/secondary artifacts
# -----------------------------------------------------------------------------
resource "aws_codebuild_project" "example" {
  name          = local.project_name
  description   = "Example CodeBuild project with secondary sources and secondary artifacts"
  service_role  = aws_iam_role.codebuild_service_role.arn
  build_timeout = 20

  source {
    type     = "GITHUB"
    location = "https://github.com/example-org/primary-build-repo.git"
    buildspec = <<-EOF
      version: 0.2

      phases:
        install:
          runtime-versions:
            python: 3.11
          commands:
            - echo "Install phase for environment $ENV_NAME (log level: $LOG_LEVEL)"
            - python -m pip install --upgrade pip
        pre_build:
          commands:
            - echo "Pre-build phase started on $(date)"
        build:
          commands:
            - echo "Build phase started on $(date)"
            - mkdir -p build-output test-output
            - echo "Primary application build output" > build-output/app-output.txt
            - echo "Test suite output" > test-output/test-results.txt
        post_build:
          commands:
            - echo "Build completed on $(date)"

      artifacts:
        name: primary-artifact
        base-directory: build-output
        files:
          - '**/*'

      secondary-artifacts:
        secondary_artifact_1:
          name: secondary-artifact-1
          base-directory: build-output
          files:
            - '**/*'
        secondary_artifact_2:
          name: secondary-artifact-2
          base-directory: test-output
          files:
            - '**/*'
    EOF
  }

  secondary_sources {
    type              = "GITHUB"
    location          = "https://github.com/example-org/secondary-source-one.git"
    source_identifier = "secondary_src_1"
    buildspec         = "buildspecs/secondary-one.yml"
  }

  secondary_sources {
    type              = "GITHUB"
    location          = "https://github.com/example-org/secondary-source-two.git"
    source_identifier = "secondary_src_2"
    buildspec         = "buildspecs/secondary-two.yml"
  }

  artifacts {
    type                   = "S3"
    location               = aws_s3_bucket.build_artifacts.id
    name                   = "primary-artifact"
    path                   = "primary-artifacts"
    namespace_type         = "NONE"
    packaging              = "ZIP"
    override_artifact_name = true
  }

  secondary_artifacts {
    artifact_identifier    = "secondary_artifact_1"
    type                   = "S3"
    location               = aws_s3_bucket.build_artifacts.id
    name                   = "secondary-artifact-1"
    path                   = "secondary-artifacts/build-output"
    namespace_type         = "NONE"
    packaging              = "ZIP"
    override_artifact_name = true
  }

  secondary_artifacts {
    artifact_identifier    = "secondary_artifact_2"
    type                   = "S3"
    location               = aws_s3_bucket.build_artifacts.id
    name                   = "secondary-artifact-2"
    path                   = "secondary-artifacts/test-output"
    namespace_type         = "NONE"
    packaging              = "ZIP"
    override_artifact_name = true
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/standard:7.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"

    environment_variable {
      name  = "ENV_NAME"
      value = "dev"
      type  = "PLAINTEXT"
    }

    environment_variable {
      name  = "LOG_LEVEL"
      value = "info"
      type  = "PLAINTEXT"
    }

    environment_variable {
      name  = "APP_SECRET"
      value = aws_secretsmanager_secret.example.arn
      type  = "SECRETS_MANAGER"
    }
  }

  cache {
    type = "NO_CACHE"
  }

  logs_config {
    cloudwatch_logs {
      status      = "ENABLED"
      group_name  = aws_cloudwatch_log_group.codebuild_build_logs.name
      stream_name = local.log_stream_name
    }
  }

  tags = merge(local.common_tags, {
    Name = local.project_name
  })
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  plain_text_content_type = "PlainText"
}

# ---------------------------------------------------------------------------
# Custom enumeration slot types
# ---------------------------------------------------------------------------

resource "aws_lex_slot_type" "pizza_size" {
  name                     = "PizzaSize"
  description              = "Enumeration of available pizza sizes."
  value_selection_strategy = "TOP_RESOLUTION"
  create_version           = true

  enumeration_value {
    value    = "small"
    synonyms = ["personal", "individual"]
  }

  enumeration_value {
    value    = "medium"
    synonyms = ["standard", "mid size"]
  }

  enumeration_value {
    value    = "large"
    synonyms = ["big", "jumbo"]
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lex_slot_type" "pizza_crust" {
  name                     = "PizzaCrust"
  description              = "Enumeration of available pizza crust options."
  value_selection_strategy = "TOP_RESOLUTION"
  create_version           = true

  enumeration_value {
    value    = "thin"
    synonyms = ["crispy", "flatbread"]
  }

  enumeration_value {
    value    = "regular"
    synonyms = ["original", "hand tossed"]
  }

  enumeration_value {
    value    = "deep_dish"
    synonyms = ["deep dish", "pan", "chicago style"]
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lex_slot_type" "pizza_toppings" {
  name                     = "PizzaToppings"
  description              = "Enumeration of available pizza toppings."
  value_selection_strategy = "TOP_RESOLUTION"
  create_version           = true

  enumeration_value {
    value    = "pepperoni"
    synonyms = ["spicy pepperoni"]
  }

  enumeration_value {
    value    = "mushroom"
    synonyms = ["mushrooms"]
  }

  enumeration_value {
    value    = "onion"
    synonyms = ["onions", "red onion"]
  }

  enumeration_value {
    value    = "sausage"
    synonyms = ["italian sausage"]
  }

  enumeration_value {
    value    = "extra_cheese"
    synonyms = ["extra cheese", "additional cheese"]
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# OrderPizza intent
# ---------------------------------------------------------------------------

resource "aws_lex_intent" "pizza_order" {
  name           = "OrderPizza"
  description    = "Intent that collects pizza order details, confirms the order with the user, and concludes within the bot."
  create_version = true

  sample_utterances = [
    "I want to order a {Size} pizza",
    "I'd like {Quantity} pizzas with {Toppings}",
    "I want to order a {Size} pizza with {Crust} crust and {Toppings}",
    "I would like to order a pizza",
    "Can I get a pizza please"
  ]

  slot {
    name            = "Quantity"
    description     = "How many pizzas the customer wants to order."
    slot_type       = "AMAZON.NUMBER"
    slot_constraint = "Required"
    priority        = 1

    sample_utterances = [
      "I would like {Quantity} pizzas",
      "I want to order {Quantity} pizzas"
    ]

    value_elicitation_prompt {
      max_attempts = 3

      message {
        content      = "How many pizzas would you like to order?"
        content_type = local.plain_text_content_type
      }
    }
  }

  slot {
    name              = "Size"
    description       = "Size of the pizza."
    slot_type         = aws_lex_slot_type.pizza_size.name
    slot_type_version = aws_lex_slot_type.pizza_size.version
    slot_constraint   = "Required"
    priority          = 2

    sample_utterances = [
      "I want a {Size} pizza",
      "Make it {Size}"
    ]

    value_elicitation_prompt {
      max_attempts = 3

      message {
        content      = "What size pizza would you like? You can choose small, medium, or large."
        content_type = local.plain_text_content_type
      }
    }
  }

  slot {
    name              = "Crust"
    description       = "Crust style of the pizza."
    slot_type         = aws_lex_slot_type.pizza_crust.name
    slot_type_version = aws_lex_slot_type.pizza_crust.version
    slot_constraint   = "Required"
    priority          = 3

    sample_utterances = [
      "I want {Crust} crust",
      "Make it {Crust} crust"
    ]

    value_elicitation_prompt {
      max_attempts = 3

      message {
        content      = "What kind of crust would you like? You can choose thin, regular, or deep dish."
        content_type = local.plain_text_content_type
      }
    }
  }

  slot {
    name              = "Toppings"
    description       = "Toppings for the pizza."
    slot_type         = aws_lex_slot_type.pizza_toppings.name
    slot_type_version = aws_lex_slot_type.pizza_toppings.version
    slot_constraint   = "Required"
    priority          = 4

    sample_utterances = [
      "with {Toppings}",
      "I want {Toppings} toppings"
    ]

    value_elicitation_prompt {
      max_attempts = 3

      message {
        content      = "What toppings would you like? You can choose pepperoni, mushroom, onion, sausage, or extra cheese."
        content_type = local.plain_text_content_type
      }
    }
  }

  confirmation_prompt {
    max_attempts = 3

    message {
      content      = "Just to confirm: you would like {Quantity} {Size} pizza(s) with {Crust} crust and {Toppings}. Is that correct?"
      content_type = local.plain_text_content_type
    }
  }

  rejection_statement {
    message {
      content      = "Okay, I have cancelled your pizza order. Is there anything else I can help you with?"
      content_type = local.plain_text_content_type
    }
  }

  fulfillment_activity {
    type = "ReturnIntent"
  }

  conclusion_statement {
    message {
      content      = "Thanks! Your order for {Quantity} {Size} pizza(s) with {Crust} crust and {Toppings} has been placed."
      content_type = local.plain_text_content_type
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Pizza ordering bot
# ---------------------------------------------------------------------------

resource "aws_lex_bot" "pizza_ordering_bot" {
  name        = "PizzaOrderingBot"
  description = "Conversational bot that takes pizza orders and concludes them within the bot."

  locale                      = "en-US"
  voice_id                    = "Joanna"
  child_directed              = false
  idle_session_ttl_in_seconds = 300
  process_behavior            = "BUILD"

  intent {
    intent_name    = aws_lex_intent.pizza_order.name
    intent_version = aws_lex_intent.pizza_order.version
  }

  clarification_prompt {
    max_attempts = 3

    message {
      content      = "Sorry, I did not understand that. You can say something like 'I want to order a large pizza with pepperoni'. What would you like to do?"
      content_type = local.plain_text_content_type
    }
  }

  abort_statement {
    message {
      content      = "I'm sorry, I was not able to complete your pizza order. Please try again later."
      content_type = local.plain_text_content_type
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_lex_slot_type" "pizza_size" {
  name           = "PizzaSizeType"
  description    = "Supported pizza sizes for the PizzaOrderingBot"
  create_version = true

  enumeration_value {
    value    = "small"
    synonyms = ["smallest"]
  }

  enumeration_value {
    value    = "medium"
    synonyms = ["regular"]
  }

  enumeration_value {
    value    = "large"
    synonyms = ["biggest", "largest"]
  }
}

resource "aws_lex_slot_type" "crust" {
  name           = "PizzaCrustType"
  description    = "Supported crust styles for the PizzaOrderingBot"
  create_version = true

  enumeration_value {
    value    = "thin"
    synonyms = ["crispy"]
  }

  enumeration_value {
    value    = "thick"
    synonyms = ["deepdish"]
  }

  enumeration_value {
    value    = "pan"
    synonyms = ["classic"]
  }

  enumeration_value {
    value    = "stuffed"
    synonyms = ["loaded"]
  }
}

resource "aws_lex_intent" "order_pizza" {
  name           = "OrderPizza"
  description    = "Handles pizza ordering requests for the PizzaOrderingBot"
  create_version = true

  sample_utterances = [
    "order a pizza",
    "I'd like to order a pizza",
    "pizza please",
    "I want to order a pizza",
    "can I get a pizza",
    "let me order a pizza",
  ]

  slot {
    name              = "pizza_size"
    description       = "The size of the pizza the customer wants"
    slot_constraint   = "Required"
    slot_type         = aws_lex_slot_type.pizza_size.name
    slot_type_version = aws_lex_slot_type.pizza_size.version
    priority          = 1

    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "What size pizza would you like? We offer small, medium, and large."
        content_type = "PlainText"
        group_number = 1
      }
    }
  }

  slot {
    name              = "crust"
    description       = "The crust style the customer wants"
    slot_constraint   = "Required"
    slot_type         = aws_lex_slot_type.crust.name
    slot_type_version = aws_lex_slot_type.crust.version
    priority          = 2

    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "What kind of crust would you like? Choose thin, thick, pan, or stuffed."
        content_type = "PlainText"
        group_number = 1
      }
    }
  }

  slot {
    name            = "quantity"
    description     = "The number of pizzas the customer wants to order"
    slot_constraint = "Required"
    slot_type       = "AMAZON.Number"
    priority        = 3

    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "How many pizzas would you like to order?"
        content_type = "PlainText"
        group_number = 1
      }
    }
  }

  confirmation_prompt {
    max_attempts = 2
    message {
      content      = "To confirm: you want {quantity} {pizza_size} pizza with {crust} crust. Should I place the order?"
      content_type = "PlainText"
      group_number = 1
    }
  }

  rejection_statement {
    message {
      content      = "Okay, I will not place the order. Say 'order a pizza' whenever you are ready to try again."
      content_type = "PlainText"
      group_number = 1
    }
  }

  fulfillment_activity {
    type = "ReturnIntent"
  }
}

resource "aws_lex_bot" "pizza_ordering_bot" {
  name                            = "PizzaOrderingBot"
  description                     = "Conversational bot for ordering pizzas"
  locale                          = "en-US"
  child_directed                  = false
  process_behavior                = "BUILD"
  enable_model_improvements       = true
  nlu_intent_confidence_threshold = 0.5
  idle_session_ttl_in_seconds     = 300

  clarification_prompt {
    max_attempts = 2
    message {
      content      = "Sorry, I did not understand that. You can say something like 'I would like to order a pizza'."
      content_type = "PlainText"
      group_number = 1
    }
  }

  abort_statement {
    message {
      content      = "Sorry, I was not able to complete your pizza order. Please try again later."
      content_type = "PlainText"
      group_number = 1
    }
  }

  intent {
    intent_name    = aws_lex_intent.order_pizza.name
    intent_version = aws_lex_intent.order_pizza.version
  }
}

terraform {
  required_version = ">= 1.5.0, < 2.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Project name used for resource naming and the Name tag."
  type        = string
  default     = "connect-lex-bot"
}

variable "environment" {
  description = "Environment name applied to the Environment tag."
  type        = string
  default     = "production"
}

locals {
  lex_bot_name      = replace(var.project_name, "-", "_")
  lex_bot_role_name = "${var.project_name}-lex-bot-role"

  common_tags = {
    Name        = var.project_name
    Environment = var.environment
  }
}

resource "aws_connect_instance" "main" {
  instance_alias            = var.project_name
  identity_management_type  = "SAML"
  inbound_calls_enabled     = true
  outbound_calls_enabled    = true
  contact_flow_logs_enabled = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "lex_bot" {
  name = local.lex_bot_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lexv2.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "lex_bot" {
  name = "${local.lex_bot_role_name}-polly"
  role = aws_iam_role.lex_bot.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "polly:DescribeVoices",
          "polly:SynthesizeSpeech"
        ]
        # Amazon Polly does not support resource-level permissions,
        # so the resource scope must remain "*".
        Resource = "*"
      }
    ]
  })
}

resource "aws_lexv2models_bot" "main" {
  name                        = local.lex_bot_name
  description                 = "Lex V2 bot associated with the Amazon Connect instance."
  role_arn                    = aws_iam_role.lex_bot.arn
  idle_session_ttl_in_seconds = 300

  data_privacy {
    child_directed = false
  }

  depends_on = [aws_iam_role_policy.lex_bot]

  tags = local.common_tags
}

resource "aws_lexv2models_bot_locale" "main" {
  bot_id                           = aws_lexv2models_bot.main.id
  bot_version                      = "DRAFT"
  locale_id                        = "en_US"
  description                      = "US English locale for the Connect-associated Lex bot."
  n_lu_intent_confidence_threshold = 0.7

  voice_settings {
    voice_id = "Joanna"
    engine   = "standard"
  }
}

resource "aws_connect_bot_association" "main" {
  instance_id = aws_connect_instance.main.id

  lex_bot {
    name       = aws_lexv2models_bot.main.name
    lex_region = "us-east-1"
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = local.common_tags
  }
}

# ----------------------------------------------------------------------------
# User-controlled variables (all defaults are set so `terraform apply` runs
# unattended; no variables are used as substitutes for resource attributes)
# ----------------------------------------------------------------------------

variable "project_name" {
  description = "Project name used for resource naming and tagging."
  type        = string
  default     = "stream_analytics"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

variable "shard_count" {
  description = "Number of shards for the provisioned input Kinesis data stream."
  type        = number
  default     = 1

  validation {
    condition     = var.shard_count >= 1
    error_message = "The shard_count value must be at least 1."
  }
}

# ----------------------------------------------------------------------------
# Locals
# ----------------------------------------------------------------------------

locals {
  # Matches the provider's fixed region above; used for ARN construction in
  # the KMS key policy so region naming is not dependent on data source
  # attribute availability across provider versions.
  region = "us-east-1"

  common_tags = {
    project     = var.project_name
    environment = var.environment
    managed-by  = "terraform"
  }

  stream_name      = "${var.project_name}_input_stream"
  app_name         = "${var.project_name}_app"
  role_name        = "${var.project_name}_${var.environment}_kinesis_analytics_role"
  log_group_name   = "/aws/kinesis-analytics/${var.project_name}"
  log_stream_name  = "${var.project_name}_${var.environment}_app_logs"
  logs_policy_name = "${var.project_name}_${var.environment}_analytics_logs_write"
}

# ----------------------------------------------------------------------------
# Data sources (static provider metadata only, no pre-existing infrastructure)
# ----------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

# ----------------------------------------------------------------------------
# Customer-managed KMS key for the Kinesis stream and CloudWatch log group
# ----------------------------------------------------------------------------

resource "aws_kms_key" "kinesis" {
  description             = "Customer managed key encrypting the ${var.project_name} Kinesis stream and its CloudWatch Logs."
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableAccountAdministration"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowKinesisServiceUse"
        Effect = "Allow"
        Principal = {
          Service = "kinesis.amazonaws.com"
        }
        Action = [
          "kms:CreateGrant",
          "kms:ListGrants",
          "kms:RevokeGrant",
          "kms:DescribeKey",
          "kms:GenerateDataKey*",
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogsUse"
        Effect = "Allow"
        Principal = {
          Service = "logs.${local.region}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt*",
          "kms:Decrypt*",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:Describe*"
        ]
        Resource = "*"
        Condition = {
          ArnEquals = {
            "kms:EncryptionContext:aws:logs:arn" = "arn:aws:logs:${local.region}:${data.aws_caller_identity.current.account_id}:log-group:${local.log_group_name}"
          }
        }
      }
    ]
  })

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------------
# Input Kinesis data stream (the sole data source for the analytics app)
# ----------------------------------------------------------------------------

resource "aws_kinesis_stream" "input_stream" {
  name        = local.stream_name
  shard_count = var.shard_count

  # Retention period is measured in hours (24 hours retention; maximum 168).
  # Do NOT rename this argument to `retention_period_hours` — that legacy
  # attribute name is unsupported in AWS provider v5 and fails validation.
  retention_period = 24

  stream_mode_details {
    stream_mode = "PROVISIONED"
  }

  encryption_type = "KMS"
  kms_key_id      = aws_kms_key.kinesis.arn

  shard_level_metrics = [
    "IncomingBytes",
    "IncomingRecords",
    "OutgoingBytes",
    "OutgoingRecords",
    "WriteProvisionedThroughputExceeded",
    "ReadProvisionedThroughputExceeded",
    "IteratorAgeMilliseconds",
  ]

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------------
# CloudWatch Logs for Kinesis Analytics application diagnostics
# ----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "kinesis_analytics" {
  name              = local.log_group_name
  retention_in_days = 365
  kms_key_id        = aws_kms_key.kinesis.arn

  tags = local.common_tags
}

resource "aws_cloudwatch_log_stream" "kinesis_analytics" {
  name           = local.log_stream_name
  log_group_name = aws_cloudwatch_log_group.kinesis_analytics.name
}

# ----------------------------------------------------------------------------
# Service execution role for the Kinesis Analytics application
# ----------------------------------------------------------------------------

resource "aws_iam_role" "kinesis_analytics" {
  name = local.role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowKinesisAnalyticsAssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

# Inline policy: least-privilege read access scoped to the input stream only.
resource "aws_iam_role_policy" "kinesis_input_stream_read" {
  name = "kinesis_input_stream_read"
  role = aws_iam_role.kinesis_analytics.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ReadInputStream"
        Effect = "Allow"
        Action = [
          "kinesis:DescribeStream",
          "kinesis:ListShards",
          "kinesis:GetShardIterator",
          "kinesis:GetRecords"
        ]
        Resource = aws_kinesis_stream.input_stream.arn
      }
    ]
  })
}

# Managed policy + attachment: minimal CloudWatch Logs write access scoped to
# the created log group and log stream only.
resource "aws_iam_policy" "analytics_logs_write" {
  name        = local.logs_policy_name
  description = "Least-privilege CloudWatch Logs write access for the ${var.project_name} Kinesis Analytics application."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "WriteApplicationDiagnostics"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams"
        ]
        Resource = [
          aws_cloudwatch_log_group.kinesis_analytics.arn,
          aws_cloudwatch_log_stream.kinesis_analytics.arn
        ]
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "analytics_logs_write" {
  role       = aws_iam_role.kinesis_analytics.name
  policy_arn = aws_iam_policy.analytics_logs_write.arn
}

# ----------------------------------------------------------------------------
# Kinesis Analytics application
#
# The classic SQL runtime is implied by the aws_kinesis_analytics_application
# resource type (vs. the Flink runtime resource). The service execution role
# is wired through the per-input kinesis_stream.role_arn and the
# cloudwatch_logging_options.role_arn, both referencing the least-privilege
# IAM role created above.
# ----------------------------------------------------------------------------

resource "aws_kinesis_analytics_application" "stream_analytics_app" {
  name        = local.app_name
  description = "Basic Kinesis Analytics (SQL) application consuming records from the ${local.stream_name} Kinesis stream."

  inputs {
    id          = "1.1"
    name_prefix = "INPUT"

    kinesis_stream {
      resource_arn = aws_kinesis_stream.input_stream.arn
      role_arn     = aws_iam_role.kinesis_analytics.arn
    }

    schema {
      record_columns {
        name     = "event_type"
        mapping  = "$.event_type"
        sql_type = "VARCHAR(64)"
      }

      record_columns {
        name     = "event_time"
        mapping  = "$.event_time"
        sql_type = "TIMESTAMP"
      }

      record_columns {
        name     = "payload"
        mapping  = "$.payload"
        sql_type = "VARCHAR(1024)"
      }

      record_format {
        # JSON records map source fields by record row path; column and row
        # delimiter mapping parameters apply only to the CSV record format.
        record_format_type = "JSON"

        mapping_parameters {
          json {
            record_row_path = "$"
          }
        }
      }

      record_encoding = "UTF-8"
    }

    starting_position_configuration {
      starting_position = "LATEST"
    }
  }

  cloudwatch_logging_options {
    log_stream_arn = aws_cloudwatch_log_stream.kinesis_analytics.arn
    role_arn       = aws_iam_role.kinesis_analytics.arn
  }

  tags = local.common_tags

  depends_on = [
    aws_iam_role_policy.kinesis_input_stream_read,
    aws_iam_role_policy_attachment.analytics_logs_write,
  ]
}

# ----------------------------------------------------------------------------
# Outputs
# ----------------------------------------------------------------------------

output "kinesis_stream_name" {
  description = "Name of the input Kinesis data stream."
  value       = aws_kinesis_stream.input_stream.name
}

output "kinesis_stream_arn" {
  description = "ARN of the input Kinesis data stream."
  value       = aws_kinesis_stream.input_stream.arn
}

output "kms_key_arn" {
  description = "ARN of the customer managed KMS key used for encryption."
  value       = aws_kms_key.kinesis.arn
}

output "analytics_application_arn" {
  description = "ARN of the Kinesis Analytics application."
  value       = aws_kinesis_analytics_application.stream_analytics_app.arn
}

output "analytics_application_id" {
  description = "ID of the Kinesis Analytics application."
  value       = aws_kinesis_analytics_application.stream_analytics_app.id
}

output "analytics_service_role_arn" {
  description = "ARN of the Kinesis Analytics service execution IAM role."
  value       = aws_iam_role.kinesis_analytics.arn
}

output "cloudwatch_log_group_arn" {
  description = "ARN of the CloudWatch log group capturing application diagnostics."
  value       = aws_cloudwatch_log_group.kinesis_analytics.arn
}

output "cloudwatch_log_stream_arn" {
  description = "ARN of the CloudWatch log stream capturing application diagnostics."
  value       = aws_cloudwatch_log_stream.kinesis_analytics.arn
}

###############################################################################
# Terraform & Provider Configuration
###############################################################################

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables
###############################################################################

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

###############################################################################
# Data Sources (static provider metadata only)
###############################################################################

data "aws_caller_identity" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  delivery_stream_name = "firehose_delivery_stream"
  log_group_name       = "/aws/kinesisfirehose/${local.delivery_stream_name}"
  es_domain_name       = "firehose-es-${var.environment}"
  es_domain_arn        = "arn:aws:es:us-east-1:${data.aws_caller_identity.current.account_id}:domain/${local.es_domain_name}"
  backup_bucket_name   = "firehose-backup-${var.environment}-${data.aws_caller_identity.current.account_id}"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
    Component   = "kinesis-firehose-elasticsearch"
  }
}

###############################################################################
# S3 Backup Bucket (failed document backup destination for Firehose)
###############################################################################

resource "aws_s3_bucket" "firehose_backup" {
  bucket = local.backup_bucket_name
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "firehose_backup" {
  bucket                  = aws_s3_bucket.firehose_backup.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "firehose_backup" {
  bucket = aws_s3_bucket.firehose_backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "firehose_backup" {
  bucket = aws_s3_bucket.firehose_backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

###############################################################################
# KMS Key (Elasticsearch encryption at rest)
###############################################################################

resource "aws_kms_key" "elasticsearch" {
  description             = "KMS key for Elasticsearch domain encryption at rest"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  tags                    = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# IAM Role for Firehose Delivery
###############################################################################

data "aws_iam_policy_document" "firehose_assume_role" {
  statement {
    sid     = "AllowFirehoseAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["firehose.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "firehose_delivery" {
  name               = "firehose-delivery-role-${var.environment}"
  assume_role_policy = data.aws_iam_policy_document.firehose_assume_role.json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "firehose_delivery_permissions" {
  statement {
    sid    = "S3BackupBucketAccess"
    effect = "Allow"

    actions = [
      "s3:AbortMultipartUpload",
      "s3:GetObject",
      "s3:PutObject",
      "s3:GetBucketLocation",
      "s3:ListBucket",
    ]

    resources = [
      aws_s3_bucket.firehose_backup.arn,
      "${aws_s3_bucket.firehose_backup.arn}/*",
    ]
  }

  statement {
    sid    = "ElasticsearchDomainAccess"
    effect = "Allow"

    actions = [
      "es:ESHttpGet",
      "es:ESHttpPost",
      "es:ESHttpPut",
    ]

    resources = [
      aws_elasticsearch_domain.search.arn,
      "${aws_elasticsearch_domain.search.arn}/*",
    ]
  }

  statement {
    sid       = "FirehoseCloudWatchLogs"
    effect    = "Allow"
    actions   = ["logs:PutLogEvents"]
    resources = ["${aws_cloudwatch_log_group.firehose.arn}:*"]
  }
}

resource "aws_iam_role_policy" "firehose_delivery" {
  name   = "firehose-delivery-policy"
  role   = aws_iam_role.firehose_delivery.name
  policy = data.aws_iam_policy_document.firehose_delivery_permissions.json
}

###############################################################################
# CloudWatch Logs for Firehose Delivery Errors
###############################################################################

resource "aws_cloudwatch_log_group" "firehose" {
  name              = local.log_group_name
  retention_in_days = 30
  tags              = local.common_tags
}

resource "aws_cloudwatch_log_stream" "elasticsearch_delivery" {
  name           = "elasticsearch_delivery"
  log_group_name = aws_cloudwatch_log_group.firehose.name
}

resource "aws_cloudwatch_log_stream" "s3_delivery" {
  name           = "s3_delivery"
  log_group_name = aws_cloudwatch_log_group.firehose.name
}

###############################################################################
# Elasticsearch Domain
###############################################################################

data "aws_iam_policy_document" "elasticsearch_domain_access" {
  statement {
    sid    = "AllowFirehoseDeliveryRole"
    effect = "Allow"

    actions = [
      "es:ESHttpGet",
      "es:ESHttpPost",
      "es:ESHttpPut",
    ]

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.firehose_delivery.arn]
    }

    resources = ["${local.es_domain_arn}/*"]
  }
}

resource "aws_elasticsearch_domain" "search" {
  domain_name           = local.es_domain_name
  elasticsearch_version = "6.8"

  cluster_config {
    instance_type  = "t3.small.elasticsearch"
    instance_count = 1
  }

  ebs_options {
    ebs_enabled = true
    volume_size = 10
  }

  encrypt_at_rest {
    enabled    = true
    kms_key_id = aws_kms_key.elasticsearch.arn
  }

  node_to_node_encryption {
    enabled = true
  }

  domain_endpoint_options {
    enforce_https       = true
    tls_security_policy = "Policy-Min-TLS-1-2-2019-07"
  }

  access_policies = data.aws_iam_policy_document.elasticsearch_domain_access.json

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Kinesis Firehose Delivery Stream (Elasticsearch Destination)
###############################################################################

resource "aws_kinesis_firehose_delivery_stream" "to_elasticsearch" {
  name        = local.delivery_stream_name
  destination = "elasticsearch"

  elasticsearch_configuration {
    role_arn              = aws_iam_role.firehose_delivery.arn
    cluster_endpoint      = "https://${aws_elasticsearch_domain.search.endpoint}"
    index_name            = "firehose-logs"
    type_name             = "_doc"
    index_rotation_period = "OneMonth"
    buffering_size        = 5
    buffering_interval    = 60
    retry_duration        = 300
    s3_backup_mode        = "FailedDocumentsOnly"

    cloudwatch_logging_options {
      enabled         = true
      log_group_name  = aws_cloudwatch_log_group.firehose.name
      log_stream_name = aws_cloudwatch_log_stream.elasticsearch_delivery.name
    }

    s3_configuration {
      role_arn           = aws_iam_role.firehose_delivery.arn
      bucket_arn         = aws_s3_bucket.firehose_backup.arn
      prefix             = "failed-documents/"
      buffering_size     = 5
      buffering_interval = 300
      compression_format = "GZIP"

      cloudwatch_logging_options {
        enabled         = true
        log_group_name  = aws_cloudwatch_log_group.firehose.name
        log_stream_name = aws_cloudwatch_log_stream.s3_delivery.name
      }
    }
  }

  depends_on = [
    aws_iam_role_policy.firehose_delivery,
    aws_elasticsearch_domain.search,
    aws_s3_bucket_public_access_block.firehose_backup,
    aws_s3_bucket_server_side_encryption_configuration.firehose_backup,
    aws_s3_bucket_versioning.firehose_backup,
  ]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables
###############################################################################

variable "project_name" {
  description = "Prefix used for all resource names. Lowercase letters, numbers and hyphens only."
  type        = string
  default     = "firehose-opensearch"
}

variable "environment" {
  description = "Value applied to the Environment tag on every resource."
  type        = string
  default     = "dev"
}

variable "vpc_cidr" {
  description = "CIDR block for the dedicated Firehose / OpenSearch VPC."
  type        = string
  default     = "10.0.0.0/16"
}

###############################################################################
# Locals
###############################################################################

locals {
  name_prefix = lower(replace(var.project_name, "_", "-"))

  domain_name        = substr("${local.name_prefix}-domain", 0, 28)
  index_name         = "${local.name_prefix}-logs"
  stream_name        = "${local.name_prefix}-to-opensearch"
  log_group_name     = "/aws/kinesisfirehose/${local.name_prefix}-elasticsearch"
  backup_bucket_name = "${local.name_prefix}-firehose-backup-${data.aws_caller_identity.current.account_id}"

  # Mirrors aws_opensearch_domain.main.arn. The domain resource cannot reference
  # its own ARN inside access_policies, so it is composed here from static
  # provider metadata and the domain name declared above.
  domain_arn = "arn:${data.aws_partition.current.partition}:es:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:domain/${local.domain_name}"

  tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

###############################################################################
# Data sources (static provider / account metadata only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Networking: VPC, subnets, IGW, NAT gateway, routing
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  availability_zone = data.aws_availability_zones.available.names[count.index]
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 10)

  tags = merge(local.tags, { Name = "${local.name_prefix}-private-${count.index + 1}" })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  map_public_ip_on_launch = true

  tags = merge(local.tags, { Name = "${local.name_prefix}-public-${count.index + 1}" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, { Name = "${local.name_prefix}-igw" })
}

resource "aws_eip" "nat" {
  domain = "vpc"

  depends_on = [aws_internet_gateway.main]

  tags = merge(local.tags, { Name = "${local.name_prefix}-nat-eip" })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  depends_on = [aws_internet_gateway.main]

  tags = merge(local.tags, { Name = "${local.name_prefix}-nat" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.tags, { Name = "${local.name_prefix}-public-rt" })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.tags, { Name = "${local.name_prefix}-private-rt" })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

###############################################################################
# Security groups
# Rules are declared as separate aws_security_group_rule resources so the
# Firehose and Elasticsearch groups can reference each other without creating
# a Terraform dependency cycle. No 0.0.0.0/0 ingress exists on any port.
###############################################################################

resource "aws_security_group" "elasticsearch" {
  name        = "${local.name_prefix}-opensearch-sg"
  description = "OpenSearch domain endpoints; accepts HTTPS only from the Firehose delivery ENIs"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.tags, { Name = "${local.name_prefix}-opensearch-sg" })
}

resource "aws_security_group" "firehose" {
  name        = "${local.name_prefix}-firehose-sg"
  description = "Kinesis Data Firehose VPC delivery ENIs"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.tags, { Name = "${local.name_prefix}-firehose-sg" })
}

resource "aws_security_group_rule" "opensearch_ingress_from_firehose" {
  description              = "TCP 443 from the Firehose VPC delivery ENIs only"
  type                     = "ingress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  security_group_id        = aws_security_group.elasticsearch.id
  source_security_group_id = aws_security_group.firehose.id
}

resource "aws_security_group_rule" "opensearch_egress_https" {
  description       = "TCP 443 egress for domain service traffic (e.g. snapshots) via the NAT gateway"
  type              = "egress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  security_group_id = aws_security_group.elasticsearch.id
  cidr_blocks       = ["0.0.0.0/0"]
}

resource "aws_security_group_rule" "firehose_egress_to_opensearch" {
  description              = "TCP 443 to the OpenSearch domain endpoints"
  type                     = "egress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  security_group_id        = aws_security_group.firehose.id
  source_security_group_id = aws_security_group.elasticsearch.id
}

resource "aws_security_group_rule" "firehose_egress_https" {
  description       = "TCP 443 outbound to S3 and CloudWatch via the NAT gateway"
  type              = "egress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  security_group_id = aws_security_group.firehose.id
  cidr_blocks       = ["0.0.0.0/0"]
}

resource "aws_security_group_rule" "firehose_egress_dns_tcp" {
  description       = "TCP 53 DNS resolution against the VPC resolver"
  type              = "egress"
  from_port         = 53
  to_port           = 53
  protocol          = "tcp"
  security_group_id = aws_security_group.firehose.id
  cidr_blocks       = [aws_vpc.main.cidr_block]
}

resource "aws_security_group_rule" "firehose_egress_dns_udp" {
  description       = "UDP 53 DNS resolution against the VPC resolver"
  type              = "egress"
  from_port         = 53
  to_port           = 53
  protocol          = "udp"
  security_group_id = aws_security_group.firehose.id
  cidr_blocks       = [aws_vpc.main.cidr_block]
}

###############################################################################
# IAM: OpenSearch service-linked role + Firehose execution role
###############################################################################

resource "aws_iam_service_linked_role" "opensearch" {
  aws_service_name = "opensearchservice.amazonaws.com"
}

data "aws_iam_policy_document" "firehose_assume_role" {
  statement {
    sid     = "AllowFirehoseToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["firehose.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "firehose" {
  name               = "${local.name_prefix}-firehose-role"
  assume_role_policy = data.aws_iam_policy_document.firehose_assume_role.json

  tags = merge(local.tags, { Name = "${local.name_prefix}-firehose-role" })
}

data "aws_iam_policy_document" "firehose_permissions" {
  statement {
    sid    = "ElasticsearchDelivery"
    effect = "Allow"
    actions = ["es:ESHttp*"]

    resources = [
      aws_opensearch_domain.main.arn,
      "${aws_opensearch_domain.main.arn}/*",
    ]
  }

  statement {
    sid    = "VpcDeliveryNetworkInterfaceManagement"
    effect = "Allow"
    actions = [
      "ec2:CreateNetworkInterface",
      "ec2:DescribeNetworkInterfaces",
      "ec2:DeleteNetworkInterface",
      "ec2:DescribeSubnets",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeVpcs",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "DeliveryLogging"
    effect = "Allow"
    actions = [
      "logs:PutLogEvents",
      "logs:CreateLogStream",
      "logs:DescribeLogStreams",
    ]
    resources = ["${aws_cloudwatch_log_group.firehose.arn}:*"]
  }

  statement {
    sid    = "BackupBucketListAndLocate"
    effect = "Allow"
    actions = [
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]
    resources = [aws_s3_bucket.backup.arn]
  }

  statement {
    sid    = "BackupBucketObjects"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:AbortMultipartUpload",
    ]
    resources = ["${aws_s3_bucket.backup.arn}/*"]
  }
}

resource "aws_iam_role_policy" "firehose" {
  name   = "${local.name_prefix}-firehose-policy"
  role   = aws_iam_role.firehose.name
  policy = data.aws_iam_policy_document.firehose_permissions.json
}

###############################################################################
# KMS customer managed key (OpenSearch encryption at rest + S3 SSE-KMS)
###############################################################################

data "aws_iam_policy_document" "kms_key" {
  statement {
    sid    = "EnableAccountRootPermissions"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowOpenSearchServiceLinkedRoleEncryptionAtRest"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [aws_iam_service_linked_role.opensearch.arn]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:CreateGrant",
      "kms:DescribeKey",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["ec2.${data.aws_region.current.name}.amazonaws.com"]
    }
  }

  statement {
    sid    = "AllowOpenSearchServiceEncryptionAtRest"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["opensearchservice.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["opensearch.${data.aws_region.current.name}.amazonaws.com"]
    }
  }

  statement {
    sid    = "AllowFirehoseRoleS3ServerSideEncryption"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.firehose.arn]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${data.aws_region.current.name}.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "main" {
  description             = "CMK for OpenSearch encryption at rest and Firehose S3 backup SSE-KMS"
  key_usage               = "ENCRYPT_DECRYPT"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  policy                  = data.aws_iam_policy_document.kms_key.json

  tags = merge(local.tags, { Name = "${local.name_prefix}-kms-key" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "main" {
  name          = "alias/${local.name_prefix}-kms"
  target_key_id = aws_kms_key.main.key_id
}

###############################################################################
# OpenSearch domain (inside the VPC, encrypted, least-privilege access policy)
###############################################################################

data "aws_iam_policy_document" "opensearch_access" {
  statement {
    sid     = "AllowFirehoseDeliveryRole"
    effect  = "Allow"
    actions = ["es:ESHttp*"]

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.firehose.arn]
    }

    resources = [
      local.domain_arn,
      "${local.domain_arn}/*",
    ]
  }
}

resource "aws_opensearch_domain" "main" {
  domain_name    = local.domain_name
  engine_version = "OpenSearch_2.11"

  cluster_config {
    instance_type          = "t3.small.search"
    instance_count         = 2
    zone_awareness_enabled = true

    zone_awareness_config {
      availability_zone_count = 2
    }
  }

  vpc_options {
    subnet_ids         = [aws_subnet.private[0].id, aws_subnet.private[1].id]
    security_group_ids = [aws_security_group.elasticsearch.id]
  }

  ebs_options {
    ebs_enabled = true
    volume_type = "gp3"
    volume_size = 20
  }

  encrypt_at_rest {
    enabled    = true
    kms_key_id = aws_kms_key.main.arn
  }

  node_to_node_encryption {
    enabled = true
  }

  domain_endpoint_options {
    enforce_https       = true
    tls_security_policy = "Policy-Min-TLS-1-2-2019-07"
  }

  access_policies = data.aws_iam_policy_document.opensearch_access.json

  tags = merge(local.tags, { Name = "${local.name_prefix}-opensearch" })

  depends_on = [
    aws_iam_service_linked_role.opensearch,
    aws_security_group_rule.opensearch_ingress_from_firehose,
  ]

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# S3 backup bucket for failed documents + Firehose delivery log group
###############################################################################

resource "aws_s3_bucket" "backup" {
  bucket = local.backup_bucket_name

  tags = merge(local.tags, { Name = local.backup_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "backup" {
  bucket = aws_s3_bucket.backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "backup" {
  bucket = aws_s3_bucket.backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.main.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "backup" {
  bucket = aws_s3_bucket.backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_cloudwatch_log_group" "firehose" {
  name              = local.log_group_name
  retention_in_days = 365

  tags = merge(local.tags, { Name = "${local.name_prefix}-firehose-delivery-logs" })
}

###############################################################################
# Kinesis Data Firehose delivery stream (VPC delivery to OpenSearch)
# Per the provider schema, both s3_configuration and vpc_config are nested
# children of elasticsearch_configuration for the "elasticsearch" destination.
###############################################################################

resource "aws_kinesis_firehose_delivery_stream" "to_opensearch" {
  name        = local.stream_name
  destination = "elasticsearch"

  elasticsearch_configuration {
    role_arn              = aws_iam_role.firehose.arn
    domain_arn            = aws_opensearch_domain.main.arn
    index_name            = local.index_name
    index_rotation_period = "OneDay"
    s3_backup_mode        = "FailedDocumentsOnly"
    buffering_size        = 5
    buffering_interval    = 300
    retry_duration        = 300

    cloudwatch_logging_options {
      enabled         = true
      log_group_name  = aws_cloudwatch_log_group.firehose.name
      log_stream_name = "ElasticsearchDelivery"
    }

    s3_configuration {
      role_arn            = aws_iam_role.firehose.arn
      bucket_arn          = aws_s3_bucket.backup.arn
      prefix              = "backup/failed-documents/"
      error_output_prefix = "backup/errors/!{firehose:error-output-type}/"
      buffering_size      = 5
      buffering_interval  = 300
      compression_format  = "GZIP"
      kms_key_arn         = aws_kms_key.main.arn
    }

    vpc_config {
      vpc_id             = aws_vpc.main.id
      subnet_ids         = aws_subnet.private[*].id
      security_group_ids = [aws_security_group.firehose.id]
      role_arn           = aws_iam_role.firehose.arn
    }
  }

  tags = merge(local.tags, { Name = local.stream_name })

  depends_on = [
    aws_iam_role_policy.firehose,
    aws_security_group_rule.opensearch_ingress_from_firehose,
    aws_security_group_rule.firehose_egress_to_opensearch,
  ]

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for tagging (cost allocation and compliance) and resource naming."
  type        = string
  default     = "dev"

  validation {
    condition     = can(regex("^[a-z0-9-]{2,16}$", var.environment))
    error_message = "Environment must be 2-16 lowercase alphanumeric characters or hyphens."
  }
}

locals {
  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# KMS: customer-managed key used to encrypt the Kinesis stream at rest
# -----------------------------------------------------------------------------
resource "aws_kms_key" "kinesis" {
  description             = "Customer-managed key for server-side encryption of the main Kinesis data stream"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, { Name = "kinesis-stream-kms-key" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "kinesis" {
  name          = "alias/kinesis-stream-${var.environment}"
  target_key_id = aws_kms_key.kinesis.key_id
}

# -----------------------------------------------------------------------------
# Kinesis Data Stream (prerequisite for the stream consumer)
# -----------------------------------------------------------------------------
resource "aws_kinesis_stream" "main" {
  name             = "kinesis-stream-${var.environment}"
  shard_count      = 1
  retention_period = 48

  encryption_type = "KMS"
  kms_key_id      = aws_kms_key.kinesis.arn

  stream_mode_details {
    stream_mode = "PROVISIONED"
  }

  tags = merge(local.common_tags, { Name = "kinesis-stream-${var.environment}" })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Kinesis Stream Consumer (enhanced fan-out)
# -----------------------------------------------------------------------------
resource "aws_kinesis_stream_consumer" "main" {
  name       = "main_stream_efo_consumer"
  stream_arn = aws_kinesis_stream.main.arn
}

# -----------------------------------------------------------------------------
# IAM: least-privilege access for consumers of the stream
# -----------------------------------------------------------------------------
resource "aws_iam_role" "stream_consumer" {
  name        = "kinesis-stream-consumer-role-${var.environment}"
  description = "Role assumed by consumers using enhanced fan-out on the main Kinesis stream"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowConsumerServiceToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "kinesis-stream-consumer-role" })
}

resource "aws_iam_policy" "stream_consumer" {
  name        = "kinesis-stream-consumer-policy-${var.environment}"
  description = "Least-privilege permissions for enhanced fan-out consumption of the main Kinesis stream"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SubscribeToShardAndDescribeConsumer"
        Effect = "Allow"
        Action = [
          "kinesis:SubscribeToShard",
          "kinesis:DescribeStreamConsumer"
        ]
        Resource = [
          aws_kinesis_stream.main.arn,
          aws_kinesis_stream_consumer.main.arn
        ]
      },
      {
        Sid    = "ListStreamConsumers"
        Effect = "Allow"
        # kinesis:ListStreamConsumers does not support resource-level
        # permissions, so AWS requires Resource "*". The Action remains
        # tightly scoped, so this is not a wildcard Action/Resource pair.
        Action   = ["kinesis:ListStreamConsumers"]
        Resource = ["*"]
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "kinesis-stream-consumer-policy" })
}

resource "aws_iam_role_policy_attachment" "stream_consumer" {
  role       = aws_iam_role.stream_consumer.name
  policy_arn = aws_iam_policy.stream_consumer.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment label used for resource tagging (non-infrastructure default)."
  type        = string
  default     = "dev"
}

locals {
  app_name    = "kinesis_analytics_app_${var.environment}"
  stream_name = "kinesis_analytics_input_stream_${var.environment}"
  role_name   = "kinesis_analytics_role_${var.environment}"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
    Application = "kinesis-analytics"
  }
}

# ------------------------------------------------------------------
# Input Kinesis stream (stateful - protected from destruction)
# ------------------------------------------------------------------
resource "aws_kinesis_stream" "input_stream" {
  name             = local.stream_name
  shard_count      = 1
  retention_period = 48

  stream_mode_details {
    stream_mode = "PROVISIONED"
  }

  encryption_type = "KMS"

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------
# CloudWatch Logs for the analytics application
# ------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "kinesis_analytics_logs" {
  name              = "/aws/kinesis-analytics/${local.app_name}"
  retention_in_days = 30

  tags = local.common_tags
}

resource "aws_cloudwatch_log_stream" "kinesis_analytics_log_stream" {
  name           = "${local.app_name}-log-stream"
  log_group_name = aws_cloudwatch_log_group.kinesis_analytics_logs.name
}

# ------------------------------------------------------------------
# IAM role and least-privilege policy for the analytics application
# ------------------------------------------------------------------
resource "aws_iam_role" "kinesis_analytics_role" {
  name = local.role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowKinesisAnalyticsAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "kinesis_analytics_policy" {
  name = "${local.role_name}_policy"
  role = aws_iam_role.kinesis_analytics_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ReadInputStream"
        Effect = "Allow"
        Action = [
          "kinesis:DescribeStream",
          "kinesis:DescribeStreamSummary",
          "kinesis:GetRecords",
          "kinesis:GetShardIterator",
          "kinesis:ListShards"
        ]
        Resource = aws_kinesis_stream.input_stream.arn
      },
      {
        Sid    = "WriteApplicationLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents"
        ]
        Resource = [
          "${aws_cloudwatch_log_group.kinesis_analytics_logs.arn}:*",
          aws_cloudwatch_log_stream.kinesis_analytics_log_stream.arn
        ]
      }
    ]
  })
}

# ------------------------------------------------------------------
# Kinesis Analytics (SQL v1) application - SQL runtime is implicit in v1;
# the execution role is supplied per-integration via role_arn references.
# ------------------------------------------------------------------
resource "aws_kinesis_analytics_application" "analytics_app" {
  name        = local.app_name
  description = "Basic SQL Kinesis Analytics application consuming the input Kinesis stream"

  code = <<-SQL
    CREATE OR REPLACE STREAM "DESTINATION_SQL_STREAM" ("payload" VARCHAR(64));

    CREATE OR REPLACE PUMP "STREAM_PUMP" AS
      INSERT INTO "DESTINATION_SQL_STREAM"
      SELECT STREAM "payload" FROM "SOURCE_SQL_STREAM_001";
  SQL

  cloudwatch_logging_options {
    log_stream_arn = aws_cloudwatch_log_stream.kinesis_analytics_log_stream.arn
    role_arn       = aws_iam_role.kinesis_analytics_role.arn
  }

  inputs {
    name_prefix = "SOURCE_SQL_STREAM"

    kinesis_stream {
      resource_arn = aws_kinesis_stream.input_stream.arn
      role_arn     = aws_iam_role.kinesis_analytics_role.arn
    }

    schema {
      record_columns {
        name     = "payload"
        sql_type = "VARCHAR(64)"
        mapping  = "$.payload"
      }

      record_format {
        record_format_type = "JSON"

        mapping_parameters {
          json {
            record_row_path = "$"
          }
        }
      }

      record_encoding = "UTF-8"
    }

    starting_position_configuration {
      starting_position = "LATEST"
    }
  }

  tags = local.common_tags

  depends_on = [aws_iam_role_policy.kinesis_analytics_policy]

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------
output "application_arn" {
  description = "ARN of the Kinesis Analytics application."
  value       = aws_kinesis_analytics_application.analytics_app.arn
}

output "application_name" {
  description = "Name of the Kinesis Analytics application."
  value       = aws_kinesis_analytics_application.analytics_app.name
}

output "cloudwatch_log_stream_arn" {
  description = "ARN of the CloudWatch log stream receiving Kinesis Analytics application logs."
  value       = aws_cloudwatch_log_stream.kinesis_analytics_log_stream.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------

variable "tags" {
  description = "Tags applied to all taggable resources in this configuration."
  type        = map(string)
  default = {
    Project     = "kendra-enterprise-index"
    Environment = "production"
  }
}

# ---------------------------------------------------------------------------
# Static provider metadata lookups (no pre-existing infrastructure required)
# ---------------------------------------------------------------------------

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------

locals {
  common_tags = merge(
    {
      ManagedBy = "terraform"
    },
    var.tags
  )

  kendra_log_group_arn_pattern = "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/kendra/*"
}

# ---------------------------------------------------------------------------
# KMS: customer-managed key used to encrypt the Kendra index at rest
# ---------------------------------------------------------------------------

resource "aws_kms_key" "kendra_index" {
  description             = "Customer-managed KMS key used to encrypt the Amazon Kendra index at rest"
  key_usage               = "ENCRYPT_DECRYPT"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableIAMUserPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowKendraIndexRoleAndService"
        Effect = "Allow"
        Principal = {
          AWS     = aws_iam_role.kendra_index.arn
          Service = "kendra.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey",
          "kms:CreateGrant"
        ]
        Resource = "*"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_kms_alias" "kendra_index" {
  name          = "alias/kendra-index"
  target_key_id = aws_kms_key.kendra_index.key_id
}

# ---------------------------------------------------------------------------
# IAM: service role assumed by Amazon Kendra
# ---------------------------------------------------------------------------

resource "aws_iam_role" "kendra_index" {
  name        = "kendra-index-role"
  description = "Service role assumed by Amazon Kendra to access AWS resources on behalf of the index"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowKendraToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kendra.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "kendra_index_logs" {
  name = "kendra-index-cloudwatch-logs"
  role = aws_iam_role.kendra_index.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "KendraIndexCloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = local.kendra_log_group_arn_pattern
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Kendra index: Enterprise Edition, CMK-encrypted, user group resolution via
# AWS SSO (IAM Identity Center)
# ---------------------------------------------------------------------------

resource "aws_kendra_index" "main" {
  name        = "enterprise-kendra-index"
  description = "Enterprise edition Amazon Kendra index with user group resolution backed by AWS SSO (IAM Identity Center) and customer-managed KMS encryption"
  role_arn    = aws_iam_role.kendra_index.arn
  edition     = "ENTERPRISE_EDITION"

  server_side_encryption_configuration {
    kms_key_id = aws_kms_key.kendra_index.arn
  }

  user_group_resolution_configuration {
    user_group_resolution_mode = "AWS_SSO"
  }

  tags = local.common_tags

  depends_on = [aws_iam_role_policy.kendra_index_logs]

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "domain_name" {
  description = "Domain name for the public hosted zone"
  type        = string
  default     = "example.com"
}

variable "record_name" {
  description = "Subdomain for the failover alias records"
  type        = string
  default     = "www"
}

variable "environment" {
  description = "Environment tag value applied to all resources"
  type        = string
  default     = "production"
}

locals {
  name_prefix = "r53-failover"
  record_fqdn = "${var.record_name}.${var.domain_name}"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# Networking
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-a"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-b"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# Security
# -----------------------------------------------------------------------------

resource "aws_security_group" "alb" {
  name        = "${local.name_prefix}-alb-sg"
  description = "Public web traffic (HTTP/HTTPS) to the failover ALBs"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-alb-sg"
  })
}

# -----------------------------------------------------------------------------
# Failover endpoint targets (Active / Passive ALBs)
# -----------------------------------------------------------------------------

resource "aws_lb" "primary" {
  name               = "${local.name_prefix}-primary"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb.id]
  subnets            = [aws_subnet.public_a.id, aws_subnet.public_b.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-primary-alb"
  })
}

resource "aws_lb" "secondary" {
  name               = "${local.name_prefix}-secondary"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb.id]
  subnets            = [aws_subnet.public_a.id, aws_subnet.public_b.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-secondary-alb"
  })
}

resource "aws_lb_listener" "primary_http" {
  load_balancer_arn = aws_lb.primary.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "fixed-response"

    fixed_response {
      content_type = "text/plain"
      message_body = "OK"
      status_code  = "200"
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-primary-listener"
  })
}

resource "aws_lb_listener" "secondary_http" {
  load_balancer_arn = aws_lb.secondary.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "fixed-response"

    fixed_response {
      content_type = "text/plain"
      message_body = "OK"
      status_code  = "200"
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-secondary-listener"
  })
}

# -----------------------------------------------------------------------------
# DNS: hosted zone, health check, and failover records
# -----------------------------------------------------------------------------

resource "aws_route53_zone" "primary" {
  name = var.domain_name

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-zone"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route53_health_check" "primary_health_check" {
  fqdn              = aws_lb.primary.dns_name
  type              = "HTTP"
  port              = 80
  resource_path     = "/"
  request_interval  = 30
  failure_threshold = 3

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-primary-health-check"
  })
}

resource "aws_route53_record" "failover_primary" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = local.record_fqdn
  type    = "A"

  set_identifier  = "primary"
  health_check_id = aws_route53_health_check.primary_health_check.id

  failover_routing_policy {
    type = "PRIMARY"
  }

  alias {
    name                   = aws_lb.primary.dns_name
    zone_id                = aws_lb.primary.zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "failover_secondary" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = local.record_fqdn
  type    = "A"

  set_identifier = "secondary"

  failover_routing_policy {
    type = "SECONDARY"
  }

  alias {
    name                   = aws_lb.secondary.dns_name
    zone_id                = aws_lb.secondary.zone_id
    evaluate_target_health = true
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "parent_domain" {
  description = "Parent domain name used for the Route 53 public hosted zone (e.g. example.com)."
  type        = string
  default     = "example.com"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023.*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

locals {
  common_tags = {
    Project   = "route53-geolocation-routing"
    ManagedBy = "terraform"
  }
}

resource "aws_route53_zone" "primary" {
  name = var.parent_domain

  tags = merge(local.common_tags, {
    Name = "primary"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "geo-routing-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "geo-routing-igw"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "geo-routing-public"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "geo-routing-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "endpoints" {
  name        = "geo-routing-endpoints"
  description = "Web tier security group for the Route 53 geolocation endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere (web tier)"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere (web tier)"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "geo-routing-endpoints"
  })
}

resource "aws_instance" "us_endpoint" {
  ami                         = data.aws_ami.amazon_linux.id
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.public.id
  vpc_security_group_ids      = [aws_security_group.endpoints.id]
  associate_public_ip_address = true

  user_data = <<-EOF
#!/bin/bash
dnf install -y httpd
echo "<h1>US geolocation endpoint</h1>" > /var/www/html/index.html
systemctl enable --now httpd
EOF

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    encrypted = true
  }

  tags = merge(local.common_tags, {
    Name        = "us-endpoint"
    GeoLocation = "US"
  })
}

resource "aws_instance" "eu_endpoint" {
  ami                         = data.aws_ami.amazon_linux.id
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.public.id
  vpc_security_group_ids      = [aws_security_group.endpoints.id]
  associate_public_ip_address = true

  user_data = <<-EOF
#!/bin/bash
dnf install -y httpd
echo "<h1>EU geolocation endpoint</h1>" > /var/www/html/index.html
systemctl enable --now httpd
EOF

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    encrypted = true
  }

  tags = merge(local.common_tags, {
    Name        = "eu-endpoint"
    GeoLocation = "EU"
  })
}

resource "aws_eip" "us_endpoint" {
  domain   = "vpc"
  instance = aws_instance.us_endpoint.id

  tags = merge(local.common_tags, {
    Name = "us-endpoint-eip"
  })
}

resource "aws_eip" "eu_endpoint" {
  domain   = "vpc"
  instance = aws_instance.eu_endpoint.id

  tags = merge(local.common_tags, {
    Name = "eu-endpoint-eip"
  })
}

resource "aws_route53_health_check" "us" {
  ip_address        = aws_eip.us_endpoint.public_ip
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  request_interval  = 30
  failure_threshold = 3

  tags = merge(local.common_tags, {
    Name = "us-endpoint-health-check"
  })
}

resource "aws_route53_health_check" "eu" {
  ip_address        = aws_eip.eu_endpoint.public_ip
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  request_interval  = 30
  failure_threshold = 3

  tags = merge(local.common_tags, {
    Name = "eu-endpoint-health-check"
  })
}

resource "aws_route53_record" "us" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = aws_route53_zone.primary.name
  type    = "A"
  ttl     = 60

  records         = [aws_eip.us_endpoint.public_ip]
  set_identifier  = "us"
  health_check_id = aws_route53_health_check.us.id

  geolocation_routing_policy {
    continent = "US"
  }
}

resource "aws_route53_record" "eu" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = aws_route53_zone.primary.name
  type    = "A"
  ttl     = 60

  records         = [aws_eip.eu_endpoint.public_ip]
  set_identifier  = "eu"
  health_check_id = aws_route53_health_check.eu.id

  geolocation_routing_policy {
    continent = "EU"
  }
}

resource "aws_route53_record" "default" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = aws_route53_zone.primary.name
  type    = "A"
  ttl     = 60

  records         = [aws_eip.us_endpoint.public_ip]
  set_identifier  = "default"
  health_check_id = aws_route53_health_check.us.id

  geolocation_routing_policy {
    country = "*"
  }
}

output "hosted_zone_id" {
  description = "Hosted zone ID of the primary Route 53 public hosted zone."
  value       = aws_route53_zone.primary.zone_id
}

output "hosted_zone_name_servers" {
  description = "Name servers assigned to the primary hosted zone."
  value       = aws_route53_zone.primary.name_servers
}

output "us_record_fqdn" {
  description = "FQDN of the US geolocation A record."
  value       = aws_route53_record.us.name
}

output "eu_record_fqdn" {
  description = "FQDN of the EU geolocation A record."
  value       = aws_route53_record.eu.name
}

output "default_record_fqdn" {
  description = "FQDN of the default (catch-all) geolocation A record."
  value       = aws_route53_record.default.name
}

###############################################################################
# Terraform + Providers
###############################################################################

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    helm = {
      source  = "hashicorp/helm"
      version = "~> 2.12"
    }
    kubernetes = {
      source  = "hashicorp/kubernetes"
      version = "~> 2.30"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = local.common_tags
  }
}

###############################################################################
# Variables
###############################################################################

variable "enable_ecr_image_lookup" {
  description = "Whether to look up the image tagged 'stable' in the application ECR repository. Disabled by default because a freshly created greenfield repository contains no images yet."
  type        = bool
  default     = false
}

variable "cluster_version" {
  description = "Kubernetes version for the EKS cluster."
  type        = string
  default     = "1.31"
}

variable "node_instance_types" {
  description = "EC2 instance types used by the EKS managed node group."
  type        = list(string)
  default     = ["t3.medium"]
}

variable "node_group_desired_size" {
  description = "Desired number of worker nodes."
  type        = number
  default     = 2

  validation {
    condition     = var.node_group_desired_size >= 1
    error_message = "The node group desired size must be at least 1."
  }
}

variable "node_group_min_size" {
  description = "Minimum number of worker nodes."
  type        = number
  default     = 2

  validation {
    condition     = var.node_group_min_size >= 1
    error_message = "The node group minimum size must be at least 1."
  }
}

variable "node_group_max_size" {
  description = "Maximum number of worker nodes."
  type        = number
  default     = 4

  validation {
    condition     = var.node_group_max_size >= 1
    error_message = "The node group maximum size must be at least 1."
  }
}

variable "eks_endpoint_public_access_cidrs" {
  description = "CIDR blocks allowed to reach the public EKS API endpoint. Must be restricted; 0.0.0.0/0 is deliberately rejected."
  type        = list(string)
  default     = ["10.0.0.0/8"]

  validation {
    condition     = !contains(var.eks_endpoint_public_access_cidrs, "0.0.0.0/0")
    error_message = "The EKS public endpoint must not be open to 0.0.0.0/0; provide a restricted CIDR list."
  }
}

###############################################################################
# Static lookups
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Locals
###############################################################################

locals {
  workspace_name = terraform.workspace
  cluster_name   = "eks-${local.workspace_name}"

  # The ECR lookup is keyed strictly by the "stable" tag (tags map to exactly
  # one image digest), so the resolved tag is deterministically "stable" in
  # both branches. The lookup's real value is confirming the image exists and
  # exposing its digest/URI via the app_image_digest output.
  image_tag = "stable"

  common_tags = {
    Project     = "eks-platform"
    Environment = local.workspace_name
    ManagedBy   = "terraform"
  }

  vpc_cidr             = "10.0.0.0/16"
  public_subnet_cidrs  = ["10.0.1.0/24", "10.0.2.0/24"]
  private_subnet_cidrs = ["10.0.11.0/24", "10.0.12.0/24"]
  azs = [
    data.aws_availability_zones.available.names[0],
    data.aws_availability_zones.available.names[1],
  ]
}

###############################################################################
# KMS keys (cluster secrets encryption + ECR image encryption)
###############################################################################

resource "aws_kms_key" "eks" {
  description             = "EKS ${local.cluster_name} Kubernetes secrets envelope encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, { Name = "${local.cluster_name}-secrets" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "eks" {
  name          = "alias/${local.cluster_name}-secrets"
  target_key_id = aws_kms_key.eks.key_id
}

resource "aws_kms_key" "ecr" {
  description             = "ECR image encryption for the ${local.cluster_name} application repository"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, { Name = "${local.cluster_name}-ecr" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "ecr" {
  name          = "alias/${local.cluster_name}-ecr"
  target_key_id = aws_kms_key.ecr.key_id
}

###############################################################################
# ECR repository (created here — greenfield) + optional image lookup
###############################################################################

resource "aws_ecr_repository" "app" {
  name                 = "${local.cluster_name}-app"
  image_tag_mutability = "MUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  encryption_configuration {
    encryption_type = "KMS"
    kms_key         = aws_kms_key.ecr.arn
  }

  tags = merge(local.common_tags, { Name = "${local.cluster_name}-app" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ecr_lifecycle_policy" "app" {
  repository = aws_ecr_repository.app.name

  policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Expire untagged images older than 14 days"
        selection = {
          tagStatus   = "untagged"
          countType   = "sinceImagePushed"
          countUnit   = "days"
          countNumber = 14
        }
        action = {
          type = "expire"
        }
      }
    ]
  })
}

data "aws_ecr_image" "stable" {
  count = var.enable_ecr_image_lookup ? 1 : 0

  repository_name = aws_ecr_repository.app.name
  image_tag       = "stable"

  depends_on = [aws_ecr_repository.app]
}

###############################################################################
# Networking foundation
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name                                          = "${local.cluster_name}-vpc"
      "kubernetes.io/cluster/${local.cluster_name}" = "shared"
    },
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.cluster_name}-igw" })
}

resource "aws_subnet" "public" {
  count = length(local.public_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name                                          = "${local.cluster_name}-public-${format("%02d", count.index + 1)}"
      "kubernetes.io/cluster/${local.cluster_name}" = "shared"
      "kubernetes.io/role/elb"                      = "1"
    },
  )
}

resource "aws_subnet" "private" {
  count = length(local.private_subnet_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = merge(
    local.common_tags,
    {
      Name                                          = "${local.cluster_name}-private-${format("%02d", count.index + 1)}"
      "kubernetes.io/cluster/${local.cluster_name}" = "shared"
      "kubernetes.io/role/internal-elb"             = "1"
    },
  )
}

resource "aws_eip" "nat" {
  count = length(local.private_subnet_cidrs)

  domain = "vpc"

  tags = merge(local.common_tags, { Name = "${local.cluster_name}-nat-${format("%02d", count.index + 1)}" })
}

resource "aws_nat_gateway" "main" {
  count = length(local.private_subnet_cidrs)

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(local.common_tags, { Name = "${local.cluster_name}-nat-${format("%02d", count.index + 1)}" })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "${local.cluster_name}-public" })
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  count = length(local.private_subnet_cidrs)

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = merge(local.common_tags, { Name = "${local.cluster_name}-private-${format("%02d", count.index + 1)}" })
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

###############################################################################
# IAM — cluster role, node role, least-privilege ECR pull policy
###############################################################################

data "aws_iam_policy_document" "eks_cluster_assume_role" {
  statement {
    sid     = "AllowEKSToAssumeClusterRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eks_cluster" {
  name               = "${local.cluster_name}-cluster-role"
  description        = "IAM role assumed by the ${local.cluster_name} EKS control plane"
  assume_role_policy = data.aws_iam_policy_document.eks_cluster_assume_role.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "cluster_policy" {
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster.name
}

data "aws_iam_policy_document" "eks_node_assume_role" {
  statement {
    sid     = "AllowEC2ToAssumeNodeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eks_node" {
  name               = "${local.cluster_name}-node-role"
  description        = "IAM role assumed by ${local.cluster_name} managed worker nodes"
  assume_role_policy = data.aws_iam_policy_document.eks_node_assume_role.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "node_worker_policy" {
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  role       = aws_iam_role.eks_node.name
}

resource "aws_iam_role_policy_attachment" "node_cni_policy" {
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKS_CNI_Policy"
  role       = aws_iam_role.eks_node.name
}

data "aws_iam_policy_document" "node_ecr_pull" {
  statement {
    sid       = "GetECRAuthorizationToken"
    effect    = "Allow"
    actions   = ["ecr:GetAuthorizationToken"]
    resources = ["*"]
  }

  statement {
    sid    = "PullImagesFromApplicationRepository"
    effect = "Allow"
    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage",
    ]
    resources = [aws_ecr_repository.app.arn]
  }

  statement {
    sid       = "DecryptKmsEncryptedImages"
    effect    = "Allow"
    actions   = ["kms:Decrypt"]
    resources = [aws_kms_key.ecr.arn]
  }
}

resource "aws_iam_policy" "node_ecr_pull" {
  name        = "${local.cluster_name}-ecr-pull"
  description = "Least-privilege image pull access scoped to the ${local.cluster_name} application repository"
  policy      = data.aws_iam_policy_document.node_ecr_pull.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "node_ecr_pull" {
  policy_arn = aws_iam_policy.node_ecr_pull.arn
  role       = aws_iam_role.eks_node.name
}

###############################################################################
# EKS cluster
###############################################################################

module "eks" {
  source  = "terraform-aws-modules/eks/aws"
  version = "~> 20.0"

  cluster_name    = local.cluster_name
  cluster_version = var.cluster_version

  vpc_id                   = aws_vpc.main.id
  subnet_ids               = aws_subnet.private[*].id
  control_plane_subnet_ids = aws_subnet.private[*].id

  cluster_endpoint_private_access      = true
  cluster_endpoint_public_access       = true
  cluster_endpoint_public_access_cidrs = var.eks_endpoint_public_access_cidrs

  enable_irsa = true

  authentication_mode                      = "API_AND_CONFIG_MAP"
  enable_cluster_creator_admin_permissions = true

  create_kms_key = false

  cluster_encryption_config = {
    provider_key_arn = aws_kms_key.eks.arn
    resources        = ["secrets"]
  }

  cluster_enabled_log_types = ["api", "audit", "authenticator", "controllerManager", "scheduler"]

  create_iam_role = false
  iam_role_arn    = aws_iam_role.eks_cluster.arn

  cluster_addons = {
    vpc-cni = {
      most_recent    = true
      before_compute = true
    }
    coredns = {
      most_recent = true
    }
    kube-proxy = {
      most_recent = true
    }
  }

  eks_managed_node_group_defaults = {
    create_iam_role = false
    iam_role_arn    = aws_iam_role.eks_node.arn
    instance_types  = var.node_instance_types

    metadata_options = {
      http_endpoint = "enabled"
      http_tokens   = "required"
    }

    block_device_mappings = {
      xvda = {
        device_name = "/dev/xvda"
        ebs = {
          volume_size           = 50
          volume_type           = "gp3"
          encrypted             = true
          delete_on_termination = true
        }
      }
    }
  }

  eks_managed_node_groups = {
    general = {
      name         = "${local.cluster_name}-general"
      desired_size = var.node_group_desired_size
      min_size     = var.node_group_min_size
      max_size     = var.node_group_max_size
      subnet_ids   = aws_subnet.private[*].id
    }
  }

  tags = local.common_tags

  depends_on = [
    aws_iam_role_policy_attachment.cluster_policy,
    aws_iam_role_policy_attachment.node_worker_policy,
    aws_iam_role_policy_attachment.node_cni_policy,
    aws_iam_role_policy_attachment.node_ecr_pull,
    aws_route_table_association.public,
    aws_route_table_association.private,
  ]
}

###############################################################################
# Post-provision cluster data sources (explicit depends_on avoids the
# authentication-token race on first apply)
###############################################################################

data "aws_eks_cluster" "main" {
  name = module.eks.cluster_name

  depends_on = [module.eks]
}

data "aws_eks_cluster_auth" "main" {
  name = module.eks.cluster_name

  depends_on = [module.eks]
}

###############################################################################
# Kubernetes + Helm providers for cluster communication
###############################################################################

provider "kubernetes" {
  host                   = data.aws_eks_cluster.main.endpoint
  cluster_ca_certificate = base64decode(data.aws_eks_cluster.main.certificate_authority[0].data)
  token                  = data.aws_eks_cluster_auth.main.token
}

provider "helm" {
  load_config_file = false

  kubernetes {
    host                   = data.aws_eks_cluster.main.endpoint
    cluster_ca_certificate = base64decode(data.aws_eks_cluster.main.certificate_authority[0].data)
    token                  = data.aws_eks_cluster_auth.main.token
  }
}

###############################################################################
# Outputs
###############################################################################

output "cluster_name" {
  description = "Name of the EKS cluster."
  value       = module.eks.cluster_name
}

output "cluster_endpoint" {
  description = "Endpoint of the EKS Kubernetes API server."
  value       = module.eks.cluster_endpoint
}

output "app_image_tag" {
  description = "Application image tag deployed from the ECR repository."
  value       = local.image_tag
}

output "app_image_digest" {
  description = "Digest of the fetched 'stable' image, or null when the image lookup is disabled."
  value       = var.enable_ecr_image_lookup ? data.aws_ecr_image.stable[0].image_digest : null
}

output "ecr_repository_url" {
  description = "URL of the application ECR repository."
  value       = aws_ecr_repository.app.repository_url
}

output "ecr_registry_url" {
  description = "ECR registry endpoint for the current AWS account."
  value       = "${data.aws_caller_identity.current.account_id}.dkr.ecr.${data.aws_region.current.name}.amazonaws.com"
}

output "configure_kubectl" {
  description = "Command to configure kubectl for this cluster."
  value       = "aws eks update-kubeconfig --region ${data.aws_region.current.name} --name ${module.eks.cluster_name}"
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables (non-infrastructure metadata only)
# -----------------------------------------------------------------------------

variable "project" {
  description = "Project name applied as a tag to all resources."
  type        = string
  default     = "example"
}

variable "environment" {
  description = "Environment name applied as a tag to all resources."
  type        = string
  default     = "dev"
}

# -----------------------------------------------------------------------------
# Static provider metadata lookups (permitted data sources only)
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  cluster_name = "${var.project}-${var.environment}-eks-cluster"

  oidc_issuer = replace(aws_eks_cluster.main.identity[0].oidc[0].issuer, "https://", "")

  common_tags = {
    Project     = var.project
    Environment = var.environment
    ManagedBy   = "terraform"
  }

  cluster_tags = merge(local.common_tags, {
    "kubernetes.io/cluster/${local.cluster_name}" = "shared"
  })
}

# -----------------------------------------------------------------------------
# Networking — dedicated VPC for the EKS cluster
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.cluster_tags, {
    Name = "${local.cluster_name}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-igw"
  })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = merge(local.cluster_tags, {
    "kubernetes.io/role/elb" = "1"
    Name                     = "${local.cluster_name}-public-a"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = true

  tags = merge(local.cluster_tags, {
    "kubernetes.io/role/elb" = "1"
    Name                     = "${local.cluster_name}-public-b"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-public-rt"
  })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# IAM — EKS cluster role (least privilege, eks.amazonaws.com trust only)
# -----------------------------------------------------------------------------

resource "aws_iam_role" "eks_cluster" {
  name = "${local.cluster_name}-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEKSServiceToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSClusterPolicy"
}

# -----------------------------------------------------------------------------
# EKS Cluster
# -----------------------------------------------------------------------------

resource "aws_eks_cluster" "main" {
  name     = local.cluster_name
  role_arn = aws_iam_role.eks_cluster.arn

  vpc_config {
    subnet_ids              = [aws_subnet.public_a.id, aws_subnet.public_b.id]
    endpoint_public_access  = true
    endpoint_private_access = false
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy
  ]

  tags = local.cluster_tags

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# OIDC provider for IRSA (used by the vpc-cni addon service account)
# -----------------------------------------------------------------------------

resource "aws_iam_openid_connect_provider" "eks" {
  url             = aws_eks_cluster.main.identity[0].oidc[0].issuer
  client_id_list  = ["sts.amazonaws.com"]
  thumbprint_list = ["9e99a48a9960b14926bb7f3b02e22da2b0ab7280"]

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# IAM — vpc-cni addon role (IRSA, scoped to kube-system/aws-node only)
# -----------------------------------------------------------------------------

resource "aws_iam_role" "vpc_cni" {
  name = "${local.cluster_name}-vpc-cni-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowVpcCniServiceAccountToAssumeRole"
        Effect = "Allow"
        Principal = {
          Federated = aws_iam_openid_connect_provider.eks.arn
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "${local.oidc_issuer}:sub" = "system:serviceaccount:kube-system:aws-node"
            "${local.oidc_issuer}:aud" = "sts.amazonaws.com"
          }
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "vpc_cni_policy" {
  role       = aws_iam_role.vpc_cni.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKS_CNI_Policy"
}

# -----------------------------------------------------------------------------
# EKS Addon — vpc-cni ("example")
# -----------------------------------------------------------------------------

resource "aws_eks_addon" "example" {
  cluster_name             = aws_eks_cluster.main.name
  addon_name               = "vpc-cni"
  service_account_role_arn = aws_iam_role.vpc_cni.arn
  resolve_conflicts        = "OVERWRITE"

  depends_on = [
    aws_eks_cluster.main,
    aws_subnet.public_a,
    aws_subnet.public_b,
    aws_iam_openid_connect_provider.eks,
    aws_iam_role.vpc_cni,
    aws_iam_role_policy_attachment.vpc_cni_policy
  ]

  tags = local.common_tags
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "oidc_client_id" {
  description = "Client ID registered in the external OIDC identity provider that EKS will trust."
  type        = string
  default     = "example-client-id"
}

variable "oidc_identity_provider_config_name" {
  description = "Name of the OIDC identity provider configuration as registered on the EKS cluster."
  type        = string
  default     = "example-idp"
}

variable "oidc_issuer_url" {
  description = "HTTPS URL of a publicly reachable OIDC issuer. EKS validates the .well-known/openid-configuration discovery endpoint at association time."
  type        = string
  default     = "https://accounts.google.com"

  validation {
    condition     = can(regex("^https://[A-Za-z0-9.-]+", var.oidc_issuer_url))
    error_message = "The oidc_issuer_url value must be an HTTPS URL pointing to a publicly reachable OIDC issuer."
  }
}

variable "tags" {
  description = "Additional tags applied to the VPC, subnets, KMS key, EKS cluster, and identity provider configuration."
  type        = map(string)
  default     = {}
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  cluster_name    = "example"
  cluster_tag_key = "kubernetes.io/cluster/${local.cluster_name}"

  subnet_tags = merge(var.tags, {
    (local.cluster_tag_key)  = "shared"
    "kubernetes.io/role/elb" = "1"
  })
}

# -----------------------------------------------------------------------------
# Network foundation
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, {
    Name = "${local.cluster_name}-vpc"
  })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.subnet_tags, {
    Name = "${local.cluster_name}-public-${count.index + 1}"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "${local.cluster_name}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(var.tags, {
    Name = "${local.cluster_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# EKS cluster IAM role
# -----------------------------------------------------------------------------

resource "aws_iam_role" "eks_cluster" {
  name = "${local.cluster_name}-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "cluster_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "vpc_resource_controller" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
}

# -----------------------------------------------------------------------------
# KMS key for Kubernetes secrets encryption
# -----------------------------------------------------------------------------

resource "aws_kms_key" "secrets" {
  description             = "KMS key used to encrypt Kubernetes secrets for the ${local.cluster_name} EKS cluster"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(var.tags, {
    Name = "${local.cluster_name}-secrets-key"
  })
}

# -----------------------------------------------------------------------------
# EKS cluster
# -----------------------------------------------------------------------------

resource "aws_eks_cluster" "example" {
  name     = local.cluster_name
  role_arn = aws_iam_role.eks_cluster.arn

  vpc_config {
    subnet_ids              = aws_subnet.public[*].id
    endpoint_private_access = true
    endpoint_public_access  = true
  }

  encryption_config {
    resources = ["secrets"]

    provider {
      key_arn = aws_kms_key.secrets.arn
    }
  }

  enabled_cluster_log_types = ["api", "audit", "authenticator", "controllerManager", "scheduler"]

  depends_on = [
    aws_iam_role_policy_attachment.cluster_policy,
    aws_iam_role_policy_attachment.vpc_resource_controller,
  ]

  tags = merge(var.tags, {
    Name = local.cluster_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# External OIDC identity provider association (NOT aws_iam_openid_connect_provider)
# -----------------------------------------------------------------------------

resource "aws_eks_identity_provider_config" "example" {
  cluster_name = aws_eks_cluster.example.name

  oidc {
    client_id                     = var.oidc_client_id
    identity_provider_config_name = var.oidc_identity_provider_config_name
    issuer_url                    = var.oidc_issuer_url
  }

  tags = var.tags
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "cluster_name" {
  description = "Name of the EKS cluster."
  value       = aws_eks_cluster.example.name
}

output "cluster_endpoint" {
  description = "Endpoint for the EKS cluster API server."
  value       = aws_eks_cluster.example.endpoint
}

output "oidc_identity_provider_config_name" {
  description = "Name of the OIDC identity provider configuration associated with the cluster."
  value       = aws_eks_identity_provider_config.example.oidc[0].identity_provider_config_name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  cluster_name = "demo"
  environment  = "demo"
}

# -----------------------------------------------------------------------------
# Data sources (static / well-known lookups only)
# -----------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_iam_policy_document" "eks_cluster_assume_role" {
  statement {
    sid     = "AllowEKSToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

# -----------------------------------------------------------------------------
# IAM: EKS cluster role
# -----------------------------------------------------------------------------
resource "aws_iam_role" "demo" {
  name               = "eks-cluster-demo"
  assume_role_policy = data.aws_iam_policy_document.eks_cluster_assume_role.json

  tags = {
    Name        = "eks-cluster-demo"
    Environment = local.environment
  }
}

resource "aws_iam_role_policy_attachment" "demo_cluster_policy" {
  role       = aws_iam_role.demo.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

# -----------------------------------------------------------------------------
# Networking: VPC, subnets, internet gateway, routing
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "${local.cluster_name}-vpc"
    Environment = local.environment
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "${local.cluster_name}-igw"
    Environment = local.environment
  }
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name                                          = "${local.cluster_name}-public-a"
    Environment                                   = local.environment
    "kubernetes.io/cluster/${local.cluster_name}" = "shared"
    "kubernetes.io/role/elb"                      = "1"
  }
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = {
    Name                                          = "${local.cluster_name}-public-b"
    Environment                                   = local.environment
    "kubernetes.io/cluster/${local.cluster_name}" = "shared"
    "kubernetes.io/role/elb"                      = "1"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name        = "${local.cluster_name}-public-rt"
    Environment = local.environment
  }
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# EKS cluster
# -----------------------------------------------------------------------------
resource "aws_eks_cluster" "demo" {
  name     = "demo"
  role_arn = aws_iam_role.demo.arn

  vpc_config {
    subnet_ids              = [aws_subnet.public_a.id, aws_subnet.public_b.id]
    endpoint_public_access  = true
    endpoint_private_access = false
  }

  # Ensure the IAM policy attachment has fully propagated before the
  # EKS control plane is created, otherwise cluster creation can fail
  # with an "unauthorized operation" error.
  depends_on = [aws_iam_role_policy_attachment.demo_cluster_policy]

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name        = "demo"
    Environment = local.environment
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "cluster_endpoint" {
  description = "Endpoint for the demo EKS cluster Kubernetes API server."
  value       = aws_eks_cluster.demo.endpoint
}

output "cluster_name" {
  description = "Name of the demo EKS cluster."
  value       = aws_eks_cluster.demo.name
}

output "cluster_iam_role_arn" {
  description = "ARN of the IAM role assumed by the EKS cluster control plane."
  value       = aws_iam_role.demo.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# S3 bucket names cannot contain underscores, so derive an S3-compliant,
# globally unique physical name from the requested "my_bucket".
resource "random_id" "bucket_suffix" {
  byte_length = 4
}

resource "aws_s3_bucket" "my_bucket" {
  bucket        = "my-bucket-${random_id.bucket_suffix.hex}"
  force_destroy = true

  tags = {
    Name = "my-bucket-${random_id.bucket_suffix.hex}"
  }
}

resource "aws_s3_bucket_public_access_block" "my_bucket" {
  bucket = aws_s3_bucket.my_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "my_bucket" {
  bucket = aws_s3_bucket.my_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "my_bucket" {
  bucket = aws_s3_bucket.my_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

# Bucket-level request metrics with no filter predicate,
# so it monitors the entire bucket's activity.
resource "aws_s3_bucket_metric" "my_bucket_metric" {
  bucket = aws_s3_bucket.my_bucket.id
  name   = "my_bucket_metric"
}

resource "aws_s3_object" "my_object" {
  bucket  = aws_s3_bucket.my_bucket.id
  key     = "data/my_object.txt"
  content = "Hello from my_object! This is the content stored in the S3 bucket."
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "bucket_tags" {
  description = "Tags to apply to the platform infrastructure bucket."
  type        = map(string)
  default = {
    Name = "wellcomecollection-platform-infra"
  }
}

resource "aws_s3_bucket" "platform_infra" {
  bucket = "wellcomecollection-platform-infra"

  tags = var.bucket_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "platform_infra" {
  bucket = aws_s3_bucket.platform_infra.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "platform_infra" {
  bucket = aws_s3_bucket.platform_infra.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "platform_infra" {
  bucket = aws_s3_bucket.platform_infra.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "platform_infra" {
  bucket = aws_s3_bucket.platform_infra.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "platform_infra" {
  bucket = aws_s3_bucket.platform_infra.id

  depends_on = [aws_s3_bucket_versioning.platform_infra]

  rule {
    id     = "expire-tmp-objects"
    status = "Enabled"

    filter {
      prefix = "tmp/"
    }

    expiration {
      days = 30
    }
  }

  rule {
    id     = "transition-and-expire-noncurrent-versions"
    status = "Enabled"

    filter {}

    noncurrent_version_transition {
      noncurrent_days = 30
      storage_class   = "STANDARD_IA"
    }

    noncurrent_version_expiration {
      noncurrent_days = 90
    }
  }
}

