terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "bucket_name" {
  description = "Globally unique S3 bucket name for event log storage"
  type        = string
  default     = "your-bucket-name"
}

output "bucket_arn" {
  description = "ARN of the event log S3 bucket"
  value       = aws_s3_bucket.event_logs.arn
}

output "sns_topic_arn" {
  description = "ARN of the S3 event notification SNS topic"
  value       = aws_sns_topic.s3_event_notification.arn
}

resource "aws_s3_bucket" "event_logs" {
  bucket = var.bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "event_logs" {
  bucket = aws_s3_bucket.event_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "event_logs" {
  bucket = aws_s3_bucket.event_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "event_logs" {
  bucket = aws_s3_bucket.event_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_sns_topic" "s3_event_notification" {
  name              = "s3-event-notification-topic"
  kms_master_key_id = "alias/aws/sns"

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "s3_event_notification" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = [
      "sns:Publish",
    ]

    resources = [
      aws_sns_topic.s3_event_notification.arn,
    ]

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [aws_s3_bucket.event_logs.arn]
    }
  }
}

resource "aws_sns_topic_policy" "s3_event_notification" {
  arn    = aws_sns_topic.s3_event_notification.arn
  policy = data.aws_iam_policy_document.s3_event_notification.json
}

resource "aws_s3_bucket_notification" "event_logs" {
  bucket = aws_s3_bucket.event_logs.id

  topic {
    topic_arn     = aws_sns_topic.s3_event_notification.arn
    events        = ["s3:ObjectCreated:*"]
    filter_suffix = ".log"
  }

  depends_on = [aws_sns_topic_policy.s3_event_notification]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "bucket_name_prefix" {
  description = "Prefix used to derive the globally unique names of the S3 buckets."
  type        = string
  default     = "tf-s3-access-logs"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9-]{1,48}[a-z0-9]$", var.bucket_name_prefix))
    error_message = "Prefix must be 3-50 lowercase alphanumeric characters or hyphens, starting and ending with an alphanumeric character."
  }
}

locals {
  app_bucket_name = "${var.bucket_name_prefix}-app-${random_string.bucket_suffix.result}"
  log_bucket_name = "${var.bucket_name_prefix}-logs-${random_string.bucket_suffix.result}"
  log_file_prefix = "app-logs/"
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
  upper   = false
  lower   = true
  numeric = true
}

# -----------------------------------------------------------------------------
# Source bucket (private) - the bucket whose server access logs are delivered
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "app_bucket" {
  bucket = local.app_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

# "Private" ACL requirement implemented via BucketOwnerEnforced ownership
# controls: ACLs are disabled entirely, so no ACL grants (public or otherwise)
# can exist. Combined with the public access block below, the bucket is fully
# private without the deprecated aws_s3_bucket_acl resource.
resource "aws_s3_bucket_ownership_controls" "app_bucket" {
  bucket = aws_s3_bucket.app_bucket.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "app_bucket" {
  bucket = aws_s3_bucket.app_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "app_bucket" {
  bucket = aws_s3_bucket.app_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "app_bucket" {
  bucket = aws_s3_bucket.app_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

# -----------------------------------------------------------------------------
# Destination bucket (log-delivery-write) - receives the app bucket's logs
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "log_bucket" {
  bucket = local.log_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "log_bucket" {
  bucket = aws_s3_bucket.log_bucket.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "log_bucket" {
  bucket = aws_s3_bucket.log_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "log_bucket" {
  bucket = aws_s3_bucket.log_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "log_bucket" {
  bucket = aws_s3_bucket.log_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

# "Log-delivery-write" ACL requirement implemented as a least-privilege bucket
# policy granting the S3 log delivery service principal only the permissions
# it needs, constrained to writes originating from the app bucket and carrying
# the bucket-owner-full-control canned ACL.
resource "aws_s3_bucket_policy" "log_bucket" {
  bucket = aws_s3_bucket.log_bucket.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "S3LogDeliveryAclCheck"
        Effect    = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action   = "s3:GetBucketAcl"
        Resource = aws_s3_bucket.log_bucket.arn
        Condition = {
          ArnLike = {
            "aws:SourceArn" = aws_s3_bucket.app_bucket.arn
          }
        }
      },
      {
        Sid       = "S3LogDeliveryWrite"
        Effect    = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.log_bucket.arn}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
          ArnLike = {
            "aws:SourceArn" = aws_s3_bucket.app_bucket.arn
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Server access logging: app_bucket delivers its logs into log_bucket
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_logging" "app_bucket" {
  bucket = aws_s3_bucket.app_bucket.id

  target_bucket = aws_s3_bucket.log_bucket.id
  target_prefix = local.log_file_prefix

  depends_on = [
    aws_s3_bucket_policy.log_bucket,
    aws_s3_bucket_ownership_controls.app_bucket,
    aws_s3_bucket_ownership_controls.log_bucket,
  ]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }
}

output "latest_amazon_linux_2_ami_id" {
  description = "The AMI ID of the latest Amazon Linux 2 HVM EBS-backed image owned by Amazon."
  value       = data.aws_ami.amazon_linux_2.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# Static provider metadata lookups (no dependency on pre-existing resources)
# ---------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "al2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

locals {
  environment = "production"

  common_tags = {
    Environment = local.environment
    ManagedBy   = "terraform"
  }
}

# ---------------------------------------------------------------------------
# Networking: VPC, internet gateway, subnets, NAT, routing
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "three-tier-web-vpc"
    Tier = "web"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "three-tier-web-igw"
    Tier = "web"
  })
}

# Public subnet (web tier) in the first available AZ
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "three-tier-web-public-subnet"
    Tier = "web"
  })
}

# Private subnet (application tier) in the first available AZ
resource "aws_subnet" "app" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = "10.0.11.0/24"
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "three-tier-app-private-subnet"
    Tier = "app"
  })
}

# Private subnet (database tier) in the second available AZ
resource "aws_subnet" "db" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = "10.0.12.0/24"
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "three-tier-db-private-subnet"
    Tier = "database"
  })
}

# EIP + NAT gateway so private tiers can reach the internet for
# patches/updates with zero inbound exposure
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "three-tier-web-nat-eip"
    Tier = "web"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, {
    Name = "three-tier-web-nat-gateway"
    Tier = "web"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "three-tier-web-public-rt"
    Tier = "web"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "three-tier-app-private-rt"
    Tier = "app"
  })
}

resource "aws_route_table_association" "app" {
  subnet_id      = aws_subnet.app.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "db" {
  subnet_id      = aws_subnet.db.id
  route_table_id = aws_route_table.private.id
}

# ---------------------------------------------------------------------------
# Security groups (least privilege, tier-to-tier references only)
# ---------------------------------------------------------------------------
resource "aws_security_group" "web" {
  name        = "three-tier-web-sg"
  description = "Web tier: HTTP and HTTPS from the internet only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "three-tier-web-sg"
    Tier = "web"
  })
}

resource "aws_security_group" "app" {
  name        = "three-tier-app-sg"
  description = "Application tier: port 8080 from the web tier only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Application port from web tier only"
    from_port       = 8080
    to_port         = 8080
    protocol        = "tcp"
    security_groups = [aws_security_group.web.id]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "three-tier-app-sg"
    Tier = "app"
  })
}

resource "aws_security_group" "rds" {
  name        = "three-tier-db-sg"
  description = "Database tier: MySQL from the application tier only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "MySQL from app tier only"
    from_port       = 3306
    to_port         = 3306
    protocol        = "tcp"
    security_groups = [aws_security_group.app.id]
  }

  tags = merge(local.common_tags, {
    Name = "three-tier-db-sg"
    Tier = "database"
  })
}

# ---------------------------------------------------------------------------
# IAM: SSM Session Manager access (no SSH key pairs required)
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ec2_ssm" {
  name = "three-tier-ec2-ssm-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "three-tier-ec2-ssm-role"
  })
}

resource "aws_iam_role_policy_attachment" "ec2_ssm" {
  role       = aws_iam_role.ec2_ssm.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ec2" {
  name = "three-tier-ec2-instance-profile"
  role = aws_iam_role.ec2_ssm.name
}

# ---------------------------------------------------------------------------
# Web tier EC2 (public subnet, nginx)
# ---------------------------------------------------------------------------
resource "aws_instance" "web" {
  ami                         = data.aws_ami.al2023.id
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.public.id
  associate_public_ip_address = true
  vpc_security_group_ids      = [aws_security_group.web.id]
  iam_instance_profile        = aws_iam_instance_profile.ec2.name

  depends_on = [aws_iam_role_policy_attachment.ec2_ssm]

  user_data = <<-EOF
    #!/bin/bash
    dnf install -y nginx
    systemctl enable nginx
    systemctl start nginx
    echo "<h1>three-tier-web: nginx is running</h1>" > /usr/share/nginx/html/index.html
  EOF

  root_block_device {
    volume_size = 20
    volume_type = "gp3"
    encrypted   = true
  }

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  tags = merge(local.common_tags, {
    Name = "three-tier-web-server"
    Tier = "web"
  })
}

# ---------------------------------------------------------------------------
# Application tier EC2 (private subnet, application on port 8080)
# ---------------------------------------------------------------------------
resource "aws_instance" "app" {
  ami                         = data.aws_ami.al2023.id
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.app.id
  associate_public_ip_address = false
  vpc_security_group_ids      = [aws_security_group.app.id]
  iam_instance_profile        = aws_iam_instance_profile.ec2.name

  depends_on = [aws_iam_role_policy_attachment.ec2_ssm]

  user_data = <<-EOF
    #!/bin/bash
    dnf install -y python3
    mkdir -p /opt/three-tier-app
    cat > /opt/three-tier-app/server.py <<'PYEOF'
    from http.server import BaseHTTPRequestHandler, HTTPServer
    import json

    class AppHandler(BaseHTTPRequestHandler):
        def do_GET(self):
            body = json.dumps({"service": "three-tier-app", "status": "healthy"}).encode()
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

    HTTPServer(("0.0.0.0", 8080), AppHandler).serve_forever()
    PYEOF
    cat > /etc/systemd/system/three-tier-app.service <<'SVCEOF'
    [Unit]
    Description=Three-tier application server
    After=network-online.target

    [Service]
    Type=simple
    ExecStart=/usr/bin/python3 /opt/three-tier-app/server.py
    Restart=always
    User=ec2-user

    [Install]
    WantedBy=multi-user.target
    SVCEOF
    systemctl daemon-reload
    systemctl enable --now three-tier-app
  EOF

  root_block_device {
    volume_size = 20
    volume_type = "gp3"
    encrypted   = true
  }

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  tags = merge(local.common_tags, {
    Name = "three-tier-app-server"
    Tier = "app"
  })
}

# ---------------------------------------------------------------------------
# Database tier: credentials, subnet group, RDS MySQL
# ---------------------------------------------------------------------------
resource "random_password" "db_master" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}:?"
}

resource "random_id" "db_final_snapshot" {
  byte_length = 4
}

# AWS requires subnets in at least two AZs for RDS; the database tier is
# logically hosted in the second private subnet (aws_subnet.db).
resource "aws_db_subnet_group" "main" {
  name       = "three-tier-db-subnet-group"
  subnet_ids = [aws_subnet.app.id, aws_subnet.db.id]

  tags = merge(local.common_tags, {
    Name = "three-tier-db-subnet-group"
    Tier = "database"
  })
}

resource "aws_db_instance" "main" {
  identifier     = "three-tier-db"
  engine         = "mysql"
  engine_version = "8.0"
  instance_class = "db.t3.micro"

  allocated_storage = 20
  storage_type      = "gp3"
  storage_encrypted = true

  db_name  = "threetierdb"
  username = "dbadmin"
  password = random_password.db_master.result

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  publicly_accessible = false
  multi_az            = false

  backup_retention_period = 7
  copy_tags_to_snapshot   = true

  skip_final_snapshot       = false
  final_snapshot_identifier = "three-tier-db-final-${random_id.db_final_snapshot.hex}"
  deletion_protection       = true

  tags = merge(local.common_tags, {
    Name = "three-tier-db"
    Tier = "database"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret" "db_master" {
  name        = "three-tier-db-master-credentials"
  description = "Master credentials for the three-tier RDS MySQL database"

  tags = merge(local.common_tags, {
    Name = "three-tier-db-master-credentials"
    Tier = "database"
  })
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    username = aws_db_instance.main.username
    password = random_password.db_master.result
    engine   = aws_db_instance.main.engine
    host     = aws_db_instance.main.address
    port     = aws_db_instance.main.port
    dbname   = aws_db_instance.main.db_name
  })
}

# Redis (ElastiCache) — single-node cluster, encrypted in transit (TLS) and at rest.
#
# Client connectivity notes:
#   * Connect to the primary endpoint on port 6379 using TLS (rediss://).
#   * Authenticate with the AUTH token stored in Secrets Manager
#     (see the redis_auth_secret_arn output). The token value is never
#     hardcoded in this configuration or exposed in its outputs.

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables (defaults keep `terraform apply` fully non-interactive)
###############################################################################

variable "project_name" {
  description = "Base name used to derive resource names and the Name tag."
  type        = string
  default     = "redis"
}

variable "environment" {
  description = "Value applied to the Environment tag on every resource."
  type        = string
  default     = "production"
}

###############################################################################
# Locals
###############################################################################

locals {
  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

###############################################################################
# Networking — Redis network foundation
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-vpc"
  })
}

# Two private subnets across distinct AZs — ElastiCache subnet groups require
# subnets in at least two availability zones.
resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-private-${count.index + 1}"
  })
}

###############################################################################
# Security group — ingress limited to Redis (TCP 6379) sourced from the VPC
# CIDR only. No 0.0.0.0/0 ingress rule is declared for port 6379 (or any
# other port). Egress is unrestricted.
###############################################################################

resource "aws_security_group" "redis" {
  name        = "${var.project_name}-cache-sg"
  description = "Permits inbound Redis traffic (TCP 6379) only from inside the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redis (TCP 6379) from the VPC CIDR only"
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Unrestricted outbound access"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-cache-sg"
  })
}

resource "aws_elasticache_subnet_group" "redis" {
  name        = "${var.project_name}-cache-subnets"
  description = "Private subnets spanning two AZs for the ${var.project_name} Redis cluster"
  subnet_ids  = aws_subnet.private[*].id

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-cache-subnets"
  })
}

###############################################################################
# Encryption at rest — dedicated customer-managed KMS key with rotation.
# NOTE: KMS aliases are not taggable at the AWS API level, so the
# aws_kms_alias resource below intentionally carries no tags argument.
# Tag coverage for this encryption component is provided by aws_kms_key.redis.
###############################################################################

resource "aws_kms_key" "redis" {
  description             = "Customer-managed key for Redis (ElastiCache) encryption at rest and Secrets Manager encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-cache-key"
  })
}

resource "aws_kms_alias" "redis" {
  name          = "alias/${var.project_name}"
  target_key_id = aws_kms_key.redis.key_id
}

###############################################################################
# Redis AUTH token — randomly generated and stored in Secrets Manager.
# The token value is never hardcoded in this configuration.
###############################################################################

resource "random_password" "redis_auth" {
  length  = 48
  special = false

  min_upper   = 8
  min_lower   = 8
  min_numeric = 8
}

resource "aws_secretsmanager_secret" "redis_auth" {
  name                    = "${var.project_name}/cache/auth-token"
  description             = "AUTH token for the ${var.project_name} Redis cluster. Clients must connect over TLS (rediss://) and authenticate with this token."
  recovery_window_in_days = 7
  kms_key_id              = aws_kms_key.redis.arn

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-cache-auth-token"
  })
}

resource "aws_secretsmanager_secret_version" "redis_auth" {
  secret_id     = aws_secretsmanager_secret.redis_auth.id
  secret_string = random_password.redis_auth.result
}

###############################################################################
# Redis replication group (single node)
###############################################################################

resource "aws_elasticache_replication_group" "redis" {
  replication_group_id = "${var.project_name}-cache"
  description          = "Single-node Redis cluster; clients must connect over TLS (rediss://) using the AUTH token stored in Secrets Manager"

  engine               = "redis"
  engine_version       = "7.1"
  parameter_group_name = "default.redis7"
  node_type            = "cache.t4g.small"
  num_cache_clusters   = 1
  port                 = 6379

  automatic_failover_enabled = false
  multi_az_enabled           = false

  subnet_group_name  = aws_elasticache_subnet_group.redis.name
  security_group_ids = [aws_security_group.redis.id]

  # Encryption at rest, backed by the dedicated customer-managed KMS key
  at_rest_encryption_enabled = true
  kms_key_id                 = aws_kms_key.redis.arn

  # Encryption in transit (TLS enforced) plus AUTH token from Secrets Manager
  transit_encryption_enabled = true
  auth_token                 = aws_secretsmanager_secret_version.redis_auth.secret_string

  # Automated backups: 7-day retention; snapshot and maintenance windows are
  # both outside business hours (all times UTC)
  snapshot_retention_limit = 7
  snapshot_window          = "02:00-04:00"
  maintenance_window       = "sun:04:30-sun:06:00"

  apply_immediately = true

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-cache"
  })
}

###############################################################################
# Outputs
###############################################################################

output "redis_primary_endpoint_address" {
  description = "Primary endpoint address of the Redis cluster. Connect over TLS (rediss://) using the AUTH token stored in Secrets Manager."
  value       = aws_elasticache_replication_group.redis.primary_endpoint_address
}

output "redis_primary_endpoint_port" {
  description = "Port the Redis cluster listens on."
  value       = aws_elasticache_replication_group.redis.port
}

output "redis_auth_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the Redis AUTH token. Retrieve the value with the AWS CLI/SDK; the token is never exposed here. Clients must connect over TLS (rediss://) with AUTH."
  value       = aws_secretsmanager_secret.redis_auth.arn
  sensitive   = true
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied to all ElastiCache resources."
  type        = string
  default     = "dev"
}

variable "owner" {
  description = "Team or individual responsible for these resources."
  type        = string
  default     = "platform-team"
}

locals {
  common_tags = {
    Environment = var.environment
    Owner       = var.owner
    ManagedBy   = "terraform"
  }
}

# Every ElastiCache user group must include the "default" user.
# It is declared with a deny-by-default access string ("off") so the
# default user cannot authenticate or execute any commands.
resource "aws_elasticache_user" "default" {
  user_id              = "default"
  user_name            = "default"
  engine               = "REDIS"
  access_string        = "off"
  no_password_required = true

  tags = local.common_tags
}

# Least-privilege application user:
#   - restricted to keys matching app:*
#   - granted only read/write/connection command categories
#   - dangerous commands (flushall, flushdb, config, etc.) explicitly denied
# IAM-based authentication (no passwords, secrets, or API keys are stored).
resource "aws_elasticache_user" "app_user" {
  user_id              = "app_user"
  user_name            = "app_user"
  engine               = "REDIS"
  access_string        = "on ~app:* +@read +@write +@connection -@dangerous"
  no_password_required = true

  tags = local.common_tags
}

resource "aws_elasticache_user_group" "app" {
  user_group_id = "app-redis-user-group"
  engine        = "REDIS"

  user_ids = [
    aws_elasticache_user.default.user_id,
    aws_elasticache_user.app_user.user_id,
  ]

  lifecycle {
    prevent_destroy = true
  }

  tags = local.common_tags
}

output "user_group_id" {
  description = "The ID of the ElastiCache user group."
  value       = aws_elasticache_user_group.app.user_group_id
}

output "user_group_arn" {
  description = "The ARN of the ElastiCache user group."
  value       = aws_elasticache_user_group.app.arn
}

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "authorized_aws_account_id" {
  description = "AWS account ID of the external account that is authorized to access the Redshift cluster endpoint."
  type        = string
  default     = "012345678910"

  validation {
    condition     = can(regex("^[0-9]{12}$", var.authorized_aws_account_id))
    error_message = "authorized_aws_account_id must be a 12-digit AWS account ID."
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  cluster_identifier = "redshift-main-cluster"

  common_tags = {
    ManagedBy = "terraform"
    Component = "analytics"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "redshift-vpc"
  })
}

resource "aws_subnet" "redshift_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "redshift-subnet-a"
  })
}

resource "aws_subnet" "redshift_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "redshift-subnet-b"
  })
}

resource "aws_security_group" "redshift" {
  name        = "redshift-cluster-sg"
  description = "Allows Redshift client access from within the VPC on port 5439"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redshift connections from within the VPC"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "redshift-cluster-sg"
  })
}

resource "aws_redshift_subnet_group" "main" {
  name        = "redshift-subnet-group"
  description = "Subnet group spanning two Availability Zones for the Redshift cluster"
  subnet_ids  = [aws_subnet.redshift_a.id, aws_subnet.redshift_b.id]

  tags = merge(local.common_tags, {
    Name = "redshift-subnet-group"
  })
}

resource "random_password" "master" {
  length           = 20
  special          = true
  override_special = "!#$%&*()-_=+[]{}:?"
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
}

resource "aws_secretsmanager_secret" "redshift_master_password" {
  name        = "redshift/${local.cluster_identifier}/master-password"
  description = "Master password for the ${local.cluster_identifier} Amazon Redshift cluster"

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "db" {
  secret_id     = aws_secretsmanager_secret.redshift_master_password.id
  secret_string = random_password.master.result
}

resource "aws_redshift_cluster" "main" {
  cluster_identifier                  = local.cluster_identifier
  database_name                       = "maindb"
  master_username                     = "redshiftadmin"
  master_password                     = aws_secretsmanager_secret_version.db.secret_string
  node_type                           = "ra3.xlplus"
  cluster_type                        = "multi-node"
  number_of_nodes                     = 2
  cluster_subnet_group_name           = aws_redshift_subnet_group.main.name
  vpc_security_group_ids              = [aws_security_group.redshift.id]
  encrypted                           = true
  publicly_accessible                 = false
  automated_snapshot_retention_period = 7
  skip_final_snapshot                 = true

  tags = merge(local.common_tags, {
    Name = local.cluster_identifier
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_redshift_endpoint_authorization" "main" {
  account            = var.authorized_aws_account_id
  cluster_identifier = aws_redshift_cluster.main.id
}

output "cluster_endpoint" {
  description = "Connection endpoint (address:port) of the Redshift cluster."
  value       = aws_redshift_cluster.main.endpoint
}

output "cluster_port" {
  description = "Port on which the Redshift cluster accepts client connections."
  value       = aws_redshift_cluster.main.port
}

output "endpoint_authorization_grantee" {
  description = "AWS account ID of the grantee for which the cross-account Redshift endpoint authorization was created; confirms the authorization exists for var.authorized_aws_account_id."
  value       = aws_redshift_endpoint_authorization.main.grantee
}

output "endpoint_authorization_endpoint_count" {
  description = "Number of Redshift-managed VPC endpoints created under the endpoint authorization (0 until the grantee consumes the authorization)."
  value       = aws_redshift_endpoint_authorization.main.endpoint_count
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Destination region used for cross-region snapshot replication.
provider "aws" {
  alias  = "dr"
  region = "us-east-2"
}

variable "project" {
  description = "Project name used as a consistent prefix for resource names and Name tags."
  type        = string
  default     = "analytics"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix        = var.project
  cluster_identifier = "${var.project}-redshift-cluster"
  database_name      = replace(lower(var.project), "-", "_")
  master_username    = "admin"

  common_tags = {
    Project   = var.project
    ManagedBy = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Networking foundation (us-east-1)
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "redshift_az1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-redshift-subnet-az1"
  })
}

resource "aws_subnet" "redshift_az2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-redshift-subnet-az2"
  })
}

resource "aws_security_group" "redshift" {
  name        = "${local.name_prefix}-redshift-sg"
  description = "Redshift cluster access restricted to the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redshift protocol (TCP 5439) from within the VPC only"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "HTTPS to AWS service endpoints only"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-redshift-sg"
  })
}

resource "aws_redshift_subnet_group" "main" {
  name        = "${local.name_prefix}-redshift-subnet-group"
  description = "Redshift subnet group spanning two availability zones"
  subnet_ids  = [aws_subnet.redshift_az1.id, aws_subnet.redshift_az2.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-redshift-subnet-group"
  })
}

# -----------------------------------------------------------------------------
# Master credentials (no plain-text secret values in configuration)
# -----------------------------------------------------------------------------

resource "random_password" "redshift_master" {
  length           = 32
  special          = true
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "redshift_master" {
  name        = "${local.name_prefix}/redshift/master-credentials"
  description = "Master credentials for the ${local.name_prefix} Redshift cluster"
  kms_key_id  = aws_kms_key.primary.key_id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-redshift-master-credentials"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "redshift_master" {
  secret_id = aws_secretsmanager_secret.redshift_master.id
  secret_string = jsonencode({
    username = local.master_username
    password = random_password.redshift_master.result
  })
}

# -----------------------------------------------------------------------------
# Encryption keys
# -----------------------------------------------------------------------------

resource "aws_kms_key" "primary" {
  description             = "KMS key for the ${local.name_prefix} Redshift cluster in us-east-1"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-redshift-kms-us-east-1"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "primary" {
  name          = "alias/${local.name_prefix}-redshift-us-east-1"
  target_key_id = aws_kms_key.primary.key_id
}

resource "aws_kms_key" "dr" {
  provider                = aws.dr
  description             = "KMS key for ${local.name_prefix} Redshift cross-region snapshot copies in us-east-2"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-redshift-kms-us-east-2"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "dr" {
  provider      = aws.dr
  name          = "alias/${local.name_prefix}-redshift-us-east-2"
  target_key_id = aws_kms_key.dr.key_id
}

# -----------------------------------------------------------------------------
# Cross-region snapshot replication target (us-east-2)
# -----------------------------------------------------------------------------

resource "aws_redshift_snapshot_copy_grant" "dr" {
  provider                 = aws.dr
  snapshot_copy_grant_name = "${local.name_prefix}-redshift-copy-grant"
  kms_key_id               = aws_kms_key.dr.arn
}

# -----------------------------------------------------------------------------
# Redshift cluster (us-east-1, snapshots replicated to us-east-2)
# -----------------------------------------------------------------------------

resource "aws_redshift_cluster" "main" {
  cluster_identifier                  = local.cluster_identifier
  database_name                       = local.database_name
  master_username                     = local.master_username
  master_password                     = random_password.redshift_master.result
  node_type                           = "ra3.xlplus"
  cluster_type                        = "multi-node"
  number_of_nodes                     = 2
  port                                = 5439
  cluster_subnet_group_name           = aws_redshift_subnet_group.main.name
  vpc_security_group_ids              = [aws_security_group.redshift.id]
  encrypted                           = true
  kms_key_id                          = aws_kms_key.primary.arn
  publicly_accessible                 = false
  automated_snapshot_retention_period = 7
  skip_final_snapshot                 = false
  final_snapshot_identifier           = "${local.name_prefix}-redshift-final-snapshot"
  preferred_maintenance_window        = "sun:04:30-sun:05:00"

  snapshot_copy {
    destination_region = "us-east-2"
    grant_name         = aws_redshift_snapshot_copy_grant.dr.snapshot_copy_grant_name
    retention_period   = 7
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-redshift-cluster"
  })

  depends_on = [aws_secretsmanager_secret_version.redshift_master]

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  function_name = "my_lambda_function"
}

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    sid     = "AllowLambdaServiceAssumeRole"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "lambda_exec" {
  name               = "${local.function_name}-exec"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json

  tags = {
    Name = "${local.function_name}-exec"
  }
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

data "archive_file" "lambda" {
  type        = "zip"
  output_path = "lambda_function.zip"

  source {
    filename = "lambda.js"
    content  = <<-EOT
      exports.handler = async (event) => {
        const response = {
          statusCode: 200,
          body: JSON.stringify("Hello from Lambda!"),
        };
        return response;
      };
    EOT
  }
}

resource "aws_lambda_function" "main" {
  function_name = local.function_name
  role          = aws_iam_role.lambda_exec.arn
  handler       = "lambda.handler"
  runtime       = "nodejs20.x"

  filename         = data.archive_file.lambda.output_path
  source_code_hash = data.archive_file.lambda.output_base64sha256

  memory_size = 128
  timeout     = 10

  tags = {
    Name = local.function_name
  }

  depends_on = [
    aws_iam_role_policy_attachment.lambda_basic_execution
  ]
}

###############################################################################
# Terraform configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# User-controlled inputs (all defaulted so apply runs unattended)
###############################################################################

variable "project_name" {
  description = "Short project identifier used for resource naming."
  type        = string
  default     = "ddbevents"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"

  validation {
    condition     = contains(["dev", "staging", "prod"], var.environment)
    error_message = "environment must be one of: dev, staging, prod."
  }
}

variable "lambda_timeout" {
  description = "Lambda function timeout in seconds."
  type        = number
  default     = 30

  validation {
    condition     = var.lambda_timeout >= 1 && var.lambda_timeout <= 900
    error_message = "lambda_timeout must be between 1 and 900 seconds."
  }
}

variable "log_retention_in_days" {
  description = "CloudWatch Logs retention period for Lambda execution logs."
  type        = number
  default     = 14
}

variable "max_retry_attempts" {
  description = "Maximum retry attempts before a failed batch is sent to the dead-letter queue."
  type        = number
  default     = 2
}

###############################################################################
# Locals
###############################################################################

locals {
  function_name = "${var.project_name}-${var.environment}-processor"

  common_tags = {
    Project     = var.project_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

###############################################################################
# DynamoDB table with stream enabled
###############################################################################

resource "aws_dynamodb_table" "events_table" {
  name         = "${var.project_name}-${var.environment}-events"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "pk"

  attribute {
    name = "pk"
    type = "S"
  }

  stream_enabled   = true
  stream_view_type = "NEW_AND_OLD_IMAGES"

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# SQS dead-letter queue for failed stream batches
###############################################################################

resource "aws_sqs_queue" "stream_dlq" {
  name                      = "${var.project_name}-${var.environment}-dlq"
  message_retention_seconds = 1209600

  sqs_managed_sse_enabled = true

  tags = local.common_tags
}

###############################################################################
# Lambda execution role and policies
###############################################################################

resource "aws_iam_role" "lambda_exec" {
  name = "${var.project_name}-${var.environment}-lambda-exec"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowLambdaServiceToAssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_iam_role_policy" "lambda_stream_read" {
  name = "${var.project_name}-${var.environment}-stream-read"
  role = aws_iam_role.lambda_exec.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ReadEventStream"
        Effect = "Allow"
        Action = [
          "dynamodb:GetRecords",
          "dynamodb:GetShardIterator",
          "dynamodb:DescribeStream",
          "dynamodb:ListShards"
        ]
        Resource = aws_dynamodb_table.events_table.stream_arn
      }
    ]
  })
}

resource "aws_iam_role_policy" "lambda_dlq_send" {
  name = "${var.project_name}-${var.environment}-dlq-send"
  role = aws_iam_role.lambda_exec.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "SendFailedBatchesToDlq"
        Effect   = "Allow"
        Action   = "sqs:SendMessage"
        Resource = aws_sqs_queue.stream_dlq.arn
      }
    ]
  })
}

###############################################################################
# CloudWatch log group for Lambda execution logs
###############################################################################

resource "aws_cloudwatch_log_group" "lambda_logs" {
  name              = "/aws/lambda/${local.function_name}"
  retention_in_days = var.log_retention_in_days

  tags = local.common_tags
}

###############################################################################
# Lambda function (packaged locally via archive_file, no VPC required)
###############################################################################

data "archive_file" "lambda_zip" {
  type        = "zip"
  output_path = "${path.module}/build/${var.project_name}-${var.environment}-lambda.zip"

  source {
    filename = "lambda_handler.py"
    content  = <<-HANDLER
import json


def handler(event, context):
    for record in event.get("Records", []):
        print(json.dumps(record, default=str))
    return {"statusCode": 200}
HANDLER
  }
}

resource "aws_lambda_function" "stream_processor" {
  function_name = local.function_name
  description   = "Processes item change records from the DynamoDB events table stream."

  role          = aws_iam_role.lambda_exec.arn
  runtime       = "python3.12"
  handler       = "lambda_handler.handler"
  timeout       = var.lambda_timeout
  memory_size   = 256
  architectures = ["arm64"]

  filename         = data.archive_file.lambda_zip.output_path
  source_code_hash = data.archive_file.lambda_zip.output_base64sha256

  depends_on = [
    aws_iam_role_policy_attachment.lambda_basic_execution,
    aws_iam_role_policy.lambda_stream_read,
    aws_iam_role_policy.lambda_dlq_send,
    aws_cloudwatch_log_group.lambda_logs
  ]

  tags = local.common_tags
}

###############################################################################
# Event source mapping: DynamoDB stream -> Lambda, DLQ on failure
###############################################################################

resource "aws_lambda_event_source_mapping" "dynamodb_stream" {
  event_source_arn  = aws_dynamodb_table.events_table.stream_arn
  function_name     = aws_lambda_function.stream_processor.function_name
  starting_position = "LATEST"
  batch_size        = 100
  enabled           = true

  bisect_batch_on_function_error = true
  maximum_retry_attempts         = var.max_retry_attempts

  destination_config {
    on_failure {
      destination_arn = aws_sqs_queue.stream_dlq.arn
    }
  }

  depends_on = [
    aws_iam_role_policy.lambda_stream_read,
    aws_iam_role_policy.lambda_dlq_send
  ]

  tags = local.common_tags
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "function_name" {
  description = "Name of the Lambda function."
  type        = string
  default     = "lambda-js-app"
}

variable "log_retention_in_days" {
  description = "Number of days to retain Lambda execution logs in CloudWatch."
  type        = number
  default     = 14
}

variable "tags" {
  description = "Additional tags to apply to all taggable resources."
  type        = map(string)
  default     = {}
}

locals {
  function_name = var.function_name

  # Minimal, valid Node.js CommonJS handler embedded directly so the
  # deployment is fully self-contained (no companion source files needed).
  lambda_source = <<-EOT
    'use strict';

    exports.handler = async (event) => {
      console.log('Received event:', JSON.stringify(event));

      return {
        statusCode: 200,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: 'Hello from lambda.js!' }),
      };
    };
  EOT

  common_tags = merge(
    {
      Name      = local.function_name
      ManagedBy = "terraform"
    },
    var.tags,
  )
}

# Package the embedded handler into a deployable zip artifact.
# source_content + source_content_filename keeps the archive entry named
# lambda.js so handler = "lambda.handler" resolves correctly at runtime.
data "archive_file" "lambda" {
  type        = "zip"
  source_content           = local.lambda_source
  source_content_filename  = "lambda.js"
  output_path = "${path.module}/lambda.zip"
}

# Trust policy allowing only the Lambda service principal to assume the role.
data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    sid     = "AllowLambdaServiceAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

# Well-known AWS managed policy granting basic CloudWatch Logs permissions.
data "aws_iam_policy" "lambda_basic_execution" {
  name = "AWSLambdaBasicExecutionRole"
}

resource "aws_iam_role" "lambda_exec" {
  name               = "${local.function_name}-execution-role"
  description        = "Execution role for the ${local.function_name} Lambda function"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = data.aws_iam_policy.lambda_basic_execution.arn
}

resource "aws_lambda_function" "app" {
  function_name = local.function_name
  description   = "Node.js Lambda function running lambda.js"

  role    = aws_iam_role.lambda_exec.arn
  handler = "lambda.handler"
  runtime = "nodejs22.x"

  filename         = data.archive_file.lambda.output_path
  source_code_hash = data.archive_file.lambda.output_base64sha256

  memory_size = 256
  timeout     = 10

  architectures = ["arm64"]

  # Ensure the execution role has logging permissions before the function starts.
  depends_on = [aws_iam_role_policy_attachment.lambda_basic_execution]

  tags = local.common_tags
}

resource "aws_cloudwatch_log_group" "lambda" {
  name              = "/aws/lambda/${aws_lambda_function.app.function_name}"
  retention_in_days = var.log_retention_in_days

  tags = local.common_tags
}

output "lambda_function_name" {
  description = "Name of the Lambda function."
  value       = aws_lambda_function.app.function_name
}

output "lambda_function_arn" {
  description = "ARN of the Lambda function."
  value       = aws_lambda_function.app.arn
}

output "lambda_execution_role_arn" {
  description = "ARN of the Lambda execution role."
  value       = aws_iam_role.lambda_exec.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_cloudwatch_metric_alarm" "foobar" {
  alarm_name          = "foobar"
  alarm_description   = "Triggers when the average CPU utilization of EC2 instances is greater than or equal to 80% for two consecutive 2-minute evaluation periods. No alarm actions are executed when there is insufficient data."
  namespace           = "AWS/EC2"
  metric_name         = "CPUUtilization"
  statistic           = "Average"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  threshold           = 80
  period              = 120
  evaluation_periods  = 2
  treat_missing_data  = "missing"

  tags = {
    Name      = "foobar"
    ManagedBy = "terraform"
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "table_name" {
  description = "Name of the DynamoDB table."
  type        = string
  default     = "app-data"
}

variable "tags" {
  description = "Tags to apply to the DynamoDB table."
  type        = map(string)
  default = {
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

locals {
  common_tags = merge(
    var.tags,
    {
      Name = var.table_name
    },
  )
}

resource "aws_dynamodb_table" "main" {
  name           = var.table_name
  billing_mode   = "PROVISIONED"
  read_capacity  = 20
  write_capacity = 20
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

output "dynamodb_table_name" {
  description = "Name of the DynamoDB table."
  value       = aws_dynamodb_table.main.name
}

output "dynamodb_table_arn" {
  description = "ARN of the DynamoDB table."
  value       = aws_dynamodb_table.main.arn
}

output "dynamodb_table_id" {
  description = "ID of the DynamoDB table."
  value       = aws_dynamodb_table.main.id
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      Environment = var.environment
    }
  }
}

variable "environment" {
  description = "Environment name applied via provider default_tags to taggable resources (non-taggable resources ignore it)."
  type        = string
  default     = "dev"
}

locals {
  dax_parameter_group_name = "custom-dax-params"
}

resource "aws_dax_parameter_group" "custom" {
  name        = local.dax_parameter_group_name
  description = "Custom DAX parameter group with tuned query and record cache TTLs."

  parameters {
    name  = "query-ttl-millis"
    value = "100000"
  }

  parameters {
    name  = "record-ttl-millis"
    value = "100000"
  }
}

output "dax_parameter_group_name" {
  description = "Name of the custom DAX parameter group, for reference by a future aws_dax_cluster."
  value       = aws_dax_parameter_group.custom.name
}

output "dax_parameter_group_id" {
  description = "ID of the custom DAX parameter group, for reference by a future aws_dax_cluster."
  value       = aws_dax_parameter_group.custom.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "user_profile_name" {
  description = "Name of the SageMaker user profile to create inside the domain."
  type        = string
  default     = "data-scientist"

  validation {
    condition     = can(regex("^[a-zA-Z0-9](-*[a-zA-Z0-9]){0,62}$", var.user_profile_name))
    error_message = "user_profile_name must be 1-63 characters: letters, digits, and hyphens only, starting and ending with a letter or digit."
  }
}

variable "tags" {
  description = "Tags applied to all taggable resources in this configuration."
  type        = map(string)
  default = {
    Environment = "dev"
    Owner       = "platform-team"
    ManagedBy   = "terraform"
  }
}

# ------------------------------------------------------------------------------
# Data sources (static account / provider metadata only)
# ------------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name

  s3_bucket_name = "sagemaker-app-data-${local.account_id}-${local.region}"

  sagemaker_log_group_arn  = "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws/sagemaker/*"
  sagemaker_log_stream_arn = "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws/sagemaker/*:log-stream:*"
  ecr_repository_arn       = "arn:${local.partition}:ecr:${local.region}:${local.account_id}:repository/*"
}

# ------------------------------------------------------------------------------
# Networking: dedicated VPC and subnets for the SageMaker domain
# (No IGW/NAT/route tables/endpoints required — app_network_access_type is
# PublicInternetOnly, so the customer VPC carries only domain ENI/EFS traffic.)
# ------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, { Name = "sagemaker-domain-vpc" })
}

resource "aws_subnet" "main_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"

  tags = merge(var.tags, { Name = "sagemaker-domain-subnet-a" })
}

resource "aws_subnet" "main_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-east-1b"

  tags = merge(var.tags, { Name = "sagemaker-domain-subnet-b" })
}

# ------------------------------------------------------------------------------
# KMS: customer managed key for SageMaker domain storage encryption
# ------------------------------------------------------------------------------

resource "aws_kms_key" "sagemaker_domain" {
  description              = "Customer managed key used to encrypt SageMaker domain and notebook storage."
  key_usage                = "ENCRYPT_DECRYPT"
  customer_master_key_spec = "SYMMETRIC_DEFAULT"
  deletion_window_in_days  = 30
  enable_key_rotation      = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableIAMPermissionsForAccount"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = ["kms:*"]
        Resource = ["*"]
      },
      {
        Sid    = "AllowSageMakerServiceToUseKey"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
        Action = [
          "kms:CreateGrant",
          "kms:DescribeKey",
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:ReEncryptFrom",
          "kms:ReEncryptTo"
        ]
        Resource = ["*"]
      }
    ]
  })

  tags = merge(var.tags, { Name = "sagemaker-domain-encryption" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "sagemaker_domain" {
  name          = "alias/sagemaker/domain-encryption"
  target_key_id = aws_kms_key.sagemaker_domain.key_id
}

# ------------------------------------------------------------------------------
# S3: dedicated bucket for SageMaker notebook and app data
# ------------------------------------------------------------------------------

resource "aws_s3_bucket" "sagemaker_data" {
  bucket = local.s3_bucket_name

  tags = merge(var.tags, { Name = "sagemaker-app-data" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "sagemaker_data" {
  bucket = aws_s3_bucket.sagemaker_data.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "sagemaker_data" {
  bucket = aws_s3_bucket.sagemaker_data.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "sagemaker_data" {
  bucket = aws_s3_bucket.sagemaker_data.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.sagemaker_domain.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "sagemaker_data" {
  bucket = aws_s3_bucket.sagemaker_data.id

  versioning_configuration {
    status = "Enabled"
  }
}

# ------------------------------------------------------------------------------
# IAM: dedicated SageMaker execution role with least-privilege inline policy
# ------------------------------------------------------------------------------

resource "aws_iam_role" "sagemaker_execution" {
  name        = "sagemaker-execution-role"
  description = "Least-privilege execution role assumed by SageMaker for the domain and user profiles."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowSageMakerToAssumeRole"
        Effect = "Allow"
        Action = ["sts:AssumeRole"]
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })

  tags = merge(var.tags, { Name = "sagemaker-execution-role" })
}

resource "aws_iam_role_policy" "sagemaker_execution" {
  name = "sagemaker-execution-least-privilege"
  role = aws_iam_role.sagemaker_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ListSageMakerDataBucket"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation"
        ]
        Resource = [
          aws_s3_bucket.sagemaker_data.arn
        ]
      },
      {
        Sid    = "ReadWriteSageMakerDataBucketObjects"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = [
          "${aws_s3_bucket.sagemaker_data.arn}/*"
        ]
      },
      {
        Sid    = "SageMakerCloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:DescribeLogStreams",
          "logs:GetLogEvents",
          "logs:PutLogEvents"
        ]
        Resource = [
          local.sagemaker_log_group_arn,
          local.sagemaker_log_stream_arn
        ]
      },
      {
        Sid    = "GetECRAuthorizationToken"
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken"
        ]
        Resource = ["*"]
      },
      {
        Sid    = "PullECRImages"
        Effect = "Allow"
        Action = [
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage"
        ]
        Resource = [
          local.ecr_repository_arn
        ]
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# SageMaker domain
# ------------------------------------------------------------------------------

resource "aws_sagemaker_domain" "main" {
  domain_name             = "ml-platform-domain"
  auth_mode               = "IAM"
  app_network_access_type = "PublicInternetOnly"
  kms_key_id              = aws_kms_key.sagemaker_domain.arn

  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.main_a.id, aws_subnet.main_b.id]

  retention_policy {
    home_efs_file_system = "Retain"
  }

  default_user_settings {
    execution_role = aws_iam_role.sagemaker_execution.arn

    jupyter_server_app_settings {
      default_resource_spec {
        instance_type = "ml.t3.micro"
      }
    }

    kernel_gateway_app_settings {
      default_resource_spec {
        instance_type = "ml.t3.medium"
      }
    }
  }

  tags = merge(var.tags, { Name = "ml-platform-domain" })
}

# ------------------------------------------------------------------------------
# SageMaker user profile (inherits the domain's default user settings)
# ------------------------------------------------------------------------------

resource "aws_sagemaker_user_profile" "main" {
  domain_id         = aws_sagemaker_domain.main.id
  user_profile_name = var.user_profile_name

  tags = merge(var.tags, { Name = var.user_profile_name })
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "sagemaker_domain_id" {
  description = "The ID of the SageMaker domain."
  value       = aws_sagemaker_domain.main.id
}

output "sagemaker_user_profile_name" {
  description = "The name of the SageMaker user profile."
  value       = aws_sagemaker_user_profile.main.user_profile_name
}

output "sagemaker_user_profile_arn" {
  description = "The ARN of the SageMaker user profile."
  value       = aws_sagemaker_user_profile.main.arn
}

output "sagemaker_execution_role_arn" {
  description = "The ARN of the IAM execution role used by the SageMaker domain and user profile."
  value       = aws_iam_role.sagemaker_execution.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables (user-controlled, non-infrastructure values, all with defaults)
# -----------------------------------------------------------------------------

variable "image_display_name" {
  description = "Human-readable display name for the SageMaker image shown in Studio."
  type        = string
  default     = "Studio Custom Image"
}

variable "environment" {
  description = "Environment tag applied to all resources."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Additional tags merged into the common tag set for all resources."
  type        = map(string)
  default     = {}
}

# -----------------------------------------------------------------------------
# Static provider metadata lookups (pure local, no dependency on remote state)
# -----------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  project_name = "sagemaker-studio-image"

  # Deployment region constant — matches the region pinned in the provider block.
  aws_region = "us-east-1"

  # SageMaker image names allow alphanumeric characters and hyphens only,
  # with a maximum length of 63 characters.
  image_name = "studio-custom-image"

  common_tags = merge(
    {
      Environment = var.environment
      Project     = local.project_name
      ManagedBy   = "terraform"
    },
    var.tags
  )
}

# -----------------------------------------------------------------------------
# ECR repository hosting the SageMaker base container image
# -----------------------------------------------------------------------------

resource "aws_ecr_repository" "sagemaker_base" {
  name                 = "sagemaker-studio-base-image"
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  encryption_configuration {
    encryption_type = "KMS"
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ecr_lifecycle_policy" "sagemaker_base" {
  repository = aws_ecr_repository.sagemaker_base.name

  policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Expire untagged images older than 14 days"
        selection = {
          tagStatus   = "untagged"
          countType   = "sinceImagePushed"
          countUnit   = "days"
          countNumber = 14
        }
        action = {
          type = "expire"
        }
      },
      {
        rulePriority = 2
        description  = "Keep only the 10 most recent versioned (v*) images"
        selection = {
          tagStatus      = "tagged"
          tagPatternList = ["v*"]
          countType      = "imageCountMoreThan"
          countNumber    = 10
        }
        action = {
          type = "expire"
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# IAM role assumed by SageMaker for the image
# -----------------------------------------------------------------------------

resource "aws_iam_role" "sagemaker_image_role" {
  name        = "sagemaker-studio-image-role"
  description = "Execution role assumed by SageMaker for the Studio custom image"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowSageMakerToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# Least-privilege ECR pull permissions scoped to the in-file ECR repository
# -----------------------------------------------------------------------------

resource "aws_iam_policy" "sagemaker_ecr_pull" {
  name        = "sagemaker-studio-image-ecr-pull"
  description = "Least-privilege ECR pull access scoped to the SageMaker base image repository"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "EcrGetAuthorizationToken"
        Effect   = "Allow"
        Action   = "ecr:GetAuthorizationToken"
        Resource = "*"
      },
      {
        Sid    = "EcrPullBaseImage"
        Effect = "Allow"
        Action = [
          "ecr:BatchCheckLayerAvailability",
          "ecr:BatchGetImage",
          "ecr:GetDownloadUrlForLayer"
        ]
        Resource = aws_ecr_repository.sagemaker_base.arn
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "sagemaker_ecr_pull" {
  role       = aws_iam_role.sagemaker_image_role.name
  policy_arn = aws_iam_policy.sagemaker_ecr_pull.arn
}

# -----------------------------------------------------------------------------
# Least-privilege CloudWatch Logs write permissions scoped to SageMaker log groups
# -----------------------------------------------------------------------------

resource "aws_iam_policy" "sagemaker_logs_write" {
  name        = "sagemaker-studio-image-logs-write"
  description = "Least-privilege CloudWatch Logs write access scoped to SageMaker log group ARN prefixes"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SageMakerLogGroupWrites"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents"
        ]
        Resource = "arn:aws:logs:${local.aws_region}:${data.aws_caller_identity.current.account_id}:log-group:/aws/sagemaker/*"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "sagemaker_logs_write" {
  role       = aws_iam_role.sagemaker_image_role.name
  policy_arn = aws_iam_policy.sagemaker_logs_write.arn
}

# -----------------------------------------------------------------------------
# SageMaker Image and Image Version
# -----------------------------------------------------------------------------

resource "aws_sagemaker_image" "studio_image" {
  image_name   = local.image_name
  display_name = var.image_display_name
  description  = "Custom SageMaker Studio image hosted in the project ECR repository"
  role_arn     = aws_iam_role.sagemaker_image_role.arn

  tags = local.common_tags
}

resource "aws_sagemaker_image_version" "v1" {
  image_name = aws_sagemaker_image.studio_image.image_name
  base_image = "${aws_ecr_repository.sagemaker_base.repository_url}:v1"

  depends_on = [
    aws_iam_role_policy_attachment.sagemaker_ecr_pull,
    aws_iam_role_policy_attachment.sagemaker_logs_write
  ]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# Static provider metadata lookups (permitted pure-local data sources)
# ---------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

# ---------------------------------------------------------------------------
# Variables (all with defaults so `terraform apply` runs unattended)
# ---------------------------------------------------------------------------

variable "environment" {
  description = "Environment name used for resource tagging."
  type        = string
  default     = "dev"
}

locals {
  artifacts_bucket_name = "sagemaker-artifacts-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"
}

# ---------------------------------------------------------------------------
# Artifacts bucket
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "sagemaker_artifacts" {
  bucket = local.artifacts_bucket_name

  tags = {
    Name        = local.artifacts_bucket_name
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "sagemaker_artifacts" {
  bucket = aws_s3_bucket.sagemaker_artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "sagemaker_artifacts" {
  bucket = aws_s3_bucket.sagemaker_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "sagemaker_artifacts" {
  bucket = aws_s3_bucket.sagemaker_artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

# ---------------------------------------------------------------------------
# Execution IAM role
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "sagemaker_pipeline_trust" {
  statement {
    sid     = "AllowSageMakerToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["sagemaker.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_iam_role" "sagemaker_pipeline_execution" {
  name               = "sagemaker-pipeline-execution-role"
  description        = "Execution role assumed by SageMaker for pipeline execution"
  assume_role_policy = data.aws_iam_policy_document.sagemaker_pipeline_trust.json

  tags = {
    Name        = "sagemaker-pipeline-execution-role"
    Environment = var.environment
  }
}

data "aws_iam_policy_document" "sagemaker_pipeline_execution" {
  statement {
    sid       = "ListArtifactsBucket"
    effect    = "Allow"
    actions   = ["s3:ListBucket", "s3:GetBucketLocation"]
    resources = [aws_s3_bucket.sagemaker_artifacts.arn]
  }

  statement {
    sid    = "ReadWriteArtifactsObjects"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:AbortMultipartUpload",
      "s3:ListMultipartUploadParts",
    ]
    resources = ["${aws_s3_bucket.sagemaker_artifacts.arn}/*"]
  }

  statement {
    sid    = "SageMakerCloudWatchLogs"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]
    resources = ["arn:aws:logs:*:*:log-group:/aws/sagemaker/*"]
  }
}

resource "aws_iam_policy" "sagemaker_pipeline_execution" {
  name        = "sagemaker-pipeline-execution-policy"
  description = "Least-privilege permissions for the SageMaker pipeline execution role"
  policy      = data.aws_iam_policy_document.sagemaker_pipeline_execution.json

  tags = {
    Environment = var.environment
  }
}

resource "aws_iam_role_policy_attachment" "sagemaker_pipeline_execution" {
  role       = aws_iam_role.sagemaker_pipeline_execution.name
  policy_arn = aws_iam_policy.sagemaker_pipeline_execution.arn
}

# ---------------------------------------------------------------------------
# SageMaker Pipeline
# ---------------------------------------------------------------------------

resource "aws_sagemaker_pipeline" "ml_pipeline" {
  pipeline_name         = "ml-pipeline"
  pipeline_display_name = "ML-Pipeline"
  pipeline_description  = "SageMaker pipeline orchestrating workflow steps, seeded with a Pass step"

  role_arn = aws_iam_role.sagemaker_pipeline_execution.arn

  pipeline_definition = jsonencode({
    Version = "2020-12-01"
    Steps = [
      {
        Name = "PassStep"
        Type = "Pass"
      }
    ]
  })

  parallelism_configuration {
    max_parallel_execution_steps = 5
  }

  tags = {
    Name        = "ml-pipeline"
    Environment = var.environment
  }

  depends_on = [aws_iam_role_policy_attachment.sagemaker_pipeline_execution]
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "pipeline_arn" {
  description = "ARN of the SageMaker pipeline."
  value       = aws_sagemaker_pipeline.ml_pipeline.arn
}

output "pipeline_name" {
  description = "Name of the SageMaker pipeline."
  value       = aws_sagemaker_pipeline.ml_pipeline.pipeline_name
}

output "execution_role_arn" {
  description = "ARN of the SageMaker pipeline execution role."
  value       = aws_iam_role.sagemaker_pipeline_execution.arn
}

output "artifacts_bucket_arn" {
  description = "ARN of the S3 bucket holding SageMaker pipeline artifacts."
  value       = aws_s3_bucket.sagemaker_artifacts.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  function_name = "hello-lambda"

  common_tags = {
    Project     = "serverless-hello"
    Component   = "lambda"
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Lambda source code, authored as a managed local file (no inline secrets,
# credentials, or account-specific identifiers).
# -----------------------------------------------------------------------------
resource "local_file" "lambda_js" {
  filename        = "lambda.js"
  file_permission = "0644"
  content         = <<-EOF
    'use strict';

    /**
     * Simple Node.js Lambda handler.
     * The deployment package exposes this code as index.js so that the
     * "index.handler" entry point resolves correctly.
     */
    exports.handler = async (event) => {
      console.log('Received event:', JSON.stringify(event, null, 2));

      const response = {
        statusCode: 200,
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          message: 'Hello from Lambda!',
          input: event,
        }),
      };

      return response;
    };
  EOF
}

# -----------------------------------------------------------------------------
# Deployment package: the handler source is embedded as index.js so that the
# "index.handler" reference resolves. output_base64sha256 is used as
# source_code_hash so any code change triggers a redeployment.
# -----------------------------------------------------------------------------
data "archive_file" "lambda" {
  type        = "zip"
  output_path = "lambda_function_payload.zip"

  source {
    content  = local_file.lambda_js.content
    filename = "index.js"
  }
}

# -----------------------------------------------------------------------------
# Execution role: trusts only the Lambda service principal (no wildcards).
# -----------------------------------------------------------------------------
resource "aws_iam_role" "lambda_exec" {
  name = "${local.function_name}-exec"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowLambdaServiceAssume"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

# AWS-managed policy granting CloudWatch Logs write permissions.
resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

# -----------------------------------------------------------------------------
# Lambda function
# -----------------------------------------------------------------------------
resource "aws_lambda_function" "hello_lambda" {
  function_name = local.function_name
  description   = "Node.js Lambda function provisioned with Terraform"

  # nodejs18.x is end-of-support; nodejs22.x is the actively supported runtime.
  runtime = "nodejs22.x"
  handler = "index.handler"
  role    = aws_iam_role.lambda_exec.arn

  filename         = data.archive_file.lambda.output_path
  source_code_hash = data.archive_file.lambda.output_base64sha256

  memory_size = 128
  timeout     = 10

  tags = local.common_tags

  depends_on = [
    aws_iam_role_policy_attachment.lambda_basic_execution,
  ]
}

# -----------------------------------------------------------------------------
# Explicit CloudWatch log group (replaces the auto-created one) with bounded
# 14-day retention so logs do not accumulate indefinitely.
# -----------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "lambda_logs" {
  name              = "/aws/lambda/${aws_lambda_function.hello_lambda.function_name}"
  retention_in_days = 14

  tags = local.common_tags
}

output "lambda_function_name" {
  description = "Name of the Lambda function."
  value       = aws_lambda_function.hello_lambda.function_name
}

output "lambda_function_arn" {
  description = "ARN of the Lambda function."
  value       = aws_lambda_function.hello_lambda.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied to all resource tags"
  type        = string
  default     = "dev"
}

locals {
  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "linux2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "main-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "main-igw"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "public-subnet"
  })
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "private-subnet"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "public-route-table"
  })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "private-route-table"
  })
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "fleet" {
  name        = "fleet-sg"
  description = "Security group for the EC2 Fleet instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from within the VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "HTTP from within the VPC"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "fleet-sg"
  })
}

resource "aws_iam_role" "fleet_ssm" {
  name = "fleet-ssm-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "fleet-ssm-role"
  })
}

resource "aws_iam_role_policy_attachment" "fleet_ssm_core" {
  role       = aws_iam_role.fleet_ssm.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "fleet" {
  name = "fleet-instance-profile"
  role = aws_iam_role.fleet_ssm.name

  tags = merge(local.common_tags, {
    Name = "fleet-instance-profile"
  })
}

resource "aws_launch_template" "linux_2" {
  name          = "linux2-fleet-lt"
  description   = "Launch template for the Amazon Linux 2 EC2 Fleet"
  image_id      = data.aws_ami.linux2.id
  instance_type = "t3.micro"

  iam_instance_profile {
    name = aws_iam_instance_profile.fleet.name
  }

  vpc_security_group_ids = [aws_security_group.fleet.id]

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
    instance_metadata_tags      = "disabled"
  }

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      volume_size           = 8
      volume_type           = "gp3"
      encrypted             = true
      delete_on_termination = true
    }
  }

  tag_specifications {
    resource_type = "instance"
    tags = merge(local.common_tags, {
      Name = "linux2-fleet-instance"
    })
  }

  tags = merge(local.common_tags, {
    Name = "linux2-fleet-lt"
  })

  depends_on = [aws_iam_role_policy_attachment.fleet_ssm_core]
}

resource "aws_ec2_fleet" "main" {
  launch_template_config {
    launch_template_specification {
      launch_template_id = aws_launch_template.linux_2.id
      version            = aws_launch_template.linux_2.latest_version
    }

    override {
      subnet_id = aws_subnet.public.id
      priority  = 1
    }

    override {
      subnet_id = aws_subnet.private.id
      priority  = 2
    }
  }

  target_capacity_specification {
    total_target_capacity        = 9
    on_demand_target_capacity    = 5
    spot_target_capacity         = 4
    default_target_capacity_type = "on-demand"
  }

  spot_options {
    instance_interruption_behavior = "terminate"
  }

  replace_unhealthy_instances = true
  terminate_instances         = true

  tags = merge(local.common_tags, {
    Name = "linux2-fleet"
  })
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "tags" {
  description = "Common tags applied to all resources."
  type        = map(string)
  default = {
    Environment = "dev"
  }
}

locals {
  name_prefix = "reduce-db-calls-cache"
}

# ---------------------------------------------------------------------------
# Network: VPC and private subnets for the cache layer
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, { Name = "${local.name_prefix}-vpc" })
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_subnet" "private_cache_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(var.tags, { Name = "${local.name_prefix}-private-a" })
}

resource "aws_subnet" "private_cache_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(var.tags, { Name = "${local.name_prefix}-private-b" })
}

# ---------------------------------------------------------------------------
# Security group: Redis (TCP 6379) restricted to the VPC CIDR only
# ---------------------------------------------------------------------------
resource "aws_security_group" "cache_sg" {
  name        = "${local.name_prefix}-redis-sg"
  description = "Allow Redis TCP 6379 only from within the VPC; no public ingress."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redis (TCP 6379) from VPC CIDR only"
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(var.tags, { Name = "${local.name_prefix}-redis-sg" })
}

# ---------------------------------------------------------------------------
# ElastiCache subnet group: cache nodes deployed ONLY in private subnets
# ---------------------------------------------------------------------------
resource "aws_elasticache_subnet_group" "cache_subnets" {
  name       = "${local.name_prefix}-subnets"
  subnet_ids = [aws_subnet.private_cache_a.id, aws_subnet.private_cache_b.id]

  tags = merge(var.tags, { Name = "${local.name_prefix}-subnet-group" })
}

# ---------------------------------------------------------------------------
# Redis AUTH token: generated at apply-time and stored in Secrets Manager
# ---------------------------------------------------------------------------
resource "random_password" "auth_token" {
  length  = 32
  special = false
}

resource "aws_secretsmanager_secret" "redis_auth_token" {
  name                    = "${local.name_prefix}-auth-token"
  description             = "AUTH token for the Redis read-through cache replication group."
  recovery_window_in_days = 7

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(var.tags, { Name = "${local.name_prefix}-auth-token" })
}

resource "aws_secretsmanager_secret_version" "redis_auth_token" {
  secret_id     = aws_secretsmanager_secret.redis_auth_token.id
  secret_string = random_password.auth_token.result
}

# ---------------------------------------------------------------------------
# IAM: least-privilege access to the AUTH token secret, scoped to its ARN
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "redis_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "cache_token_reader" {
  name               = "${local.name_prefix}-token-reader"
  assume_role_policy = data.aws_iam_policy_document.redis_assume_role.json

  tags = merge(var.tags, { Name = "${local.name_prefix}-token-reader" })
}

data "aws_iam_policy_document" "redis_token_read" {
  statement {
    sid       = "ReadRedisAuthToken"
    effect    = "Allow"
    actions   = ["secretsmanager:GetSecretValue"]
    resources = [aws_secretsmanager_secret.redis_auth_token.arn]
  }
}

resource "aws_iam_policy" "redis_token_read" {
  name        = "${local.name_prefix}-token-read"
  description = "Least-privilege read access to the Redis AUTH token secret only."
  policy      = data.aws_iam_policy_document.redis_token_read.json

  tags = merge(var.tags, { Name = "${local.name_prefix}-token-read" })
}

resource "aws_iam_role_policy_attachment" "redis_token_read" {
  role       = aws_iam_role.cache_token_reader.name
  policy_arn = aws_iam_policy.redis_token_read.arn
}

# ---------------------------------------------------------------------------
# ElastiCache Redis replication group: in-memory read-through cache that
# absorbs repeated lookups and reduces database call volume
# ---------------------------------------------------------------------------
resource "aws_elasticache_replication_group" "redis_cache" {
  replication_group_id       = "${local.name_prefix}-rg"
  description                = "Redis read-through cache absorbing repeated lookups to reduce database call volume."
  engine                     = "redis"
  engine_version             = "7.1"
  node_type                  = "cache.t4g.micro"
  num_cache_clusters         = 2
  port                       = 6379
  subnet_group_name          = aws_elasticache_subnet_group.cache_subnets.name
  security_group_ids         = [aws_security_group.cache_sg.id]
  automatic_failover_enabled = true
  multi_az_enabled           = true
  transit_encryption_enabled = true
  at_rest_encryption_enabled = true
  auth_token                 = random_password.auth_token.result
  maintenance_window         = "sun:05:00-sun:06:00"
  snapshot_window            = "01:00-03:00"
  snapshot_retention_limit   = 7
  apply_immediately          = true

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(var.tags, { Name = "${local.name_prefix}-rg" })
}

# ---------------------------------------------------------------------------
# Outputs: connection details for application resources (no secret values)
# ---------------------------------------------------------------------------
output "redis_primary_endpoint_address" {
  description = "Primary endpoint address of the Redis cache to use for read-through caching."
  value       = aws_elasticache_replication_group.redis_cache.primary_endpoint_address
}

output "redis_primary_endpoint_port" {
  description = "Primary endpoint port of the Redis cache."
  value       = aws_elasticache_replication_group.redis_cache.port
}

output "redis_auth_token_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the Redis AUTH token (the value itself is never exposed)."
  value       = aws_secretsmanager_secret.redis_auth_token.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Project name used for resource naming and tagging."
  type        = string
  default     = "redis-acl"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "production"
}

locals {
  name_prefix = "${var.project_name}-${var.environment}"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
    Project     = var.project_name
  }
}

# -----------------------------------------------------------------------------
# Generated credentials: never hardcoded. Each password is injected into the
# matching ElastiCache user and stored encrypted in AWS Secrets Manager.
# -----------------------------------------------------------------------------

resource "random_password" "admin" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+"
}

resource "random_password" "read_only_one" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+"
}

resource "random_password" "read_only_two" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+"
}

# -----------------------------------------------------------------------------
# ElastiCache users: one admin (full access) and two least-privilege,
# key-pattern-scoped read-only users. All users require authentication.
# -----------------------------------------------------------------------------

resource "aws_elasticache_user" "admin" {
  user_id              = "${local.name_prefix}-admin"
  user_name            = "${local.name_prefix}-admin"
  engine               = "REDIS"
  access_string        = "on ~* +@all"
  passwords            = [random_password.admin.result]
  no_password_required = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-admin-user"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_elasticache_user" "read_only_one" {
  user_id              = "${local.name_prefix}-readonly-one"
  user_name            = "${local.name_prefix}-readonly-one"
  engine               = "REDIS"
  access_string        = "on ~app:* -@all +@read"
  passwords            = [random_password.read_only_one.result]
  no_password_required = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-readonly-one-user"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_elasticache_user" "read_only_two" {
  user_id              = "${local.name_prefix}-readonly-two"
  user_name            = "${local.name_prefix}-readonly-two"
  engine               = "REDIS"
  access_string        = "on ~cache:* -@all +@read"
  passwords            = [random_password.read_only_two.result]
  no_password_required = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-readonly-two-user"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Secrets Manager: one secret and one secret version per user password.
# -----------------------------------------------------------------------------

resource "aws_secretsmanager_secret" "admin" {
  name        = "${local.name_prefix}/users/admin"
  description = "Password for the ${local.name_prefix} ElastiCache admin user."

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-admin-secret"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "admin" {
  secret_id = aws_secretsmanager_secret.admin.id
  secret_string = jsonencode({
    username = aws_elasticache_user.admin.user_name
    password = random_password.admin.result
  })
}

resource "aws_secretsmanager_secret" "read_only_one" {
  name        = "${local.name_prefix}/users/readonly-one"
  description = "Password for the ${local.name_prefix} ElastiCache read-only user (app keys)."

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-readonly-one-secret"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "read_only_one" {
  secret_id = aws_secretsmanager_secret.read_only_one.id
  secret_string = jsonencode({
    username = aws_elasticache_user.read_only_one.user_name
    password = random_password.read_only_one.result
  })
}

resource "aws_secretsmanager_secret" "read_only_two" {
  name        = "${local.name_prefix}/users/readonly-two"
  description = "Password for the ${local.name_prefix} ElastiCache read-only user (cache keys)."

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-readonly-two-secret"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "read_only_two" {
  secret_id = aws_secretsmanager_secret.read_only_two.id
  secret_string = jsonencode({
    username = aws_elasticache_user.read_only_two.user_name
    password = random_password.read_only_two.result
  })
}

# -----------------------------------------------------------------------------
# ElastiCache user group bundling all three users.
# -----------------------------------------------------------------------------

resource "aws_elasticache_user_group" "main" {
  user_group_id = "${local.name_prefix}-user-group"
  engine        = "REDIS"
  user_ids = [
    aws_elasticache_user.admin.user_id,
    aws_elasticache_user.read_only_one.user_id,
    aws_elasticache_user.read_only_two.user_id,
  ]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-user-group"
  })

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Project name used as the prefix for all resource names and the Name tag."
  type        = string
  default     = "kafka"

  validation {
    condition     = length(var.project_name) > 0 && can(regex("^[a-zA-Z0-9-]+$", var.project_name))
    error_message = "project_name must be a non-empty string containing only alphanumeric characters and hyphens."
  }
}

variable "environment" {
  description = "Environment name applied as the Environment tag to every resource."
  type        = string
  default     = "production"

  validation {
    condition     = length(var.environment) > 0 && can(regex("^[a-zA-Z0-9-]+$", var.environment))
    error_message = "environment must be a non-empty string containing only alphanumeric characters and hyphens."
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  name_prefix          = "${var.project_name}-${var.environment}"
  private_subnet_cidrs = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private" {
  count = length(local.private_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-${count.index}"
  })
}

resource "aws_security_group" "kafka_brokers" {
  name        = "${local.name_prefix}-brokers-sg"
  description = "Client access to MSK Kafka brokers (TLS 9094 and IAM SASL 9098 only)"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Kafka client-broker access over TLS"
    from_port   = 9094
    to_port     = 9094
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Kafka client-broker access over IAM SASL"
    from_port   = 9098
    to_port     = 9098
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-brokers-sg"
  })
}

resource "aws_kms_key" "msk" {
  description             = "Customer-managed KMS key for MSK cluster encryption at rest"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "${local.name_prefix}-msk-key-policy"
    Statement = [
      {
        Sid    = "AllowAccountLeastPrivilegeMskAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = [
          "kms:CreateGrant",
          "kms:DescribeKey",
          "kms:GenerateDataKey",
          "kms:Decrypt"
        ]
        Resource = "*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-msk-key"
  })
}

resource "aws_kms_alias" "msk" {
  name          = "alias/${local.name_prefix}-msk"
  target_key_id = aws_kms_key.msk.key_id
}

resource "aws_cloudwatch_log_group" "msk_broker_logs" {
  name              = "/aws/msk/${local.name_prefix}"
  retention_in_days = 365

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-broker-logs"
  })
}

resource "aws_msk_cluster" "main" {
  cluster_name           = local.name_prefix
  kafka_version          = "3.6.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type   = "kafka.m5.large"
    client_subnets  = aws_subnet.private[*].id
    security_groups = [aws_security_group.kafka_brokers.id]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  client_authentication {
    sasl {
      iam = true
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk.arn

    encryption_in_transit {
      client_broker = "TLS"
      in_cluster    = true
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_broker_logs.name
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-cluster"
  })
}

output "msk_cluster_arn" {
  description = "ARN of the MSK cluster."
  value       = aws_msk_cluster.main.arn
}

output "bootstrap_brokers_sasl_iam" {
  description = "Comma-separated list of broker endpoints for SASL/IAM authenticated clients."
  value       = aws_msk_cluster.main.bootstrap_brokers_sasl_iam
}

output "bootstrap_brokers_tls" {
  description = "Comma-separated list of broker endpoints for TLS authenticated clients."
  value       = aws_msk_cluster.main.bootstrap_brokers_tls
}

output "zookeeper_connect_string" {
  description = "Comma-separated list of ZooKeeper connection string endpoints."
  value       = aws_msk_cluster.main.zookeeper_connect_string
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "tags" {
  description = "Common tags applied to all taggable resources."
  type        = map(string)
  default = {
    Project   = "msk-firehose-broker-logging"
    ManagedBy = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

locals {
  kafka_ports = {
    zookeeper     = 2181
    client_tls    = 9092
    client_tls2   = 9094
    iam_auth      = 9096
    iam_auth_tls  = 9098
  }
  log_prefix                  = "msk-broker-logs"
  auxiliary_endpoint_services = ["kms", "monitoring"]
}

# ---------------------------------------------------------------------------
# Network: dedicated VPC, one subnet per AZ, MSK security group
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, { Name = "msk-logging-vpc" })
}

resource "aws_subnet" "msk" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  map_public_ip_on_launch = false

  tags = merge(var.tags, { Name = "msk-broker-subnet-${count.index + 1}" })
}

resource "aws_security_group" "msk" {
  name        = "msk-broker-security-group"
  description = "Kafka client/broker traffic for the MSK cluster and HTTPS access to in-VPC AWS service endpoints. No public ingress."
  vpc_id      = aws_vpc.main.id

  tags = merge(var.tags, { Name = "msk-broker-security-group" })
}

resource "aws_security_group_rule" "msk_ingress_kafka" {
  for_each = local.kafka_ports

  type              = "ingress"
  from_port         = each.value
  to_port           = each.value
  protocol          = "tcp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.msk.id
  description       = "Kafka ${each.key} port ${each.value} from within the VPC only"
}

# This security group is also attached to the in-VPC AWS service endpoint ENIs
# (Firehose, KMS, CloudWatch), so HTTPS ingress sourced from the VPC CIDR is
# required to allow brokers to reach those endpoints.
resource "aws_security_group_rule" "msk_ingress_https" {
  type              = "ingress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.msk.id
  description       = "HTTPS from within the VPC to the AWS service endpoint ENIs"
}

resource "aws_security_group_rule" "msk_egress_https" {
  type              = "egress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.msk.id
  description       = "HTTPS toward AWS service endpoints"
}

resource "aws_security_group_rule" "msk_egress_kafka" {
  for_each = local.kafka_ports

  type              = "egress"
  from_port         = each.value
  to_port           = each.value
  protocol          = "tcp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.msk.id
  description       = "Intra-VPC Kafka ${each.key} traffic on port ${each.value}"
}

# ---------------------------------------------------------------------------
# Encryption: customer managed KMS key for MSK broker storage, the Firehose
# stream (at rest), and encrypted broker log delivery to S3
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "msk_kms_key_policy" {
  statement {
    sid       = "EnableIAMPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowFirehoseStreamEncryption"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:CreateGrant",
      "kms:ListGrants",
      "kms:DescribeKey",
    ]

    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["firehose.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["firehose.us-east-1.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "msk" {
  description             = "Customer managed key for MSK broker storage encryption and encrypted broker log delivery"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.msk_kms_key_policy.json

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(var.tags, { Name = "msk-broker-storage-key" })
}

resource "aws_kms_alias" "msk" {
  name          = "alias/msk-broker-storage"
  target_key_id = aws_kms_key.msk.key_id
}

# ---------------------------------------------------------------------------
# In-VPC AWS service endpoints so brokers need no public internet path
# ---------------------------------------------------------------------------

resource "aws_vpc_endpoint" "firehose" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.firehose"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.msk[*].id
  security_group_ids  = [aws_security_group.msk.id]
  private_dns_enabled = true

  tags = merge(var.tags, { Name = "firehose-interface-endpoint" })
}

resource "aws_vpc_endpoint" "auxiliary" {
  for_each = toset(local.auxiliary_endpoint_services)

  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.${each.value}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.msk[*].id
  security_group_ids  = [aws_security_group.msk.id]
  private_dns_enabled = true

  tags = merge(var.tags, { Name = "${each.value}-interface-endpoint" })
}

# ---------------------------------------------------------------------------
# S3 destination for Firehose-delivered broker logs
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "msk_logs" {
  bucket = "msk-broker-logs-${data.aws_caller_identity.current.account_id}"

  tags = merge(var.tags, { Name = "msk-broker-logs" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "msk_logs" {
  bucket = aws_s3_bucket.msk_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "msk_logs" {
  bucket = aws_s3_bucket.msk_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "msk_logs" {
  bucket = aws_s3_bucket.msk_logs.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.msk.arn
    }
  }
}

# ---------------------------------------------------------------------------
# IAM: Firehose delivery role (stream -> S3) and MSK broker log delivery role
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "firehose_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["firehose.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "firehose_delivery" {
  name               = "msk-firehose-delivery-role"
  assume_role_policy = data.aws_iam_policy_document.firehose_assume_role.json

  tags = merge(var.tags, { Name = "msk-firehose-delivery-role" })
}

data "aws_iam_policy_document" "firehose_s3_access" {
  statement {
    sid    = "WriteBrokerLogObjects"
    effect = "Allow"

    actions = [
      "s3:PutObject",
      "s3:PutObjectAcl",
      "s3:AbortMultipartUpload",
    ]

    resources = ["${aws_s3_bucket.msk_logs.arn}/${local.log_prefix}/*"]
  }

  statement {
    sid    = "BucketLevelAccess"
    effect = "Allow"

    actions = [
      "s3:GetBucketLocation",
      "s3:ListBucket",
    ]

    resources = [aws_s3_bucket.msk_logs.arn]
  }

  statement {
    sid    = "EncryptDeliveredLogObjects"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]

    resources = [aws_kms_key.msk.arn]
  }
}

resource "aws_iam_policy" "firehose_delivery" {
  name        = "msk-firehose-delivery-policy"
  description = "Least-privilege S3 and KMS access for the MSK broker log Firehose delivery stream"
  policy      = data.aws_iam_policy_document.firehose_s3_access.json
}

resource "aws_iam_role_policy_attachment" "firehose_delivery" {
  role       = aws_iam_role.firehose_delivery.name
  policy_arn = aws_iam_policy.firehose_delivery.arn
}

data "aws_iam_policy_document" "msk_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["kafka.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "msk_log_delivery" {
  name               = "msk-broker-log-delivery-role"
  assume_role_policy = data.aws_iam_policy_document.msk_assume_role.json

  tags = merge(var.tags, { Name = "msk-broker-log-delivery-role" })
}

data "aws_iam_policy_document" "msk_firehose_delivery" {
  statement {
    sid    = "PutBrokerLogsToFirehoseStream"
    effect = "Allow"

    actions = [
      "firehose:PutRecord",
      "firehose:PutRecordBatch",
    ]

    resources = [aws_kinesis_firehose_delivery_stream.msk_logs.arn]
  }

  statement {
    sid    = "UseCustomerManagedKeyForStreamEncryption"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]

    resources = [aws_kms_key.msk.arn]
  }
}

resource "aws_iam_policy" "msk_log_delivery" {
  name        = "msk-broker-log-delivery-policy"
  description = "Least-privilege Firehose and KMS access for Amazon MSK broker log delivery"
  policy      = data.aws_iam_policy_document.msk_firehose_delivery.json
}

resource "aws_iam_role_policy_attachment" "msk_log_delivery" {
  role       = aws_iam_role.msk_log_delivery.name
  policy_arn = aws_iam_policy.msk_log_delivery.arn
}

# ---------------------------------------------------------------------------
# Kinesis Data Firehose delivery stream (direct put -> date-prefixed S3)
# ---------------------------------------------------------------------------

resource "aws_kinesis_firehose_delivery_stream" "msk_logs" {
  name        = "msk-broker-logs"
  destination = "extended_s3"

  server_side_encryption {
    enabled  = true
    key_type = "CUSTOMER_MANAGED_CMK"
    key_arn  = aws_kms_key.msk.arn
  }

  extended_s3_configuration {
    role_arn           = aws_iam_role.firehose_delivery.arn
    bucket_arn         = aws_s3_bucket.msk_logs.arn
    prefix             = "${local.log_prefix}/!{timestamp:yyyy/MM/dd}/"
    buffering_size     = 5
    buffering_interval = 60
    compression_format = "GZIP"
    kms_key_arn        = aws_kms_key.msk.arn
  }

  tags = merge(var.tags, { Name = "msk-broker-logs" })

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Amazon MSK cluster streaming broker logs to the Firehose delivery stream
# ---------------------------------------------------------------------------

resource "aws_msk_cluster" "main" {
  cluster_name           = "msk-logging-cluster"
  kafka_version          = "3.6.0"
  number_of_broker_nodes = 3
  enhanced_monitoring    = "PER_BROKER"

  broker_node_group_info {
    az_distribution = "DEFAULT"
    instance_type   = "kafka.m5.large"
    client_subnets  = aws_subnet.msk[*].id
    security_groups = [aws_security_group.msk.id]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  client_authentication {
    sasl {
      iam = true
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk.arn

    encryption_in_transit {
      client_broker = "TLS"
      in_cluster    = true
    }
  }

  logging_info {
    broker_logs {
      # MSK's Firehose broker-log destination expects the delivery stream name;
      # the delivery stream ARN is granted to the msk_log_delivery IAM role.
      firehose {
        enabled         = true
        delivery_stream = aws_kinesis_firehose_delivery_stream.msk_logs.name
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(var.tags, { Name = "msk-logging-cluster" })
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "msk_cluster_arn" {
  description = "ARN of the Amazon MSK cluster."
  value       = aws_msk_cluster.main.arn
}

output "msk_bootstrap_brokers_tls" {
  description = "TLS bootstrap broker string for Kafka clients."
  value       = aws_msk_cluster.main.bootstrap_brokers_tls
}

output "firehose_delivery_stream_name" {
  description = "Name of the Firehose delivery stream receiving MSK broker logs."
  value       = aws_kinesis_firehose_delivery_stream.msk_logs.name
}

output "firehose_delivery_stream_arn" {
  description = "ARN of the Firehose delivery stream receiving MSK broker logs."
  value       = aws_kinesis_firehose_delivery_stream.msk_logs.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# -----------------------------------------------------------------------------
# Input variable: used for resource naming and tags ONLY (never as a substitute
# for a resource attribute), with a default so `terraform apply` runs unattended.
# -----------------------------------------------------------------------------

variable "environment" {
  description = "Environment name used for resource naming and tagging only."
  type        = string
  default     = "dev"
}

locals {
  name_prefix  = "msk-${var.environment}"
  cluster_name = "${local.name_prefix}-kafka"

  common_tags = {
    Application = "kafka"
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Static, well-known provider metadata lookups (no dependency on pre-existing
# infrastructure)
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# Greenfield networking: VPC, internet gateway, three subnets (one per AZ),
# routing, and the MSK broker security group
# -----------------------------------------------------------------------------

resource "aws_vpc" "kafka_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "kafka_igw" {
  vpc_id = aws_vpc.kafka_vpc.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

# MSK requires each broker subnet to be in a distinct Availability Zone:
# 3 brokers => 3 subnets in 3 AZs.
resource "aws_subnet" "kafka_subnet_az1" {
  vpc_id            = aws_vpc.kafka_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-az1"
  })
}

resource "aws_subnet" "kafka_subnet_az2" {
  vpc_id            = aws_vpc.kafka_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-az2"
  })
}

resource "aws_subnet" "kafka_subnet_az3" {
  vpc_id            = aws_vpc.kafka_vpc.id
  cidr_block        = "10.0.3.0/24"
  availability_zone = data.aws_availability_zones.available.names[2]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-az3"
  })
}

resource "aws_route_table" "kafka_route_table" {
  vpc_id = aws_vpc.kafka_vpc.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-route-table"
  })
}

resource "aws_route" "kafka_default_route" {
  route_table_id         = aws_route_table.kafka_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.kafka_igw.id
}

resource "aws_route_table_association" "kafka_rta_az1" {
  subnet_id      = aws_subnet.kafka_subnet_az1.id
  route_table_id = aws_route_table.kafka_route_table.id
}

resource "aws_route_table_association" "kafka_rta_az2" {
  subnet_id      = aws_subnet.kafka_subnet_az2.id
  route_table_id = aws_route_table.kafka_route_table.id
}

resource "aws_route_table_association" "kafka_rta_az3" {
  subnet_id      = aws_subnet.kafka_subnet_az3.id
  route_table_id = aws_route_table.kafka_route_table.id
}

# Broker security group: ingress restricted to TLS (9094), SASL/IAM (9098) and
# ZooKeeper (2181) from within the VPC only, plus a self-referencing rule for
# broker-to-broker traffic. No 0.0.0.0/0 ingress is permitted.
resource "aws_security_group" "kafka_broker_sg" {
  name        = "${local.name_prefix}-brokers-sg"
  description = "Security group for the MSK broker nodes (TLS 9094, SASL/IAM 9098, ZooKeeper 2181, broker-to-broker)"
  vpc_id      = aws_vpc.kafka_vpc.id

  ingress {
    description = "TLS client-broker connections"
    from_port   = 9094
    to_port     = 9094
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.kafka_vpc.cidr_block]
  }

  ingress {
    description = "SASL/IAM client-broker connections"
    from_port   = 9098
    to_port     = 9098
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.kafka_vpc.cidr_block]
  }

  ingress {
    description = "ZooKeeper client connections"
    from_port   = 2181
    to_port     = 2181
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.kafka_vpc.cidr_block]
  }

  ingress {
    description = "Broker-to-broker traffic from the security group itself"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  egress {
    description = "Allow broker outbound access to AWS service endpoints"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-brokers-sg"
  })
}

# -----------------------------------------------------------------------------
# Customer managed KMS key for encryption at rest and broker log encryption
# -----------------------------------------------------------------------------

resource "aws_kms_key" "kafka_kms_key" {
  description             = "Customer managed key for MSK cluster encryption at rest and CloudWatch broker log encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableIAMUserPermissions"
        Effect    = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid       = "AllowCloudWatchLogsToEncryptLogs"
        Effect    = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          ArnLike = {
            "kms:EncryptionContext:aws:logs:arn" = "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:*"
          }
        }
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-kms-key"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "kafka_kms_alias" {
  name          = "alias/${local.name_prefix}-kafka"
  target_key_id = aws_kms_key.kafka_kms_key.key_id
}

# -----------------------------------------------------------------------------
# CloudWatch log group for MSK broker logs
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "kafka_broker_logs" {
  name              = "/aws/msk/${local.cluster_name}"
  retention_in_days = 30
  kms_key_id        = aws_kms_key.kafka_kms_key.arn

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-broker-logs"
  })
}

# -----------------------------------------------------------------------------
# Provisioned MSK cluster with exactly 3 broker nodes (serverless MSK does not
# support broker nodes, so a provisioned cluster is used). Broker EBS storage
# size uses the provider v5 nested form:
#   broker_node_group_info.storage_info.ebs_storage_info.volume_size
# -----------------------------------------------------------------------------

resource "aws_msk_cluster" "kafka_cluster" {
  cluster_name           = local.cluster_name
  kafka_version          = "3.6.0"
  number_of_broker_nodes = 3
  enhanced_monitoring    = "DEFAULT"

  broker_node_group_info {
    instance_type  = "kafka.m5.large"
    client_subnets = [
      aws_subnet.kafka_subnet_az1.id,
      aws_subnet.kafka_subnet_az2.id,
      aws_subnet.kafka_subnet_az3.id,
    ]
    security_groups = [aws_security_group.kafka_broker_sg.id]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.kafka_kms_key.arn

    encryption_in_transit {
      client_broker = "TLS"
      in_cluster    = true
    }
  }

  client_authentication {
    sasl {
      iam = true
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.kafka_broker_logs.name
      }
    }
  }

  tags = merge(local.common_tags, {
    Name = local.cluster_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# IAM: least-privilege client role for IAM access control on the cluster.
# Only kafka-cluster actions, scoped to this cluster's ARN and its
# topic/group ARNs. No wildcard Action/Resource statements.
# -----------------------------------------------------------------------------

resource "aws_iam_role" "kafka_client_role" {
  name = "${local.name_prefix}-kafka-client-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowEC2ClientAssume"
        Effect    = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-kafka-client-role"
  })
}

resource "aws_iam_role_policy" "kafka_client_policy" {
  name = "${local.name_prefix}-kafka-client-access"
  role = aws_iam_role.kafka_client_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "KafkaClusterConnect"
        Effect = "Allow"
        Action = [
          "kafka-cluster:Connect",
        ]
        Resource = [
          aws_msk_cluster.kafka_cluster.arn,
        ]
      },
      {
        Sid    = "KafkaTopicOperations"
        Effect = "Allow"
        Action = [
          "kafka-cluster:CreateTopic",
          "kafka-cluster:DescribeTopic",
          "kafka-cluster:ReadData",
          "kafka-cluster:WriteData",
        ]
        Resource = [
          aws_msk_cluster.kafka_cluster.arn,
          "${aws_msk_cluster.kafka_cluster.arn}/topic/*",
        ]
      },
      {
        Sid    = "KafkaConsumerGroupOperations"
        Effect = "Allow"
        Action = [
          "kafka-cluster:AlterGroup",
        ]
        Resource = [
          "${aws_msk_cluster.kafka_cluster.arn}/group/*",
        ]
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Outputs for client onboarding
# -----------------------------------------------------------------------------

output "msk_cluster_arn" {
  description = "ARN of the provisioned MSK cluster (3 broker nodes)."
  value       = aws_msk_cluster.kafka_cluster.arn
}

output "msk_bootstrap_brokers_tls" {
  description = "Comma-separated list of bootstrap broker endpoints for TLS clients (port 9094)."
  value       = aws_msk_cluster.kafka_cluster.bootstrap_brokers_tls
}

output "msk_bootstrap_brokers_sasl_iam" {
  description = "Comma-separated list of bootstrap broker endpoints for SASL/IAM authenticated clients (port 9098)."
  value       = aws_msk_cluster.kafka_cluster.bootstrap_brokers_sasl_iam
}

output "kafka_client_role_arn" {
  description = "ARN of the least-privilege IAM role clients assume for IAM-authenticated access to the cluster."
  value       = aws_iam_role.kafka_client_role.arn
}

###############################################################################
# Terraform + provider configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables
###############################################################################

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

variable "vpc_cidr" {
  description = "CIDR block for the dedicated MSK VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "debezium_plugin_zip_path" {
  description = "Local path to the Debezium plugin archive (debezium.zip) uploaded to S3."
  type        = string
  default     = "debezium.zip"
}

variable "db_username" {
  description = "Username of the Debezium source database (non-secret identifier)."
  type        = string
  default     = "debezium"
}

variable "db_password" {
  description = "Password of the Debezium source database. Supply via a sensitive input in real deployments; when omitted, a deterministic value is generated and persisted only in Secrets Manager."
  type        = string
  sensitive   = true
  default     = null
}

variable "db_hostname" {
  description = "Hostname of the Debezium source database."
  type        = string
  default     = "source-database.internal"
}

variable "db_port" {
  description = "Port of the Debezium source database."
  type        = string
  default     = "3306"
}

###############################################################################
# Data sources (static / provider metadata lookups only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  name_prefix = "msk-debezium-${lower(var.environment)}"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
    Project     = "msk-connect-debezium"
  }

  # The source database password is never stored as plaintext in this
  # configuration: it is either supplied as a sensitive variable or derived
  # deterministically from non-secret infrastructure identifiers and then
  # persisted in AWS Secrets Manager.
  source_db_password = coalesce(var.db_password, sha256("debezium-source-db-seed-${aws_vpc.main.id}"))
}

###############################################################################
# Networking: VPC, subnets, routing, service endpoints
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-igw" })
}

# Public subnets (one per AZ) host the NAT gateways that provide the private
# MSK / MSK Connect subnets with outbound connectivity to AWS service endpoints.
resource "aws_subnet" "public_0" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, 0)
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-0" })
}

resource "aws_subnet" "public_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, 1)
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-1" })
}

resource "aws_subnet" "public_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, 2)
  availability_zone       = data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-2" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-rt" })
}

resource "aws_route_table_association" "public_0" {
  subnet_id      = aws_subnet.public_0.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_1" {
  subnet_id      = aws_subnet.public_1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_2" {
  subnet_id      = aws_subnet.public_2.id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat_0" {
  domain = "vpc"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-nat-eip-0" })
}

resource "aws_eip" "nat_1" {
  domain = "vpc"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-nat-eip-1" })
}

resource "aws_eip" "nat_2" {
  domain = "vpc"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-nat-eip-2" })
}

resource "aws_nat_gateway" "nat_0" {
  allocation_id = aws_eip.nat_0.id
  subnet_id     = aws_subnet.public_0.id

  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-nat-0" })
}

resource "aws_nat_gateway" "nat_1" {
  allocation_id = aws_eip.nat_1.id
  subnet_id     = aws_subnet.public_1.id

  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-nat-1" })
}

resource "aws_nat_gateway" "nat_2" {
  allocation_id = aws_eip.nat_2.id
  subnet_id     = aws_subnet.public_2.id

  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-nat-2" })
}

# Private subnets (one per distinct AZ) host the 3 MSK broker nodes and the
# MSK Connect workers.
resource "aws_subnet" "private_0" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, 10)
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-0" })
}

resource "aws_subnet" "private_1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, 11)
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-1" })
}

resource "aws_subnet" "private_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, 12)
  availability_zone = data.aws_availability_zones.available.names[2]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-2" })
}

resource "aws_route_table" "private_0" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat_0.id
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-rt-0" })
}

resource "aws_route_table" "private_1" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat_1.id
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-rt-1" })
}

resource "aws_route_table" "private_2" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat_2.id
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-rt-2" })
}

resource "aws_route_table_association" "private_0" {
  subnet_id      = aws_subnet.private_0.id
  route_table_id = aws_route_table.private_0.id
}

resource "aws_route_table_association" "private_1" {
  subnet_id      = aws_subnet.private_1.id
  route_table_id = aws_route_table.private_1.id
}

resource "aws_route_table_association" "private_2" {
  subnet_id      = aws_subnet.private_2.id
  route_table_id = aws_route_table.private_2.id
}

# S3 gateway endpoint keeps custom-plugin artifact traffic on the AWS backbone.
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private_0.id, aws_route_table.private_1.id, aws_route_table.private_2.id]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-s3-endpoint" })
}

###############################################################################
# Security groups
###############################################################################

resource "aws_security_group" "msk_connect_workers" {
  name_prefix = "${local.name_prefix}-workers-"
  description = "MSK Connect worker nodes. Outbound access to MSK brokers (9094/9098), S3, CloudWatch Logs and Secrets Manager."
  vpc_id      = aws_vpc.main.id

  egress {
    description = "All outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-msk-connect-workers" })
}

resource "aws_security_group" "msk_brokers" {
  name_prefix = "${local.name_prefix}-brokers-"
  description = "MSK broker nodes. TLS client traffic (9094) and SASL/IAM traffic (9098) only from MSK Connect workers, plus self-referencing inter-broker traffic."
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "TLS client traffic (9094) from MSK Connect workers"
    from_port       = 9094
    to_port         = 9094
    protocol        = "tcp"
    security_groups = [aws_security_group.msk_connect_workers.id]
  }

  ingress {
    description     = "SASL/IAM client traffic (9098) from MSK Connect workers"
    from_port       = 9098
    to_port         = 9098
    protocol        = "tcp"
    security_groups = [aws_security_group.msk_connect_workers.id]
  }

  ingress {
    description = "Inter-broker communication (self-referencing security group)"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  egress {
    description = "All outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-msk-brokers" })
}

###############################################################################
# MSK cluster (3 brokers, TLS + SASL/IAM auth, KMS-managed encryption at rest)
###############################################################################

resource "aws_msk_cluster" "main" {
  cluster_name           = "${local.name_prefix}-cluster"
  kafka_version          = "3.6.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type   = "kafka.m5.large"
    client_subnets  = [aws_subnet.private_0.id, aws_subnet.private_1.id, aws_subnet.private_2.id]
    security_groups = [aws_security_group.msk_brokers.id]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  # TLS client authentication with AWS-signed certificates and SASL/IAM
  # (SigV4) authentication for MSK Connect; unauthenticated client access
  # is explicitly disabled.
  client_authentication {
    tls {}

    sasl {
      iam = true
    }

    unauthenticated = false
  }

  # Encryption at rest is KMS-managed (AWS managed key aws/msk by default);
  # client-broker traffic is encrypted in transit with TLS only.
  encryption_info {
    encryption_in_transit {
      client_broker = "TLS"
      in_cluster    = true
    }
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-cluster" })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# S3 bucket for the custom plugin artifact
###############################################################################

resource "aws_s3_bucket" "plugin_artifacts" {
  bucket = "${local.name_prefix}-plugin-artifacts-${data.aws_caller_identity.current.account_id}"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-plugin-artifacts" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "plugin_artifacts" {
  bucket                  = aws_s3_bucket.plugin_artifacts.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "plugin_artifacts" {
  bucket = aws_s3_bucket.plugin_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "plugin_artifacts" {
  bucket = aws_s3_bucket.plugin_artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_object" "debezium_plugin" {
  bucket       = aws_s3_bucket.plugin_artifacts.id
  key          = "plugins/debezium.zip"
  source       = var.debezium_plugin_zip_path
  content_type = "application/zip"

  depends_on = [aws_s3_bucket_versioning.plugin_artifacts]
}

###############################################################################
# MSK Connect custom plugin (Debezium)
###############################################################################

resource "aws_mskconnect_custom_plugin" "debezium" {
  name         = "${local.name_prefix}-debezium-plugin"
  content_type = "ZIP"

  location {
    s3 {
      bucket_arn     = aws_s3_bucket.plugin_artifacts.arn
      file_key       = aws_s3_object.debezium_plugin.key
      object_version = aws_s3_object.debezium_plugin.version_id
    }
  }

  tags = local.common_tags
}

###############################################################################
# CloudWatch Logs for connector worker logs
###############################################################################

resource "aws_cloudwatch_log_group" "msk_connect_worker" {
  name              = "/aws/msk-connect/${local.name_prefix}/workers"
  retention_in_days = 30

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-worker-logs" })
}

###############################################################################
# Source database credentials in Secrets Manager (no plaintext secrets here)
###############################################################################

resource "aws_secretsmanager_secret" "db_credentials" {
  name                    = "${local.name_prefix}-debezium-db-credentials"
  description             = "Credentials of the source database consumed by the Debezium MSK Connect connector."
  recovery_window_in_days = 7

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-db-credentials" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "db_credentials" {
  secret_id = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({
    username = var.db_username
    password = local.source_db_password
  })
}

###############################################################################
# MSK Connect service execution role (least privilege, inline policies)
###############################################################################

data "aws_iam_policy_document" "msk_connect_assume_role" {
  statement {
    sid     = "AllowMSKConnectToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["kafkaconnect.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "msk_connect_execution" {
  name               = "${local.name_prefix}-connector-execution"
  description        = "Service execution role assumed by MSK Connect connector workers."
  assume_role_policy = data.aws_iam_policy_document.msk_connect_assume_role.json

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-connector-execution" })
}

data "aws_iam_policy_document" "plugin_artifact_read" {
  statement {
    sid       = "ReadCustomPluginArtifact"
    effect    = "Allow"
    actions   = ["s3:GetObject"]
    resources = ["${aws_s3_bucket.plugin_artifacts.arn}/plugins/*"]
  }
}

data "aws_iam_policy_document" "msk_cluster_access" {
  statement {
    sid    = "ConnectAndDescribeMSKCluster"
    effect = "Allow"
    actions = [
      "kafka:Connect",
      "kafka:CreateVpcConnection",
      "kafka:DescribeCluster",
      "kafka:DescribeClusterV2",
      "kafka:GetBootstrapBrokers",
    ]
    resources = [aws_msk_cluster.main.arn]
  }

  # Data-plane permissions enforced by the cluster's SASL/IAM access control.
  statement {
    sid    = "IAMAuthClusterDataPlane"
    effect = "Allow"
    actions = [
      "kafka-cluster:Connect",
      "kafka-cluster:DescribeCluster",
    ]
    resources = [aws_msk_cluster.main.arn]
  }

  statement {
    sid    = "IAMAuthTopicDataPlane"
    effect = "Allow"
    actions = [
      "kafka-cluster:CreateTopic",
      "kafka-cluster:DescribeTopic",
      "kafka-cluster:AlterTopic",
      "kafka-cluster:WriteData",
      "kafka-cluster:ReadData",
    ]
    resources = ["${aws_msk_cluster.main.arn}/topic/*"]
  }

  statement {
    sid    = "IAMAuthGroupDataPlane"
    effect = "Allow"
    actions = [
      "kafka-cluster:DescribeGroup",
      "kafka-cluster:AlterGroup",
    ]
    resources = ["${aws_msk_cluster.main.arn}/group/*"]
  }
}

data "aws_iam_policy_document" "worker_log_delivery" {
  statement {
    sid       = "DeliverWorkerLogsToCloudWatch"
    effect    = "Allow"
    actions   = ["logs:CreateLogStream", "logs:PutLogEvents"]
    resources = ["${aws_cloudwatch_log_group.msk_connect_worker.arn}:*"]
  }
}

data "aws_iam_policy_document" "db_credentials_read" {
  statement {
    sid       = "ReadSourceDatabaseCredentials"
    effect    = "Allow"
    actions   = ["secretsmanager:GetSecretValue"]
    resources = [aws_secretsmanager_secret.db_credentials.arn]
  }
}

resource "aws_iam_role_policy" "plugin_artifact_read" {
  name   = "custom-plugin-artifact-read"
  role   = aws_iam_role.msk_connect_execution.name
  policy = data.aws_iam_policy_document.plugin_artifact_read.json
}

resource "aws_iam_role_policy" "msk_cluster_access" {
  name   = "msk-cluster-access"
  role   = aws_iam_role.msk_connect_execution.name
  policy = data.aws_iam_policy_document.msk_cluster_access.json
}

resource "aws_iam_role_policy" "worker_log_delivery" {
  name   = "worker-log-delivery"
  role   = aws_iam_role.msk_connect_execution.name
  policy = data.aws_iam_policy_document.worker_log_delivery.json
}

resource "aws_iam_role_policy" "db_credentials_read" {
  name   = "source-db-credentials-read"
  role   = aws_iam_role.msk_connect_execution.name
  policy = data.aws_iam_policy_document.db_credentials_read.json
}

###############################################################################
# MSK Connect connector (Debezium, SASL/IAM over TLS to the MSK cluster)
###############################################################################

resource "aws_mskconnect_connector" "debezium_source" {
  name        = "${local.name_prefix}-debezium-connector"
  description = "Debezium source connector streaming change data events from the source database into the MSK cluster."

  kafkaconnect_version = "3.6.0"

  kafka_cluster {
    apache_kafka_cluster {
      bootstrap_servers = aws_msk_cluster.main.bootstrap_brokers_sasl_iam

      vpc {
        security_groups = [aws_security_group.msk_connect_workers.id]
        subnets         = [aws_subnet.private_0.id, aws_subnet.private_1.id, aws_subnet.private_2.id]
      }
    }
  }

  kafka_cluster_client_authentication {
    authentication_type = "IAM"
  }

  kafka_cluster_encryption_in_transit {
    encryption_type = "TLS"
  }

  capacity {
    provisioned_capacity {
      worker_count = 1
      mcu_count    = 1
    }
  }

  connector_configuration = {
    "bootstrap.servers"                               = aws_msk_cluster.main.bootstrap_brokers_sasl_iam
    "connector.class"                                 = "io.debezium.connector.mysql.MySqlConnector"
    "tasks.max"                                       = "1"
    "database.hostname"                               = var.db_hostname
    "database.port"                                   = var.db_port
    "database.user"                                   = "$${secretsManager:${aws_secretsmanager_secret.db_credentials.arn}:username}"
    "database.password"                               = "$${secretsManager:${aws_secretsmanager_secret.db_credentials.arn}:password}"
    "database.server.id"                              = "184054"
    "database.include.list"                           = "inventory"
    "topic.prefix"                                    = "debezium-source"
    "schema.history.internal.kafka.bootstrap.servers" = aws_msk_cluster.main.bootstrap_brokers_sasl_iam
    "schema.history.internal.kafka.topic"             = "debezium-source.schema-changes"
    "schema.history.internal.kafka.security.protocol" = "SASL_SSL"
    "key.converter"                                   = "org.apache.kafka.connect.json.JsonConverter"
    "value.converter"                                 = "org.apache.kafka.connect.json.JsonConverter"
  }

  plugin {
    custom_plugin {
      arn      = aws_mskconnect_custom_plugin.debezium.arn
      revision = aws_mskconnect_custom_plugin.debezium.latest_revision
    }
  }

  service_execution_role_arn = aws_iam_role.msk_connect_execution.arn

  log_delivery {
    worker_log_delivery {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_connect_worker.name
      }
    }
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-debezium-connector" })

  depends_on = [
    aws_iam_role_policy.plugin_artifact_read,
    aws_iam_role_policy.msk_cluster_access,
    aws_iam_role_policy.worker_log_delivery,
    aws_iam_role_policy.db_credentials_read,
  ]
}

###############################################################################
# Outputs
###############################################################################

output "msk_cluster_arn" {
  description = "ARN of the MSK cluster."
  value       = aws_msk_cluster.main.arn
}

output "msk_cluster_bootstrap_brokers_tls" {
  description = "TLS bootstrap broker string of the MSK cluster."
  value       = aws_msk_cluster.main.bootstrap_brokers_tls
}

output "msk_cluster_bootstrap_brokers_sasl_iam" {
  description = "SASL/IAM bootstrap broker string of the MSK cluster."
  value       = aws_msk_cluster.main.bootstrap_brokers_sasl_iam
}

output "msk_connect_custom_plugin_arn" {
  description = "ARN of the Debezium MSK Connect custom plugin."
  value       = aws_mskconnect_custom_plugin.debezium.arn
}

output "msk_connect_connector_arn" {
  description = "ARN of the Debezium MSK Connect connector."
  value       = aws_mskconnect_connector.debezium_source.arn
}

terraform {
  required_version = ">= 1.5.0, < 2.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  environment = "production"

  common_tags = {
    Environment = local.environment
    ManagedBy   = "terraform"
  }
}

# --- Network foundation (greenfield: all resources created in this file) ---

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "mysql-cluster-vpc"
  })
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.11.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "mysql-cluster-private-a"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.12.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "mysql-cluster-private-b"
  })
}

resource "aws_subnet" "private_c" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.13.0/24"
  availability_zone       = data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "mysql-cluster-private-c"
  })
}

resource "aws_db_subnet_group" "mysql" {
  name        = "mysql-cluster-db-subnet-group"
  description = "Private subnets across three AZs for the MySQL Multi-AZ DB cluster"

  subnet_ids = [
    aws_subnet.private_a.id,
    aws_subnet.private_b.id,
    aws_subnet.private_c.id,
  ]

  tags = merge(local.common_tags, {
    Name = "mysql-cluster-db-subnet-group"
  })
}

# --- Security group: TCP 3306 from the VPC only, restricted egress ---

resource "aws_security_group" "mysql_cluster" {
  name        = "mysql-cluster-sg"
  description = "MySQL Multi-AZ DB cluster: TCP 3306 from VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL client and replication traffic from within the VPC"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "MySQL replication traffic to cluster peers within the VPC"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "mysql-cluster-sg"
  })
}

# --- Encryption at rest ---

resource "aws_kms_key" "mysql" {
  description             = "Customer-managed key for the MySQL Multi-AZ DB cluster"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "mysql-cluster-kms-key"
  })
}

resource "aws_kms_alias" "mysql" {
  name          = "alias/rds-mysql-cluster"
  target_key_id = aws_kms_key.mysql.key_id
}

# --- Master credentials (generated, stored in Secrets Manager, KMS-encrypted) ---

resource "random_password" "master" {
  length           = 32
  special          = true
  override_special = "!#$%*()-_=+[]{}:?"
}

resource "random_id" "final_snapshot" {
  byte_length = 4
}

resource "aws_secretsmanager_secret" "master" {
  name        = "rds/mysql-cluster/master"
  description = "Master credentials for the MySQL Multi-AZ DB cluster"
  kms_key_id  = aws_kms_key.mysql.arn

  tags = merge(local.common_tags, {
    Name = "rds-mysql-cluster-master"
  })
}

resource "aws_secretsmanager_secret_version" "master" {
  secret_id = aws_secretsmanager_secret.master.id
  secret_string = jsonencode({
    username = "dbadmin"
    password = random_password.master.result
  })
}

# --- Cluster parameter group ---

resource "aws_rds_cluster_parameter_group" "mysql" {
  name        = "mysql-cluster-params"
  family      = "mysql8.0"
  description = "Secure cluster parameters for the MySQL Multi-AZ DB cluster"

  parameter {
    name  = "require_secure_transport"
    value = "1"
  }

  tags = merge(local.common_tags, {
    Name = "mysql-cluster-params"
  })
}

# --- MySQL Multi-AZ DB cluster: writer + two readers, 100 GiB io1 per AZ ---
# Note: automatic minor engine version upgrades are applied by RDS at the
# service level for Multi-AZ DB clusters; no instance-level flag is needed.

resource "aws_rds_cluster" "mysql" {
  cluster_identifier = "mysql-multiaz-cluster"
  engine             = "mysql"
  engine_version     = "8.0.35"

  master_username = "dbadmin"
  master_password = random_password.master.result

  port                      = 3306
  db_cluster_instance_class = "db.r6gd.xlarge"
  allocated_storage         = 100
  storage_type              = "io1"
  iops                      = 1000

  storage_encrypted = true
  kms_key_id        = aws_kms_key.mysql.arn

  db_subnet_group_name   = aws_db_subnet_group.mysql.name
  vpc_security_group_ids = [aws_security_group.mysql_cluster.id]

  db_cluster_parameter_group_name = aws_rds_cluster_parameter_group.mysql.name

  backup_retention_period = 7
  copy_tags_to_snapshot   = true

  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "mysql-multiaz-cluster-final-${random_id.final_snapshot.hex}"

  iam_database_authentication_enabled = true
  performance_insights_enabled        = true

  tags = merge(local.common_tags, {
    Name = "mysql-multiaz-cluster"
  })

  lifecycle {
    prevent_destroy = true
    ignore_changes  = [engine_version]
  }
}

# --- Outputs (non-sensitive only) ---

output "cluster_writer_endpoint" {
  description = "Writer endpoint of the MySQL Multi-AZ DB cluster"
  value       = aws_rds_cluster.mysql.endpoint
}

output "cluster_reader_endpoint" {
  description = "Reader endpoint of the MySQL Multi-AZ DB cluster"
  value       = aws_rds_cluster.mysql.reader_endpoint
}

output "cluster_port" {
  description = "Port the MySQL Multi-AZ DB cluster listens on"
  value       = aws_rds_cluster.mysql.port
}

output "master_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the cluster master credentials"
  value       = aws_secretsmanager_secret.master.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Logical environment name used for resource tagging (non-infrastructure identifier)."
  type        = string
  default     = "dev"

  validation {
    condition     = contains(["dev", "staging", "prod"], var.environment)
    error_message = "environment must be one of: dev, staging, prod."
  }
}

locals {
  table_name = "app-data-${var.environment}"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_kms_key" "dynamodb" {
  description             = "Customer managed CMK used for DynamoDB server-side encryption"
  key_usage               = "ENCRYPT_DECRYPT"
  is_enabled              = true
  enable_key_rotation     = true
  deletion_window_in_days = 7

  tags = merge(local.common_tags, {
    Name = "dynamodb-cmk-${var.environment}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "dynamodb" {
  name          = "alias/dynamodb-${var.environment}"
  target_key_id = aws_kms_key.dynamodb.key_id
}

resource "aws_dynamodb_table" "main" {
  name         = local.table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "PK"
  range_key    = "SK"

  attribute {
    name = "PK"
    type = "S"
  }

  attribute {
    name = "SK"
    type = "S"
  }

  deletion_protection_enabled = true

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.dynamodb.arn
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = merge(local.common_tags, {
    Name = local.table_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

output "dynamodb_table_id" {
  description = "ID of the DynamoDB table."
  value       = aws_dynamodb_table.main.id
}

output "dynamodb_table_arn" {
  description = "ARN of the DynamoDB table."
  value       = aws_dynamodb_table.main.arn
}

output "dynamodb_kms_key_arn" {
  description = "ARN of the customer managed KMS key used for table encryption."
  value       = aws_kms_key.dynamodb.arn
}

