  }
}

resource "aws_vpc" "main" {
  cidr_block                       = "10.0.0.0/16"
  assign_generated_ipv6_cidr_block = true

  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "example-vpc"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  # Explicitly defined trusted CIDR (e.g. corporate network reachable via VPN/Direct Connect).
  # Narrowed to a subset of RFC 1918 space outside the VPC CIDR (10.0.0.0/16)
  # to tighten the ingress surface. Adjust to the smallest legitimate corporate range.
  trusted_ingress_cidr = "10.10.0.0/16"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "main" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "main-subnet"
  }
}

resource "aws_network_acl" "main" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.main.id]

  tags = {
    Name = "main-nacl"
  }
}

# -----------------------------------------------------------------------------
# Ingress rules.
# Network ACLs are stateless, so an explicit ephemeral-port (1024-65535) rule is
# required for TCP return traffic. All traffic not matching an allow rule is
# implicitly denied by the default-deny (*) rule AWS appends to every NACL.
# Per-rule traceability is provided by the snake_case resource labels below;
# the aws_network_acl_rule schema does not support tags.
# -----------------------------------------------------------------------------

resource "aws_network_acl_rule" "ingress_https" {
  network_acl_id = aws_network_acl.main.id
  rule_number    = 100
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = local.trusted_ingress_cidr
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "ingress_http" {
  network_acl_id = aws_network_acl.main.id
  rule_number    = 110
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = local.trusted_ingress_cidr
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "ingress_ephemeral_return" {
  network_acl_id = aws_network_acl.main.id
  rule_number    = 120
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = local.trusted_ingress_cidr
  from_port      = 1024
  to_port        = 65535
}

# -----------------------------------------------------------------------------
# Egress rules. All unmatched egress remains implicitly denied.
# -----------------------------------------------------------------------------

resource "aws_network_acl_rule" "egress_https" {
  network_acl_id = aws_network_acl.main.id
  rule_number    = 100
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "egress_http" {
  network_acl_id = aws_network_acl.main.id
  rule_number    = 110
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "egress_ephemeral_return" {
  network_acl_id = aws_network_acl.main.id
  rule_number    = 120
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 1024
  to_port        = 65535
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "tags" {
  description = "Tags applied to all taggable resources for consistent tagging."
  type        = map(string)

  default = {
    Environment = "dev"
    Project     = "neptune-basic"
  }
}

locals {
  name_prefix = "neptune-basic"
}

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# Networking foundation
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 10)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(var.tags, {
    Name = "${local.name_prefix}-private-${count.index}"
  })
}

resource "aws_security_group" "neptune" {
  name        = "${local.name_prefix}-neptune-sg"
  description = "Allow Neptune (8182) traffic from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Neptune from VPC CIDR only"
    from_port   = 8182
    to_port     = 8182
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(var.tags, {
    Name = "${local.name_prefix}-neptune-sg"
  })
}

# ---------------------------------------------------------------------------
# Encryption
# ---------------------------------------------------------------------------

resource "aws_kms_key" "neptune" {
  description             = "KMS key for Neptune cluster storage encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(var.tags, {
    Name = "${local.name_prefix}-neptune-kms"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "neptune" {
  name          = "alias/${local.name_prefix}-neptune"
  target_key_id = aws_kms_key.neptune.key_id
}

# ---------------------------------------------------------------------------
# Neptune parameter groups
# ---------------------------------------------------------------------------

resource "aws_neptune_cluster_parameter_group" "main" {
  family      = "neptune1.3"
  name        = "${local.name_prefix}-cluster-pg"
  description = "Custom Neptune cluster parameter group with audit logging enabled"

  parameter {
    name  = "neptune_enable_audit_log"
    value = "1"
  }

  tags = var.tags
}

resource "aws_neptune_parameter_group" "main" {
  family      = "neptune1.3"
  name        = "${local.name_prefix}-instance-pg"
  description = "Custom Neptune DB instance parameter group"

  parameter {
    name  = "neptune_query_timeout"
    value = "120000"
  }

  tags = var.tags
}

# ---------------------------------------------------------------------------
# Neptune subnet group
# ---------------------------------------------------------------------------

resource "aws_neptune_subnet_group" "main" {
  name        = "${local.name_prefix}-subnet-group"
  description = "Neptune subnet group spanning multiple availability zones"
  subnet_ids  = [aws_subnet.private[0].id, aws_subnet.private[1].id]

  tags = var.tags
}

# ---------------------------------------------------------------------------
# Neptune cluster and writer instance
# ---------------------------------------------------------------------------

resource "aws_neptune_cluster" "main" {
  cluster_identifier = "${local.name_prefix}-cluster"
  engine             = "neptune"
  engine_version     = "1.3.0.0"

  neptune_subnet_group_name            = aws_neptune_subnet_group.main.name
  neptune_cluster_parameter_group_name = aws_neptune_cluster_parameter_group.main.name
  vpc_security_group_ids               = [aws_security_group.neptune.id]

  iam_database_authentication_enabled = true

  storage_encrypted = true
  kms_key_arn       = aws_kms_key.neptune.arn

  backup_retention_period        = 14
  copy_tags_to_snapshot          = true
  deletion_protection            = true
  apply_immediately              = false
  skip_final_snapshot            = true
  enable_cloudwatch_logs_exports = ["audit"]

  tags = merge(var.tags, {
    Name = "${local.name_prefix}-cluster"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_neptune_cluster_instance" "writer" {
  identifier         = "${local.name_prefix}-writer"
  cluster_identifier = aws_neptune_cluster.main.cluster_identifier
  instance_class     = "db.r6g.large"

  neptune_parameter_group_name = aws_neptune_parameter_group.main.name

  apply_immediately = false

  tags = merge(var.tags, {
    Name = "${local.name_prefix}-writer"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "cluster_endpoint" {
  description = "Neptune cluster writer endpoint"
  value       = aws_neptune_cluster.main.endpoint
}

output "reader_endpoint" {
  description = "Neptune cluster reader endpoint"
  value       = aws_neptune_cluster.main.reader_endpoint
}

output "port" {
  description = "Port on which the Neptune cluster accepts connections"
  value       = aws_neptune_cluster.main.port
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ------------------------------------------------------------------------------
# Variables (all have defaults so `terraform apply` runs unattended)
# ------------------------------------------------------------------------------

variable "name_prefix" {
  description = "Name prefix assigned to every created resource."
  type        = string
  default     = "neptune"
}

variable "vpc_cidr" {
  description = "Private (RFC 1918) CIDR block for the VPC hosting the Neptune cluster."
  type        = string
  default     = "10.0.0.0/16"
}

variable "example_subnet_cidr" {
  description = "CIDR block of the example subnet that is allowed to reach Neptune."
  type        = string
  default     = "10.0.1.0/24"
}

variable "secondary_subnet_cidr" {
  description = "CIDR block of the additional subnet in a second AZ (required by Neptune subnet groups)."
  type        = string
  default     = "10.0.2.0/24"
}

variable "neptune_instance_class" {
  description = "Instance class of the Neptune cluster instance."
  type        = string
  default     = "db.r5.large"
}

variable "backup_retention_period" {
  description = "Number of days automated Neptune backups are retained."
  type        = number
  default     = 7
}

variable "tags" {
  description = "Tags applied to every created resource."
  type        = map(string)
  default = {
    Environment = "example"
    ManagedBy   = "terraform"
    Project     = "neptune-example"
  }
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------

locals {
  common_tags = merge(var.tags, {
    Terraform = "true"
  })
}

# ------------------------------------------------------------------------------
# Data sources (static/well-known lookups only)
# ------------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# ------------------------------------------------------------------------------
# Networking
# ------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-vpc"
  })
}

# The "example" subnet - the only network allowed to reach the Neptune cluster.
resource "aws_subnet" "example" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.example_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-example-subnet"
  })
}

# Neptune subnet groups require subnets spanning at least two AZs.
resource "aws_subnet" "neptune_secondary" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.secondary_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-secondary-subnet"
  })
}

# ------------------------------------------------------------------------------
# Security group - the only connection path attached to the cluster
# ------------------------------------------------------------------------------

resource "aws_security_group" "neptune" {
  name        = "${var.name_prefix}-cluster-sg"
  description = "Allow Neptune (TCP 8182) from the example subnet only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Neptune traffic from the example subnet only"
    from_port   = 8182
    to_port     = 8182
    protocol    = "tcp"
    cidr_blocks = [aws_subnet.example.cidr_block]
  }

  egress {
    description = "Responses restricted to the example subnet"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_subnet.example.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-cluster-sg"
  })
}

# ------------------------------------------------------------------------------
# Neptune subnet group
# ------------------------------------------------------------------------------

resource "aws_neptune_subnet_group" "main" {
  name        = "${var.name_prefix}-subnet-group"
  description = "Subnets the Neptune cluster is deployed into (two AZs)"
  subnet_ids  = [aws_subnet.example.id, aws_subnet.neptune_secondary.id]

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-subnet-group"
  })
}

# ------------------------------------------------------------------------------
# Custom parameter groups (neptune1.3 family)
# ------------------------------------------------------------------------------

resource "aws_neptune_cluster_parameter_group" "main" {
  family      = "neptune1.3"
  name        = "${var.name_prefix}-cluster-param-group"
  description = "Custom cluster level parameters"

  parameter {
    name  = "neptune_enable_audit_log"
    value = "1"
  }

  parameter {
    name  = "neptune_enforce_ssl"
    value = "1"
  }

  tags = local.common_tags
}

resource "aws_neptune_parameter_group" "main" {
  family      = "neptune1.3"
  name        = "${var.name_prefix}-instance-param-group"
  description = "Custom instance level parameters"

  parameter {
    name  = "neptune_query_timeout"
    value = "25000"
  }

  tags = local.common_tags
}

# ------------------------------------------------------------------------------
# IAM - least privilege support for IAM database authentication
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "neptune_assume_role" {
  statement {
    sid     = "AllowAssumeByExplicitlyTrustedPrincipals"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }
}

data "aws_iam_policy_document" "neptune_db_connect" {
  statement {
    sid       = "AllowNeptuneDbConnect"
    effect    = "Allow"
    actions   = ["neptune-db:connect"]
    resources = [aws_neptune_cluster.main.arn]
  }
}

resource "aws_iam_role" "neptune_db_auth" {
  name               = "${var.name_prefix}-db-auth-role"
  description        = "Assumable only by explicitly trusted principals for Neptune IAM database authentication"
  assume_role_policy = data.aws_iam_policy_document.neptune_assume_role.json

  tags = local.common_tags
}

resource "aws_iam_policy" "neptune_db_connect" {
  name        = "${var.name_prefix}-db-connect-policy"
  description = "Allow neptune-db:connect against the Neptune cluster only"
  policy      = data.aws_iam_policy_document.neptune_db_connect.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "neptune_db_connect" {
  role       = aws_iam_role.neptune_db_auth.name
  policy_arn = aws_iam_policy.neptune_db_connect.arn
}

# ------------------------------------------------------------------------------
# Neptune cluster
# ------------------------------------------------------------------------------

# Neptune identifiers only accept letters, digits and hyphens (they build the
# cluster DNS name), so a lowercase hyphenated identifier is used.
resource "aws_neptune_cluster" "main" {
  cluster_identifier                   = "${var.name_prefix}-cluster"
  engine                               = "neptune"
  port                                 = 8182
  neptune_cluster_parameter_group_name = aws_neptune_cluster_parameter_group.main.name
  neptune_subnet_group_name            = aws_neptune_subnet_group.main.name
  vpc_security_group_ids               = [aws_security_group.neptune.id]

  storage_encrypted                   = true
  iam_database_authentication_enabled = true
  deletion_protection                 = true

  backup_retention_period   = var.backup_retention_period
  preferred_backup_window   = "07:00-09:00"
  skip_final_snapshot       = false
  final_snapshot_identifier = "${var.name_prefix}-cluster-final-snapshot"

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-cluster"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_neptune_cluster_instance" "main" {
  identifier                   = "${var.name_prefix}-instance-1"
  cluster_identifier           = aws_neptune_cluster.main.id
  instance_class               = var.neptune_instance_class
  neptune_parameter_group_name = aws_neptune_parameter_group.main.name

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-instance-1"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "neptune_cluster_endpoint" {
  description = "Writer endpoint of the Neptune cluster."
  value       = aws_neptune_cluster.main.endpoint
}

output "neptune_cluster_reader_endpoint" {
  description = "Reader endpoint of the Neptune cluster."
  value       = aws_neptune_cluster.main.reader_endpoint
}

output "neptune_security_group_id" {
  description = "Security group attached to the Neptune cluster, for consumers inside the example subnet."
  value       = aws_security_group.neptune.id
}

terraform {
  required_version = "~> 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_chime_voice_connector" "primary" {
  name               = "primary_voice_connector"
  aws_region         = "us-east-1"
  require_encryption = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_chime_voice_connector" "secondary" {
  name               = "secondary_voice_connector"
  aws_region         = "us-east-1"
  require_encryption = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_chime_voice_connector_group" "main" {
  name = "main_voice_connector_group"

  connector {
    voice_connector_id = aws_chime_voice_connector.primary.id
    priority           = 1
  }

  connector {
    voice_connector_id = aws_chime_voice_connector.secondary.id
    priority           = 2
  }
}

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  voice_connector_name = "encrypted-voice-connector"
  sns_topic_name       = "chime-voice-connector-streaming-notifications"
}

resource "aws_chime_voice_connector" "main" {
  name               = local.voice_connector_name
  require_encryption = true

  tags = {
    Name        = local.voice_connector_name
    Environment = "production"
  }
}

resource "aws_sns_topic" "notifications" {
  name = local.sns_topic_name

  tags = {
    Name        = local.sns_topic_name
    Environment = "production"
  }
}

resource "aws_chime_voice_connector_streaming" "streaming" {
  voice_connector_id = aws_chime_voice_connector.main.id
  data_retention     = 5
  disabled           = true

  streaming_notification_targets = ["SNS"]

  depends_on = [aws_sns_topic.notifications]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = local.common_tags
  }
}

variable "project_name" {
  description = "Project name used for resource naming and tagging."
  type        = string
  default     = "analytics-platform"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9-]*$", var.project_name))
    error_message = "project_name must start with a lowercase letter or digit and contain only lowercase letters, digits, and hyphens."
  }
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9-]*$", var.environment))
    error_message = "environment must start with a lowercase letter or digit and contain only lowercase letters, digits, and hyphens."
  }
}

variable "alert_email" {
  description = "Email endpoint subscribed to the Redshift event notification topic."
  type        = string
  default     = "ops-team@example.com"

  validation {
    condition     = can(regex("@", var.alert_email))
    error_message = "alert_email must be a valid email address."
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  name_prefix     = "${var.project_name}-${var.environment}"
  master_username = "redshiftadmin"
  database_name   = "analytics_db"

  common_tags = {
    Project     = var.project_name
    Environment = var.environment
  }
}

# ------------------------------------------------------------------
# Network foundation
# ------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-a" })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-b" })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-route-table" })
}

resource "aws_main_route_table_association" "main" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_b" {
  subnet_id      = aws_subnet.private_b.id
  route_table_id = aws_route_table.private.id
}

# ------------------------------------------------------------------
# Cluster security group
# ------------------------------------------------------------------

resource "aws_security_group" "redshift" {
  name        = "${local.name_prefix}-redshift-sg"
  description = "Redshift cluster access restricted to the VPC on port 5439"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redshift engine port from the VPC CIDR only"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-redshift-sg" })
}

# ------------------------------------------------------------------
# KMS encryption
# ------------------------------------------------------------------

data "aws_iam_policy_document" "redshift_kms_key" {
  statement {
    sid    = "KeyAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions = [
      "kms:Create*",
      "kms:Describe*",
      "kms:Enable*",
      "kms:List*",
      "kms:Put*",
      "kms:Update*",
      "kms:Revoke*",
      "kms:Disable*",
      "kms:Get*",
      "kms:Delete*",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:ScheduleKeyDeletion",
      "kms:CancelKeyDeletion",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "KeyUsageByAccount"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:DescribeKey",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "KeyUsageByRedshiftService"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["redshift.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:DescribeKey",
      "kms:CreateGrant",
      "kms:RetireGrant",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values = [
        "redshift.${data.aws_region.current.name}.amazonaws.com",
        "sns.${data.aws_region.current.name}.amazonaws.com",
      ]
    }
  }

  statement {
    sid    = "KeyUsageBySnsService"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:DescribeKey",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["sns.${data.aws_region.current.name}.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "redshift" {
  description             = "Encrypts the Redshift cluster, its snapshots, and the event notification SNS topic"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.redshift_kms_key.json

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-redshift-key" })
}

resource "aws_kms_alias" "redshift" {
  name          = "alias/${local.name_prefix}-redshift"
  target_key_id = aws_kms_key.redshift.key_id
}

# ------------------------------------------------------------------
# Master credentials
# ------------------------------------------------------------------

resource "random_password" "redshift_master" {
  length           = 20
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
}

resource "aws_secretsmanager_secret" "redshift" {
  name        = "${local.name_prefix}/redshift/master-credentials"
  description = "Master credentials for the ${local.name_prefix} Redshift cluster"
  kms_key_id  = aws_kms_key.redshift.arn

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-redshift-credentials" })
}

resource "aws_secretsmanager_secret_version" "redshift" {
  secret_id = aws_secretsmanager_secret.redshift.id
  secret_string = jsonencode({
    username = local.master_username
    password = random_password.redshift_master.result
    engine   = "redshift"
    db_name  = local.database_name
  })
}

# ------------------------------------------------------------------
# Redshift cluster
# ------------------------------------------------------------------

resource "aws_redshift_subnet_group" "main" {
  name        = "${local.name_prefix}-redshift-subnet-group"
  description = "Private subnets hosting the Redshift cluster"
  subnet_ids  = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-redshift-subnet-group" })
}

resource "aws_redshift_parameter_group" "main" {
  name   = "${local.name_prefix}-redshift-parameter-group"
  family = "redshift-1.0"

  parameter {
    name  = "require_ssl"
    value = "true"
  }

  parameter {
    name  = "enable_user_activity_logging"
    value = "true"
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-redshift-parameter-group" })
}

resource "aws_redshift_cluster" "main" {
  cluster_identifier  = "${local.name_prefix}-redshift-cluster"
  database_name       = local.database_name
  master_username     = local.master_username
  master_password     = jsondecode(aws_secretsmanager_secret_version.redshift.secret_string)["password"]
  node_type           = "ra3.xlplus"
  cluster_type        = "single-node"
  number_of_nodes     = 1

  cluster_subnet_group_name    = aws_redshift_subnet_group.main.name
  vpc_security_group_ids       = [aws_security_group.redshift.id]
  cluster_parameter_group_name = aws_redshift_parameter_group.main.name

  encrypted           = true
  kms_key_id          = aws_kms_key.redshift.arn
  publicly_accessible = false

  automated_snapshot_retention_period = 7

  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-redshift-cluster-final"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-redshift-cluster" })

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------
# Event notifications
# ------------------------------------------------------------------

resource "aws_sns_topic" "redshift_events" {
  name              = "${local.name_prefix}-redshift-events"
  kms_master_key_id = aws_kms_key.redshift.arn

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-redshift-events" })
}

data "aws_iam_policy_document" "redshift_events_topic" {
  statement {
    sid       = "AllowRedshiftServicePublish"
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.redshift_events.arn]

    principals {
      type        = "Service"
      identifiers = ["redshift.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_sns_topic_policy" "redshift_events" {
  arn    = aws_sns_topic.redshift_events.arn
  policy = data.aws_iam_policy_document.redshift_events_topic.json
}

resource "aws_sns_topic_subscription" "redshift_events_email" {
  topic_arn = aws_sns_topic.redshift_events.arn
  protocol  = "email"
  endpoint  = var.alert_email
}

resource "aws_redshift_event_subscription" "main" {
  name          = "${local.name_prefix}-redshift-event-subscription"
  sns_topic_arn = aws_sns_topic.redshift_events.arn
  source_type   = "cluster"
  source_ids    = [aws_redshift_cluster.main.cluster_identifier]
  severity      = "INFO"

  event_categories = [
    "configuration",
    "management",
    "monitoring",
    "security",
  ]

  depends_on = [aws_sns_topic_policy.redshift_events]
}

# ------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------

output "redshift_cluster_endpoint" {
  description = "Full connection endpoint of the Redshift cluster in host:port form (includes the port)."
  value       = aws_redshift_cluster.main.endpoint
}

output "redshift_event_topic_arn" {
  description = "ARN of the SNS topic that receives Redshift event notifications."
  value       = aws_sns_topic.redshift_events.arn
}

output "redshift_master_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the Redshift master credentials. The secret value itself is never exposed."
  value       = aws_secretsmanager_secret.redshift.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "iam_group_name" {
  description = "Name of the IAM group that both users will belong to."
  type        = string
  default     = "app-developers"
}

variable "iam_usernames" {
  description = "Exactly two IAM usernames to create."
  type        = set(string)
  default     = ["alice", "bob"]

  validation {
    condition     = length(var.iam_usernames) == 2
    error_message = "Exactly two IAM usernames must be provided."
  }
}

variable "tags" {
  description = "Tags applied to all taggable IAM resources."
  type        = map(string)
  default = {
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

locals {
  s3_readonly_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowS3ReadOnlyListing"
        Effect   = "Allow"
        Action   = ["s3:ListAllMyBuckets", "s3:GetBucketLocation"]
        Resource = "arn:aws:s3:::*"
      }
    ]
  })
}

resource "aws_iam_group" "developers" {
  name = var.iam_group_name
  path = "/"
}

resource "aws_iam_user" "app_users" {
  for_each = var.iam_usernames

  name = each.value
  path = "/"
  tags = var.tags
}

resource "aws_iam_user_group_membership" "app_users_developers" {
  for_each = var.iam_usernames

  user   = aws_iam_user.app_users[each.key].name
  groups = [aws_iam_group.developers.name]
}

resource "aws_iam_policy" "developer_s3_readonly" {
  name        = "${var.iam_group_name}-s3-readonly"
  description = "Least-privilege read-only S3 listing permissions for the ${var.iam_group_name} group."
  path        = "/"
  policy      = local.s3_readonly_policy
  tags        = var.tags
}

resource "aws_iam_group_policy_attachment" "developers_s3_readonly" {
  group      = aws_iam_group.developers.name
  policy_arn = aws_iam_policy.developer_s3_readonly.arn
}

output "iam_group_name" {
  description = "Name of the IAM group that both users belong to."
  value       = aws_iam_group.developers.name
}

output "iam_usernames" {
  description = "Usernames of the two created IAM users."
  value       = [for user in aws_iam_user.app_users : user.name]
}

terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "iam_user_name" {
  description = "Name of the IAM user to create."
  type        = string
  default     = "example-user"

  validation {
    condition     = can(regex("^[A-Za-z0-9+=,.@_-]{1,64}$", var.iam_user_name))
    error_message = "IAM user name must be 1-64 characters consisting of letters, digits, or the symbols plus (+), equal (=), comma (,), period (.), at (@), underscore (_), and hyphen (-)."
  }
}

variable "environment" {
  description = "Value applied to the Environment tag on all resources."
  type        = string
  default     = "dev"
}

locals {
  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }

  policy_name        = "${var.iam_user_name}-s3-read-only"
  secret_name        = "${var.iam_user_name}-access-keys"
  data_bucket_prefix = "${var.iam_user_name}-data"
}

resource "aws_iam_user" "example" {
  name = var.iam_user_name

  tags = merge(
    local.common_tags,
    {
      Name = var.iam_user_name
    },
  )
}

resource "aws_iam_policy" "example" {
  name        = local.policy_name
  description = "Least-privilege read-only access to the ${local.data_bucket_prefix} S3 location."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ListDataBucket"
        Effect   = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation"
        ]
        Resource = "arn:aws:s3:::${local.data_bucket_prefix}"
      },
      {
        Sid    = "ReadDataObjects"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion"
        ]
        Resource = "arn:aws:s3:::${local.data_bucket_prefix}/*"
      }
    ]
  })

  tags = merge(
    local.common_tags,
    {
      Name = local.policy_name
    },
  )
}

resource "aws_iam_user_policy_attachment" "example" {
  user       = aws_iam_user.example.name
  policy_arn = aws_iam_policy.example.arn
}

resource "aws_iam_access_key" "example" {
  user = aws_iam_user.example.name
}

resource "aws_secretsmanager_secret" "example" {
  name        = local.secret_name
  description = "Programmatic access credentials for the ${var.iam_user_name} IAM user."

  tags = merge(
    local.common_tags,
    {
      Name = local.secret_name
    },
  )
}

resource "aws_secretsmanager_secret_version" "example" {
  secret_id = aws_secretsmanager_secret.example.arn

  secret_string = jsonencode({
    username          = aws_iam_user.example.name
    access_key_id     = aws_iam_access_key.example.id
    secret_access_key = aws_iam_access_key.example.secret
  })
}

output "iam_user_name" {
  description = "Name of the IAM user."
  value       = aws_iam_user.example.name
}

output "iam_user_arn" {
  description = "ARN of the IAM user."
  value       = aws_iam_user.example.arn
}

output "iam_user_unique_id" {
  description = "Unique ID assigned by AWS to the IAM user."
  value       = aws_iam_user.example.unique_id
}

output "iam_access_key_id" {
  description = "Access key ID for the IAM user. The secret access key is stored in AWS Secrets Manager."
  value       = aws_iam_access_key.example.id
}

output "iam_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret containing the IAM user's access credentials."
  value       = aws_secretsmanager_secret.example.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  bucket_name = "mybucket"
}

resource "aws_s3_bucket" "my_bucket" {
  bucket = local.bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_accelerate_configuration" "my_bucket" {
  bucket = aws_s3_bucket.my_bucket.id
  status = "Enabled"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "my_bucket" {
  bucket = aws_s3_bucket.my_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "my_bucket" {
  bucket = aws_s3_bucket.my_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "my_bucket" {
  bucket = aws_s3_bucket.my_bucket.id

  versioning_configuration {
    status = "Enabled"
  }

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

locals {
  inventory_prefix            = "inventory"
  inventory_service_principal = "inventory.s3.amazonaws.com"
}

# Source bucket whose contents are inventoried daily.
resource "aws_s3_bucket" "mybucket" {
  bucket = "mybucket"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "mybucket" {
  bucket = aws_s3_bucket.mybucket.id

  versioning_configuration {
    status = "Enabled"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "mybucket" {
  bucket = aws_s3_bucket.mybucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "mybucket" {
  bucket = aws_s3_bucket.mybucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Dedicated destination bucket for inventory report delivery.
resource "aws_s3_bucket" "mybucket_inventory" {
  bucket = "mybucket-inventory-${data.aws_caller_identity.current.account_id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "mybucket_inventory" {
  bucket = aws_s3_bucket.mybucket_inventory.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "mybucket_inventory" {
  bucket = aws_s3_bucket.mybucket_inventory.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Least-privilege delivery policy for the S3 inventory service principal,
# scoped to the destination prefix and to the source bucket via aws:SourceArn.
resource "aws_s3_bucket_policy" "mybucket_inventory" {
  bucket = aws_s3_bucket.mybucket_inventory.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowInventoryPutObjectFromSourceBucket"
        Effect = "Allow"
        Principal = {
          Service = local.inventory_service_principal
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.mybucket_inventory.arn}/${local.inventory_prefix}/*"
        Condition = {
          ArnLike = {
            "aws:SourceArn" = aws_s3_bucket.mybucket.arn
          }
        }
      },
      {
        Sid    = "RequireBucketOwnerFullControlOnInventoryDelivery"
        Effect = "Allow"
        Principal = {
          Service = local.inventory_service_principal
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.mybucket_inventory.arn}/${local.inventory_prefix}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      }
    ]
  })
}

# Daily inventory configuration for the source bucket.
# Destination hierarchy per provider schema: destination -> bucket -> arguments.
resource "aws_s3_bucket_inventory" "mybucket_daily" {
  bucket = aws_s3_bucket.mybucket.id
  name   = "mybucket-daily-inventory"

  included_object_versions = "All"

  schedule {
    frequency = "Daily"
  }

  optional_fields = [
    "Size",
    "LastModifiedDate",
    "StorageClass",
    "ETag",
    "IsMultipartUploaded",
    "ReplicationStatus",
  ]

  destination {
    bucket {
      bucket_arn = aws_s3_bucket.mybucket_inventory.arn
      format     = "CSV"
      account_id = data.aws_caller_identity.current.account_id
      prefix     = local.inventory_prefix

      encryption {
        sse_s3 {}
      }
    }
  }

  depends_on = [aws_s3_bucket_policy.mybucket_inventory]
}

