# Server Access Logging for S3
# Source bucket ships access logs to a dedicated, locked-down log bucket.

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "project_name" {
  description = "Project name used to derive globally unique S3 bucket names."
  type        = string
  default     = "terraform-access-logging"

  validation {
    condition = can(regex("^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$", var.project_name)) && length(var.project_name) <= 41
    error_message = "Project name must be lowercase alphanumeric with hyphens (starting/ending alphanumeric) and at most 41 characters so derived bucket names stay within the 63 character limit."
  }
}

variable "tags" {
  description = "Tags applied to all taggable S3 resources for cost tracking and governance."
  type        = map(string)
  default = {
    Environment = "dev"
    ManagedBy   = "terraform"
    Purpose     = "s3-server-access-logging"
  }
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  access_log_prefix = "access-logs/"

  main_bucket_name        = "${var.project_name}-main-${random_id.bucket_suffix.hex}"
  access_logs_bucket_name = "${var.project_name}-access-logs-${random_id.bucket_suffix.hex}"

  common_tags = merge(
    {
      Project = var.project_name
    },
    var.tags
  )
}

# Random suffix guarantees bucket-name global uniqueness for unattended applies.
resource "random_id" "bucket_suffix" {
  byte_length = 4
}

# Current account ID, used to harden the log-delivery bucket policy.
data "aws_caller_identity" "current" {}

# -----------------------------------------------------------------------------
# S3 buckets (stateful data - protected from destruction)
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "main" {
  bucket = local.main_bucket_name
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "access_logs" {
  bucket = local.access_logs_bucket_name
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Ownership controls: ACLs disabled entirely; the log bucket account owns
# every delivered log object.
# -----------------------------------------------------------------------------

resource "aws_s3_bucket_ownership_controls" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_ownership_controls" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

# -----------------------------------------------------------------------------
# Block ALL public access on both buckets
# -----------------------------------------------------------------------------

resource "aws_s3_bucket_public_access_block" "main" {
  bucket = aws_s3_bucket.main.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# -----------------------------------------------------------------------------
# Default encryption (SSE-S3 / AES256) on both buckets
# -----------------------------------------------------------------------------

resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# -----------------------------------------------------------------------------
# Versioning enabled on both buckets (stateful, retained data)
# -----------------------------------------------------------------------------

resource "aws_s3_bucket_versioning" "main" {
  bucket = aws_s3_bucket.main.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

# -----------------------------------------------------------------------------
# Bucket policy: allow the S3 log-delivery service principal to write access
# logs, restricted to objects generated by the source bucket only.
# -----------------------------------------------------------------------------

resource "aws_s3_bucket_policy" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3ServerAccessLogsPolicy"
        Effect = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.access_logs.arn}/${local.access_log_prefix}*"
        Condition = {
          ArnLike = {
            "aws:SourceArn" = aws_s3_bucket.main.arn
          }
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Server access logging: source bucket ships logs to the dedicated log bucket.
# -----------------------------------------------------------------------------

resource "aws_s3_bucket_logging" "main" {
  bucket        = aws_s3_bucket.main.id
  target_bucket = aws_s3_bucket.access_logs.id
  target_prefix = local.access_log_prefix

  depends_on = [
    aws_s3_bucket_policy.access_logs,
    aws_s3_bucket_ownership_controls.access_logs,
  ]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

locals {
  codebuild_project_name   = "students-codebuild-project"
  codebuild_log_group_name = "/aws/codebuild/${local.codebuild_project_name}"
  artifact_bucket_name     = "students-codebuild-artifacts-${data.aws_caller_identity.current.account_id}"
}

# -----------------------------------------------------------------------------
# S3 bucket to store students' CodeBuild output artifacts
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "codebuild_artifacts" {
  bucket = local.artifact_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "codebuild_artifacts" {
  bucket = aws_s3_bucket.codebuild_artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "codebuild_artifacts" {
  bucket = aws_s3_bucket.codebuild_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "codebuild_artifacts" {
  bucket = aws_s3_bucket.codebuild_artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

# -----------------------------------------------------------------------------
# CloudWatch log group for CodeBuild build logs
# -----------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "codebuild" {
  name              = local.codebuild_log_group_name
  retention_in_days = 14
}

# -----------------------------------------------------------------------------
# IAM role assumed by the CodeBuild service
# -----------------------------------------------------------------------------
resource "aws_iam_role" "codebuild" {
  name = "${local.codebuild_project_name}-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "codebuild_artifacts_access" {
  name = "${local.codebuild_project_name}-least-privilege"
  role = aws_iam_role.codebuild.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ReadWriteBuildArtifacts"
        Effect   = "Allow"
        Action   = ["s3:GetObject", "s3:PutObject"]
        Resource = "${aws_s3_bucket.codebuild_artifacts.arn}/*"
      },
      {
        Sid      = "ListBuildArtifactsBucket"
        Effect   = "Allow"
        Action   = "s3:ListBucket"
        Resource = aws_s3_bucket.codebuild_artifacts.arn
      },
      {
        Sid      = "WriteBuildLogs"
        Effect   = "Allow"
        Action   = ["logs:CreateLogStream", "logs:PutLogEvents"]
        Resource = "${aws_cloudwatch_log_group.codebuild.arn}:*"
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# CodeBuild project for students' code
# -----------------------------------------------------------------------------
resource "aws_codebuild_project" "students_codebuild" {
  name         = local.codebuild_project_name
  description  = "Builds student code and stores output artifacts in S3"
  service_role = aws_iam_role.codebuild.arn

  artifacts {
    type      = "S3"
    location  = aws_s3_bucket.codebuild_artifacts.id
    packaging = "ZIP"
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "alpine"
    type         = "LINUX_CONTAINER"
  }

  source {
    type            = "GITHUB"
    location        = "github.com/source-location"
    git_clone_depth = 1
  }

  logs_config {
    cloudwatch_logs {
      group_name = aws_cloudwatch_log_group.codebuild.name
    }
  }

  depends_on = [aws_iam_role_policy.codebuild_artifacts_access]
