}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

locals {
  artifact_bucket_name = "codebuild-artifacts-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"

  codebuild_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ArtifactBucketReadWrite"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Resource = [
          aws_s3_bucket.codebuild_artifacts.arn,
          "${aws_s3_bucket.codebuild_artifacts.arn}/*"
