      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "codebuild-service-role"
  })
}

resource "aws_iam_role_policy" "codebuild_inline_policy" {
  name   = "codebuild-artifacts-and-vpc-access"
  role   = aws_iam_role.codebuild_role.id
  policy = local.codebuild_role_policy
}

resource "aws_iam_policy" "codebuild_policy" {
  name   = "codebuild-artifacts-and-vpc-access"
  policy = local.codebuild_role_policy

  tags = merge(local.common_tags, {
    Name = "codebuild-artifacts-and-vpc-access"
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_policy_attachment" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = aws_iam_policy.codebuild_policy.arn
}

resource "aws_codebuild_project" "students_build" {
  name         = "students-codebuild"
  description  = "CodeBuild project storing student build output in S3"
  service_role = aws_iam_role.codebuild_role.arn

  artifacts {
    type     = "S3"
    location = aws_s3_bucket.codebuild_artifacts.id
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "alpine"
    type         = "LINUX_CONTAINER"
  }

  source {
    type            = "GITHUB"
    location        = "github.com/source-location"
    git_clone_depth = 1
    buildspec       = <<-EOT
      version: 0.2
      phases:
        build:
          commands:
            - echo "Building student project"
    EOT
  }

  vpc_config {
    vpc_id             = aws_vpc.main.id
    subnets            = [aws_subnet.private.id]
    security_group_ids = [aws_security_group.codebuild.id]
  }

  tags = merge(local.common_tags, {
    Name = "students-codebuild"
  })
