terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  lambda_runtime = "python3.12"
  lambda_handler = "lambda_function.lambda_handler"
  common_tags = {
    Project   = "caas"
    ManagedBy = "terraform"
  }
}

resource "random_id" "cat_pictures_suffix" {
  byte_length = 4
}

# -----------------------------------------------------------------------------
# Lambda deployment packages (built inline, no pre-existing artifacts)
# -----------------------------------------------------------------------------

data "archive_file" "caas_get_zip" {
  type        = "zip"
  output_path = "${path.module}/build/caas_get_lambda.zip"

  source {
    filename = "lambda_function.py"
    content  = <<PYTHON
import base64
import json
import os

import boto3

s3 = boto3.client("s3")
dynamodb = boto3.resource("dynamodb")

bucket_name = os.environ["BUCKET_NAME"]
table_name = os.environ["TABLE_NAME"]


def _response(status_code, payload):
    return {
        "statusCode": status_code,
        "headers": {"Content-Type": "application/json"},
        "body": json.dumps(payload),
    }


def lambda_handler(event, context):
    try:
        params = event.get("queryStringParameters") or {}
        name = params.get("name")
        if not name:
            return _response(400, {"error": "Query parameter 'name' is required."})

        item = dynamodb.Table(table_name).get_item(Key={"name": name}).get("Item")
        if item is None:
            return _response(404, {"error": "Cat '%s' not found." % name})

        image_key = item.get("image_key", "%s.jpg" % name)
        image = s3.get_object(Bucket=bucket_name, Key=image_key)
        image_body = image["Body"].read()

        return {
            "statusCode": 200,
            "headers": {"Content-Type": image.get("ContentType", "application/octet-stream")},
            "isBase64Encoded": True,
            "body": base64.b64encode(image_body).decode("utf-8"),
        }
    except Exception as exc:
        return _response(500, {"error": str(exc)})
PYTHON
  }
}

data "archive_file" "caas_put_zip" {
  type        = "zip"
  output_path = "${path.module}/build/caas_put_lambda.zip"

  source {
    filename = "lambda_function.py"
    content  = <<PYTHON
import base64
import json
import os

import boto3

s3 = boto3.client("s3")
dynamodb = boto3.resource("dynamodb")

bucket_name = os.environ["BUCKET_NAME"]
table_name = os.environ["TABLE_NAME"]


def _response(status_code, payload):
    return {
        "statusCode": status_code,
        "headers": {"Content-Type": "application/json"},
        "body": json.dumps(payload),
    }


def lambda_handler(event, context):
    try:
        raw_body = event.get("body") or "{}"
        if event.get("isBase64Encoded"):
            raw_body = base64.b64decode(raw_body).decode("utf-8")
        payload = json.loads(raw_body)

        name = payload.get("name")
        if not name:
            return _response(400, {"error": "Request body must include a 'name' attribute."})

        image_key = "%s.jpg" % name
        image_base64 = payload.get("image_base64")
        if image_base64:
            s3.put_object(
                Bucket=bucket_name,
                Key=image_key,
                Body=base64.b64decode(image_base64),
                ContentType=payload.get("content_type", "image/jpeg"),
            )

        dynamodb.Table(table_name).put_item(
            Item={
                "name": name,
                "image_key": image_key,
                "description": payload.get("description", ""),
            }
        )

        return _response(
            200,
            {"message": "Cat '%s' stored successfully." % name, "image_key": image_key},
        )
    except Exception as exc:
        return _response(500, {"error": str(exc)})
PYTHON
  }
}

# -----------------------------------------------------------------------------
# IAM (shared Lambda execution role + least-privilege inline policies)
# -----------------------------------------------------------------------------

resource "aws_iam_role" "lambda_execution_role" {
  name = "caas-lambda-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_iam_role_policy" "caas_get_lambda_access" {
  name = "caas-get-lambda-least-privilege"
  role = aws_iam_role.lambda_execution_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ReadCatPictures"
        Effect = "Allow"
        Action = [
          "s3:GetObject"
        ]
        Resource = [
          aws_s3_bucket.cat_pictures.arn,
          "${aws_s3_bucket.cat_pictures.arn}/*"
        ]
      },
      {
        Sid    = "ReadCatRecord"
        Effect = "Allow"
        Action = [
          "dynamodb:GetItem"
        ]
        Resource = aws_dynamodb_table.cats.arn
      }
    ]
  })
}

resource "aws_iam_role_policy" "caas_put_lambda_access" {
  name = "caas-put-lambda-least-privilege"
  role = aws_iam_role.lambda_execution_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "WriteCatPictures"
        Effect = "Allow"
        Action = [
          "s3:PutObject"
        ]
        Resource = [
          aws_s3_bucket.cat_pictures.arn,
          "${aws_s3_bucket.cat_pictures.arn}/*"
        ]
      },
      {
        Sid    = "WriteCatRecord"
        Effect = "Allow"
        Action = [
          "dynamodb:PutItem"
        ]
        Resource = aws_dynamodb_table.cats.arn
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Storage: S3 bucket for cat pictures
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "cat_pictures" {
  bucket = "caas-cat-pictures-${random_id.cat_pictures_suffix.hex}"

  lifecycle {
    prevent_destroy = true
  }

  tags = local.common_tags
}

resource "aws_s3_bucket_versioning" "cat_pictures" {
  bucket = aws_s3_bucket.cat_pictures.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cat_pictures" {
  bucket = aws_s3_bucket.cat_pictures.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "cat_pictures" {
  bucket = aws_s3_bucket.cat_pictures.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# -----------------------------------------------------------------------------
# Storage: DynamoDB table for cat records
# -----------------------------------------------------------------------------

resource "aws_dynamodb_table" "cats" {
  name         = "caas_cats"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "name"

  attribute {
    name = "name"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# Lambda functions
# -----------------------------------------------------------------------------

resource "aws_lambda_function" "caas_get_lambda" {
  function_name = "caas-get-cat"
  description   = "Returns a cat picture and its record from S3 and DynamoDB."
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = local.lambda_handler
  runtime       = local.lambda_runtime
  timeout       = 10

  filename         = data.archive_file.caas_get_zip.output_path
  source_code_hash = data.archive_file.caas_get_zip.output_base64sha256

  environment {
    variables = {
      BUCKET_NAME = aws_s3_bucket.cat_pictures.id
      TABLE_NAME  = aws_dynamodb_table.cats.name
    }
  }

  depends_on = [
    aws_iam_role_policy_attachment.lambda_basic_execution,
    aws_iam_role_policy.caas_get_lambda_access
  ]

  tags = local.common_tags
}

resource "aws_lambda_function" "caas_put_lambda" {
  function_name = "caas-put-cat"
  description   = "Stores a cat picture in S3 and its record in DynamoDB."
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = local.lambda_handler
  runtime       = local.lambda_runtime
  timeout       = 10

  filename         = data.archive_file.caas_put_zip.output_path
  source_code_hash = data.archive_file.caas_put_zip.output_base64sha256

  environment {
    variables = {
      BUCKET_NAME = aws_s3_bucket.cat_pictures.id
      TABLE_NAME  = aws_dynamodb_table.cats.name
    }
  }

  depends_on = [
    aws_iam_role_policy_attachment.lambda_basic_execution,
    aws_iam_role_policy.caas_put_lambda_access
  ]

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# API Gateway REST API
# -----------------------------------------------------------------------------

resource "aws_api_gateway_rest_api" "caas" {
  name = "caas"

  binary_media_types = ["image/jpeg"]

  tags = local.common_tags
}

resource "aws_api_gateway_resource" "caas_cat" {
  rest_api_id = aws_api_gateway_rest_api.caas.id
  parent_id   = aws_api_gateway_rest_api.caas.root_resource_id
  path_part   = "cat"
}

resource "aws_api_gateway_method" "caas_get" {
  rest_api_id   = aws_api_gateway_rest_api.caas.id
  resource_id   = aws_api_gateway_resource.caas_cat.id
  http_method   = "GET"
  authorization = "NONE"
}

resource "aws_api_gateway_method" "caas_put" {
  rest_api_id   = aws_api_gateway_rest_api.caas.id
  resource_id   = aws_api_gateway_resource.caas_cat.id
  http_method   = "PUT"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "caas_get_integration" {
  rest_api_id             = aws_api_gateway_rest_api.caas.id
  resource_id             = aws_api_gateway_resource.caas_cat.id
  http_method             = aws_api_gateway_method.caas_get.http_method
  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = aws_lambda_function.caas_get_lambda.invoke_arn
}

resource "aws_api_gateway_integration" "caas_put_integration" {
  rest_api_id             = aws_api_gateway_rest_api.caas.id
  resource_id             = aws_api_gateway_resource.caas_cat.id
  http_method             = aws_api_gateway_method.caas_put.http_method
  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = aws_lambda_function.caas_put_lambda.invoke_arn
}

resource "aws_lambda_permission" "caas_get_lambda_permission" {
  statement_id  = "AllowAPIGatewayInvokeGetCat"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.caas_get_lambda.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_api_gateway_rest_api.caas.execution_arn}/*/GET/cat"
}

resource "aws_lambda_permission" "caas_put_lambda_permission" {
  statement_id  = "AllowAPIGatewayInvokePutCat"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.caas_put_lambda.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_api_gateway_rest_api.caas.execution_arn}/*/PUT/cat"
}

resource "aws_api_gateway_deployment" "caas_deployment" {
  rest_api_id = aws_api_gateway_rest_api.caas.id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_resource.caas_cat.id,
      aws_api_gateway_method.caas_get.id,
      aws_api_gateway_method.caas_put.id,
      aws_api_gateway_integration.caas_get_integration.id,
      aws_api_gateway_integration.caas_put_integration.id
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    aws_api_gateway_integration.caas_get_integration,
    aws_api_gateway_integration.caas_put_integration
  ]
}

resource "aws_api_gateway_stage" "caas_stage" {
  rest_api_id   = aws_api_gateway_rest_api.caas.id
  deployment_id = aws_api_gateway_deployment.caas_deployment.id
  stage_name    = "prod"

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

data "aws_region" "current" {}

output "caas_invoke_url" {
  description = "Invoke URL for the /cat resource on the deployed prod stage."
  value       = "https://${aws_api_gateway_rest_api.caas.id}.execute-api.${data.aws_region.current.name}.amazonaws.com/${aws_api_gateway_stage.caas_stage.stage_name}/cat"
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "trusted_ssh_cidr" {
  description = "CIDR block permitted to reach TCP/22 (SSH) on the EC2 instance. Must be a restricted, trusted range."
  type        = string
  default     = "10.0.0.0/8"

  validation {
    condition     = var.trusted_ssh_cidr != "0.0.0.0/0"
    error_message = "SSH ingress must be restricted to a trusted CIDR; 0.0.0.0/0 is not allowed."
  }
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  common_tags = {
    Project     = "ec2-backup"
    Environment = "sandbox"
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Data sources (pure static / well-known lookups only)
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "al2023_x86_64" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023.*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

# -----------------------------------------------------------------------------
# Networking (greenfield: all prerequisites created here)
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "main-vpc"
  })
}

resource "aws_subnet" "main" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "main-public-subnet"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "main-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "main-public-route-table"
  })
}

resource "aws_route_table_association" "main" {
  subnet_id      = aws_subnet.main.id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# SSH key pair: apply-time generation (no file dependency)
# -----------------------------------------------------------------------------

resource "tls_private_key" "main" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_key_pair" "main" {
  key_name   = "main_ec2_key"
  public_key = tls_private_key.main.public_key_openssh

  tags = merge(local.common_tags, {
    Name = "main-ec2-key-pair"
  })
}

# -----------------------------------------------------------------------------
# EC2 instance and security group
# -----------------------------------------------------------------------------

resource "aws_security_group" "main" {
  name        = "main-ec2-ssh-sg"
  description = "Restrict ingress to SSH from a trusted CIDR; allow all egress"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from trusted CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.trusted_ssh_cidr]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "main-ec2-ssh-sg"
  })
}

resource "aws_instance" "main" {
  ami                    = data.aws_ami.al2023_x86_64.id
  instance_type          = "t2.micro"
  key_name               = aws_key_pair.main.key_name
  subnet_id              = aws_subnet.main.id
  vpc_security_group_ids = [aws_security_group.main.id]

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    encrypted   = true
    volume_size = 8
    volume_type = "gp3"
  }

  tags = merge(local.common_tags, {
    Name = "backup-ec2-instance"
  })
}

# -----------------------------------------------------------------------------
# AWS Backup: KMS key, vault, plan, selection IAM role
# -----------------------------------------------------------------------------

resource "aws_kms_key" "backup" {
  description             = "KMS key used to encrypt the AWS Backup vault and SSH key secret"
  deletion_window_in_days = 7
  is_enabled              = true
  enable_key_rotation     = true

  tags = local.common_tags
}

resource "aws_backup_vault" "main" {
  name        = "main_backup_vault"
  kms_key_arn = aws_kms_key.backup.arn

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_plan" "daily" {
  name = "daily_midnight_backup_plan"

  rule {
    rule_name         = "daily_midnight"
    target_vault_name = aws_backup_vault.main.name
    schedule          = "cron(0 0 * * ? *)"

    lifecycle {
      delete_after = 7
    }
  }

  advanced_backup_setting {
    backup_options = {
      resource_type = "EC2"
    }
    resource_type = "EC2"
  }

  tags = local.common_tags
}

resource "aws_iam_role" "backup_selection" {
  name = "backup_selection_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowBackupServiceAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "backup_kms_access" {
  name = "backup-kms-access"
  role = aws_iam_role.backup_selection.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowBackupVaultKmsUsage"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:DescribeKey"
        ]
        Resource = aws_kms_key.backup.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "backup_selection" {
  role       = aws_iam_role.backup_selection.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

# NOTE: aws_backup_selection does not support tagging at the provider/API level,
# so no tags argument is applied to this resource.

resource "aws_backup_selection" "ec2" {
  name         = "ec2_backup_selection"
  plan_id      = aws_backup_plan.daily.id
  iam_role_arn = aws_iam_role.backup_selection.arn
  resources    = [aws_instance.main.arn]
}

# -----------------------------------------------------------------------------
# SSH private key persistence (Secrets Manager, encrypted with the CMK)
# -----------------------------------------------------------------------------

resource "aws_secretsmanager_secret" "ssh_private_key" {
  name                    = "ec2/main-ssh-private-key"
  description             = "Private key for the main EC2 key pair (apply-time generated)"
  kms_key_id              = aws_kms_key.backup.arn
  recovery_window_in_days = 7

  tags = local.common_tags
}

resource "aws_secretsmanager_secret_version" "ssh_private_key" {
  secret_id     = aws_secretsmanager_secret.ssh_private_key.id
  secret_string = tls_private_key.main.private_key_pem
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  lambda_zip_path = "./supplement/lambda_func.zip"
}

resource "aws_iam_role" "lambda_exec" {
  name = "cron-lambda-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_lambda_function" "cron_target" {
  function_name    = "cron-target"
  role             = aws_iam_role.lambda_exec.arn
  handler          = "lambda_function.lambda_handler"
  runtime          = "python3.12"
  filename         = local.lambda_zip_path
  source_code_hash = fileexists(local.lambda_zip_path) ? filebase64sha256(local.lambda_zip_path) : null
  timeout          = 10
  memory_size      = 128

  depends_on = [aws_iam_role_policy_attachment.lambda_basic_execution]
}

resource "aws_cloudwatch_event_rule" "cron" {
  name                = "cron"
  description         = "Triggers the cron target Lambda every day at 07:00 UTC"
  schedule_expression = "cron(0 7 * * ? *)"
}

resource "aws_cloudwatch_event_target" "cron_lambda" {
  rule      = aws_cloudwatch_event_rule.cron.arn
  target_id = "cron-lambda-target"
  arn       = aws_lambda_function.cron_target.arn
}

resource "aws_lambda_permission" "allow_eventbridge_cron" {
  statement_id  = "AllowExecutionFromEventBridgeCronRule"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.cron_target.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.cron.arn
}

###############################################################################
# Video streaming platform
# Global video delivery: CloudFront (CDN) -> S3 (SSE-KMS origin, OAC) with
# Route 53 (DNS + ACM DNS validation) and KMS (media encryption).
###############################################################################

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# us-east-1 is the only region from which an ACM certificate can be attached
# to CloudFront, so the whole stack is deployed there.
provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      Project     = "video-streaming"
      Environment = var.environment
    }
  }
}

###############################################################################
# Variables (user-controlled, all with defaults for unattended apply)
###############################################################################

variable "domain_name" {
  description = "Public domain name for the video streaming site (e.g. stream.example.com). The domain itself is assumed to be registered outside of Terraform."
  type        = string
  default     = "stream.example.com"
}

variable "environment" {
  description = "Deployment environment name applied via provider default_tags."
  type        = string
  default     = "production"
}

###############################################################################
# Data sources (pure static lookups only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  sanitized_domain  = replace(lower(var.domain_name), ".", "-")
  video_bucket_name = "video-content-${local.sanitized_domain}"
  logs_bucket_name  = "video-content-logs-${local.sanitized_domain}"
  log_prefix        = "cloudfront-logs/${var.domain_name}"
  s3_origin_id      = "s3-video-content-origin"
}

###############################################################################
# Route 53 public hosted zone (domain registered outside Terraform)
###############################################################################

resource "aws_route53_zone" "main" {
  name    = var.domain_name
  comment = "Public hosted zone for the video streaming site"

  tags = {
    Name = "${var.domain_name}-zone"
  }
}

###############################################################################
# ACM certificate (must live in us-east-1 for CloudFront) + DNS validation
###############################################################################

resource "aws_acm_certificate" "streaming" {
  domain_name       = var.domain_name
  validation_method = "DNS"

  tags = {
    Name = "${var.domain_name}-certificate"
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_route53_record" "cert_validation" {
  for_each = {
    for dvo in aws_acm_certificate.streaming.domain_validation_options : dvo.domain_name => {
      name   = dvo.resource_record_name
      type   = dvo.resource_record_type
      record = dvo.resource_record_value
    }
  }

  allow_overwrite = true
  name            = each.value.name
  records         = [each.value.record]
  ttl             = 300
  type            = each.value.type
  zone_id         = aws_route53_zone.main.zone_id
}

resource "aws_acm_certificate_validation" "streaming" {
  certificate_arn         = aws_acm_certificate.streaming.arn
  validation_record_fqdns = [for record in aws_route53_record.cert_validation : record.fqdn]
}

###############################################################################
# KMS key + alias for SSE-KMS encryption of video content
###############################################################################

resource "aws_kms_key" "video_content" {
  description             = "SSE-KMS key for the ${local.video_bucket_name} video content bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.video_content_kms.json

  tags = {
    Name = "video-content-kms-key"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "video_content" {
  name          = "alias/video-content-${local.sanitized_domain}"
  target_key_id = aws_kms_key.video_content.key_id
}

data "aws_iam_policy_document" "video_content_kms" {
  statement {
    sid    = "EnableAccountRootPermissions"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudFrontDecryptForVideoContent"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudfront.amazonaws.com"]
    }

    actions   = ["kms:Decrypt"]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "AWS:SourceArn"
      values   = [aws_cloudfront_distribution.streaming.arn]
    }

    condition {
      test     = "StringLike"
      variable = "kms:EncryptionContext:aws:s3:arn"
      values = [
        aws_s3_bucket.video_content.arn,
        "${aws_s3_bucket.video_content.arn}/*",
      ]
    }
  }
}

###############################################################################
# Video content bucket (CloudFront origin)
###############################################################################

resource "aws_s3_bucket" "video_content" {
  bucket = local.video_bucket_name

  tags = {
    Name = local.video_bucket_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.video_content.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  rule {
    id     = "expire-noncurrent-versions"
    status = "Enabled"

    filter {}

    noncurrent_version_expiration {
      noncurrent_days = 30
    }
  }

  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }

  depends_on = [aws_s3_bucket_versioning.video_content]
}

data "aws_iam_policy_document" "video_content_bucket" {
  statement {
    sid    = "AllowCloudFrontOACGetObject"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudfront.amazonaws.com"]
    }

    actions   = ["s3:GetObject"]
    resources = ["${aws_s3_bucket.video_content.arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "AWS:SourceArn"
      values   = [aws_cloudfront_distribution.streaming.arn]
    }
  }

  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.video_content.arn,
      "${aws_s3_bucket.video_content.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "video_content" {
  bucket = aws_s3_bucket.video_content.id
  policy = data.aws_iam_policy_document.video_content_bucket.json
}

###############################################################################
# CloudFront access log bucket
# Note: CloudFront standard log delivery requires SSE-S3 (not SSE-KMS), so
# this bucket uses AES256, and BucketOwnerPreferred so the log delivery
# PUTs (bucket-owner-full-control) succeed.
###############################################################################

resource "aws_s3_bucket" "cloudfront_logs" {
  bucket = local.logs_bucket_name

  tags = {
    Name = local.logs_bucket_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cloudfront_logs" {
  bucket = aws_s3_bucket.cloudfront_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "cloudfront_logs" {
  bucket = aws_s3_bucket.cloudfront_logs.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudfront_logs" {
  bucket = aws_s3_bucket.cloudfront_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "cloudfront_logs" {
  bucket = aws_s3_bucket.cloudfront_logs.id

  rule {
    id     = "expire-access-logs"
    status = "Enabled"

    filter {}

    expiration {
      days = 365
    }
  }
}

data "aws_iam_policy_document" "cloudfront_logs_bucket" {
  statement {
    sid    = "AllowCloudFrontLogDelivery"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudfront.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.cloudfront_logs.arn}/${local.log_prefix}/*"]

    condition {
      test     = "StringEquals"
      variable = "AWS:SourceArn"
      values   = [aws_cloudfront_distribution.streaming.arn]
    }
  }

  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.cloudfront_logs.arn,
      "${aws_s3_bucket.cloudfront_logs.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "cloudfront_logs" {
  bucket = aws_s3_bucket.cloudfront_logs.id
  policy = data.aws_iam_policy_document.cloudfront_logs_bucket.json
}

###############################################################################
# CloudFront: OAC, custom cache policy, custom security headers policy
###############################################################################

resource "aws_cloudfront_origin_access_control" "video_content" {
  name                              = "video-content-origin-access-control"
  description                       = "SigV4-signed origin access control for the video content S3 origin"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

resource "aws_cloudfront_cache_policy" "video_media" {
  name        = "video-streaming-media-cache-${var.environment}"
  comment     = "GET/HEAD caching for video media with long TTLs and selected query-string keys forwarded"
  default_ttl = 86400
  max_ttl     = 31536000
  min_ttl     = 0

  parameters_in_cache_key_and_forwarded_to_origin {
    cookies_config {
      cookie_behavior = "none"
    }

    headers_config {
      header_behavior = "none"
    }

    query_strings_config {
      query_string_behavior = "whitelist"

      query_strings {
        items = ["v", "version", "quality", "resolution", "bitrate"]
      }
    }

    enable_accept_encoding_gzip   = true
    enable_accept_encoding_brotli = true
  }
}

resource "aws_cloudfront_response_headers_policy" "video_security" {
  name    = "video-streaming-security-headers-${var.environment}"
  comment = "Injects HSTS, nosniff, and a strict referrer policy on all viewer responses"

  security_headers_config {
    strict_transport_security {
      override                   = true
      include_subdomains         = true
      preload                    = true
      access_control_max_age_sec = 63072000
    }

    content_type_options {
      override = true
    }

    referrer_policy {
      override        = true
      referrer_policy = "strict-origin-when-cross-origin"
    }
  }
}

###############################################################################
# CloudFront distribution
###############################################################################

resource "aws_cloudfront_distribution" "streaming" {
  enabled         = true
  is_ipv6_enabled = true
  http_version    = "http2and3"
  comment         = "Global video streaming distribution for ${var.domain_name}"
  price_class     = "PriceClass_All"
  aliases         = [var.domain_name]

  origin {
    domain_name              = aws_s3_bucket.video_content.bucket_regional_domain_name
    origin_id                = local.s3_origin_id
    origin_access_control_id = aws_cloudfront_origin_access_control.video_content.id
  }

  default_cache_behavior {
    target_origin_id           = local.s3_origin_id
    viewer_protocol_policy     = "redirect-to-https"
    allowed_methods            = ["GET", "HEAD"]
    cached_methods             = ["GET", "HEAD"]
    cache_policy_id            = aws_cloudfront_cache_policy.video_media.id
    response_headers_policy_id = aws_cloudfront_response_headers_policy.video_security.id
    compress                   = true
  }

  logging_config {
    bucket          = aws_s3_bucket.cloudfront_logs.bucket_regional_domain_name
    prefix          = "${local.log_prefix}/"
    include_cookies = false
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    acm_certificate_arn      = aws_acm_certificate.streaming.arn
    ssl_support_method       = "sni-only"
    minimum_protocol_version = "TLSv1.2_2021"
  }

  tags = {
    Name = "video-streaming-distribution"
  }

  depends_on = [aws_acm_certificate_validation.streaming]
}

###############################################################################
# Route 53 alias records (A + AAAA) pointing the domain at CloudFront
###############################################################################

resource "aws_route53_record" "streaming_alias_a" {
  zone_id = aws_route53_zone.main.zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_cloudfront_distribution.streaming.domain_name
    zone_id                = aws_cloudfront_distribution.streaming.hosted_zone_id
    evaluate_target_health = false
  }
}

resource "aws_route53_record" "streaming_alias_aaaa" {
  zone_id = aws_route53_zone.main.zone_id
  name    = var.domain_name
  type    = "AAAA"

  alias {
    name                   = aws_cloudfront_distribution.streaming.domain_name
    zone_id                = aws_cloudfront_distribution.streaming.hosted_zone_id
    evaluate_target_health = false
  }
}

###############################################################################
# Outputs
###############################################################################

output "cloudfront_distribution_domain_name" {
  description = "CloudFront distribution domain name serving the video content."
  value       = aws_cloudfront_distribution.streaming.domain_name
}

output "content_bucket_name" {
  description = "Name of the S3 bucket holding the video content (CloudFront origin)."
  value       = aws_s3_bucket.video_content.id
}

output "hosted_zone_name_servers" {
  description = "Name servers to configure at the domain registrar to delegate DNS for the streaming domain."
  value       = aws_route53_zone.main.name_servers
}

###############################################################################
# Video Streaming Platform
# VPC (multi-AZ) + ALB + EC2 Auto Scaling + Route 53 + ACM + S3 + IAM + CloudWatch
###############################################################################

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

#------------------------------------------------------------------------------
# Variables
#------------------------------------------------------------------------------

variable "domain_name" {
  description = "Public domain name for the streaming site."
  type        = string
  default     = "example-streaming.com"
}

variable "vpc_cidr" {
  description = "CIDR block for the streaming VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "app_port" {
  description = "Port the streaming application listens on behind the ALB."
  type        = number
  default     = 8080
}

variable "instance_type" {
  description = "EC2 instance type for the streaming servers."
  type        = string
  default     = "t3.medium"
}

variable "environment" {
  description = "Environment tag value applied to all resources."
  type        = string
  default     = "production"
}

variable "project" {
  description = "Project tag value applied to all resources."
  type        = string
  default     = "video-streaming"
}

variable "alarm_email" {
  description = "Email endpoint for CloudWatch alarm notifications."
  type        = string
  default     = "ops@example-streaming.com"
}

#------------------------------------------------------------------------------
# Data sources (static/well-known lookups only)
#------------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "al2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023.*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

#------------------------------------------------------------------------------
# Locals
#------------------------------------------------------------------------------

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 2)

  common_tags = {
    Environment = var.environment
    Project     = var.project
    ManagedBy   = "terraform"
  }

  video_assets_bucket_name = "${var.project}-video-assets-${data.aws_caller_identity.current.account_id}"
  alb_logs_bucket_name     = "${var.project}-alb-logs-${data.aws_caller_identity.current.account_id}"

  user_data = <<-USER_DATA
    #!/bin/bash
    set -euo pipefail

    dnf install -y nginx aws-cli

    mkdir -p /usr/share/nginx/html/videos
    aws s3 sync "s3://${aws_s3_bucket.video_assets.bucket}/videos/" /usr/share/nginx/html/videos/ || true

    cat >/etc/nginx/conf.d/streaming.conf <<'NGINX_CONF'
    server {
        listen ${var.app_port};
        server_name _;

        location = /health {
            access_log off;
            add_header Content-Type text/plain;
            return 200 "healthy";
        }

        location /videos/ {
            alias /usr/share/nginx/html/videos/;
            autoindex on;
            add_header Accept-Ranges bytes;
            types {
                text/html html;
                video/mp4 mp4;
                video/webm webm;
                video/ogg ogg;
            }
        }
    }
    NGINX_CONF

    systemctl enable nginx
    systemctl restart nginx
  USER_DATA
}

#------------------------------------------------------------------------------
# Networking foundation
#------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "streaming-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "streaming-igw"
  })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "streaming-public-${count.index + 1}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, count.index + 10)
  availability_zone = local.azs[count.index]

  tags = merge(local.common_tags, {
    Name = "streaming-private-${count.index + 1}"
    Tier = "private"
  })
}

resource "aws_eip" "nat" {
  count = 2

  domain     = "vpc"
  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, {
    Name = "streaming-nat-eip-${count.index + 1}"
  })
}

resource "aws_nat_gateway" "main" {
  count = 2

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, {
    Name = "streaming-nat-${count.index + 1}"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "streaming-public-rt"
  })
}

resource "aws_route_table" "private" {
  count = 2

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = merge(local.common_tags, {
    Name = "streaming-private-rt-${count.index + 1}"
  })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [for rt in aws_route_table.private : rt.id]

  tags = merge(local.common_tags, {
    Name = "streaming-s3-gateway-endpoint"
  })
}

#------------------------------------------------------------------------------
# Security groups
#------------------------------------------------------------------------------

resource "aws_security_group" "alb" {
  name        = "streaming-alb-sg"
  description = "Public entry point for the streaming ALB (HTTP/HTTPS only)."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from the internet"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from the internet"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Forward traffic to the app tier on the streaming app port only"
    from_port   = var.app_port
    to_port     = var.app_port
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "streaming-alb-sg"
  })
}

resource "aws_security_group" "app" {
  name        = "streaming-app-sg"
  description = "Streaming app servers; app port reachable only from the ALB."
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Streaming app port from the ALB only"
    from_port       = var.app_port
    to_port         = var.app_port
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "All outbound (package downloads, S3 via NAT/endpoint)"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "streaming-app-sg"
  })
}

#------------------------------------------------------------------------------
# Content storage (video assets)
#------------------------------------------------------------------------------

resource "aws_s3_bucket" "video_assets" {
  bucket = local.video_assets_bucket_name

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "video-assets"
  })
}

resource "aws_s3_bucket_versioning" "video_assets" {
  bucket = aws_s3_bucket.video_assets.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "video_assets" {
  bucket = aws_s3_bucket.video_assets.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "video_assets" {
  bucket = aws_s3_bucket.video_assets.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "video_assets" {
  bucket = aws_s3_bucket.video_assets.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = {
          AWS = "*"
        }
        Action = "s3:*"
        Resource = [
          aws_s3_bucket.video_assets.arn,
          "${aws_s3_bucket.video_assets.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

#------------------------------------------------------------------------------
# ALB access log storage
#------------------------------------------------------------------------------

resource "aws_s3_bucket" "alb_logs" {
  bucket = local.alb_logs_bucket_name

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "alb-access-logs"
  })
}

resource "aws_s3_bucket_server_side_encryption_configuration" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "ELBLogDeliveryWrite"
        Effect    = "Allow"
        Principal = {
          Service = "logdelivery.elasticloadbalancing.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.alb_logs.arn}/alb-logs/AWSLogs/${data.aws_caller_identity.current.account_id}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      },
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = {
          AWS = "*"
        }
        Action = "s3:*"
        Resource = [
          aws_s3_bucket.alb_logs.arn,
          "${aws_s3_bucket.alb_logs.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_s3_bucket_lifecycle_configuration" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  rule {
    id     = "expire-alb-access-logs"
    status = "Enabled"

    filter {
      prefix = "alb-logs/"
    }

    expiration {
      days = 90
    }
  }
}

#------------------------------------------------------------------------------
# IAM for the EC2 fleet (least privilege)
#------------------------------------------------------------------------------

resource "aws_iam_role" "video_server" {
  name = "streaming-video-server-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy" "video_assets_readonly" {
  name        = "streaming-video-assets-readonly"
  description = "Read-only access to the video assets bucket for the streaming fleet."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ListVideoAssets"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = [aws_s3_bucket.video_assets.arn]
      },
      {
        Sid      = "GetVideoAssets"
        Effect   = "Allow"
        Action   = ["s3:GetObject"]
        Resource = ["${aws_s3_bucket.video_assets.arn}/*"]
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "video_assets_readonly" {
  role       = aws_iam_role.video_server.name
  policy_arn = aws_iam_policy.video_assets_readonly.arn
}

resource "aws_iam_instance_profile" "video_server" {
  name = "streaming-video-server-profile"
  role = aws_iam_role.video_server.name

  tags = local.common_tags
}

#------------------------------------------------------------------------------
# Backend fleet (launch template with IMDSv2 enforced)
#------------------------------------------------------------------------------

resource "aws_launch_template" "video_server" {
  name_prefix            = "streaming-video-server-"
  description            = "Video streaming server fleet template"
  image_id               = data.aws_ami.al2023.id
  instance_type          = var.instance_type
  update_default_version = true

  iam_instance_profile {
    name = aws_iam_instance_profile.video_server.name
  }

  vpc_security_group_ids = [aws_security_group.app.id]

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      volume_size           = 30
      volume_type           = "gp3"
      encrypted             = true
      delete_on_termination = true
    }
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
    instance_metadata_tags      = "disabled"
  }

  user_data = base64encode(local.user_data)

  tag_specifications {
    resource_type = "instance"
    tags = merge(local.common_tags, {
      Name = "streaming-video-server"
    })
  }

  tag_specifications {
    resource_type = "volume"
    tags = merge(local.common_tags, {
      Name = "streaming-video-server"
    })
  }

  tags = local.common_tags
}

#------------------------------------------------------------------------------
# Load balancing
#------------------------------------------------------------------------------

resource "aws_lb_target_group" "video" {
  name                 = "video"
  port                 = var.app_port
  protocol             = "HTTP"
  vpc_id               = aws_vpc.main.id
  target_type          = "instance"
  deregistration_delay = 600

  health_check {
    enabled             = true
    path                = "/health"
    protocol            = "HTTP"
    port                = "traffic-port"
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 3
  }

  tags = merge(local.common_tags, {
    Name = "video-targets"
  })
}

resource "aws_lb" "streaming" {
  name                       = "streaming"
  internal                   = false
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.public[*].id
  drop_invalid_header_fields = true

  access_logs {
    bucket  = aws_s3_bucket.alb_logs.id
    prefix  = "alb-logs"
    enabled = true
  }

  depends_on = [aws_s3_bucket_policy.alb_logs]

  tags = merge(local.common_tags, {
    Name = "streaming-alb"
  })
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.streaming.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.site.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.video.arn
  }

  depends_on = [aws_acm_certificate_validation.site]

  tags = local.common_tags
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.streaming.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }

  tags = local.common_tags
}

#------------------------------------------------------------------------------
# DNS (Route 53) and TLS certificate (ACM)
#------------------------------------------------------------------------------

resource "aws_route53_zone" "streaming" {
  name = var.domain_name

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "streaming-hosted-zone"
  })
}

resource "aws_acm_certificate" "site" {
  domain_name       = var.domain_name
  validation_method = "DNS"

  lifecycle {
    create_before_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "streaming-site-cert"
  })
}

resource "aws_route53_record" "cert_validation" {
  for_each = {
    for dvo in aws_acm_certificate.site.domain_validation_options : dvo.domain_name => {
      name   = dvo.resource_record_name
      record = dvo.resource_record_value
      type   = dvo.resource_record_type
    }
  }

  allow_overwrite = true
  zone_id         = aws_route53_zone.streaming.zone_id
  name            = each.value.name
  type            = each.value.type
  records         = [each.value.record]
  ttl             = 60
}

resource "aws_acm_certificate_validation" "site" {
  certificate_arn         = aws_acm_certificate.site.arn
  validation_record_fqdns = [for record in aws_route53_record.cert_validation : record.fqdn]
}

resource "aws_route53_record" "site_a" {
  zone_id = aws_route53_zone.streaming.zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_lb.streaming.dns_name
    zone_id                = aws_lb.streaming.zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "site_aaaa" {
  zone_id = aws_route53_zone.streaming.zone_id
  name    = var.domain_name
  type    = "AAAA"

  alias {
    name                   = aws_lb.streaming.dns_name
    zone_id                = aws_lb.streaming.zone_id
    evaluate_target_health = true
  }
}

#------------------------------------------------------------------------------
# Auto Scaling
#------------------------------------------------------------------------------

resource "aws_autoscaling_group" "video_fleet" {
  name                      = "streaming-video-fleet"
  vpc_zone_identifier       = aws_subnet.private[*].id
  min_size                  = 2
  max_size                  = 6
  desired_capacity          = 2
  health_check_type         = "ELB"
  health_check_grace_period = 300
  target_group_arns         = [aws_lb_target_group.video.arn]

  launch_template {
    name    = aws_launch_template.video_server.name
    version = "$Latest"
  }

  instance_refresh {
    strategy = "Rolling"

    preferences {
      min_healthy_percentage = 50
    }
  }

  tag {
    key                 = "Environment"
    value               = var.environment
    propagate_at_launch = true
  }

  tag {
    key                 = "Project"
    value               = var.project
    propagate_at_launch = true
  }

  tag {
    key                 = "Name"
    value               = "streaming-video-server"
    propagate_at_launch = true
  }
}

resource "aws_autoscaling_policy" "video_fleet_cpu" {
  name                   = "streaming-video-fleet-cpu-target-60"
  autoscaling_group_name = aws_autoscaling_group.video_fleet.name
  policy_type            = "TargetTrackingScaling"

  target_tracking_configuration {
    predefined_metric_specification {
      predefined_metric_type = "ASGAverageCPUUtilization"
    }

    target_value = 60
  }
}

#------------------------------------------------------------------------------
# Observability
#------------------------------------------------------------------------------

resource "aws_sns_topic" "alerts" {
  name = "streaming-alarm-alerts"

  tags = merge(local.common_tags, {
    Name = "streaming-alerts"
  })
}

resource "aws_sns_topic_subscription" "alerts_email" {
  topic_arn = aws_sns_topic.alerts.arn
  protocol  = "email"
  endpoint  = var.alarm_email
}

resource "aws_cloudwatch_metric_alarm" "alb_5xx" {
  alarm_name          = "streaming-alb-5xx"
  alarm_description   = "Alerts when the streaming ALB returns elevated 5xx error counts."
  namespace           = "AWS/ApplicationELB"
  metric_name         = "HTTPCode_ELB_5XX_Count"
  comparison_operator = "GreaterThanThreshold"
  statistic           = "Sum"
  threshold           = 10
  period              = 60
  evaluation_periods  = 2
  treat_missing_data  = "notBreaching"

  dimensions = {
    LoadBalancer = aws_lb.streaming.arn_suffix
  }

  alarm_actions = [aws_sns_topic.alerts.arn]

  tags = local.common_tags
}

resource "aws_cloudwatch_metric_alarm" "target_response_time" {
  alarm_name          = "streaming-target-response-time"
  alarm_description   = "Alerts when average target response time for the video target group exceeds 2 seconds."
  namespace           = "AWS/ApplicationELB"
  metric_name         = "TargetResponseTime"
  comparison_operator = "GreaterThanThreshold"
  statistic           = "Average"
  threshold           = 2
  period              = 60
  evaluation_periods  = 3
  treat_missing_data  = "notBreaching"

  dimensions = {
    LoadBalancer = aws_lb.streaming.arn_suffix
    TargetGroup  = aws_lb_target_group.video.arn_suffix
  }

  alarm_actions = [aws_sns_topic.alerts.arn]

  tags = local.common_tags
}

#------------------------------------------------------------------------------
# Outputs
#------------------------------------------------------------------------------

output "streaming_site_url" {
  description = "HTTPS URL of the streaming site."
  value       = "https://${var.domain_name}"
}

output "alb_dns_name" {
  description = "Public DNS name of the streaming ALB."
  value       = aws_lb.streaming.dns_name
}

output "video_assets_bucket_name" {
  description = "Name of the S3 bucket holding video assets."
  value       = aws_s3_bucket.video_assets.bucket
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  db_username = random_string.db_username.result

  common_tags = {
    Project   = "mysql-database"
    ManagedBy = "terraform"
  }
}

# Randomly generated master username: alphanumeric (lowercase letters only),
# guaranteed to start with a letter, and <= 16 characters for MySQL/RDS constraints.
resource "random_string" "db_username" {
  length  = 12
  special = false
  upper   = false
  lower   = true
  numeric = false
}

# Randomly generated master password: length >= 16 with special characters,
# restricted to characters valid for RDS MySQL (excludes /, @, ", and space).
resource "random_password" "db_password" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
  min_upper        = 2
  min_lower        = 2
  min_numeric      = 2
  min_special      = 2
}

# Random suffix for unique naming of globally named resources.
resource "random_id" "db_suffix" {
  byte_length = 4
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "mysql-vpc" })
}

resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, { Name = "mysql-private-a" })
}

resource "aws_subnet" "private_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, { Name = "mysql-private-b" })
}

resource "aws_route_table" "private_a" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "mysql-private-a-rt" })
}

resource "aws_route_table" "private_b" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "mysql-private-b-rt" })
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private_a.id
}

resource "aws_route_table_association" "private_b" {
  subnet_id      = aws_subnet.private_b.id
  route_table_id = aws_route_table.private_b.id
}

resource "aws_db_subnet_group" "main" {
  name       = "mysql-db-subnet-group-${random_id.db_suffix.hex}"
  subnet_ids = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = merge(local.common_tags, { Name = "mysql-db-subnet-group" })
}

resource "aws_security_group" "db" {
  name        = "mysql-db-sg-${random_id.db_suffix.hex}"
  description = "Restrict MySQL access to the VPC CIDR only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from within the VPC"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "mysql-db-sg" })
}

resource "aws_db_parameter_group" "mysql8" {
  name   = "mysql8-params-${random_id.db_suffix.hex}"
  family = "mysql8.0"

  parameter {
    name  = "character_set_server"
    value = "utf8mb4"
  }

  tags = merge(local.common_tags, { Name = "mysql8-parameter-group" })
}

resource "aws_db_instance" "mysql" {
  identifier     = "mysql-db-${random_id.db_suffix.hex}"
  engine         = "mysql"
  engine_version = "8.0"
  instance_class = "db.t3.micro"

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"
  storage_encrypted     = true

  db_name  = "appdb"
  username = local.db_username
  password = random_password.db_password.result

  port                   = 3306
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.db.id]
  parameter_group_name   = aws_db_parameter_group.mysql8.name

  publicly_accessible = false
  multi_az            = false

  backup_retention_period    = 7
  copy_tags_to_snapshot      = true
  deletion_protection        = true
  auto_minor_version_upgrade = true

  skip_final_snapshot       = false
  final_snapshot_identifier = "mysql-db-${random_id.db_suffix.hex}-final"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, { Name = "mysql-db" })
}

resource "aws_secretsmanager_secret" "db_credentials" {
  name        = "mysql/db-credentials-${random_id.db_suffix.hex}"
  description = "Master credentials for the MySQL RDS instance"

  tags = merge(local.common_tags, { Name = "mysql-db-credentials" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "db_credentials" {
  secret_id = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({
    engine   = "mysql"
    host     = aws_db_instance.mysql.address
    port     = aws_db_instance.mysql.port
    dbname   = aws_db_instance.mysql.db_name
    username = local.db_username
    password = random_password.db_password.result
  })
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Project name used for resource naming and tagging."
  type        = string
  default     = "app"
}

variable "environment" {
  description = "Deployment environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Additional tags merged onto every taggable resource."
  type        = map(string)
  default     = {}
}

locals {
  name_prefix = "${var.project_name}-${var.environment}"

  common_tags = merge(
    {
      Project     = var.project_name
      Environment = var.environment
      ManagedBy   = "terraform"
    },
    var.tags,
  )
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 4, 0)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-a"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 4, 1)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-b"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "database" {
  name        = "${local.name_prefix}-database-sg"
  description = "Designated database access security group: permits MySQL (TCP 3306) from the VPC CIDR only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from within the VPC only"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-database-sg"
  })
}

resource "aws_db_subnet_group" "main" {
  name        = "${local.name_prefix}-db-subnet-group"
  description = "RDS subnet group spanning public subnets in two Availability Zones"
  subnet_ids  = [aws_subnet.public_a.id, aws_subnet.public_b.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-subnet-group"
  })
}

resource "aws_db_parameter_group" "mysql" {
  name        = "${local.name_prefix}-mysql-8-4-params"
  family      = "mysql8.4"
  description = "MySQL 8.4 parameter group for ${local.name_prefix}"

  parameter {
    name  = "character_set_server"
    value = "utf8mb4"
  }

  parameter {
    name  = "collation_server"
    value = "utf8mb4_unicode_ci"
  }

  tags = local.common_tags
}

resource "random_password" "db_master" {
  length  = 24
  special = true
  # Excludes "/", "@", double quote, and space, which are not permitted in RDS
  # master passwords and are problematic in connection strings.
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "db" {
  name        = "${local.name_prefix}/rds/mysql/master"
  description = "Master credentials for the ${local.name_prefix} MySQL RDS instance"

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "db" {
  secret_id = aws_secretsmanager_secret.db.id
  secret_string = jsonencode({
    engine   = aws_db_instance.mysql.engine
    host     = aws_db_instance.mysql.address
    port     = aws_db_instance.mysql.port
    dbname   = aws_db_instance.mysql.db_name
    username = aws_db_instance.mysql.username
    password = random_password.db_master.result
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_db_instance" "mysql" {
  identifier     = "${local.name_prefix}-mysql"
  engine         = "mysql"
  engine_version = "8.4.3"
  instance_class = "db.t3.micro"

  # RDS enforces a 20 GiB minimum for MySQL; the requested 5 GB is below the
  # enforced floor, so the compliant minimum of 20 GiB is used.
  allocated_storage = 20
  storage_encrypted = true

  db_name  = "appdb"
  username = "appadmin"
  password = random_password.db_master.result
  port     = 3306

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.database.id]
  parameter_group_name   = aws_db_parameter_group.mysql.name

  publicly_accessible = true
  multi_az            = false

  # Keep the engine pinned to 8.4.3 instead of drifting via minor upgrades.
  auto_minor_version_upgrade = false

  backup_retention_period = 7
  copy_tags_to_snapshot   = true
  deletion_protection     = true

  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-mysql-final-snapshot"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-mysql"
  })

  lifecycle {
    prevent_destroy = true
  }
}

output "db_endpoint_address" {
  description = "Hostname endpoint of the MySQL RDS instance."
  value       = aws_db_instance.mysql.address
  sensitive   = true
}

output "db_endpoint_port" {
  description = "Port on which the MySQL RDS instance listens."
  value       = aws_db_instance.mysql.port
}

output "db_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the MySQL master credentials."
  value       = aws_secretsmanager_secret.db.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Project name used for resource naming and tagging."
  type        = string
  default     = "pg-secure"
}

variable "environment" {
  description = "Environment name applied to resources and tags."
  type        = string
  default     = "production"
}

variable "common_tags" {
  description = "Additional user-defined tags applied to every tagged resource."
  type        = map(string)
  default = {
    ManagedBy = "terraform"
  }
}

locals {
  name_prefix        = lower(replace("${var.project_name}-${var.environment}", "/[^a-zA-Z0-9-]/", "-"))
  db_master_username = "pgadmin"
  db_name            = "appdb"
  tags = merge(
    var.common_tags,
    {
      Project     = var.project_name
      Environment = var.environment
      ManagedBy   = "terraform"
    },
  )
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 11)
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-private-a"
    Tier = "database"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 12)
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-private-b"
    Tier = "database"
  })
}

resource "aws_db_subnet_group" "main" {
  name       = "${local.name_prefix}-db-subnet-group"
  subnet_ids = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = merge(local.tags, { Name = "${local.name_prefix}-db-subnet-group" })
}

resource "aws_kms_key" "rds" {
  description             = "Customer-managed KMS key for RDS PostgreSQL storage encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.tags, { Name = "${local.name_prefix}-rds-key" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "rds_postgres" {
  name          = "alias/rds-postgres"
  target_key_id = aws_kms_key.rds.key_id
}

resource "random_password" "db_master" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "db_master" {
  name                    = "${local.name_prefix}/rds-postgres/master"
  description             = "Master credentials for the ${local.name_prefix} RDS PostgreSQL instance"
  kms_key_id              = aws_kms_key.rds.arn
  recovery_window_in_days = 7

  tags = merge(local.tags, { Name = "${local.name_prefix}-rds-master-secret" })
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    username = local.db_master_username
    password = random_password.db_master.result
    engine   = "postgres"
    host     = aws_db_instance.postgres.address
    port     = aws_db_instance.postgres.port
    dbname   = local.db_name
  })
}

resource "aws_db_parameter_group" "postgres16" {
  name        = "${local.name_prefix}-postgres16-params"
  family      = "postgres16"
  description = "Custom parameters for the PostgreSQL 16 RDS instance"

  parameter {
    name         = "max_connections"
    value        = "200"
    apply_method = "immediate"
  }

  parameter {
    name         = "log_min_duration_statement"
    value        = "5000"
    apply_method = "immediate"
  }

  parameter {
    name         = "log_connections"
    value        = "1"
    apply_method = "immediate"
  }

  parameter {
    name         = "log_disconnections"
    value        = "1"
    apply_method = "immediate"
  }

  parameter {
    name         = "rds.force_ssl"
    value        = "1"
    apply_method = "immediate"
  }

  parameter {
    name         = "shared_preload_libraries"
    value        = "pg_stat_statements"
    apply_method = "pending-reboot"
  }

  tags = local.tags
}

resource "aws_security_group" "postgres" {
  name        = "${local.name_prefix}-postgres-sg"
  description = "Restrict access to the RDS PostgreSQL instance to VPC traffic on port 5432"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from within the VPC"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound TLS"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.tags, { Name = "${local.name_prefix}-postgres-sg" })
}

resource "aws_db_instance" "postgres" {
  identifier     = "${local.name_prefix}-postgres"
  engine         = "postgres"
  engine_version = "16.4"
  instance_class = "db.t3.medium"

  allocated_storage     = 50
  max_allocated_storage = 500
  storage_type          = "gp3"
  storage_encrypted     = true
  kms_key_id            = aws_kms_key.rds.arn

  db_name  = local.db_name
  username = local.db_master_username
  password = random_password.db_master.result
  port     = 5432

  db_subnet_group_name   = aws_db_subnet_group.main.name
  parameter_group_name   = aws_db_parameter_group.postgres16.name
  vpc_security_group_ids = [aws_security_group.postgres.id]

  publicly_accessible = false
  multi_az            = true

  backup_retention_period  = 14
  backup_window            = "03:00-04:00"
  maintenance_window       = "sun:05:00-sun:06:00"
  delete_automated_backups = false

  auto_minor_version_upgrade = true
  copy_tags_to_snapshot      = true
  deletion_protection        = true

  performance_insights_enabled          = true
  performance_insights_retention_period = 7
  performance_insights_kms_key_id       = aws_kms_key.rds.arn

  skip_final_snapshot       = false
  final_snapshot_identifier = "pgsnapshot"

  tags = merge(local.tags, { Name = "${local.name_prefix}-postgres" })

  lifecycle {
    prevent_destroy = true
  }
}

output "db_master_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the RDS master credentials."
  value       = aws_secretsmanager_secret.db_master.arn
}

output "db_instance_endpoint" {
  description = "Connection endpoint (host:port) of the RDS PostgreSQL instance."
  value       = aws_db_instance.postgres.endpoint
}

###############################################################################
# Terraform & Provider configuration
###############################################################################

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables
###############################################################################

variable "environment" {
  description = "Environment name applied as a tag to every resource."
  type        = string
  default     = "test"
}

variable "db_instance_class" {
  description = "RDS instance class for the Airbyte connector test PostgreSQL instance."
  type        = string
  default     = "db.t3.medium"
}

variable "db_master_username" {
  description = "Master username for the Airbyte connector test PostgreSQL instance."
  type        = string
  default     = "airbyteadmin"
}

variable "allowed_cidr_blocks" {
  description = "CIDR blocks allowed to reach PostgreSQL on port 5432. Set this to the egress CIDR(s) of the Airbyte connector test harness (e.g., CI runner networks outside AWS). 0.0.0.0/0 is rejected."
  type        = list(string)
  default     = ["203.0.113.0/24"]

  validation {
    condition = (
      length(var.allowed_cidr_blocks) > 0 &&
      !contains(var.allowed_cidr_blocks, "0.0.0.0/0") &&
      alltrue([for cidr in var.allowed_cidr_blocks : can(cidrnetmask(cidr))])
    )
    error_message = "allowed_cidr_blocks must be non-empty, contain valid CIDR blocks, and must not include 0.0.0.0/0."
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  name_prefix = "airbyte-connector-test"

  common_tags = {
    Environment = var.environment
    Purpose     = "airbyte-connector-testing"
  }
}

###############################################################################
# Availability zone lookup (static provider metadata only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Networking: VPC, public subnets, IGW, and routing
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 0)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-a" })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 1)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-b" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-igw" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-rt" })
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# RDS subnet group and security group
###############################################################################

resource "aws_db_subnet_group" "airbyte" {
  name        = "${local.name_prefix}-db-subnet-group"
  description = "Public subnets hosting the Airbyte connector test PostgreSQL instance"
  subnet_ids  = [aws_subnet.public_a.id, aws_subnet.public_b.id]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-db-subnet-group" })
}

resource "aws_security_group" "airbyte_pg" {
  name        = "${local.name_prefix}-pg-sg"
  description = "PostgreSQL access for Airbyte connector testing, restricted to approved harness CIDRs"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from Airbyte connector test harness CIDRs"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = var.allowed_cidr_blocks
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-pg-sg" })
}

###############################################################################
# Encryption: customer-managed KMS key (rotation enabled)
###############################################################################

resource "aws_kms_key" "rds" {
  description             = "KMS key for Airbyte connector test PostgreSQL storage and Secrets Manager encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-kms" })
}

resource "aws_kms_alias" "rds" {
  name          = "alias/${local.name_prefix}-postgres"
  target_key_id = aws_kms_key.rds.key_id
}

###############################################################################
# Master credentials: apply-time generation, stored in Secrets Manager
###############################################################################

resource "random_password" "master_password" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
  min_upper        = 2
  min_lower        = 2
  min_numeric      = 2
  min_special      = 2
}

resource "aws_secretsmanager_secret" "db_master" {
  name                    = "${local.name_prefix}/postgres/master-credentials"
  description             = "Master credentials for the Airbyte connector test PostgreSQL instance"
  kms_key_id              = aws_kms_key.rds.arn
  recovery_window_in_days = 7

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-postgres-master-secret" })
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    username = var.db_master_username
    password = random_password.master_password.result
  })
}

###############################################################################
# Parameter group (postgres15 family)
###############################################################################

resource "aws_db_parameter_group" "airbyte_postgres15" {
  name        = "${local.name_prefix}-postgres15-params"
  family      = "postgres15"
  description = "Parameter tuning for the Airbyte connector test PostgreSQL 15 instance"

  parameter {
    name  = "idle_in_transaction_session_timeout"
    value = "300000"
  }

  parameter {
    name  = "log_min_duration_statement"
    value = "5000"
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-postgres15-params" })
}

###############################################################################
# PostgreSQL 15 instance for Airbyte connector testing
###############################################################################

resource "aws_db_instance" "airbyte_postgres" {
  identifier     = "${local.name_prefix}-postgres"
  engine         = "postgres"
  engine_version = "15"
  instance_class = var.db_instance_class

  allocated_storage     = 500
  max_allocated_storage = 1000
  storage_type          = "gp3"
  storage_encrypted     = true
  kms_key_id            = aws_kms_key.rds.arn

  db_name  = "airbyte"
  username = jsondecode(aws_secretsmanager_secret_version.db_master.secret_string)["username"]
  password = jsondecode(aws_secretsmanager_secret_version.db_master.secret_string)["password"]

  db_subnet_group_name   = aws_db_subnet_group.airbyte.name
  vpc_security_group_ids = [aws_security_group.airbyte_pg.id]
  parameter_group_name   = aws_db_parameter_group.airbyte_postgres15.name

  port                = 5432
  publicly_accessible = true
  multi_az            = false

  backup_retention_period    = 7
  backup_window              = "01:00-03:00"
  maintenance_window         = "sun:04:00-sun:06:00"
  auto_minor_version_upgrade = true

  copy_tags_to_snapshot     = true
  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-postgres-final-snapshot"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-postgres" })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Outputs
###############################################################################

output "db_instance_endpoint" {
  description = "Connection endpoint (host:port) of the Airbyte connector test PostgreSQL instance."
  value       = aws_db_instance.airbyte_postgres.endpoint
}

output "db_master_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the PostgreSQL master credentials."
  value       = aws_secretsmanager_secret.db_master.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  db_username = "dbadmin"
  db_name     = "appdb"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 0)
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-a"
  }
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 1)
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-b"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "public-route-table"
  }
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "rds" {
  name        = "rds-postgres-sg"
  description = "Allow PostgreSQL access on TCP 5432"
  vpc_id      = aws_vpc.main.id

  # Justified exception: the request explicitly mandates a publicly accessible
  # database, so PostgreSQL (TCP 5432) is open to 0.0.0.0/0. All other ingress
  # ports remain closed.
  ingress {
    description = "PostgreSQL from anywhere (required for publicly accessible RDS)"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "rds-postgres-sg"
  }
}

resource "random_password" "db_master" {
  length            = 24
  special           = true
  override_special  = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "db_master" {
  name        = "rds-postgres-master-credentials"
  description = "Master credentials for the publicly accessible RDS PostgreSQL instance"

  tags = {
    Name = "rds-postgres-master-credentials"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    username = local.db_username
    password = random_password.db_master.result
  })
}

resource "aws_db_subnet_group" "postgres" {
  name        = "postgres-db-subnet-group"
  description = "Subnet group for the PostgreSQL RDS instance (subnets in distinct AZs)"
  subnet_ids  = [aws_subnet.public_a.id, aws_subnet.public_b.id]

  tags = {
    Name = "postgres-db-subnet-group"
  }
}

resource "aws_db_instance" "postgres" {
  identifier             = "postgres-db"
  engine                 = "postgres"
  engine_version         = "15.3"
  instance_class         = "db.t3.micro"
  allocated_storage      = 20
  storage_type           = "gp3"
  db_name                = local.db_name
  username               = local.db_username
  password               = random_password.db_master.result
  db_subnet_group_name   = aws_db_subnet_group.postgres.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  publicly_accessible    = true

  storage_encrypted         = true
  deletion_protection       = true
  backup_retention_period   = 7
  skip_final_snapshot       = false
  final_snapshot_identifier = "postgres-db-final-snapshot"
  copy_tags_to_snapshot     = true
  multi_az                  = false

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "postgres-db"
  }
}

output "db_endpoint" {
  description = "Connection endpoint for the PostgreSQL RDS instance"
  value       = aws_db_instance.postgres.endpoint
}

output "db_port" {
  description = "Port the PostgreSQL RDS instance listens on"
  value       = aws_db_instance.postgres.port
}

output "db_master_secret_arn" {
  description = "ARN of the Secrets Manager secret containing the database master credentials"
  value       = aws_secretsmanager_secret.db_master.arn
  sensitive   = true
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied to every resource tag."
  type        = string
  default     = "dev"
}

variable "project_name" {
  description = "Project name used as the resource naming prefix."
  type        = string
  default     = "myapp"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix        = "${var.project_name}-${var.environment}"
  db_master_username = "dbadmin"
  db_name            = "appdb"

  common_tags = {
    Environment = var.environment
    Project     = var.project_name
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-a"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-b"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

resource "random_password" "db_master" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "random_id" "final_snapshot_suffix" {
  byte_length = 4
}

resource "aws_secretsmanager_secret" "db_master" {
  name                    = "${local.name_prefix}-db-master-credentials"
  description             = "Master credentials for the ${local.name_prefix} MySQL RDS instance."
  recovery_window_in_days = 7

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-master-credentials"
  })
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.arn
  secret_string = jsonencode({
    engine   = "mysql"
    host     = aws_db_instance.mysql_db.address
    port     = aws_db_instance.mysql_db.port
    dbname   = local.db_name
    username = local.db_master_username
    password = random_password.db_master.result
  })
}

resource "aws_db_subnet_group" "main" {
  name        = "${local.name_prefix}-db-subnet-group"
  description = "Subnet group for the ${local.name_prefix} MySQL instance."
  subnet_ids  = [aws_subnet.public_a.id, aws_subnet.public_b.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-subnet-group"
  })
}

resource "aws_security_group" "mysql_db" {
  name        = "${local.name_prefix}-mysql-sg"
  description = "Inbound MySQL (3306) access; public access is an explicit requirement of this deployment."
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-mysql-sg"
  })
}

resource "aws_vpc_security_group_ingress_rule" "mysql_3306" {
  security_group_id = aws_security_group.mysql_db.id
  description       = "Allow MySQL from anywhere (public access explicitly required)"
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 3306
  to_port           = 3306
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_egress_rule" "allow_all" {
  security_group_id = aws_security_group.mysql_db.id
  description       = "Allow all outbound traffic"
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "-1"
}

resource "aws_db_instance" "mysql_db" {
  identifier     = "${local.name_prefix}-mysql"
  engine         = "mysql"
  engine_version = "8.0"
  instance_class = "db.t3.micro"

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"
  storage_encrypted     = true

  db_name  = local.db_name
  username = local.db_master_username
  password = random_password.db_master.result
  port     = 3306

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.mysql_db.id]
  publicly_accessible    = true
  multi_az               = false

  backup_retention_period    = 7
  backup_window              = "03:00-04:00"
  maintenance_window         = "sun:04:30-sun:05:30"
  copy_tags_to_snapshot      = true
  auto_minor_version_upgrade = true

  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-mysql-final-${random_id.final_snapshot_suffix.hex}"

  deletion_protection = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-mysql"
  })

  lifecycle {
    prevent_destroy = true
  }
}

output "db_instance_endpoint" {
  description = "Connection endpoint for the MySQL instance."
  value       = aws_db_instance.mysql_db.endpoint
}

output "db_master_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the MySQL master credentials."
  value       = aws_secretsmanager_secret.db_master.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for consistent resource naming and tagging"
  type        = string
  default     = "dev"
}

locals {
  name_prefix = "${var.environment}-postgres"
  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
    Component   = "database"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "db_az1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-az1"
  })
}

resource "aws_subnet" "db_az2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-az2"
  })
}

resource "aws_db_subnet_group" "main" {
  name       = "${local.name_prefix}-db-subnet-group"
  subnet_ids = [aws_subnet.db_az1.id, aws_subnet.db_az2.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-subnet-group"
  })
}

resource "aws_security_group" "db" {
  name        = "${local.name_prefix}-db-sg"
  description = "Restrict PostgreSQL access to traffic originating from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from within the VPC only"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-sg"
  })
}

resource "aws_db_instance" "postgres" {
  identifier     = "${local.name_prefix}-db"
  engine         = "postgresql"
  engine_version = "15.7"
  instance_class = "db.t3.medium"

  allocated_storage = 50
  storage_type      = "gp3"
  storage_encrypted = true

  db_name  = "appdb"
  username = "dbadmin"

  # RDS-managed master password stored in AWS Secrets Manager;
  # no plaintext credentials in configuration.
  manage_master_user_password = true

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.db.id]

  publicly_accessible         = false
  allow_major_version_upgrade = true
  auto_minor_version_upgrade  = true

  backup_retention_period = 7
  deletion_protection     = true

  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-final-snapshot"
  copy_tags_to_snapshot     = true

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db"
  })
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      Project     = var.project
      Environment = var.environment
      ManagedBy   = "terraform"
    }
  }
}

variable "project" {
  description = "Project name applied to all resources through provider default_tags."
  type        = string
  default     = "aurora-mysql-proxy"
}

variable "environment" {
  description = "Environment name applied to all resources through provider default_tags."
  type        = string
  default     = "dev"
}

locals {
  name_prefix        = "aurora-mysql"
  db_master_username = "dbadmin"
  mysql_port         = 3306
}

# Well-known static lookups only: AZ metadata and the current account ID
# (used to scope the service trust policy). No discovery of pre-existing
# infrastructure.

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

# -----------------------------------------------------------------------------
# Network foundation: DNS-enabled VPC (required for RDS Proxy endpoint name
# resolution) with two private subnets across two AZs. No internet gateway,
# no public subnets, no NAT.
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.name_prefix}-vpc"
  }
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.11.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}-private-a"
  }
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.12.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}-private-b"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-private-rt"
  }
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_b" {
  subnet_id      = aws_subnet.private_b.id
  route_table_id = aws_route_table.private.id
}

resource "aws_db_subnet_group" "main" {
  name        = "${local.name_prefix}-subnet-group"
  description = "Private subnets across two AZs for the Aurora MySQL cluster and RDS Proxy"
  subnet_ids  = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = {
    Name = "${local.name_prefix}-subnet-group"
  }
}

# -----------------------------------------------------------------------------
# Dedicated KMS key used for both Aurora storage encryption and Secrets Manager.
# -----------------------------------------------------------------------------

resource "aws_kms_key" "aurora" {
  description             = "Encrypts Aurora MySQL storage and the database credentials secret"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "aurora" {
  name          = "alias/${local.name_prefix}-encryption-key"
  target_key_id = aws_kms_key.aurora.key_id
}

# -----------------------------------------------------------------------------
# Security groups. SG bodies are declared separately from their rules so the
# proxy and cluster groups can reference each other without a dependency cycle.
# -----------------------------------------------------------------------------

resource "aws_security_group" "rds_proxy" {
  name        = "${local.name_prefix}-proxy-sg"
  description = "RDS Proxy: MySQL ingress from the VPC only, egress limited to the Aurora cluster"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-proxy-sg"
  }
}

resource "aws_security_group" "aurora" {
  name        = "${local.name_prefix}-cluster-sg"
  description = "Aurora MySQL: MySQL ingress from the RDS Proxy security group only"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-cluster-sg"
  }
}

resource "aws_vpc_security_group_ingress_rule" "proxy_ingress_from_vpc" {
  security_group_id = aws_security_group.rds_proxy.id
  description       = "MySQL from the VPC CIDR only - never 0.0.0.0/0"
  cidr_ipv4         = aws_vpc.main.cidr_block
  from_port         = local.mysql_port
  ip_protocol       = "tcp"
  to_port           = local.mysql_port
}

resource "aws_vpc_security_group_egress_rule" "proxy_egress_to_aurora" {
  security_group_id            = aws_security_group.rds_proxy.id
  description                  = "MySQL to the Aurora cluster security group only"
  referenced_security_group_id = aws_security_group.aurora.id
  from_port                    = local.mysql_port
  ip_protocol                  = "tcp"
  to_port                      = local.mysql_port
}

resource "aws_vpc_security_group_ingress_rule" "aurora_ingress_from_proxy" {
  security_group_id            = aws_security_group.aurora.id
  description                  = "MySQL from the RDS Proxy security group only"
  referenced_security_group_id = aws_security_group.rds_proxy.id
  from_port                    = local.mysql_port
  ip_protocol                  = "tcp"
  to_port                      = local.mysql_port
}

# -----------------------------------------------------------------------------
# Master credentials: generated password stored encrypted in Secrets Manager
# and reused by the Aurora cluster so the two stay in sync.
# -----------------------------------------------------------------------------

resource "random_password" "db_master_password" {
  length           = 28
  special          = true
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
  override_special = "!#%&*()-_=+[]{}:?"
}

resource "aws_secretsmanager_secret" "db" {
  name        = "${local.name_prefix}-db-master-credentials"
  description = "Master credentials for the Aurora MySQL cluster, consumed by RDS Proxy"
  kms_key_id  = aws_kms_key.aurora.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "db" {
  secret_id = aws_secretsmanager_secret.db.id
  secret_string = jsonencode({
    username = local.db_master_username
    password = random_password.db_master_password.result
  })
}

# -----------------------------------------------------------------------------
# IAM: role trusted by the RDS service, with a least-privilege policy that only
# allows reading the single database secret and decrypting it with the
# dedicated KMS key.
# -----------------------------------------------------------------------------

resource "aws_iam_role" "db_proxy" {
  name = "${local.name_prefix}-proxy-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

resource "aws_iam_policy" "db_proxy_secret_access" {
  name        = "${local.name_prefix}-proxy-secret-access"
  description = "Least-privilege access for RDS Proxy to the database secret and its KMS key"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ReadDatabaseSecret"
        Effect   = "Allow"
        Action   = "secretsmanager:GetSecretValue"
        Resource = aws_secretsmanager_secret.db.arn
      },
      {
        Sid      = "DecryptDatabaseSecret"
        Effect   = "Allow"
        Action   = "kms:Decrypt"
        Resource = aws_kms_key.aurora.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "db_proxy_secret_access" {
  role       = aws_iam_role.db_proxy.name
  policy_arn = aws_iam_policy.db_proxy_secret_access.arn
}

# -----------------------------------------------------------------------------
# Aurora MySQL cluster (encrypted, backed up, deletion-protected) reachable
# only through the RDS Proxy security group.
# -----------------------------------------------------------------------------

resource "aws_rds_cluster" "main" {
  cluster_identifier        = "${local.name_prefix}-cluster"
  engine                    = "aurora-mysql"
  engine_version            = "8.0.mysql_aurora.3.05.2"
  database_name             = "appdb"
  master_username           = local.db_master_username
  master_password           = random_password.db_master_password.result
  db_subnet_group_name      = aws_db_subnet_group.main.name
  vpc_security_group_ids    = [aws_security_group.aurora.id]
  storage_encrypted         = true
  kms_key_id                = aws_kms_key.aurora.arn
  backup_retention_period   = 14
  copy_tags_to_snapshot     = true
  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-cluster-final-snapshot"

  tags = {
    Name = "${local.name_prefix}-cluster"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_rds_cluster_instance" "writer" {
  identifier                            = "${local.name_prefix}-writer-1"
  cluster_identifier                    = aws_rds_cluster.main.id
  engine                                = "aurora-mysql"
  instance_class                        = "db.t4g.medium"
  availability_zone                     = data.aws_availability_zones.available.names[0]
  db_subnet_group_name                  = aws_db_subnet_group.main.name
  publicly_accessible                   = false
  performance_insights_enabled          = true
  performance_insights_kms_key_id       = aws_kms_key.aurora.arn
  performance_insights_retention_period = 7
  copy_tags_to_snapshot                 = true

  tags = {
    Name = "${local.name_prefix}-writer-1"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_rds_cluster_instance" "reader" {
  identifier                            = "${local.name_prefix}-reader-1"
  cluster_identifier                    = aws_rds_cluster.main.id
  engine                                = "aurora-mysql"
  instance_class                        = "db.t4g.medium"
  availability_zone                     = data.aws_availability_zones.available.names[1]
  db_subnet_group_name                  = aws_db_subnet_group.main.name
  publicly_accessible                   = false
  performance_insights_enabled          = true
  performance_insights_kms_key_id       = aws_kms_key.aurora.arn
  performance_insights_retention_period = 7
  copy_tags_to_snapshot                 = true

  tags = {
    Name = "${local.name_prefix}-reader-1"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# RDS Proxy for connection pooling and management. engine_family = "MYSQL" is
# the provider-level value for any MySQL-protocol database, including Aurora
# MySQL 8.0 clusters. There is no separate "engine" argument on aws_db_proxy;
# "MYSQL" here denotes the engine family, which the provider schema restricts
# to MYSQL, POSTGRESQL, or SQLSERVER.
# -----------------------------------------------------------------------------

resource "aws_db_proxy" "main" {
  name                   = "${local.name_prefix}-proxy"
  debug_logging          = false
  engine_family          = "MYSQL"
  idle_client_timeout    = 1800
  require_tls            = true
  role_arn               = aws_iam_role.db_proxy.arn
  vpc_security_group_ids = [aws_security_group.rds_proxy.id]
  vpc_subnet_ids         = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  auth {
    auth_scheme = "SECRETS"
    description = "Aurora MySQL master credentials from Secrets Manager"
    iam_auth    = "DISABLED"
    secret_arn  = aws_secretsmanager_secret.db.arn
  }

  tags = {
    Name = "${local.name_prefix}-proxy"
  }

  depends_on = [
    aws_iam_role_policy_attachment.db_proxy_secret_access,
    aws_secretsmanager_secret_version.db,
  ]
}

# The default target group's name is assigned automatically by the RDS service
# (it is always "default") and is a computed-only attribute in provider v5.x,
# so it must not be configured here. The group exists solely to carry the
# connection_pool_config for the proxy.

resource "aws_db_proxy_default_target_group" "main" {
  db_proxy_name = aws_db_proxy.main.name

  connection_pool_config {
    connection_borrow_timeout    = 120
    max_connections_percent      = 100
    max_idle_connections_percent = 50
  }
}

# Registers the cluster as the proxy target; AWS resolves it to the cluster's
# immutable resource ID (aws_rds_cluster.main.cluster_resource_id) and routes
# to the writer/reader endpoints. target_group_name reads the computed "name"
# of the default target group rather than hardcoding the string "default".

resource "aws_db_proxy_target" "aurora" {
  db_proxy_name         = aws_db_proxy.main.name
  target_group_name     = aws_db_proxy_default_target_group.main.name
  db_cluster_identifier = aws_rds_cluster.main.id
}

# -----------------------------------------------------------------------------
# Outputs (no secret values)
# -----------------------------------------------------------------------------

output "rds_proxy_endpoint" {
  description = "RDS Proxy endpoint for managed, pooled connections to Aurora MySQL."
  value       = aws_db_proxy.main.endpoint
}

output "aurora_cluster_writer_endpoint" {
  description = "Writer endpoint of the Aurora MySQL cluster."
  value       = aws_rds_cluster.main.endpoint
}

output "aurora_cluster_reader_endpoint" {
  description = "Reader endpoint of the Aurora MySQL cluster."
  value       = aws_rds_cluster.main.reader_endpoint
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used to derive resource names and tags (non-infrastructure value only)"
  type        = string
  default     = "production"
}

locals {
  name_prefix     = "${var.environment}-aurora-mysql"
  master_username = "dbadmin"

  common_tags = {
    Project     = "aurora-mysql-rds-proxy"
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-a"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-b"
  })
}

resource "aws_db_subnet_group" "main" {
  name       = "${local.name_prefix}-db-subnet-group"
  subnet_ids = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-subnet-group"
  })
}

resource "aws_security_group" "proxy" {
  name        = "${local.name_prefix}-proxy-sg"
  description = "RDS Proxy security group - MySQL ingress from application tier within VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from within the VPC (application tier)"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound so the proxy can reach the Aurora cluster"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-proxy-sg"
  })
}

resource "aws_security_group" "db" {
  name        = "${local.name_prefix}-db-sg"
  description = "Aurora MySQL security group - MySQL ingress only from the RDS Proxy"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "MySQL from the RDS Proxy security group only"
    from_port       = 3306
    to_port         = 3306
    protocol        = "tcp"
    security_groups = [aws_security_group.proxy.id]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-sg"
  })
}

resource "aws_kms_key" "db_credentials" {
  description             = "Customer managed KMS key used to encrypt the Aurora MySQL credentials secret"
  enable_key_rotation     = true
  is_enabled              = true
  deletion_window_in_days = 7

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-credentials-key"
  })
}

resource "aws_kms_alias" "db_credentials" {
  name          = "alias/${local.name_prefix}-db-credentials"
  target_key_id = aws_kms_key.db_credentials.key_id
}

resource "random_password" "master_password" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
}

resource "aws_secretsmanager_secret" "db_credentials" {
  name                    = "${local.name_prefix}-db-credentials"
  description             = "Master credentials for the Aurora MySQL cluster, consumed by RDS Proxy"
  kms_key_id              = aws_kms_key.db_credentials.arn
  recovery_window_in_days = 7

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-credentials"
  })
}

resource "aws_secretsmanager_secret_version" "db_credentials" {
  secret_id = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({
    username = local.master_username
    password = random_password.master_password.result
  })
}

resource "aws_iam_role" "rds_proxy" {
  name        = "${local.name_prefix}-proxy-role"
  description = "IAM role assumed by RDS Proxy to read the database credentials secret"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowRDSProxyAssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy" "rds_proxy_secret_access" {
  name        = "${local.name_prefix}-proxy-secret-access"
  description = "Least-privilege access for RDS Proxy: read the credentials secret and decrypt it with the customer managed KMS key"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ReadDatabaseSecret"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret"
        ]
        Resource = [
          aws_secretsmanager_secret.db_credentials.arn
        ]
      },
      {
        Sid      = "DecryptDatabaseSecret"
        Effect   = "Allow"
        Action   = ["kms:Decrypt"]
        Resource = [aws_kms_key.db_credentials.arn]
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "rds_proxy_secret_access" {
  role       = aws_iam_role.rds_proxy.name
  policy_arn = aws_iam_policy.rds_proxy_secret_access.arn
}

resource "aws_rds_cluster" "main" {
  cluster_identifier              = "${local.name_prefix}-cluster"
  engine                          = "aurora-mysql"
  engine_version                  = "8.0.mysql_aurora.3.05.2"
  engine_mode                     = "provisioned"
  database_name                   = "appdb"
  master_username                 = local.master_username
  master_password                 = random_password.master_password.result
  db_subnet_group_name            = aws_db_subnet_group.main.name
  vpc_security_group_ids          = [aws_security_group.db.id]
  storage_encrypted               = true
  kms_key_id                      = aws_kms_key.db_credentials.arn
  port                            = 3306
  backup_retention_period         = 7
  preferred_backup_window         = "03:00-04:00"
  preferred_maintenance_window    = "sun:04:30-sun:05:30"
  deletion_protection             = true
  copy_tags_to_snapshot           = true
  enabled_cloudwatch_logs_exports = ["error"]
  apply_immediately               = true
  skip_final_snapshot             = false
  final_snapshot_identifier       = "snapshot"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-cluster"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_rds_cluster_instance" "writer" {
  identifier_prefix                     = "aurora-mysql-"
  cluster_identifier                    = aws_rds_cluster.main.id
  instance_class                        = "db.r6g.large"
  engine                                = "aurora-mysql"
  engine_version                        = aws_rds_cluster.main.engine_version
  availability_zone                     = data.aws_availability_zones.available.names[0]
  performance_insights_enabled          = true
  performance_insights_retention_period = 7
  auto_minor_version_upgrade            = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance-1"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_rds_cluster_instance" "reader" {
  identifier_prefix                     = "aurora-mysql-"
  cluster_identifier                    = aws_rds_cluster.main.id
  instance_class                        = "db.r6g.large"
  engine                                = "aurora-mysql"
  engine_version                        = aws_rds_cluster.main.engine_version
  availability_zone                     = data.aws_availability_zones.available.names[1]
  performance_insights_enabled          = true
  performance_insights_retention_period = 7
  auto_minor_version_upgrade            = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance-2"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_db_proxy" "main" {
  name                   = "${local.name_prefix}-proxy"
  debug_logging          = false
  engine_family          = "MYSQL"
  idle_client_timeout    = 1800
  require_tls            = true
  role_arn               = aws_iam_role.rds_proxy.arn
  vpc_security_group_ids = [aws_security_group.proxy.id]
  vpc_subnet_ids         = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  auth {
    auth_scheme = "SECRETS"
    description = "Aurora MySQL master credentials"
    iam_auth    = "DISABLED"
    secret_arn  = aws_secretsmanager_secret.db_credentials.arn
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-proxy"
  })

  depends_on = [
    aws_iam_role_policy_attachment.rds_proxy_secret_access,
    aws_secretsmanager_secret_version.db_credentials
  ]
}

resource "aws_db_proxy_default_target_group" "main" {
  db_proxy_name = aws_db_proxy.main.name

  connection_pool_config {
    connection_borrow_timeout    = 120
    max_connections_percent      = 100
    max_idle_connections_percent = 50
    session_pinning_filters      = ["EXCLUDE_VARIABLE_SETS"]
  }
}

resource "aws_db_proxy_target" "main" {
  db_proxy_name        = aws_db_proxy.main.name
  target_group_name    = aws_db_proxy_default_target_group.main.name
  db_cluster_identifier = aws_rds_cluster.main.id
}

output "aurora_cluster_writer_endpoint" {
  description = "Writer endpoint of the Aurora MySQL cluster"
  value       = aws_rds_cluster.main.endpoint
}

output "aurora_cluster_reader_endpoint" {
  description = "Reader endpoint of the Aurora MySQL cluster"
  value       = aws_rds_cluster.main.reader_endpoint
}

output "rds_proxy_endpoint" {
  description = "Connection endpoint of the RDS Proxy"
  value       = aws_db_proxy.main.endpoint
}

output "db_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the master credentials (secret value is never exposed)"
  value       = aws_secretsmanager_secret.db_credentials.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

variable "instance_name" {
  description = "Name of the Lightsail instance."
  type        = string
  default     = "lightsail-amazon-linux"
}

variable "environment" {
  description = "Environment tag value applied to the instance."
  type        = string
  default     = "dev"
}

variable "admin_cidr" {
  description = "CIDR block permitted to reach the instance over SSH (TCP 22). Must be a narrow administrative range, never 0.0.0.0/0."
  type        = string
  default     = "10.0.0.0/8"
}

locals {
  common_tags = {
    Name        = var.instance_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_lightsail_key_pair" "main" {
  name = "${var.instance_name}-key-pair"
}

resource "aws_lightsail_instance" "main" {
  name              = var.instance_name
  availability_zone = data.aws_availability_zones.available.names[0]
  blueprint_id      = "amazon_linux_2023"
  bundle_id         = "nano_3_0"
  key_pair_name     = aws_lightsail_key_pair.main.name

  tags = local.common_tags
}

resource "aws_lightsail_instance_public_ports" "main" {
  instance_name = aws_lightsail_instance.main.name

  port_info {
    protocol  = "tcp"
    from_port = 22
    to_port   = 22
    cidrs     = [var.admin_cidr]
  }

  port_info {
    protocol  = "tcp"
    from_port = 80
    to_port   = 80
    cidrs     = ["0.0.0.0/0"]
  }

  port_info {
    protocol  = "tcp"
    from_port = 443
    to_port   = 443
    cidrs     = ["0.0.0.0/0"]
  }
}

output "public_ip_address" {
  description = "Public IP address of the Lightsail instance."
  value       = aws_lightsail_instance.main.public_ip_address
}

output "instance_arn" {
  description = "ARN of the Lightsail instance."
  value       = aws_lightsail_instance.main.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Project name used for the Lightsail instance, SSH key pair, and related resource naming."
  type        = string
  default     = "greenfield"
}

variable "blueprint_id" {
  description = "Lightsail blueprint (operating system image) for the instance."
  type        = string
  default     = "amazon_linux_2023"
}

variable "bundle_id" {
  description = "Lightsail bundle (instance size) for the instance."
  type        = string
  default     = "micro_3_0"
}

variable "ssh_allowed_cidr" {
  description = "Admin CIDR block permitted to reach SSH (TCP/22) on the Lightsail instance. Must never be 0.0.0.0/0."
  type        = string
  default     = "203.0.113.0/24"

  validation {
    condition     = var.ssh_allowed_cidr != "0.0.0.0/0" && can(cidrnetmask(var.ssh_allowed_cidr))
    error_message = "ssh_allowed_cidr must be a valid CIDR block and must not be the open internet (0.0.0.0/0)."
  }
}

variable "common_tags" {
  description = "Common tags applied to all taggable resources."
  type        = map(string)
  default = {
    Project   = "greenfield"
    ManagedBy = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  ssh_key_pair_name   = "${var.project_name}-ssh-key"
  ssh_key_secret_name = "${var.project_name}-ssh-private-key"
  static_ip_name      = "${var.project_name}-static-ip"
}

resource "tls_private_key" "main" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_lightsail_key_pair" "main" {
  name       = local.ssh_key_pair_name
  public_key = tls_private_key.main.public_key_openssh

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret" "ssh_key" {
  name        = local.ssh_key_secret_name
  description = "SSH private key for the ${var.project_name} Lightsail instance."

  tags = var.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "ssh_key" {
  secret_id     = aws_secretsmanager_secret.ssh_key.arn
  secret_string = tls_private_key.main.private_key_openssh
}

resource "aws_lightsail_instance" "main" {
  name              = var.project_name
  availability_zone = data.aws_availability_zones.available.names[0]
  blueprint_id      = var.blueprint_id
  bundle_id         = var.bundle_id
  key_pair_name     = aws_lightsail_key_pair.main.name

  tags = var.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lightsail_static_ip" "main" {
  name = local.static_ip_name
}

resource "aws_lightsail_static_ip_attachment" "main" {
  static_ip_name = aws_lightsail_static_ip.main.name
  instance_name  = aws_lightsail_instance.main.name
}

resource "aws_lightsail_instance_public_ports" "main" {
  instance_name = aws_lightsail_instance.main.name

  port_info {
    protocol  = "tcp"
    from_port = 22
    to_port   = 22
    cidrs     = [var.ssh_allowed_cidr]
  }
}

output "static_ip" {
  description = "Public static IP address attached to the Lightsail instance."
  value       = aws_lightsail_static_ip.main.ip_address
}

output "instance_name" {
  description = "Name of the Lightsail instance."
  value       = aws_lightsail_instance.main.name
}

output "ssh_private_key_secret_arn" {
  description = "ARN of the Secrets Manager secret storing the SSH private key. Retrieve the key with aws secretsmanager get-secret-value."
  value       = aws_secretsmanager_secret.ssh_key.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# Static provider metadata lookup only (no dependency on existing infrastructure)
# ---------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# Variables (safe defaults so `terraform apply` runs unattended)
# ---------------------------------------------------------------------------
variable "database_identifier" {
  description = "Unique name of the Lightsail relational database."
  type        = string
  default     = "appdb-postgres"

  validation {
    condition     = can(regex("^[a-zA-Z][a-zA-Z0-9_-]{0,254}$", var.database_identifier))
    error_message = "database_identifier must start with a letter and contain only letters, digits, underscores, and hyphens (max 255 characters)."
  }
}

variable "master_database_name" {
  description = "Name of the initial PostgreSQL database created on the instance."
  type        = string
  default     = "appdb"

  validation {
    condition     = can(regex("^[a-z][a-z0-9_]{0,62}$", var.master_database_name))
    error_message = "master_database_name must start with a lowercase letter and contain only lowercase letters, digits, and underscores (max 63 characters)."
  }
}

variable "master_username" {
  description = "Master username for the Lightsail PostgreSQL instance."
  type        = string
  default     = "dbadmin"

  validation {
    condition     = can(regex("^[a-z][a-z0-9_]{0,62}$", var.master_username))
    error_message = "master_username must start with a lowercase letter and contain only lowercase letters, digits, and underscores (max 63 characters)."
  }
}

variable "environment" {
  description = "Environment name applied as a tag to all resources."
  type        = string
  default     = "production"
}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------
locals {
  final_snapshot_name = "${var.database_identifier}-final-snapshot"

  common_tags = {
    Name        = var.database_identifier
    Environment = var.environment
  }
}

# ---------------------------------------------------------------------------
# Master credential generation (no plaintext passwords anywhere in config)
# ---------------------------------------------------------------------------
resource "random_password" "master_password" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
}

# ---------------------------------------------------------------------------
# Secret persistence (credential stored in Secrets Manager, never output)
# ---------------------------------------------------------------------------
resource "aws_secretsmanager_secret" "postgres_master_credentials" {
  name        = "${var.database_identifier}/master-credentials"
  description = "Master credentials for the ${var.database_identifier} Lightsail PostgreSQL database."
  tags        = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "postgres_master_credentials" {
  secret_id = aws_secretsmanager_secret.postgres_master_credentials.id
  secret_string = jsonencode({
    engine   = "postgres"
    host     = aws_lightsail_database.postgres.master_endpoint_address
    port     = aws_lightsail_database.postgres.master_endpoint_port
    dbname   = var.master_database_name
    username = var.master_username
    password = random_password.master_password.result
  })
}

# ---------------------------------------------------------------------------
# Lightsail PostgreSQL database
# ---------------------------------------------------------------------------
resource "aws_lightsail_database" "postgres" {
  relational_database_name = var.database_identifier
  availability_zone        = data.aws_availability_zones.available.names[0]
  master_database_name     = var.master_database_name
  master_username          = var.master_username
  master_password          = random_password.master_password.result
  blueprint_id             = "postgres_16"
  bundle_id                = "micro_2_0"

  # Keep the database private; no public exposure.
  publicly_accessible = false

  # Automated backups
  backup_retention_enabled     = true
  preferred_backup_window      = "03:00-04:00"
  preferred_maintenance_window = "sun:05:00-sun:06:00"

  # Create a final snapshot on intentional deletion.
  skip_final_snapshot = false
  final_snapshot_name = local.final_snapshot_name

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Outputs (non-sensitive only)
# ---------------------------------------------------------------------------
output "database_arn" {
  description = "ARN of the Lightsail PostgreSQL database."
  value       = aws_lightsail_database.postgres.arn
}

output "master_database_name" {
  description = "Name of the initial database created on the Lightsail PostgreSQL instance."
  value       = aws_lightsail_database.postgres.master_database_name
}

output "database_endpoint_address" {
  description = "Private endpoint address of the Lightsail PostgreSQL database (publicly_accessible is false)."
  value       = aws_lightsail_database.postgres.master_endpoint_address
}

output "database_endpoint_port" {
  description = "Port the Lightsail PostgreSQL database listens on."
  value       = aws_lightsail_database.postgres.master_endpoint_port
}

output "master_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret storing the database master credentials."
  value       = aws_secretsmanager_secret.postgres_master_credentials.arn
}

terraform {
  required_version = "~> 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Inputs (user-controlled values only via variables with safe defaults)
# -----------------------------------------------------------------------------

variable "project_name" {
  description = "Project name used for resource naming and tagging (lowercase letters, digits, hyphens)."
  type        = string
  default     = "storage-demo"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9-]{1,30}$", var.project_name))
    error_message = "project_name must be 2-31 lowercase alphanumeric characters or hyphens, starting with a letter or digit."
  }
}

variable "environment" {
  description = "Deployment environment used for naming and tagging (e.g. dev, staging, prod)."
  type        = string
  default     = "dev"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9-]{0,14}$", var.environment))
    error_message = "environment must be up to 15 lowercase alphanumeric characters or hyphens, starting with a letter or digit."
  }
}

# -----------------------------------------------------------------------------
# Static provider metadata only
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  name_prefix   = "${var.project_name}-${var.environment}"
  key_pair_name = "${local.name_prefix}-key-pair"
  # Random suffix keeps the bucket name DNS-compatible and globally unique
  # (3-63 chars, lowercase letters, digits, hyphens).
  bucket_name   = "${local.name_prefix}-storage-${random_id.bucket_suffix.hex}"
  instance_name = "${local.name_prefix}-compute"

  common_tags = {
    Project     = var.project_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

# -----------------------------------------------------------------------------
# SSH key pair for the compute instance (key material generated by Lightsail)
# -----------------------------------------------------------------------------

resource "aws_lightsail_key_pair" "compute" {
  name = local.key_pair_name
}

# -----------------------------------------------------------------------------
# Storage unit: Lightsail object storage bucket
# -----------------------------------------------------------------------------

resource "aws_lightsail_bucket" "storage" {
  name      = local.bucket_name
  bundle_id = "small_1_0"

  tags = merge(local.common_tags, {
    Name = local.bucket_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

# Programmatic credentials so the compute instance can authenticate to the
# bucket. Only the provider-generated attributes are referenced.
resource "aws_lightsail_bucket_access_key" "compute" {
  bucket_name = aws_lightsail_bucket.storage.name
}

# -----------------------------------------------------------------------------
# Compute service: Lightsail instance linked to the bucket
# -----------------------------------------------------------------------------

resource "aws_lightsail_instance" "compute" {
  name              = local.instance_name
  availability_zone = data.aws_availability_zones.available.names[0]
  blueprint_id      = "amazon_linux_2023"
  bundle_id         = "nano_3_0"
  key_pair_name     = aws_lightsail_key_pair.compute.name

  # Bootstrap script: install/configure the AWS CLI, write the Lightsail
  # bucket access-key credentials (Terraform references only), then perform
  # a round-trip object write/read to verify the storage <-> compute linkage.
  user_data = <<-EOF
#!/bin/bash
set -euo pipefail

LOG_FILE="/var/log/lightsail-bucket-linkage.log"
exec > "$LOG_FILE" 2>&1

echo "Lightsail bucket linkage bootstrap started at $(date --iso-8601=seconds)"

# Install the AWS CLI if it is not already present.
if ! command -v aws >/dev/null 2>&1; then
  dnf install -y aws-cli || dnf install -y awscli || true
fi
if ! command -v aws >/dev/null 2>&1; then
  curl -sSL "https://awscli.amazonaws.com/awscli-exe-linux-x86_64.sh" -o /tmp/awscliv2-install.sh
  bash /tmp/awscliv2-install.sh --update
fi
aws --version

# Write the Lightsail bucket access-key credentials for root and ec2-user.
ACCESS_KEY_ID="${aws_lightsail_bucket_access_key.compute.access_key_id}"
SECRET_ACCESS_KEY="${aws_lightsail_bucket_access_key.compute.secret_access_key}"
BUCKET_NAME="${aws_lightsail_bucket.storage.name}"

for AWS_DIR in /root/.aws /home/ec2-user/.aws; do
  install -d -m 0700 "$AWS_DIR"
  printf '[default]\naws_access_key_id = %s\naws_secret_access_key = %s\n' "$ACCESS_KEY_ID" "$SECRET_ACCESS_KEY" > "$AWS_DIR/credentials"
  printf '[default]\nregion = %s\noutput = json\n' "us-east-1" > "$AWS_DIR/config"
  chmod 0600 "$AWS_DIR/credentials" "$AWS_DIR/config"
done
chown -R ec2-user:ec2-user /home/ec2-user/.aws

# Verify the linkage with a round-trip object write/read against the bucket.
TEST_FILE="/tmp/lightsail-linkage-test.txt"
TEST_COPY="/tmp/lightsail-linkage-test-download.txt"
TEST_KEY="verification/lightsail-linkage-test.txt"

echo "lightsail-bucket-linkage-test $(date --iso-8601=seconds)" > "$TEST_FILE"

aws s3 cp "$TEST_FILE" "s3://$BUCKET_NAME/$TEST_KEY"
aws s3 cp "s3://$BUCKET_NAME/$TEST_KEY" "$TEST_COPY"
diff -q "$TEST_FILE" "$TEST_COPY"
aws s3 ls "s3://$BUCKET_NAME/verification/"

echo "SUCCESS: bucket linkage verified; round-trip write/read to s3://$BUCKET_NAME completed."
echo "linkage_status=success" > /var/log/lightsail-bucket-linkage-status.txt
EOF

  tags = merge(local.common_tags, {
    Name = local.instance_name
  })
}

# -----------------------------------------------------------------------------
# Firewall hygiene: SSH (TCP 22) only, restricted to the default port set
# -----------------------------------------------------------------------------

resource "aws_lightsail_instance_public_ports" "compute" {
  instance_name = aws_lightsail_instance.compute.name

  port_info {
    protocol  = "tcp"
    from_port = 22
    to_port   = 22
    cidrs     = ["0.0.0.0/0"]
  }
}

# -----------------------------------------------------------------------------
# Outputs for automated verification
# -----------------------------------------------------------------------------

output "bucket_name" {
  description = "Name of the Lightsail object storage bucket."
  value       = aws_lightsail_bucket.storage.name
}

output "bucket_arn" {
  description = "ARN of the Lightsail object storage bucket."
  value       = aws_lightsail_bucket.storage.arn
}

output "instance_name" {
  description = "Name of the Lightsail compute instance."
  value       = aws_lightsail_instance.compute.name
}

output "instance_public_ip" {
  description = "Public IP address of the Lightsail compute instance."
  value       = aws_lightsail_instance.compute.public_ip_address
}

terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "tags" {
  description = "Tags to apply to all taggable resources."
  type        = map(string)
  default     = {}
}

variable "custom_domain_name" {
  description = "Custom domain name to serve the distribution from. Leave empty (default) to serve from the distribution's default HTTPS-enabled DNS target."
  type        = string
  default     = ""
}

resource "random_id" "suffix" {
  byte_length = 4
}

locals {
  # Lightsail bucket names live in the global S3 namespace and only allow
  # lowercase letters, numbers and hyphens, so a random suffix is appended
  # to guarantee a globally unique name.
  bucket_name = "static-assets-${random_id.suffix.hex}"

  distribution_name = "static-cdn-${random_id.suffix.hex}"
}

# Private Lightsail bucket used as the sole origin of the distribution.
# Lightsail buckets are private by default; they are never exposed publicly
# and are only shared with the distribution through
# aws_lightsail_bucket_resource_access below.
#
# Note: the provider cannot manage Lightsail bucket objects via Terraform
# (no aws_lightsail_bucket_object resource exists), so origin content such as
# index.html is seeded post-apply via the Lightsail console/CLI or the
# S3-compatible API with bucket access keys, outside Terraform state.
resource "aws_lightsail_bucket" "static_assets" {
  name      = local.bucket_name
  bundle_id = "small_2_0"

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# Lightsail distributions support exactly one origin; default_cache_behavior
# always targets that origin (there is no separate target_origin_id argument).
resource "aws_lightsail_distribution" "static_cdn" {
  name             = local.distribution_name
  bundle_id        = "small_1_0"
  ip_address_type  = "dualstack"
  is_enabled       = true
  certificate_name = var.custom_domain_name != "" ? aws_lightsail_certificate.custom_domain[0].name : null

  default_cache_behavior {
    behavior = "cache"
  }

  cache_behavior_settings {
    allowed_http_methods = "GET, HEAD, OPTIONS"
    cached_http_methods  = "GET, HEAD"
    default_ttl          = 86400
    minimum_ttl          = 0
    maximum_ttl          = 31536000

    forwarded_query_strings {
      option = true
    }
  }

  origin {
    name        = aws_lightsail_bucket.static_assets.name
    region_name = "us-east-1"
  }

  tags = var.tags
}

# Grant the distribution read access to the private bucket. The bucket itself
# stays private; the distribution is the only egress path.
resource "aws_lightsail_bucket_resource_access" "distribution_origin_access" {
  bucket_name   = aws_lightsail_bucket.static_assets.name
  resource_name = aws_lightsail_distribution.static_cdn.name
}

# Only created when a custom domain is supplied; otherwise the distribution
# serves content over HTTPS from its default DNS target.
resource "aws_lightsail_certificate" "custom_domain" {
  count = var.custom_domain_name != "" ? 1 : 0

  name        = "static-cdn-cert-${random_id.suffix.hex}"
  domain_name = var.custom_domain_name

  tags = var.tags
}

output "distribution_dns_target" {
  description = "Default DNS target of the Lightsail distribution (CloudFront endpoint serving the bucket origin)."
  value       = aws_lightsail_distribution.static_cdn.domain_name
}

output "static_assets_bucket_name" {
  description = "Name of the private Lightsail bucket used as the distribution origin."
  value       = aws_lightsail_bucket.static_assets.name
}

# =============================================================================
# S3 Glacier vault + AWS Data Lifecycle Manager (DLM) snapshot archiving
# =============================================================================

terraform {
  required_version = ">= 1.5.0, < 2.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "project_name" {
  description = "Base project name used to derive resource names."
  type        = string
  default     = "glacier-archive"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9-]*$", var.project_name))
    error_message = "project_name must start with a lowercase letter or digit and contain only lowercase letters, digits, and hyphens."
  }
}

variable "snapshot_retention" {
  description = "Number of daily snapshots retained by the DLM lifecycle policy."
  type        = number
  default     = 14

  validation {
    condition     = var.snapshot_retention >= 1 && var.snapshot_retention <= 1000
    error_message = "snapshot_retention must be between 1 and 1000."
  }
}

variable "common_tags" {
  description = "Common tags applied to all taggable resources."
  type        = map(string)
  default = {
    Environment = "production"
    Owner       = "platform-team"
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Data sources (pure static provider metadata lookups only)
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  name_prefix = lower(var.project_name)
  vault_name  = "${local.name_prefix}-vault"

  # The vault ARN is composed from static provider metadata (partition, region,
  # account ID) plus the deterministic vault name. Terraform rejects a resource
  # referencing its own attributes (a self-reference is treated as a graph
  # cycle), so the inline vault access policy cannot use
  # aws_glacier_vault.archive_vault.arn directly. This local produces the exact
  # same ARN the vault resource will receive.
  glacier_vault_arn = "arn:${data.aws_partition.current.partition}:glacier:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:vaults/${local.vault_name}"

  dlm_target_tags = { Backup = "true" }
}

# -----------------------------------------------------------------------------
# KMS key: encrypts the backup source volume; DLM snapshots inherit it
# -----------------------------------------------------------------------------

resource "aws_kms_key" "archive_key" {
  description             = "CMK for the backup source volume and DLM-managed snapshots"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = var.common_tags
}

resource "aws_kms_alias" "archive_key_alias" {
  name          = "alias/${local.name_prefix}-archive-key"
  target_key_id = aws_kms_key.archive_key.key_id
}

resource "aws_kms_key_policy" "archive_key_policy" {
  key_id = aws_kms_key.archive_key.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableAccountRootAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = aws_kms_key.archive_key.arn
      },
      {
        Sid    = "AllowDLMRoleSnapshotOperations"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.dlm_exec.arn
        }
        Action = [
          "kms:CreateGrant",
          "kms:DescribeKey",
          "kms:Decrypt",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:ReEncrypt*"
        ]
        Resource = aws_kms_key.archive_key.arn
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# DLM execution role
# -----------------------------------------------------------------------------

resource "aws_iam_role" "dlm_exec" {
  name = "${local.name_prefix}-dlm-exec"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "dlm.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.common_tags
}

resource "aws_iam_role_policy_attachment" "dlm_exec_default" {
  role       = aws_iam_role.dlm_exec.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSDataLifecycleManagerDefaultRole"
}

# -----------------------------------------------------------------------------
# S3 Glacier archive vault (server-side AES-256 encryption at rest is built in)
# The provider models the vault access policy as the inline `access_policy`
# string attribute; there is no standalone vault-policy resource type.
# -----------------------------------------------------------------------------

resource "aws_glacier_vault" "archive_vault" {
  name = local.vault_name

  access_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowDLMRoleGlacierOperations"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.dlm_exec.arn
        }
        Action = [
          "glacier:UploadArchive",
          "glacier:InitiateJob",
          "glacier:DownloadJob",
          "glacier:AbortMultipartUpload"
        ]
        Resource = local.glacier_vault_arn
      }
    ]
  })

  tags = var.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Encrypted backup source volume (DLM target; snapshots inherit the CMK)
# -----------------------------------------------------------------------------

resource "aws_ebs_volume" "backup_source" {
  availability_zone = data.aws_availability_zones.available.names[0]
  size              = 10
  type              = "gp3"
  encrypted         = true
  kms_key_id        = aws_kms_key.archive_key.arn

  tags = merge(
    var.common_tags,
    local.dlm_target_tags,
    {
      Name = "${local.name_prefix}-backup-source"
    },
  )

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# DLM lifecycle policy: daily 0300 UTC snapshots with bounded retention.
# The Glacier vault above (aws_glacier_vault.archive_vault) serves as the
# long-term archive destination; the retain_rule below delivers the daily
# snapshot rotation that feeds the vault archival strategy.
# Note: the DLM API restricts policy descriptions to [0-9A-Za-z _-], so the
# description below deliberately avoids colons, equals signs, and commas.
# -----------------------------------------------------------------------------

resource "aws_dlm_lifecycle_policy" "glacier_archive_lifecycle" {
  description        = "Daily snapshot retention for Backup-tagged volumes feeding the Glacier vault archival strategy"
  execution_role_arn = aws_iam_role.dlm_exec.arn
  state              = "ENABLED"

  policy_details {
    resource_types = ["VOLUME"]

    target_tags = local.dlm_target_tags

    schedule {
      name      = "daily-0300-utc"
      copy_tags = true

      create_rule {
        cron_expression = "cron(0 3 * * ? *)"
      }

      # Snapshots inherit encryption from the encrypted source volume
      # (aws_kms_key.archive_key), so every DLM-managed snapshot is
      # encrypted with the archive CMK.
      retain_rule {
        count = var.snapshot_retention
      }
    }
  }

  tags = var.common_tags

  depends_on = [aws_iam_role_policy_attachment.dlm_exec_default]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "glacier_vault_name" {
  description = "Name of the S3 Glacier archive vault."
  value       = aws_glacier_vault.archive_vault.name
}

output "glacier_vault_arn" {
  description = "ARN of the S3 Glacier archive vault."
  value       = aws_glacier_vault.archive_vault.arn
}

output "dlm_lifecycle_policy_arn" {
  description = "ARN of the DLM lifecycle policy."
  value       = aws_dlm_lifecycle_policy.glacier_archive_lifecycle.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Static, well-known provider/account metadata used to build the vault ARN and
# vault URL without hardcoding any account-specific identifiers.
data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

variable "vault_name" {
  description = "Name of the S3 Glacier vault used as the long-term archival storage target."
  type        = string
  default     = "app-archive-vault"
}

variable "retention_in_days" {
  description = "Minimum archive retention window (in days) enforced by the vault access policy."
  type        = number
  default     = 365

  validation {
    condition     = var.retention_in_days > 0
    error_message = "retention_in_days must be a positive number of days."
  }
}

variable "environment" {
  description = "Environment tag value applied to the vault."
  type        = string
  default     = "production"
}

variable "owner" {
  description = "Owner tag value applied to the vault."
  type        = string
  default     = "platform-engineering"
}

variable "purpose" {
  description = "Purpose tag value applied to the vault."
  type        = string
  default     = "long-term-archive"
}

locals {
  vault_arn = "arn:${data.aws_partition.current.partition}:glacier:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:vaults/${var.vault_name}"
  vault_url = "https://glacier.${data.aws_region.current.name}.amazonaws.com/${data.aws_caller_identity.current.account_id}/vaults/${var.vault_name}"
}

# S3 Glacier automatically encrypts all vault contents at rest with AES-256
# server-side encryption; no additional encryption configuration is required
# and no secrets are managed in this configuration.
#
# Note: the Terraform AWS provider does not support initiating a Glacier
# Vault Lock (there is no vault_lock block or aws_glacier_vault_lock
# resource), so the minimum archive retention window is enforced through the
# vault access policy below instead of a Vault Lock policy.
resource "aws_glacier_vault" "archive_vault" {
  name = var.vault_name

  # Vault access policy:
  #   1. DenyInsecureTransportRequests - denies all glacier service requests
  #      made over insecure transport for this vault.
  #   2. DenyDeleteArchiveBeforeRetentionWindow - enforces the minimum archive
  #      retention window by denying glacier:DeleteArchive for any archive
  #      younger than var.retention_in_days (glacier:ArchiveAgeInDays
  #      condition, expressed as a JSON string as IAM numeric conditions
  #      require).
  #
  # Both statements are scoped to this vault's ARN only, so the policy never
  # combines a wildcard Action with a wildcard Resource.
  access_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransportRequests"
        Effect    = "Deny"
        Principal = "*"
        Action    = "glacier:*"
        Resource  = local.vault_arn
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
      {
        Sid       = "DenyDeleteArchiveBeforeRetentionWindow"
        Effect    = "Deny"
        Principal = "*"
        Action    = "glacier:DeleteArchive"
        Resource  = local.vault_arn
        Condition = {
          NumericLessThan = {
            "glacier:ArchiveAgeInDays" = tostring(var.retention_in_days)
          }
        }
      }
    ]
  })

  tags = {
    Environment = var.environment
    Owner       = var.owner
    Purpose     = var.purpose
  }

  # The vault holds immutable, long-lived archives; block accidental deletion.
  lifecycle {
    prevent_destroy = true
  }
}

output "vault_name" {
  description = "Name of the S3 Glacier archive vault."
  value       = aws_glacier_vault.archive_vault.name
}

output "vault_arn" {
  description = "ARN of the S3 Glacier archive vault."
  value       = aws_glacier_vault.archive_vault.arn
}

output "vault_url" {
  description = "HTTPS URL of the S3 Glacier archive vault."
  value       = local.vault_url
}

output "vault_lock_status" {
  description = "Vault Lock completion status. The Terraform AWS provider does not support Glacier Vault Lock initiation, so no Vault Lock is provisioned here; minimum archive retention is instead enforced through the vault access policy (DenyDeleteArchiveBeforeRetentionWindow statement)."
  value       = "NotConfigured"
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

locals {
  name_prefix = "alb-${var.environment}"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "${local.name_prefix}-vpc"
    Environment = var.environment
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "${local.name_prefix}-igw"
    Environment = var.environment
  }
}

resource "aws_subnet" "public_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.0.0/20"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name        = "${local.name_prefix}-public-1"
    Environment = var.environment
  }
}

resource "aws_subnet" "public_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.16.0/20"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = {
    Name        = "${local.name_prefix}-public-2"
    Environment = var.environment
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name        = "${local.name_prefix}-public-rt"
    Environment = var.environment
  }
}

resource "aws_route_table_association" "public_1" {
  subnet_id      = aws_subnet.public_1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_2" {
  subnet_id      = aws_subnet.public_2.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "alb" {
  name        = "${local.name_prefix}-alb-sg"
  description = "Security group for the internet-facing ALB: allows public HTTP/HTTPS ingress and restricts egress to HTTP within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "HTTP to backend targets within the VPC only"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name        = "${local.name_prefix}-alb-sg"
    Environment = var.environment
  }
}

resource "aws_lb_target_group" "main" {
  name        = "${local.name_prefix}-tg"
  port        = 80
  protocol    = "HTTP"
  target_type = "instance"
  vpc_id      = aws_vpc.main.id

  health_check {
    enabled             = true
    path                = "/"
    protocol            = "HTTP"
    matcher             = "200"
    healthy_threshold   = 2
    unhealthy_threshold = 2
    interval            = 30
    timeout             = 5
  }

  tags = {
    Name        = "${local.name_prefix}-tg"
    Environment = var.environment
  }
}

resource "aws_lb" "main" {
  name               = "${local.name_prefix}-alb"
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb.id]
  subnets            = [aws_subnet.public_1.id, aws_subnet.public_2.id]

  drop_invalid_header_fields = true
  enable_deletion_protection = true
  idle_timeout               = 60

  tags = {
    Name        = "${local.name_prefix}-alb"
    Environment = var.environment
  }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }

  tags = {
    Name        = "${local.name_prefix}-listener-http"
    Environment = var.environment
  }
}

output "alb_dns_name" {
  description = "Public DNS name of the Application Load Balancer."
  value       = aws_lb.main.dns_name
}

output "alb_arn" {
  description = "ARN of the Application Load Balancer."
  value       = aws_lb.main.arn
}

output "target_group_arn" {
  description = "ARN of the ALB target group."
  value       = aws_lb_target_group.main.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied to resource names and tags."
  type        = string
  default     = "dev"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix = "internal_alb_${var.environment}"

  # "internal" must not be the leading token: the AWS ELB API reserves the
  # "internal-" name prefix, so it is placed after the environment segment.
  alb_name_prefix = "${var.environment}-internal"

  # Statically assigned private IPs, one per private subnet, each inside the
  # corresponding subnet CIDR (10.0.1.0/24 and 10.0.2.0/24).
  alb_private_ips = [
    "10.0.1.10",
    "10.0.2.10",
  ]

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_vpc"
  })
}

resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_private_a"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_private_b"
  })
}

resource "aws_security_group" "alb_sg" {
  name        = "${local.alb_name_prefix}-alb-sg"
  description = "Internal ALB ingress restricted to the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from within the VPC only"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "HTTPS from within the VPC only"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Egress restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_alb_sg"
  })
}

resource "aws_security_group" "backend_sg" {
  name        = "${local.alb_name_prefix}-backend-sg"
  description = "Allows HTTP only from the internal ALB security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "HTTP from the internal ALB only (SG-to-SG reference)"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.alb_sg.id]
  }

  egress {
    description = "Egress restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_backend_sg"
  })
}

resource "aws_lb" "internal_alb" {
  name                       = "${local.alb_name_prefix}-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb_sg.id]
  drop_invalid_header_fields = true

  subnet_mapping {
    subnet_id            = aws_subnet.private_a.id
    private_ipv4_address = local.alb_private_ips[0]
  }

  subnet_mapping {
    subnet_id            = aws_subnet.private_b.id
    private_ipv4_address = local.alb_private_ips[1]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_alb"
  })
}

resource "aws_lb_target_group" "app_tg" {
  name        = "${local.alb_name_prefix}-tg"
  port        = 80
  protocol    = "HTTP"
  target_type = "instance"
  vpc_id      = aws_vpc.main.id

  health_check {
    enabled             = true
    path                = "/"
    protocol            = "HTTP"
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 3
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_app_tg"
  })
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.internal_alb.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.app_tg.arn
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_http_listener"
  })
}

data "aws_ami" "amazon_linux_2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023.*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

resource "aws_instance" "backend" {
  ami                         = data.aws_ami.amazon_linux_2023.id
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.private_a.id
  vpc_security_group_ids      = [aws_security_group.backend_sg.id]
  associate_public_ip_address = false

  user_data = <<-EOF
    #!/bin/bash
    set -euo pipefail
    dnf install -y httpd
    systemctl enable --now httpd
    echo "Hello from $(hostname -f)" > /var/www/html/index.html
  EOF

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    volume_size = 8
    volume_type = "gp3"
    encrypted   = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_backend"
  })
}

resource "aws_lb_target_group_attachment" "backend" {
  target_group_arn = aws_lb_target_group.app_tg.arn
  target_id        = aws_instance.backend.id
  port             = 80
}

output "alb_dns_name" {
  description = "Private DNS name of the internal application load balancer."
  value       = aws_lb.internal_alb.dns_name
}

output "alb_private_ips" {
  description = "Statically assigned private IPs of the internal application load balancer."
  value       = aws_lb.internal_alb.subnet_mapping[*].private_ipv4_address
}

