resource "aws_security_group" "alb" {
  name        = "alb-fixed-response-sg"
  description = "Allows inbound HTTP to the fixed-response ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(
    local.common_tags,
    {
      Name = "alb-fixed-response-sg"
    }
  )
}

resource "aws_lb" "main" {
  name                       = "alb-fixed-response"
  load_balancer_type         = "application"
  internal                   = false
  security_groups            = [aws_security_group.alb.id]
  subnets                    = [aws_subnet.public_a.id, aws_subnet.public_b.id]
  drop_invalid_header_fields = true

  tags = merge(
    local.common_tags,
    {
      Name = "alb-fixed-response"
    }
  )
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "fixed-response"

    fixed_response {
      content_type = "text/plain"
      message_body = "OK - served by ALB fixed-response"
      status_code  = "200"
    }
  }

  tags = merge(
    local.common_tags,
    {
      Name = "alb-fixed-response-http-listener"
    }
  )
}

output "alb_dns_name" {
  description = "Public DNS name of the ALB. Verify the fixed response with: curl http://$(terraform output -raw alb_dns_name)"
  value       = aws_lb.main.dns_name
}

