provider "aws" {
  region = "us-east-1"
}

locals {
  name_prefix = "main"

  # SECURITY WARNING: 0.0.0.0/0 on database ports is intentionally open per
  # the request. This exposes MySQL (3306) and PostgreSQL (5432) to the entire
  # internet and is a significant security risk. Restrict cidr_blocks to
  # trusted CIDR ranges in any production deployment.
  open_cidr = "0.0.0.0/0"

  common_tags = {
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-vpc"
    },
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-igw"
    },
  )
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-subnet-a"
    },
  )
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-subnet-b"
    },
  )
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-rt"
    },
  )
}

resource "aws_route_table_association" "subnet_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.main.id
}

resource "aws_route_table_association" "subnet_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.main.id
}

# SECURITY WARNING: This security group permits MySQL and PostgreSQL from the
# entire internet (0.0.0.0/0) as explicitly requested. This must be restricted
# to trusted CIDR ranges in production.
resource "aws_security_group" "database" {
  name        = "${local.name_prefix}-database-sg"
  description = "Allow MySQL and PostgreSQL from anywhere (SECURITY RISK - restrict to trusted CIDRs in production)"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from anywhere - SECURITY RISK, restrict in production"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [local.open_cidr]
  }

  ingress {
    description = "PostgreSQL from anywhere - SECURITY RISK, restrict in production"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [local.open_cidr]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.open_cidr]
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-database-sg"
    },
  )
}

resource "aws_db_subnet_group" "main" {
  name       = "${local.name_prefix}-db-subnet-group"
  subnet_ids = [aws_subnet.public_a.id, aws_subnet.public_b.id]

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-db-subnet-group"
    },
  )

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment tag applied to all resources"
  type        = string
  default     = "dev"
}

variable "vpc_cidr" {
  description = "IPv4 CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_ipv4_cidr" {
  description = "IPv4 CIDR block for the IPv6-enabled subnet"
  type        = string
  default     = "10.0.1.0/24"
}

locals {
  name_prefix = "egress-only-ipv6"
  common_tags = {
    Name        = local.name_prefix
    Environment = var.environment
    Purpose     = "IPv6 egress-only internet access"
  }
}

resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  assign_generated_ipv6_cidr_block = true
  enable_dns_support               = true
  enable_dns_hostnames             = true

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-vpc"
    }
  )
}

resource "aws_egress_only_internet_gateway" "egress" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-eigw"
    }
  )
}

resource "aws_subnet" "ipv6" {
  vpc_id                          = aws_vpc.main.id
  cidr_block                      = var.subnet_ipv4_cidr
  ipv6_cidr_block                 = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, 1)
  assign_ipv6_address_on_creation = true
  map_public_ip_on_launch         = false

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-subnet"
    }
  )
}

resource "aws_route_table" "egress" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-egress-rt"
    }
  )
}

resource "aws_route" "ipv6_egress" {
  route_table_id              = aws_route_table.egress.id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.egress.id
}

resource "aws_route_table_association" "ipv6" {
  subnet_id      = aws_subnet.ipv6.id
  route_table_id = aws_route_table.egress.id
}

output "vpc_id" {
  description = "ID of the VPC containing the egress-only internet gateway"
  value       = aws_vpc.main.id
}

output "vpc_ipv6_cidr_block" {
  description = "Amazon-provided IPv6 CIDR block of the VPC"
  value       = aws_vpc.main.ipv6_cidr_block
}

output "egress_only_internet_gateway_id" {
  description = "ID of the egress-only internet gateway"
  value       = aws_egress_only_internet_gateway.egress.id
}

output "ipv6_subnet_id" {
  description = "ID of the IPv6-enabled subnet"
  value       = aws_subnet.ipv6.id
}

output "egress_route_table_id" {
  description = "ID of the route table containing the egress-only IPv6 route"
  value       = aws_route_table.egress.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "main" {
  cidr_block           = "192.168.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "windomain-vpc"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_vpc_dhcp_options" "main" {
  domain_name          = "windomain.local"
  domain_name_servers  = ["192.168.56.102", "8.8.8.8"]
  netbios_name_servers = ["192.168.56.102"]

  tags = {
    Name = "windomain-dhcp-options"
  }
}

resource "aws_vpc_dhcp_options_association" "main" {
  dhcp_options_id = aws_vpc_dhcp_options.main.id
  vpc_id          = aws_vpc.main.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-internet-gateway"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "public-route-table"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain     = "vpc"
  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "main-nat-eip"
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id
  depends_on    = [aws_internet_gateway.main]

  tags = {
    Name = "main-nat-gateway"
    pike = "permissions"
  }
}

output "nat_gateway_id" {
  description = "ID of the NAT Gateway"
  value       = aws_nat_gateway.main.id
}

output "nat_gateway_public_ip" {
  description = "Elastic IP associated with the NAT Gateway"
  value       = aws_eip.nat.public_ip
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "peer" {
  cidr_block           = "10.0.0.0/24"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "peer"
  }
}

resource "aws_vpc" "base" {
  cidr_block           = "10.1.0.0/24"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "base"
  }
}

resource "aws_vpc_peering_connection" "pike" {
  vpc_id      = aws_vpc.peer.id
  peer_vpc_id = aws_vpc.base.id
  auto_accept = true

  requester {
    allow_remote_vpc_dns_resolution = true
  }

  accepter {
    allow_remote_vpc_dns_resolution = true
  }

  tags = {
    Name = "pike"
  }
}

resource "aws_route" "peer_to_base" {
  route_table_id            = aws_vpc.peer.default_route_table_id
  destination_cidr_block    = "10.1.0.0/24"
  vpc_peering_connection_id = aws_vpc_peering_connection.pike.id
}

resource "aws_route" "base_to_peer" {
  route_table_id            = aws_vpc.base.default_route_table_id
  destination_cidr_block    = "10.0.0.0/24"
  vpc_peering_connection_id = aws_vpc_peering_connection.pike.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  name            = "main-vpc"
  vpc_cidr_block  = "10.0.0.0/16"
  internet_cidr   = "0.0.0.0/0"
  ephemeral_start = 1024
  ephemeral_end   = 65535
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = local.name
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_network_acl" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = local.name
  }
}

resource "aws_network_acl_rule" "ingress_http" {
  network_acl_id = aws_network_acl.main.id
  rule_number    = 100
  rule_action    = "allow"
  protocol       = "tcp"
  cidr_block     = local.internet_cidr
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "ingress_https" {
  network_acl_id = aws_network_acl.main.id
  rule_number    = 110
  rule_action    = "allow"
  protocol       = "tcp"
  cidr_block     = local.internet_cidr
  from_port      = 443
  to_port        = 443
}

# Required return traffic for established sessions: ephemeral port range
resource "aws_network_acl_rule" "ingress_ephemeral" {
  network_acl_id = aws_network_acl.main.id
  rule_number    = 120
  rule_action    = "allow"
  protocol       = "tcp"
  cidr_block     = local.internet_cidr
  from_port      = local.ephemeral_start
  to_port        = local.ephemeral_end
}

resource "aws_network_acl_rule" "egress_http" {
  network_acl_id = aws_network_acl.main.id
  rule_number    = 100
  rule_action    = "allow"
  protocol       = "tcp"
  egress         = true
  cidr_block     = local.internet_cidr
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "egress_https" {
  network_acl_id = aws_network_acl.main.id
  rule_number    = 110
  rule_action    = "allow"
  protocol       = "tcp"
  egress         = true
  cidr_block     = local.internet_cidr
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "egress_ephemeral" {
  network_acl_id = aws_network_acl.main.id
  rule_number    = 120
  rule_action    = "allow"
  protocol       = "tcp"
  egress         = true
  cidr_block     = local.internet_cidr
  from_port      = local.ephemeral_start
  to_port        = local.ephemeral_end
}
